INTRX1_HANDLER:		; 1F736
	PUSH XIZ
	PUSH XIY
	PUSH XIX
	PUSH XHL
	PUSH XDE
	PUSH XBC
	PUSH XWA
	LD C, (SC1BUF)
	LD A, (SC1CR)
	AND A, 01ch    ; 0001 1100
	JR Z, Serial1_RX_NoError
	
	; serial comms error happened:
	db 0c0h, 0d5h, 019h, 036h, 010h ; LD (1036h), (SC1CR)
	JR T, Serial1_RX_Exit

Serial1_RX_NoError:		; 01F74Fh
	BIT 2, (SERIAL_1_VAR_1034)	; Check if RX enabled
	JR Z, Serial1_RX_Exit
	LD XWA, 00000e00h		; Ring buffer descriptor at 0x0E00
	CALR SAVE_BYTE_TO_RING_BUFFER

Serial1_RX_Exit:		; 01F75Dh
	POP XWA
	POP XBC
	POP XDE
	POP XHL
	POP XIX
	POP XIY
	POP XIZ
	RETI


; ----------------------------------------------------------------------------
; INTTX1_HANDLER - Serial Port 1 Transmit Complete Interrupt
; Entry: None
; Notes: Sends next byte from TX ring buffer (0x1016) or 0xFE if sync needed
; ----------------------------------------------------------------------------
INTTX1_HANDLER:			; 01F765h
	PUSH XIZ
	PUSH XIY
	PUSH XIX
	PUSH XHL
	PUSH XDE
	PUSH XBC
	PUSH XWA
	BIT 0, (SERIAL_1_VAR_1034)	; Check sync flag
	JR Z, Serial1_TX_Normal
	RES 0, (SERIAL_1_VAR_1034)
	LD (SC1BUF), 0feh		; Send sync byte
	JR T, Serial1_TX_CheckEmpty

Serial1_TX_Normal:		; 01F77Bh
	LD XWA, 00001016h		; TX ring buffer descriptor
	CALR READ_BYTE_FROM_RING_BUFFER
	CP HL, 0ffffh			; Buffer empty?
	JR Z, Serial1_TX_CheckEmpty
	LD (SC1BUF), L			; Send byte

Serial1_TX_CheckEmpty:		; 01F78Ch
	BIT 0, (SERIAL_1_VAR_1034)
	JR NZ, Serial1_TX_Exit
	LD XWA, 00001016h
	CALR RING_BUFFER_HAS_OVERRUN
	CP HL, 0ffffh			; Buffer empty?
	JR NZ, Serial1_TX_Exit
	LD (INTES1), 0fdh		; Disable TX interrupt

Serial1_TX_Exit:		; 01F7A3h
	POP XWA
	POP XBC
	POP XDE
	POP XHL
	POP XIX
	POP XIY
	POP XIZ
	RETI


; returns:
; HL = 0ffffh (True)
; HL = 0000h (False)
;
RING_BUFFER_HAS_OVERRUN:  ; 1F7AB
	LD HL, 0
	LD XBC, (XWA + 00ch)  ; current_read_pointer
	CP XBC, (XWA + 008h)  ; current_write_pointer
	RET NZ
	LD HL, 0ffffh
	RET


; ----------------------------------------------------------------------------
; READ_BYTE_FROM_RING_BUFFER - Read a byte from a ring buffer
; Entry: XWA = ring buffer descriptor pointer
; Exit:  L = byte read, HL = 0 on success
;        HL = 0xFFFF if buffer empty
; Notes: Ring buffer descriptor format:
;        +0x00: buffer_start pointer
;        +0x04: buffer_end pointer
;        +0x08: write_pointer
;        +0x0C: read_pointer
;        +0x14: available_bytes count
; ----------------------------------------------------------------------------
READ_BYTE_FROM_RING_BUFFER:	; 01F7B9h
	LD HL, 0ffffh
	LDA XDE, XWA + 008h  ; current_write_pointer
	LD XBC, (XDE)
	LD XIX, XBC
	CP (XWA + 00ch), XBC  ; current_read_pointer
	RET Z			; Buffer empty
	LD L, (XBC)		; Read byte
	CP XBC, (XWA + 004h)  ; buffer_end
	JR NZ, RingBuf_Read_NoWrap
	LD XIX, (XWA)  ; buffer_start - wrap around
	JR T, RingBuf_Read_Update

RingBuf_Read_NoWrap:		; 01F7D3h
	INC 1, XIX

RingBuf_Read_Update:		; 01F7D5h
	LD (XDE), XIX		; Update write pointer
	INCW 1, (XWA + 014h)	; Increment available count
	EXTZ HL
	RET

; ----------------------------------------------------------------------------
; SAVE_BYTE_TO_RING_BUFFER - Write a byte to a ring buffer
; Entry: XWA = ring buffer descriptor pointer
;        C = byte to write
; Exit:  HL = available bytes remaining
; Notes: Returns without writing if buffer full (available == 0)
; ----------------------------------------------------------------------------
SAVE_BYTE_TO_RING_BUFFER:	; 01F7DDh
	LDA XIX, XWA + 014h
	LD HL, (XIX)		; Get available count
	LDA XDE, XWA + 00ch
	LD XIY, (XDE)
	CP HL, 0
	RET Z			; Buffer full
	LD (XIY), C		; Write byte
	CP XIY, (XWA + 004h)
	JR NZ, RingBuf_Write_NoWrap
	LD XIY, (XWA)		; Wrap around
	JR T, RingBuf_Write_Update

RingBuf_Write_NoWrap:		; 01F7F6h
	INC 1, XIY

RingBuf_Write_Update:		; 01F7F8h
	LD (XDE), XIY		; Update read pointer
	LD HL, (XIX)
	DEC 1, HL		; Decrement available count
	LD (XIX), HL
	RET

; ----------------------------------------------------------------------------
; Serial1_Enable_TX_Interrupt - Enable serial port 1 TX interrupt
; Entry: None
; Notes: Used to start transmission when data is queued
; ----------------------------------------------------------------------------
Serial1_Enable_TX_Interrupt:	; 01F801h
	PUSH SR
	EI 6
	LD (INTES1), 0ddh
	POP SR
	RET

Serial1_BaudRate_Config_Table:
	db 002h, 006h, 006h, 008h, 0EBh, 0FDh, 003h, 00Eh

Serial1_CommandHandler_RX_F4F5:
	CP A, 0f5h
	JR Z, Serial1_F5_BaudRate_Switch
	CP A, 0f4h
	RET NZ
	LD (SERIAL_1_VAR_1038), 003h
	SET 2, (SERIAL_1_VAR_1034)
	EI 6
	LD (SC1MOD), 02bh
	EI 0
	RET

Serial1_F5_BaudRate_Switch:
	LD (SERIAL_1_VAR_1038), 002h
	SET 2, (SERIAL_1_VAR_1034)
	RET

Audio_CheckQueuedData_Send:
	LD XWA, (102Ch)
	LD XBC, (1040h)
	LD XDE, XBC
	SUB XDE, XWA
	CP XDE, 00000087h
	RET C
	LD (102Ch), XBC
	SET 0, (SERIAL_1_VAR_1034)
	CALR Serial1_Enable_TX_Interrupt
	RET

Audio_DMA_RingBuffer_To_Maincpu:
	PUSH IZ
	LD IZ, 0

Audio_DMA_RingBuf_ReadLoop:
	LD XWA, 00000e00h
	CALR READ_BYTE_FROM_RING_BUFFER
	CP HL, 0ffffh
	JR Z, Audio_DMA_RingBuf_CheckSend
	LD WA, IZ
	INC 1, IZ
	LDA XBC, 0600h
	EXTZ XWA
	ADD XWA, XBC
	LD (XWA), L
	CP IZ, 0400h
	JR C, Audio_DMA_RingBuf_ReadLoop

Audio_DMA_RingBuf_CheckSend:
	CP IZ, 0
	JR Z, Audio_DMA_RingBuf_Done
	EI 0
	LD WA, 4
	LD BC, IZ
	LD XDE, 00000600h
	CALL InterCPU_DMA_Send

Audio_DMA_RingBuf_Done:
	POP IZ
	RET

Serial1_DataTransmit_Loop:
	LD A, (XSP + 004h)
	DEC 1, (XSP + 004h)
	CP A, 0
	JR Z, Serial1_TX_Done

Serial1_TX_LoopBody:
	BIT 2, (SERIAL_1_VAR_1034)
	JR NZ, Serial1_TX_ViaRingBuf
	LD XWA, (XSP + 006h)
	LD C, (XWA+)
	LD (XSP + 006h), XWA
	EXTZ BC
	LD WA, BC
	CALR Serial1_CommandHandler_RX_F4F5
	JR T, Serial1_TX_CheckNext

Serial1_TX_ViaRingBuf:
	LD XWA, (XSP + 006h)
	LD C, (XWA+)
	LD (XSP + 006h), XWA
	EXTZ BC
	LD XWA, 00001016h
	CALR SAVE_BYTE_TO_RING_BUFFER
	CALR Serial1_Enable_TX_Interrupt

Serial1_TX_CheckNext:
	LD A, (XSP + 004h)
	DEC 1, (XSP + 004h)
	CP A, 0
	JR NZ, Serial1_TX_LoopBody

Serial1_TX_Done:
	LD HL, 0
	RET

Audio_Process_Final:
	PUSH SR
	EI 6
	CALR Audio_DMA_RingBuffer_To_Maincpu
	POP SR
	JRL T, Audio_CheckQueuedData_Send

INIT_RING_BUFFERS:
	LD (SERIAL_1_VAR_1034), 000h
	SET 0, (SERIAL_1_VAR_1034)
	LD (SERIAL_1_VAR_1038), 000h
	LD XIY, Serial1_TxBuf_Struct
	LD XIX, 00000e00h
	LD BC, 000bh
	LDIRW_95
	LD XIY, Serial1_RxBuf_Struct
	LD XIX, 00001016h
	LD BC, 000bh
	LDIRW_95
	EI 6 ; <-------  1f90b
	LD (SC1MOD), 029h
	LD (SC1CR), 000h
	LD (BR1CR), 00ah
	LD (INTES1), 05dh
	LD (SC1BUF), 0feh
	EI 0
	RET

Serial1_Config_Constants:
	db 005h, 00Eh, 068h, 001h, 00Eh


