MemClear_DRAM_And_ExtRAM:
	LD XDE, 0003ee76h
	LD XBC, 000066f2h
	LD IX, BC
	SRL 1, XBC
	JR Z, MemClear_DRAM_OddByte
	LD XHL, XDE
	LDW (XDE+), 0000h
	DEC 1, XBC
	OR XBC, XBC
	JR Z, MemClear_DRAM_OddByte
	LDIRW_93
	CP QBC, 0
	JR Z, MemClear_DRAM_OddByte
	LD WA, QBC

MemClear_DRAM_BulkLoop:
	LDIRW_93
	DJNZ WA, MemClear_DRAM_BulkLoop

MemClear_DRAM_OddByte:
