	JR Z, MemClear_ExtRAM
	LD (XDE), 000h

MemClear_ExtRAM:
	LD XDE, 00000600h
	LD XBC, 000044cbh
	LD IX, BC
	SRL 1, XBC
	JR Z, MemClear_ExtRAM_OddByte
	LD XHL, XDE
	LDW (XDE+), 0000h
	DEC 1, XBC
	OR XBC, XBC
	JR Z, MemClear_ExtRAM_OddByte
	LDIRW_93
	CP QBC, 0
	JR Z, MemClear_ExtRAM_OddByte
	LD WA, QBC

MemClear_ExtRAM_BulkLoop:
	LDIRW_93
	DJNZ WA, MemClear_ExtRAM_BulkLoop

MemClear_ExtRAM_OddByte:
	BIT 0, IX
	JR Z, MemClear_ExtRAM_Finish
	LD (XDE), 000h

