	INC 1, (1045h)
	PUSH WA
	PUSH BC
	CALR Task_DequeueDispatch_Prio3
	POP BC
	POP WA
	JRL T, TaskSwitch_Countdown

TaskSched_Init:
	LD XSP, 00040b1eh
	XOR WA, WA
	LD (1046h), WA
	INC 1, WA
	LDC_INTNEST_WA
	LD (10D2h), WA
	LD HL, 106ch
	EXTZ XHL
	LD DE, 4
	LD_B 003h

TaskSched_Init_QueueHeaders:
	LD IX, HL
	LD (XHL+), IX
	LD (XHL+), IX
	DJNZ B, TaskSched_Init_QueueHeaders
	LD IX, 1048h
	EXTZ XIX
	LD_B 003h
	LD_A 000h

TaskSched_Init_TaskDescriptors:
	LD (XIX + 009h), A
	LD (XIX + 00ah), 000h
	LD (XIX + 00bh), 000h
	ADD IX, 000ch
	DJNZ B, TaskSched_Init_TaskDescriptors
	LD IX, 10cah
	EXTZ XIX
	LD_B 001h
	LD XWA, 0ffffffffh

TaskSched_Init_FreeList_A:
	LD (XIX + 004h), XWA
	ADD IX, 0008h
	DJNZ B, TaskSched_Init_FreeList_A
	LD XHL, 0001fdbch
	LD DE, 1080h
	EXTZ XDE
	LD BC, 2
	LDIR_83
	LD HL, 1078h
	EXTZ XHL
	LD_B 002h

TaskSched_Init_QueueGroup_B:
	LD IX, HL
	LD (XHL+), IX
	LD (XHL+), IX
	DJNZ B, TaskSched_Init_QueueGroup_B
	LD XHL, 0001fdbeh
	LD DE, 1092h
	EXTZ XDE
	LD BC, 4
	LDIR_83
	LD HL, 1082h
	EXTZ XHL
	LD_B 004h

TaskSched_Init_QueueGroup_C:
