	LD (XHL+), IX
	LD (XHL+), IX
	DJNZ B, TaskSched_Init_QueueGroup_C
	LD HL, 10a6h
	EXTZ XHL
	LD_B 004h
	LD XWA, 0ffffffffh

TaskSched_Init_FreeList_B:
	LD (XHL + 004h), XWA
	ADD HL, 0008h
	DJNZ B, TaskSched_Init_FreeList_B
	LD IY, 10c6h
	EXTZ XIY
	LD (XIY + 000h:8), IY
	LD (XIY + 002h:8), IY
	LD IX, 10a6h
	LD_B 004h

TaskSched_Init_LinkFreeNodes:
	EXTZ XIX
	EXTZ XIY
	XOR XWA, XWA
	LD (XIX + 000h:8), IY
	LD WA, (XIY + 002h)
	LD (XIX + 002h), WA
	LD (XWA), IX
	LD (XIY + 002h), IX
	ADD IX, 0008h
	DJNZ B, TaskSched_Init_LinkFreeNodes
	LD HL, 1096h
	EXTZ XHL
	LD_B 002h

TaskSched_Init_QueueGroup_D:
	LD IX, HL
	LD (XHL+), IX
	LD (XHL+), IX
	DJNZ B, TaskSched_Init_QueueGroup_D
	LD HL, 109eh
	EXTZ XHL
	LD_B 002h

TaskSched_Init_QueueGroup_E:
	LD IX, HL
	LD (XHL+), IX
	LD (XHL+), IX
	DJNZ B, TaskSched_Init_QueueGroup_E
	LD XWA, TaskSched_Init_ConfigData
	JR T, TaskSched_ConfigAndDispatch

TaskSched_Init_ConfigData:
	db 001h, 000h, 001h, 000h, 0c7h, 0fdh, 001h, 000h

TaskSched_ConfigAndDispatch:
	CALL Task_ConfigTimer
	CALR IntMask_ClearBit3
	LD (TREG3), 01dh
	LD A, (INTET23)
	AND A, 00fh
	OR A, 020h
	LD (INTET23), A
	CALR IntMask_SetBit3
	LD_A 001h
	CALR TaskSched_SpawnTask
	EI 6
	LD (1044h), 000h
	XOR WA, WA
	LDC_INTNEST_WA
	LD (10D2h), WA
	JRL T, TaskSched_Dispatch

TaskSched_Halt:
	EI 0
	LD (DAREG1), 0ffh

TaskSched_HaltLoop:
	JR T, TaskSched_HaltLoop

TaskSched_Dispatch:
	LD (DAREG1), 000h
	LD WA, (10D2h)
	OR WA, WA
	JR NZ, TaskSched_ContextRestore
	XOR WA, WA
	CP (1046h), WA
	JR Z, TaskSched_Dispatch_ScanQueues
	LD IY, (1046h)
	EXTZ XIY
	LD (XIY + 004h), XSP
	LD XSP, 00040b1eh
	XOR WA, WA
	LD (1046h), WA

TaskSched_Dispatch_ScanQueues:
	LD_B 003h
	LD IX, 106ch
	EXTZ XIX

TaskSched_Dispatch_ScanLoop:
	LD HL, (XIX + 000h:8)
	CP HL, IX
	JR NZ, TaskSched_Dispatch_SwitchTo
	INC 4, IX
	DJNZ B, TaskSched_Dispatch_ScanLoop
	JR T, TaskSched_Halt

TaskSched_Dispatch_SwitchTo:
	LD (1046h), HL
	EXTZ XHL
	LD A, (XHL + 00bh)
	SLL 5, A
	LD (DAREG1), A
	LD XSP, (XHL + 004h)

TaskSched_ContextRestore:
	POP XIZ
	POP XIY
	POP XIX
	POP XDE
	POP XBC
	POP XWA
	POP XHL
	POP SR
	RET

TaskSched_SoftTimer_Service:
