	db 0ACh, 004h, 020h, 0B0h, 0D8h

TaskSwitch_Countdown:
	PUSH WA
	LD WA, (10D2h)
	CP WA, 1
	JR Z, TaskSwitch_Expired
	DEC 1, WA
	LD (10D2h), WA
	LDC_INTNEST_WA
	POP WA
	RETI

TaskSwitch_Expired:
	XOR WA, WA
	LD (10D2h), WA
	LDC_INTNEST_WA
	POP WA
	EI 0
	NOP
	EI 6
	PUSH XHL
	PUSH XWA
	PUSH XBC
	PUSH XDE
	PUSH XIX
	PUSH XIY
	PUSH XIZ
	JRL T, TaskSched_Dispatch

TaskSched_SpawnTask:
	PUSH SR
	EI 6
	PUSH XHL
	PUSH XWA
	PUSH XBC
	PUSH XDE
	PUSH XIX
	PUSH XIY
	PUSH XIZ
	LD W, A
	LD_L 00ch
	MUL HL, A
	EXTZ XHL
	ADD XHL, 0001fd8ch
	LD_C 00ch
	MUL BC, A
	ADD BC, 103ch
	EXTZ XBC
	LD XIX, XBC
	LD A, (XIX + 009h)
	CP A, 0
	JRL NZ, TaskSched_ContextRestore
	LD (XIX + 00bh), W
	LD XIY, (XHL + 004h)
	SUB XIY, 00000022h
	LD WA, (XHL + 008h)
	LD (XIY + 01ch), WA
	LD XWA, (XHL + 000h:8)
	LD (XIY + 01eh), XWA
	LD (XIX + 004h), XIY
	LD A, (XHL + 00ah)
	LD (XIX + 008h), A
	LD (XIX + 009h), 004h
	LD (XIX + 00ah), 000h
	LD A, (XHL + 00ah)
	SLL 2, A
	EXTZ WA
	ADD WA, 1068h
	LD IY, WA
	EXTZ XIX
	EXTZ XIY
	XOR XWA, XWA
	LD (XIX + 000h:8), IY
	LD WA, (XIY + 002h)
	LD (XIX + 002h), WA
	LD (XWA), IX
	LD (XIY + 002h), IX
	JRL T, TaskSched_Dispatch
	EI 6
	LD XSP, 00040b1eh
	LD IX, (1046h)
	EXTZ XIX
	LD (XIX + 009h), 000h
	LD (XIX + 00ah), 000h
	XOR WA, WA
	LD (1046h), WA
	EXTZ XIX
	XOR XWA, XWA
	XOR XHL, XHL
	LD WA, (XIX + 000h:8)
	LD HL, (XIX + 002h)
	LD (XHL + 000h:8), WA
	LD (XWA + 002h), HL
	JRL T, TaskSched_Dispatch
	LD HL, (10D2h)
	OR HL, HL
	JR NZ, TaskSched_ReturnZero
	PUSH XIX
	LD IX, (1046h)
	EXTZ XIX
	LD L, (XIX + 00bh)
	EXTZ HL
	POP XIX
	RET

TaskSched_ReturnZero:
	XOR HL, HL
	RET

TaskSched_PreemptiveYield:
	PUSH SR
	EI 6
	PUSH XHL
	PUSH XWA
	PUSH XBC
	PUSH XDE
	PUSH XIX
	PUSH XIY
	PUSH XIZ
	SLL 2, A
	EXTZ WA
	ADD WA, 1068h
	LD IY, WA
	EXTZ XIY
	LD IX, (XIY + 000h:8)
	CP IX, (XIY + 002h)
	JRL Z, TaskSched_ContextRestore
	EXTZ XIX
	XOR XWA, XWA
	XOR XHL, XHL
	LD WA, (XIX + 000h:8)
	LD HL, (XIX + 002h)
	LD (XHL + 000h:8), WA
	LD (XWA + 002h), HL
	EXTZ XIX
	EXTZ XIY
	XOR XWA, XWA
	LD (XIX + 000h:8), IY
	LD WA, (XIY + 002h)
	LD (XIX + 002h), WA
	LD (XWA), IX
	LD (XIY + 002h), IX
	JRL T, TaskSched_Dispatch

TaskQueue_Dequeue:
	PUSH XWA
	PUSH XIX
	PUSH XIY
	PUSH XHL
	SLL 2, A
	EXTZ WA
	ADD WA, 1068h
	LD IY, WA
	EXTZ XIY
	LD IX, (XIY + 000h:8)
	CP IX, (XIY + 002h)
	JR Z, TaskQueue_Dequeue_Return
	EXTZ XIX
	XOR XWA, XWA
	XOR XHL, XHL
	LD WA, (XIX + 000h:8)
	LD HL, (XIX + 002h)
	LD (XHL + 000h:8), WA
	LD (XWA + 002h), HL
	EXTZ XIX
	EXTZ XIY
	XOR XWA, XWA
	LD (XIX + 000h:8), IY
	LD WA, (XIY + 002h)
	LD (XIX + 002h), WA
	LD (XWA), IX
	LD (XIY + 002h), IX

TaskQueue_Dequeue_Return:
	POP XHL
	POP XIY
	POP XIX
	POP XWA
	RET

