	db 033h, 0FFh, 0FFh, 00Eh, 0DBh, 0D3h, 0C3h, 007h
	db 0E8h, 0F0h, 027h, 0DCh, 038h, 0FFh, 003h, 0BAh
	db 0F8h, 054h, 09Ah, 0FEh, 061h, 00Eh, 09Ah, 0F6h
	db 024h, 09Ah, 0FAh, 0F4h, 06Eh, 004h, 033h, 0FFh
	db 0FFh, 00Eh, 0DBh, 0D3h, 0C3h, 007h, 0E8h, 0F0h
	db 027h, 0DCh, 038h, 0FFh, 003h, 0BAh, 0F6h, 054h
	db 00Eh, 09Ah, 0F6h, 024h, 09Ah, 0FCh, 0F4h, 06Eh
	db 004h, 033h, 0FFh, 0FFh, 00Eh, 0DBh, 0D3h, 0C3h
	db 007h, 0E8h, 0F0h, 027h, 0DCh, 038h, 0FFh, 003h
	db 0BAh, 0F6h, 054h, 00Eh, 09Ah, 0FEh, 03Fh, 000h
	db 000h, 06Eh, 004h, 033h, 0FFh, 0FFh, 00Eh, 09Ah
	db 0FCh, 024h, 0F3h, 007h, 0E8h, 0F0h, 041h, 0DCh
