; ===========================================================================
; InterCPU_Latch_Setup - Setup inter-CPU communication via latches
; ===========================================================================
; Entry: None
; Exit:  DMA channels and interrupt handlers configured
; Notes: Configures interrupt priority for DMA channels 0-3
;        Sets up MicroDMA for inter-CPU latch communication at 0x120000
;        Initializes DMA_XFER_STATE and CMD_PROCESSING_STATE to 0
; ===========================================================================
InterCPU_Latch_Setup:
	AND (INTET23), 0f8h
	RES 2, (T8RUN)
	LDA XBC, INTETC01
	LD A, (XBC)
	AND A, 0f8h
	OR A, 005h
	LD (XBC), A
	LDA XBC, INTETC23
	LD A, (XBC)
	AND A, 0f8h
	OR A, 005h
	LD (XBC), A
	LDA XBC, INTE0AD
	LD A, (XBC)
	AND A, 0f8h
	SET 0, A
	LD (XBC), A
	LD (TREG2), 014h
	LDA XWA, INTER_CPU_COMM_LATCHES
	LDC_DMAD2_XWA
	LD_A 8
	LDC_DMAM2_A
	LDA XWA, INTER_CPU_COMM_LATCHES
	LDC DMAS0, XWA
	LD_A 0
	LDC_DMAM0_A
	LD (DMA_XFER_STATE), 0
	LD (CMD_PROCESSING_STATE), 0
	RET

; ===========================================================================
; InterCPU_DMA_Send - Send data via DMA to main CPU
; ===========================================================================
; Entry: XDE = source data pointer
;        BC = byte count
;        A = command/channel identifier
; Exit:  Data transferred to main CPU via inter-CPU latch
; Notes: Splits large transfers into 32-byte chunks
;        Used by tone generator and audio subsystem for command responses
; ===========================================================================
InterCPU_DMA_Send:
	DEC 6, XSP
	PUSH IZ
	LD (XSP + 002h), XDE
	LD IZ, BC
	LD (XSP + 006h), A
	CP IZ, 0020h
	JR ULE, DMA_Send_Final

DMA_Send_Loop:
	LD A, (XSP + 006h)
	EXTZ WA
	LD BC, 0020h
	LD XDE, (XSP + 002h)
	CALR InterCPU_DMA_Send_Chunk
	LD XWA, 00000020h
	ADD (XSP + 002h), XWA
	SUB IZ, 0020h
	CP IZ, 0020h
	JR UGT, DMA_Send_Loop

DMA_Send_Final:
	LD A, (XSP + 006h)
	EXTZ WA
	LD C, IZL
	EXTZ BC
	LD XDE, (XSP + 002h)
	CALR InterCPU_DMA_Send_Chunk
	POP IZ
	INC 6, XSP
	RET

; ===========================================================================
; InterCPU_DMA_Send_Chunk - Transfer a single chunk of data to main CPU
; ===========================================================================
; Entry: XDE = source data pointer
;        BC = byte count (must be non-zero)
;        A = command/channel identifier (bits 7-5 used for dispatch)
; Exit:  Data transferred via DMA channel 2
; Notes: Helper for InterCPU_DMA_Send - handles one transfer operation.
;        Waits for MSTAT1 handshake, sets up DMA, then waits for completion.
;        Command byte format: (A << 5) | (length - 1)
; ===========================================================================
InterCPU_DMA_Send_Chunk:
	CP C, 0
	RET Z
	LD IX, 0

DMA_Chunk_Start:
	BIT 4, (PD)  ; MSTAT1 - test if Main CPU is requesting handshake
	JR Z, DMA_Chunk_Wait_MSTAT1_Clear
	RES 0, (PD)  ; SSTAT0 - clear to acknowledge Main CPU handshake request
	LD (DMA_XFER_STATE), 001h
	LD L, C
	DEC 1, L
	SLL 5, A
	OR A, L
	LD (INTER_CPU_COMM_LATCHES), A
	LD IX, 0

DMA_Chunk_Transfer:
	BIT 4, (PD)  ; MSTAT1 - wait for Main CPU to clear (data ready to receive)
	JR NZ, DMA_Chunk_Wait_MSTAT1_Set
	SET 0, (PD)  ; SSTAT0 - set to signal ready to receive DMA data
	LDC_DMAS2_XDE
	EXTZ BC
	LDC_DMAC2_BC
	LD (DMA2V), 016h
	SET 2, (T8RUN)
	CP (DMA_XFER_STATE), 000h
	RET Z

DMA_Chunk_Wait:
	CP (DMA_XFER_STATE), 000h
	JR NZ, DMA_Chunk_Wait
	RET

DMA_Chunk_Wait_MSTAT1_Clear:
	LD HL, IX
	INC 1, IX
	CP HL, 0ea60h
	JR ULE, DMA_Chunk_Start
	RET

DMA_Chunk_Wait_MSTAT1_Set:
	LD WA, IX
	INC 1, IX
	CP WA, 0ea60h
	JR ULE, DMA_Chunk_Transfer
	SET 0, (PD)  ; SSTAT0 - timeout recovery: force ready state before exit
	RET

InterCPU_LatchProtocol_Opaque:
	db 0D9h, 0A8h, 0F0h, 034h, 0CCh, 066h, 012h, 0F0h
	db 034h, 0B0h, 0F2h, 000h, 000h, 012h, 000h, 0E3h
	db 0F0h, 034h, 0CCh, 06Eh, 00Fh, 0F0h, 034h, 0B8h
	db 00Eh

; Retry counter for gate 1 of the 0xE3 send; spins back to 020D15h while MSTAT1 is still low, gives up after 60001 tries.
E3_Wait_MSTAT1_Clear:
	db 0D9h, 088h, 0D9h, 061h, 0D8h, 0CFh, 060h, 0EAh
	db 063h, 0DFh, 00Eh

; Retry counter for gate 2 of the 0xE3 send; spins back to 020D23h while MSTAT1 is still high.
E3_Wait_MSTAT1_Set:
	db 0D9h, 088h, 0D9h, 061h, 0D8h, 0CFh, 060h, 0EAh
	db 06Bh, 0E7h, 068h, 0E0h

; Sends command byte 0xE2 followed by a fixed 10-byte parameter block staged at 010D4h (XWA/XDE/BC) via micro-DMA ch2. Sibling of InterCPU_E1_DMA_Transfer.
InterCPU_E2_DMA_Transfer:
	db 0DCh, 0A8h, 0C1h, 0E8h, 010h, 03Fh, 000h, 066h
	db 011h

; Spins while the TX-state flag (DMA_XFER_STATE) is non-zero, i.e. a previous micro-DMA burst is still running.
E2_Wait_DMA_Idle:
	db 0DCh, 08Bh, 0DCh, 061h, 0DBh, 0CFh, 060h, 0EAh
	db 0B0h, 0FBh, 0C1h, 0E8h, 010h, 03Fh, 000h, 06Eh
	db 0EFh

; TX engine idle: assert SSTAT0, mark busy, push the 0xE2 header into the latch.
E2_DMA_Ready:
	db 0F0h, 034h, 0B0h, 0F1h, 0E8h, 010h, 000h, 001h
	db 0F2h, 000h, 000h, 012h, 000h, 0E2h, 0DCh, 0A8h
	db 0F0h, 034h, 0CCh, 06Eh, 033h

; Header acknowledged: stage the 10-byte block at 010D4h, program DMAS2/DMAC2/DMA2V and start timer 2.
E2_Start_Transfer:
	db 0F0h, 034h, 0B8h, 0F1h, 0D4h, 010h, 033h, 0B3h
	db 060h, 0BBh, 004h, 062h, 0BBh, 008h, 051h, 0EBh
	db 02Eh, 008h, 030h, 00Ah, 000h, 0D8h, 02Eh, 048h
	db 0F1h, 002h, 001h, 000h, 016h, 0F0h, 080h, 0BAh
	db 0F1h, 0FEh, 004h, 0BFh, 0C1h, 0E8h, 010h, 03Fh
	db 000h, 0B0h, 0F6h, 0C1h, 0E8h, 010h, 03Fh, 000h
	db 06Eh, 0F9h, 00Eh

; Retry counter for the 0xE2 header acknowledge; spins back to 020D6Dh while MSTAT1 is still high.
E2_Wait_MSTAT1_Set:
	db 0DCh, 08Bh, 0DCh, 061h, 0DBh, 0CFh, 060h, 0EAh
	db 063h, 0BEh, 0F0h, 034h, 0B8h, 00Eh

; ===========================================================================
; InterCPU_E1_DMA_Transfer - E1 command bulk data transfer (Sub→Main CPU)
; ===========================================================================
; Entry: XWA = destination address (in main CPU memory)
;        XDE = source address (in sub CPU memory)
;        BC = byte count
; Exit:  Data transferred to main CPU via two-phase E1 protocol
; Notes: Called from Cmd_Check_E2_Pending to send response data.
;        Phase 1: Send E1 command + 6-byte header (dest addr, byte count)
;        Phase 2: Actual data transfer via DMA channel 2
;        Uses 60000 iteration timeout (0xEA60) for handshake waits.
;        Stores parameters at 0x1110 and 0x10DE for DMA setup.
; ===========================================================================
InterCPU_E1_DMA_Transfer:
	PUSH IZ
	LD IZ, 0
	CP (DMA_XFER_STATE), 000h
	JR Z, E1_DMA_Ready

E1_Wait_DMA_Idle:
	LD HL, IZ
	INC 1, IZ
	CP HL, 0ea60h
	JRL UGT, E1_Exit
	CP (DMA_XFER_STATE), 000h
	JR NZ, E1_Wait_DMA_Idle

E1_DMA_Ready:
	LD IZ, 0

E1_Check_MSTAT1:
	BIT 4, (PD)  ; MSTAT1 - test if Main CPU is initiating E1 transfer
	JRL Z, E1_Timeout_Retry
	RES 0, (PD)  ; SSTAT0 - clear to acknowledge E1 command from Main CPU
	LD (DMA_XFER_STATE), 002h
	LD (INTER_CPU_COMM_LATCHES), 0e1h
	LD IZ, 0

E1_Start_Transfer:
	BIT 4, (PD)  ; MSTAT1 - wait for Main CPU to clear (header data ready)
	JRL NZ, E1_Busy_Wait
	SET 0, (PD)  ; SSTAT0 - set to signal ready to receive DMA header
	LDA XHL, 1110h
	LD (XHL), XWA
	LDA XWA, 10DEh
	LD (XWA), XDE
	LD (XHL + 004h), BC
	LD (XWA + 004h), BC
	LDC_DMAS2_XWA
	LD WA, 6
	LDC_DMAC2_WA
	LD (DMA2V), 016h
	SET 2, (T8RUN)
	CP (DMA_XFER_STATE), 001h
	JR Z, E1_Delay_Loop1

E1_Wait_State1:
	CP (DMA_XFER_STATE), 001h
	JR NZ, E1_Wait_State1

E1_Delay_Loop1:
	LD IZ, 0
	CP IZ, 00c8h
	JR NC, E1_Phase2_Setup

E1_Delay1:
	NOP
	INC 1, IZ
	CP IZ, 00c8h
	JR C, E1_Delay1

E1_Phase2_Setup:
	LDA XWA, 1110h
	LD XBC, (XWA)
	LDC_DMAS2_XBC
	LD WA, (XWA + 004h)
	LDC_DMAC2_WA
	LD (DMA2V), 016h
	SET 2, (T8RUN)
	CP (DMA_XFER_STATE), 000h
	JR Z, E1_Delay_Loop2

E1_Wait_Complete:
	CP (DMA_XFER_STATE), 000h
	JR NZ, E1_Wait_Complete

E1_Delay_Loop2:
	LD IZ, 0
	CP IZ, 00c8h
	JR NC, E1_Done

E1_Delay2:
	NOP
	INC 1, IZ
	CP IZ, 00c8h
	JR C, E1_Delay2

E1_Done:
	JR T, E1_Exit

E1_Timeout_Retry:
	LD HL, IZ
	INC 1, IZ
	CP HL, 0ea60h
	JRL ULE, E1_Check_MSTAT1
	JR T, E1_Exit

E1_Busy_Wait:
	LD HL, IZ
	INC 1, IZ
	CP HL, 0ea60h
	JRL ULE, E1_Start_Transfer
	SET 0, (PD)  ; SSTAT0 - timeout recovery: force ready state before exit

E1_Exit:
	POP IZ
	RET


; ----------------------------------------------------------------------------
; INT0_HANDLER - External Interrupt 0 Handler (Inter-CPU Command Reception)
; Entry: Triggered when main CPU sends command via latch at 0x120000
; Notes: Reads command byte from latch, dispatches based on value:
;        0xE1 = Start E1 command (6 bytes, state 2) - bulk data transfer setup
;        0xE2 = Start E2 command (10 bytes, state 3) - extended data transfer
;        0xE3 = Payload ready signal (sets PAYLOAD_LOADED_FLAG bit 6)
;        Other = Standard command (1-32 bytes based on bits 4-0, state 1)
; ----------------------------------------------------------------------------
INT0_HANDLER:				; 20E86
	PUSH XWA
	BIT 2, (PD)  ; MSTAT0 - test if Main CPU is currently sending data
	JR NZ, INT0_Exit
	LD A, (INTER_CPU_COMM_LATCHES)
	LD (BYTE_FROM_MAINCPU_LATCH), A
	CP A, 0e1h
	JR NZ, INT0_Check_E2
	LD (CMD_PROCESSING_STATE), 002h	; E1 command - state 2
	LDA XWA, 1116h			; E1 data buffer
	LD (10E4h), XWA			; Save DMA target
	LDC_DMAD0_XWA
	LD WA, 6			; 6 bytes for E1
	LDC_DMAC0_WA
	JR T, INT0_Start_DMA

INT0_Check_E2:				; 020EB1h
	CP A, 0e2h
	JR NZ, INT0_Check_E3
	LD (CMD_PROCESSING_STATE), 003h	; E2 command - state 3
	LDA XWA, 111Ch			; E2 data buffer
	LD (10E4h), XWA
	LDC_DMAD0_XWA
	LD WA, 000ah			; 10 bytes for E2
	LDC_DMAC0_WA
	JR T, INT0_Start_DMA

INT0_Check_E3:				; 020ECEh
	CP A, 0e3h
	JR NZ, INT0_Standard_Cmd
	SET 6, (PAYLOAD_LOADED_FLAG)	; E3 = payload ready
	JR T, INT0_Ack

INT0_Standard_Cmd:			; 020ED9h - standard variable-length command
	LD (CMD_PROCESSING_STATE), 001h	; State 1
	LDA XWA, 10F0h			; Standard command buffer
	LD (10E4h), XWA
	LDC_DMAD0_XWA
	LD A, (BYTE_FROM_MAINCPU_LATCH)
	AND A, 01fh			; Bits 4-0 = length - 1
	INC 1, A			; Add 1 for actual length
	EXTZ WA
	LDC_DMAC0_WA

INT0_Start_DMA:				; 020EF7h
	LD (DMA0V), 00ah		; Start DMA channel 0

INT0_Ack:				; 020EFCh
	RES 1, (PD)  ; SSTAT1 - clear to acknowledge command received from Main CPU

INT0_Exit:				; 020EFFh
	POP XWA
	RETI


;=============================================================================
; MICRODMA_CH2_HANDLER - MicroDMA Channel 2 Completion Interrupt
;=============================================================================
; Called when DMA channel 2 transfer completes (payload data transfers).
; Manages the DMA state machine for multi-phase transfers:
;   - State 2 (two-phase) -> State 1 (waiting for phase 2)
;   - State 1 (single xfer) -> State 0 (idle)
; Stops Timer 8 which triggers the DMA transfers.
;=============================================================================
MICRODMA_CH2_HANDLER:  ; Channel #2 completion		; 20F01
	RES 2, (T8RUN)
	CP (DMA_XFER_STATE), 001h
	JR NZ, MICRODMA_CH2_State2
	LD (DMA_XFER_STATE), 000h
	JR T, MICRODMA_CH2_Done

MICRODMA_CH2_State2:			; 020F12h - two-phase transfer, go to state 1
	CP (DMA_XFER_STATE), 002h
	JR NZ, MICRODMA_CH2_Done
	LD (DMA_XFER_STATE), 001h

MICRODMA_CH2_Done:			; 020F1Eh
	RETI


;=============================================================================
; MICRODMA_CH0_HANDLER - MicroDMA Channel 0 Completion Interrupt
;=============================================================================
; Called when DMA channel 0 transfer completes (inter-CPU latch reads).
; This is the main command dispatcher - receives commands from main CPU
; and processes them based on CMD_PROCESSING_STATE:
;   State 1: Decode command byte (bits 7-5 = handler, bits 4-0 = length)
;   State 2: Process E1 command (two-phase transfer setup)
;   State 3: Process E2 command (transfer parameters)
;   State 4: Process E3 command (payload ready signal)
;=============================================================================
MICRODMA_CH0_HANDLER:			; 20F1Fh - Channel #0 completion (command dispatch)
	PUSH XIZ
	PUSH XIY
	PUSH XIX
	PUSH XHL
	PUSH XDE
	PUSH XBC
	PUSH XWA
	LD A, (CMD_PROCESSING_STATE)
	CP A, 4
	JR Z, CH0_State4_E1_Done
	CP A, 3
	JR Z, CH0_State3_E2
	CP A, 2
	JR Z, CH0_State2_E1
	CP A, 1
	JR NZ, CH0_Timer_Reset
	; State 1: Standard command processing
	PUSHW 0000h
	PUSHW 10f0h			; Command buffer address
	LD C, (BYTE_FROM_MAINCPU_LATCH)
	LD A, C
	AND A, 01fh
	INC 1, A			; Length = (byte & 0x1F) + 1
	EXTZ WA
	PUSH WA
	SRL 5, C  ; The 3 highest bits from the byte received via maincpu latch
	             ; are used to select one of the 8 call-table entries
	LD A, C
	EXTZ WA
	SLA 2, WA			; Multiply by 4 (table entry size)
	LDA XBC, CMD_DISPATCH_TABLE:24
	LD XWA, (XBC + WA)
	CALL T, XWA			; Dispatch to handler
	INC 6, XSP
	LD (CMD_PROCESSING_STATE), 000h
	JR T, CH0_Ack

CH0_State2_E1:				; 020F6Dh - E1 command phase 1 complete, start phase 2
	LDA XWA, 1116h			; E1 data buffer
	LD XBC, (XWA)			; Get DMA destination address
	LDC_DMAD0_XBC
	LD WA, (XWA + 004h)		; Get DMA byte count
	LDC_DMAC0_WA
	LD (DMA0V), 00ah		; Start DMA
	LD (CMD_PROCESSING_STATE), 004h	; Move to state 4
	JR T, CH0_Timer_Reset

CH0_State3_E2:				; 020F88h - E2 command complete
	LD (10EEh), 0ffh
	LD (CMD_PROCESSING_STATE), 000h
	SET 1, (PD)  ; SSTAT1 - set to signal ready for next command from Main CPU
	SET 7, (1126h)			; Set E2 pending flag
	JR T, CH0_Timer_Reset

CH0_State4_E1_Done:			; 020F9Bh - E1 two-phase transfer complete
	LD (CMD_PROCESSING_STATE), 000h
	RES 7, (PAYLOAD_LOADED_FLAG)

CH0_Ack:				; 020FA4h
	SET 1, (PD)  ; SSTAT1 - set to signal E1 transfer complete, ready for next

CH0_Timer_Reset:			; 020FA7h - reset Timer 8 if running
	BIT 2, (T8RUN)
	JR Z, CH0_Exit
	RES 2, (T8RUN)			; Stop timer
	NOP
	NOP
	SET 2, (T8RUN)			; Restart timer

CH0_Exit:				; 020FB4h
	POP XWA
	POP XBC
	POP XDE
	POP XHL
	POP XIX
	POP XIY
	POP XIZ
	RETI

; ----------------------------------------------------------------------------
; Cmd_Check_E2_Pending - Check and process pending E2 command
; Entry: None
; Exit:  E2 data processed if pending flag set
; Notes: Called from main loop to handle deferred E2 processing
; ----------------------------------------------------------------------------
Cmd_Check_E2_Pending:		; 020FBCh
	EI 6
	LDA XWA, 1126h
	BIT 7, (XWA)		; Check E2 pending flag
	JR Z, Cmd_Check_DMA_Timeout
	RES 7, (XWA)		; Clear pending flag
	EI 0
	LDA XDE, 111Ch		; E2 data buffer
	LD XWA, (XDE)
	LD BC, (XDE + 008h)
	LD XDE, (XDE + 004h)
	CALR InterCPU_E1_DMA_Transfer	; Process E2 data

; Check for DMA timeout (stuck transfer detection)
Cmd_Check_DMA_Timeout:		; 020FD9h
	EI 0
	BIT 1, (PD)  ; SSTAT1 - test own status: if set, no DMA transfer in progress
	JR NZ, Cmd_DMA_Idle
	LDC_WA_DMAC0		; Get current DMA byte count
	CP (0F01Ch), WA		; Compare with previous
	JR NZ, Cmd_DMA_Reset_Counter
	INCW 1, (0F01Ah)	; Increment stuck counter
	JR T, Cmd_DMA_Save_Count

Cmd_DMA_Reset_Counter:		; 020FEFh
	LDW (0F01Ah), 0000h	; Reset stuck counter

Cmd_DMA_Save_Count:		; 020FF5h
	LD (0F01Ch), WA		; Save current count
	JR T, Cmd_DMA_Check_Stuck

Cmd_DMA_Idle:			; 020FFBh
	LDW (0F01Ah), 0000h

Cmd_DMA_Check_Stuck:		; 021001h
	LD WA, (0F01Ah)
	CP WA, 000ah		; Stuck for 10 iterations?
	RET ULE
	; Timeout recovery - abort stuck DMA
	LDW (0F01Ah), 0000h
	LD (DMA0V), 000h	; Stop DMA
	LD (CMD_PROCESSING_STATE), 000h
	SET 1, (PD)  ; SSTAT1 - timeout recovery: force ready state after DMA abort
	INC 1, (0F018h)		; Increment error counter
	RET

; ===========================================================================
; ToneGen_Read_Register - Read one tone-generator register
; ===========================================================================
; (Was DAC_Write_Sample.  0x100000 is the tone generator's register-ADDRESS
;  latch on write and its status word on read; nothing here writes a sample.)
; Entry: WA = TG register number to latch.
; Exit:  HL = the word read back for that register.
; Notes: clearing P6.7 drives A23 low, selecting the TG side of the multiplex.
;        Latch 0..3 -> the 16-bit active-voice bitmap for that bank;
;        latch 0x180+ch -> that channel's envelope level.
; ===========================================================================
ToneGen_Read_Register:
	RES 7, (P6)
	LD (100000h), WA
	LD HL, (100000h)
	RET

; MIDI_Backlog_Publish(WA = the MIDI ring's byte count) -- was RingBuf_SetOffsetHi.  It
; stores the count to the MIDI backlog gauge at 0x27E7, which RingBuf_CheckOffset_ClearFlags
; compares against 0x20/0x30 (or 0x40/0x50) to drop layer slots: a backpressure threshold.
MIDI_Backlog_Publish:
	LD (27E7h), WA
	RET

RingBuf_SetOffsetLo:
	LD (27E6h), A
	RET

RingBuf_CheckOffset_ClearFlags:
	CP (27E6h), 000h
	JR Z, RingBuf_CheckOffset_LoZero
	CPW (27E7h), 0030h
	JR C, RingBuf_CheckOffset_Level1
	RES 7, (XWA + 003h)
	RES 7, (XWA + 004h)
	RES 7, (XWA + 005h)
	RET

RingBuf_CheckOffset_Level1:
	CPW (27E7h), 0020h
	RET C
	RES 7, (XWA + 004h)
	RES 7, (XWA + 005h)
	RET

RingBuf_CheckOffset_LoZero:
	CPW (27E7h), 0050h
	JR C, RingBuf_CheckOffset_LoZero_Level1
	RES 7, (XWA + 003h)
	RES 7, (XWA + 004h)
	RES 7, (XWA + 005h)
	RET

RingBuf_CheckOffset_LoZero_Level1:
	CPW (27E7h), 0040h
	RET C
	RES 7, (XWA + 004h)
	RES 7, (XWA + 005h)
	RET

Quad_Decode_A_To_L:
	CP A, 040h
	JR NC, Quad_Decode_Quarter2
	LD_L 000h
	JR T, Quad_Decode_Return

Quad_Decode_Quarter2:
	CP A, 080h
	JR NC, Quad_Decode_Quarter3
	LD_L 004h
	JR T, Quad_Decode_Return

Quad_Decode_Quarter3:
	CP A, 0c0h
	JR NC, Quad_Decode_Quarter4
	LD_L 008h
	JR T, Quad_Decode_Return

Quad_Decode_Quarter4:
	LD_L 000h

Quad_Decode_Return:
	RET

; ----------------------------------------------------------------------------
; ExtVoice_Fold_SlotNumber - fold a raw slot byte into its bank's numbering
; Entry: A = raw slot byte, C = bank selector (only bits 0..1 are used)
; Exit:  L = the folded slot number
; Notes: MEASURED.  Selector 0/1 -> A & 0x3F; 2 -> (A - 0x40) with bit 7 cleared;
;        3 -> a third variant.  INFERRED that this normalises a slot index into
;        the 0..0x7F space the caller ORs into its return value.
;        It is NOT a "wave number" computation - see ExtVoice_Alloc_StreamSlot.
; ----------------------------------------------------------------------------
ExtVoice_Fold_SlotNumber:	; 0210A2h
	AND C, 003h
	CP C, 3
	JR Z, SlotPair_Decode_Case3
	CP C, 2
	JR Z, SlotPair_Decode_Case2
	CP C, 1
	JR Z, SlotPair_Decode_Case1
	CP C, 0
	RET NZ

SlotPair_Decode_Case1:
	AND A, 03fh
	LD L, A
	JR T, SlotPair_Decode_Return

SlotPair_Decode_Case2:
	SUB A, 040h
	LD L, A
	RES 7, L
	JR T, SlotPair_Decode_Return

SlotPair_Decode_Case3:
	LD L, A
	RES 7, L

SlotPair_Decode_Return:
	RET

VoiceState_SwapSlot_DE_BC:
	LD E, C
	EXTZ DE
	LD IX, DE
	LD E, A
	EXTZ DE
	MULS_DE 000ch
	LDA XHL, 24E6h
	EXTS XDE
	ADD XDE, XHL
	LD HL, IX
	EXTZ XHL
	ADD XHL, XDE
	LD B, (XHL)
	LD E, C
	EXTZ DE
	LD IX, DE
	INC 4, IX
	LD E, A
	EXTZ DE
	MULS_DE 000ch
	LDA XHL, 24E6h
	EXTS XDE
	ADD XDE, XHL
	LD HL, IX
	EXTZ XHL
	ADD XHL, XDE
	LD W, (XHL)
	LD E, C
	EXTZ DE
	LD IX, DE
	LD E, W
	EXTZ DE
	MULS_DE 000ch
	LDA XHL, 24E6h
	EXTS XDE
	ADD XDE, XHL
	LD HL, IX
	EXTZ XHL
	ADD XHL, XDE
	LD (XHL), B
	LD E, C
	EXTZ DE
	LD IX, DE
	INC 4, IX
	LD E, B
	EXTZ DE
	MULS_DE 000ch
	LDA XHL, 24E6h
	EXTS XDE
	ADD XDE, XHL
	LD HL, IX
	EXTZ XHL
	ADD XHL, XDE
	LD (XHL), W
	LD E, C
	EXTZ DE
	LD IX, DE
	LD E, A
	EXTZ DE
	MULS_DE 000ch
	LDA XHL, 24E6h
	EXTS XDE
	ADD XDE, XHL
	LD HL, IX
	EXTZ XHL
	ADD XHL, XDE
	LD (XHL), A
	EXTZ BC
	LD HL, BC
	INC 4, HL
	LD C, A
	EXTZ BC
	MULS_BC 000ch
	LDA XDE, 24E6h
	EXTS XBC
	ADD XBC, XDE
	LD DE, HL
	EXTZ XDE
	ADD XDE, XBC
	LD (XDE), A
	RET

VoiceState_SwapSlot_HL_IY:
	LD L, C
	EXTZ HL
	LD IY, HL
	LD L, A
	EXTZ HL
	MULS_HL 000ch
	LDA XIX, 24E6h
	EXTS XHL
	ADD XHL, XIX
	LD IX, IY
	EXTZ XIX
	ADD XIX, XHL
	LD B, (XIX)
	LD L, C
	EXTZ HL
	LD IY, HL
	INC 4, IY
	LD L, A
	EXTZ HL
	MULS_HL 000ch
	LDA XIX, 24E6h
	EXTS XHL
	ADD XHL, XIX
	LD IX, IY
	EXTZ XIX
	ADD XIX, XHL
	LD W, (XIX)
	LD L, C
	EXTZ HL
	LD IY, HL
	LD L, W
	EXTZ HL
	MULS_HL 000ch
	LDA XIX, 24E6h
	EXTS XHL
	ADD XHL, XIX
	LD IX, IY
	EXTZ XIX
	ADD XIX, XHL
	LD (XIX), B
	LD L, C
	EXTZ HL
	LD IY, HL
	INC 4, IY
	LD L, B
	EXTZ HL
	MULS_HL 000ch
	LDA XIX, 24E6h
	EXTS XHL
	ADD XHL, XIX
	LD IX, IY
	EXTZ XIX
	ADD XIX, XHL
	LD (XIX), W
	LD L, C
	EXTZ HL
	LD IY, HL
	INC 4, IY
	LD L, E
	EXTZ HL
	MULS_HL 000ch
	LDA XIX, 24E6h
	EXTS XHL
	ADD XHL, XIX
	LD IX, IY
	EXTZ XIX
	ADD XIX, XHL
	LD W, (XIX)
	LD L, C
	EXTZ HL
	LD IY, HL
	LD L, W
	EXTZ HL
	MULS_HL 000ch
	LDA XIX, 24E6h
	EXTS XHL
	ADD XHL, XIX
	LD IX, IY
	EXTZ XIX
	ADD XIX, XHL
	LD (XIX), A
	LD L, C
	EXTZ HL
	LD IY, HL
	INC 4, IY
	LD L, A
	EXTZ HL
	MULS_HL 000ch
	LDA XIX, 24E6h
	EXTS XHL
	ADD XHL, XIX
	LD IX, IY
	EXTZ XIX
	ADD XIX, XHL
	LD (XIX), W
	LD L, C
	EXTZ HL
	LD IY, HL
	LD L, A
	EXTZ HL
	MULS_HL 000ch
	LDA XIX, 24E6h
	EXTS XHL
	ADD XHL, XIX
	LD IX, IY
	EXTZ XIX
	ADD XIX, XHL
	LD (XIX), E
	EXTZ BC
	LD HL, BC
	INC 4, HL
	LD C, E
	EXTZ BC
	MULS_BC 000ch
	LDA XDE, 24E6h
	EXTS XBC
	ADD XBC, XDE
	LD DE, HL
	EXTZ XDE
	ADD XDE, XBC
	LD (XDE), A
	RET

VoiceState_SwapSlot_Guarded:
	DEC 8, XSP
	LD (XSP + 004h), E
	LD (XSP + 006h), C
	LD C, A
	EXTZ BC
	MULS_BC 000ch
	LDA XDE, 24E6h
	EXTS XBC
	ADD XBC, XDE
	LD (XSP), XBC
	LD C, (XSP + 006h)
	EXTZ BC
	LD DE, BC
	INC 8, DE
	LD XBC, (XSP)
	LD E, (XBC + DE)
	LD C, E
	CP C, 0c0h
	JR NC, VoiceState_SwapSlot_Guarded_WriteDst
	LD C, E
	EXTZ BC
	MULS_BC 0005h
	LDA XDE, 2126h
	LDA XIX, XDE + BC
	CP (XIX + 004h), A
	JR NZ, VoiceState_SwapSlot_Guarded_WriteDst
	LD C, (XSP + 006h)
	LD E, C
	EXTZ DE
	LD XBC, (XSP)
	CP (XBC + DE), A
	JR Z, VoiceState_SwapSlot_Guarded_MarkInactive
	LD C, (XSP + 006h)
	LD E, C
	EXTZ DE
	LD XBC, (XSP)
	LD C, (XBC + DE)
	LD (XIX + 004h), C
	JR T, VoiceState_SwapSlot_Guarded_WriteDst

VoiceState_SwapSlot_Guarded_MarkInactive:
	LD (XIX + 004h), 0ffh

VoiceState_SwapSlot_Guarded_WriteDst:
	LD C, (XSP + 004h)
	EXTZ BC
	MULS_BC 0005h
	LDA XDE, 2126h
	LDA XIX, XDE + BC
	CP (XIX + 004h), 040h
	JR ULE, VoiceState_SwapSlot_Guarded_UseHL_IY
	LD (XIX + 004h), A
	LD E, A
	EXTZ DE
	LD A, (XSP + 006h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR VoiceState_SwapSlot_DE_BC
	JR T, VoiceState_SwapSlot_Guarded_Return

VoiceState_SwapSlot_Guarded_UseHL_IY:
	LD L, A
	EXTZ HL
	LD A, (XSP + 006h)
	LD C, A
	EXTZ BC
	LD A, (XIX + 004h)
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR VoiceState_SwapSlot_HL_IY

VoiceState_SwapSlot_Guarded_Return:
	LD A, (XSP + 006h)
	EXTZ WA
	LD DE, WA
	INC 8, DE
	LD XWA, (XSP)
	LD C, (XSP + 004h)
	LD (XWA + DE), C
	INC 8, XSP
	RET

VoiceRow_FetchPair_WA_SP:
	LD C, A
	EXTZ BC
	MULS_BC 0005h
	LDA XDE, 2126h
	LD W, (XDE + BC)
	LD C, A
	EXTZ BC
	MULS_BC 0005h
	LDA XDE, 2127h
	LD L, (XDE + BC)
	LD C, L
	EXTZ BC
	MULS_BC 0005h
	LDA XDE, 2126h
	LD (XDE + BC), W
	LD C, W
	EXTZ BC
	MULS_BC 0005h
	LDA XDE, 2127h
	LD (XDE + BC), L
	LD C, A
	EXTZ BC
	MULS_BC 0005h
	LDA XDE, 2126h
	LD (XDE + BC), A
	LD C, A
	EXTZ BC
	MULS_BC 0005h
	LDA XDE, 2127h
	LD (XDE + BC), A
	RET

VoiceRow_FetchPair_DE_WA:
	LD E, A
	EXTZ DE
	MULS_DE 0005h
	LDA XHL, 2126h
	LD B, (XHL + DE)
	LD E, A
	EXTZ DE
	MULS_DE 0005h
	LDA XHL, 2127h
	LD W, (XHL + DE)
	LD E, W
	EXTZ DE
	MULS_DE 0005h
	LDA XHL, 2126h
	LD (XHL + DE), B
	LD E, B
	EXTZ DE
	MULS_DE 0005h
	LDA XHL, 2127h
	LD (XHL + DE), W
	LD E, C
	EXTZ DE
	MULS_DE 0005h
	LDA XHL, 2127h
	LD W, (XHL + DE)
	LD E, W
	EXTZ DE
	MULS_DE 0005h
	LDA XHL, 2126h
	LD (XHL + DE), A
	LD E, A
	EXTZ DE
	MULS_DE 0005h
	LDA XHL, 2127h
	LD (XHL + DE), W
	LD E, A
	EXTZ DE
	MULS_DE 0005h
	LDA XHL, 2126h
	LD (XHL + DE), C
	EXTZ BC
	MULS_BC 0005h
	LDA XDE, 2127h
	LD (XDE + BC), A
	RET

VoiceSlot_UpdateNoteSource:
	DEC 4, XSP
	PUSH XIZ
	LD (XSP + 004h), E
	LD (XSP + 006h), C
	LD C, A
	EXTZ BC
	MULS_BC 0005h
	LDA XDE, 2126h
	LDA XIZ, XDE + BC
	LD C, (XIZ + 002h)
	EXTZ BC
	MULS_BC 001bh
	LDA XDE, 1E4Dh
	LDA XHL, XDE + BC
	LD E, (XIZ + 003h)
	LD C, E
	EXTZ BC
	CP (XHL + BC), A
	JR NZ, VoiceSlot_UpdateNoteSource_WriteCurrent
	CP (XIZ), A
	JR Z, VoiceSlot_UpdateNoteSource_MarkInactive
	EXTZ DE
	LD C, (XIZ)
	LD (XHL + DE), C
	JR T, VoiceSlot_UpdateNoteSource_WriteCurrent

VoiceSlot_UpdateNoteSource_MarkInactive:
	LD C, E
	EXTZ BC
	LD (XHL + BC), 0ffh

VoiceSlot_UpdateNoteSource_WriteCurrent:
	LD C, (XSP + 006h)
	EXTZ BC
	MULS_BC 001bh
	LDA XDE, 1E4Dh
	LDA XHL, XDE + BC
	LD C, (XSP + 004h)
	EXTZ BC
	CP (XHL + BC), 0c0h
	JR ULE, VoiceSlot_UpdateNoteSource_UseDE_WA
	LD C, (XSP + 004h)
	EXTZ BC
	LD (XHL + BC), A
	EXTZ WA
	CALR VoiceRow_FetchPair_WA_SP
	JR T, VoiceSlot_UpdateNoteSource_Return

VoiceSlot_UpdateNoteSource_UseDE_WA:
	LD E, A
	EXTZ DE
	LD A, (XSP + 004h)
	EXTZ WA
	LD A, (XHL + WA)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR VoiceRow_FetchPair_DE_WA

VoiceSlot_UpdateNoteSource_Return:
	LD A, (XSP + 006h)
	LD (XIZ + 002h), A
	LD A, (XSP + 004h)
	LD (XIZ + 003h), A
	POP XIZ
	INC 4, XSP
	RET

Voice_ScanSlots_ReassignSources:
	DEC 6, XSP
	PUSH XIZ
	LD (XSP + 008h), A
	LD A, (XSP + 008h)
	EXTZ WA
	MULS_WA 00ch
	LDA XBC, 24E6h
	EXTS XWA
	ADD XWA, XBC
	LD (XSP + 004h), XWA
	LD QIZH, 0
	CP QIZH, 4
	JRL NC, Voice_ScanSlots_Return

Voice_ScanSlots_LoopBody:
	LD A, QIZH
	EXTZ WA
	LD BC, WA
	INC 8, BC
	LD XWA, (XSP + 004h)
	LD L, (XWA + BC)
	LD A, L
	CP A, 0c0h
	JRL NC, Voice_ScanSlots_LoopNext
	LD A, L
	EXTZ WA
	MULS_WA 005h
	LDA XBC, 2126h
	LDA XDE, XBC + WA
	LD A, (XDE + 004h)
	CP A, (XSP + 008h)
	JR NZ, Voice_ScanSlots_MarkSlotInactive
	LD A, QIZH
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 004h)
	LD A, (XWA + BC)
	CP A, (XSP + 008h)
	JR Z, Voice_ScanSlots_PromoteSource
	LD A, QIZH
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 004h)
	LD A, (XWA + BC)
	LD (XDE + 004h), A
	JR T, Voice_ScanSlots_MarkSlotInactive

Voice_ScanSlots_PromoteSource:
	LD (XDE + 004h), 0ffh
	LD IZL, L
	EXTZ IZ
	LD A, L
	EXTZ WA
	CALR Quad_Decode_A_To_L
	LD C, L
	EXTZ BC
	LD WA, IZ
	LD DE, BC
	LD BC, 001ah
	CALR VoiceSlot_UpdateNoteSource

Voice_ScanSlots_MarkSlotInactive:
	LD A, (XSP + 008h)
	LD E, A
	EXTZ DE
	LD A, QIZH
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR VoiceState_SwapSlot_DE_BC
	LD A, QIZH
	EXTZ WA
	LD BC, WA
	INC 8, BC
	LD XWA, (XSP + 004h)
	LD (XWA + BC), 0ffh

Voice_ScanSlots_LoopNext:
	INC 1, QIZH
	CP QIZH, 4
	JRL C, Voice_ScanSlots_LoopBody

Voice_ScanSlots_Return:
	POP XIZ
	INC 6, XSP
	RET

VoiceState_FullReset:
	PUSH XIZ
	LD QIZH, 0
	CP QIZH, 040h
	JR NC, VoiceState_FullReset_Phase2

VoiceState_FullReset_Phase1_SlotLoop:
	LD_C 000h
	CP C, 4
	JR NC, VoiceState_FullReset_Phase1_Next

VoiceState_FullReset_Phase1_ColLoop:
	LD A, C
	EXTZ WA
	LD HL, WA
	INC 8, HL
	LD A, QIZH
	EXTZ WA
	MULS_WA 00ch
	LDA XDE, 24E6h
	EXTS XWA
	ADD XWA, XDE
	LD DE, HL
	EXTZ XDE
	ADD XDE, XWA
	LD (XDE), 0ffh
	LD A, C
	EXTZ WA
	LD HL, WA
	LD A, QIZH
	EXTZ WA
	MULS_WA 00ch
	LDA XDE, 24E6h
	EXTS XWA
	ADD XWA, XDE
	LD DE, HL
	EXTZ XDE
	ADD XDE, XWA
	LD A, QIZH
	LD (XDE), A
	LD A, C
	EXTZ WA
	LD HL, WA
	INC 4, HL
	LD A, QIZH
	EXTZ WA
	MULS_WA 00ch
	LDA XDE, 24E6h
	EXTS XWA
	ADD XWA, XDE
	LD DE, HL
	EXTZ XDE
	ADD XDE, XWA
	LD A, QIZH
	LD (XDE), A
	INC 1, C
	CP C, 4
	JR C, VoiceState_FullReset_Phase1_ColLoop

VoiceState_FullReset_Phase1_Next:
	INC 1, QIZH
	CP QIZH, 040h
	JR C, VoiceState_FullReset_Phase1_SlotLoop

VoiceState_FullReset_Phase2:
	LD QIZH, 0
	CP QIZH, 0c0h
	JR NC, VoiceState_FullReset_Phase3

VoiceState_FullReset_Phase2_Body:
	LD A, QIZH
	EXTZ WA
	MULS_WA 005h
	LD BC, WA
	LDA XDE, 2126h
	LD A, QIZH
	LD (XDE + BC), A
	LD A, QIZH
	EXTZ WA
	MULS_WA 005h
	LD BC, WA
	LDA XDE, 2127h
	LD A, QIZH
	LD (XDE + BC), A
	LD A, QIZH
	EXTZ WA
	MULS_WA 005h
	LDA XBC, 2128h
	LD (XBC + WA), 000h
	LD A, QIZH
	EXTZ WA
	MULS_WA 005h
	LDA XBC, 2129h
	LD (XBC + WA), 000h
	LD A, QIZH
	EXTZ WA
	MULS_WA 005h
	LDA XBC, 212Ah
	LD (XBC + WA), 0ffh
	INC 1, QIZH
	CP QIZH, 0c0h
	JR C, VoiceState_FullReset_Phase2_Body

VoiceState_FullReset_Phase3:
	LD QIZH, 0
	CP QIZH, 01bh
	JR NC, VoiceState_FullReset_Phase3_InitSlots

VoiceState_FullReset_Phase3_ClearLoop:
	LD_C 000h
	CP C, 01bh
	JR NC, VoiceState_FullReset_Phase3_ClearNext

VoiceState_FullReset_Phase3_ClearInner:
	LD A, C
	EXTZ WA
	LD HL, WA
	LD A, QIZH
	EXTZ WA
	MULS_WA 01bh
	LDA XDE, 1E4Dh
	EXTS XWA
	ADD XWA, XDE
	LD DE, HL
	EXTZ XDE
	ADD XDE, XWA
	LD (XDE), 0ffh
	INC 1, C
	CP C, 01bh
	JR C, VoiceState_FullReset_Phase3_ClearInner

VoiceState_FullReset_Phase3_ClearNext:
	INC 1, QIZH
	CP QIZH, 01bh
	JR C, VoiceState_FullReset_Phase3_ClearLoop

VoiceState_FullReset_Phase3_InitSlots:
	LD QIZH, 0
	CP QIZH, 0c0h
	JR NC, VoiceState_FullReset_Phase3_Return

VoiceState_FullReset_Phase3_InitBody:
	LD A, QIZH
	LD IZL, A
	EXTZ IZ
	LD A, QIZH
	EXTZ WA
	CALR Quad_Decode_A_To_L
	LD C, L
	EXTZ BC
	LD WA, IZ
	LD DE, BC
	LD BC, 001ah
	CALR VoiceSlot_UpdateNoteSource
	INC 1, QIZH
	CP QIZH, 0c0h
	JR C, VoiceState_FullReset_Phase3_InitBody

VoiceState_FullReset_Phase3_Return:
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; ExtVoice_Lookup_SlotFallback - read the 3-entry slot fallback table (INFERRED)
; Entry: WA = selector (only bits 0..1 are used)
; Exit:  L = the selected byte from ExtVoice_Slot_FallbackTable
; Notes: MEASURED that it reads ExtVoice_Slot_FallbackTable at +0, +4 and +8, and
;        that selector 2 falls back to entry +4 when entry +8 exceeds 0xC0.
;        The three bytes are 0x00 / 0x40 / 0x80 at rest.  INFERRED that they are
;        per-bank slot bases; the allocation protocol itself is not decoded.
; ----------------------------------------------------------------------------
ExtVoice_Lookup_SlotFallback:	; 02174Ch
	LDA XBC, 210Bh
	AND WA, 0003h
	CP WA, 3
	JR Z, ExtVoice_Lookup_SlotFallback_Case3
	CP WA, 2
	JR Z, ExtVoice_Lookup_SlotFallback_Case2
	CP WA, 1
	JR Z, ExtVoice_Lookup_SlotFallback_Case1
	CP WA, 0
	RET NZ
	LD L, (XBC)
	JR T, ExtVoice_Lookup_SlotFallback_Return

ExtVoice_Lookup_SlotFallback_Case1:
	LD L, (XBC + 004h)
	JR T, ExtVoice_Lookup_SlotFallback_Return

ExtVoice_Lookup_SlotFallback_Case2:
	LD L, (XBC + 008h)
	CP L, 0c0h
	RET ULE
	LD L, (XBC + 004h)
	JR T, ExtVoice_Lookup_SlotFallback_Return

ExtVoice_Lookup_SlotFallback_Case3:
	LD L, (XBC + 008h)

ExtVoice_Lookup_SlotFallback_Return:
	RET

; ----------------------------------------------------------------------------
; ExtVoice_Alloc_StreamSlot - allocate a streaming/DMA voice slot (INFERRED)
; Entry: A = part index (must be < 0x1A), C = desc+0x00 (must be < 0x40),
;        E = keyflag / bank-mode byte (masked to 0x3F on entry)
; Exit:  HL = (keyflag << 8) | slot number;  slot 0xFF means allocation failed
; Notes: This is NOT a wave-number resolver, despite its historical role in the
;        notes.  MEASURED (notes/kn5000-pipe-resolver.md): its wave-mapping
;        columns read 0xFF for all 64 tones and all 26 valid rows at runtime, so
;        the lookup always degenerates to the fallback table; and the value the
;        caller ships to register +0x440 increments by exactly 1 per note-on and
;        is INDEPENDENT of pitch (C3/C4/C5 -> 0x40/0x41/0x42).
;        INFERRED that the tables are voice/DMA slot occupancy maps.  Decisive
;        tell: the helpers VoiceState_SwapSlot_Guarded and VoiceSlot_UpdateNoteSource WRITE them, which a ROM
;        lookup table never does, and ExtVoice_SlotPool_Entries has a
;        next/prev/.../slot free-list shape with slot 0xFF meaning free.
;        CORRECTION: A is the PART index - both descriptor builders write the part
;        index into desc+0x04, and the note lives at desc+0x05 | 0x80 - which is
;        what the A < 0x1A bound checks.  kn5000-pipe-resolver.md 2 called it a
;        note and then a key-zone index.
;        Ordinary PCM voices never reach here: their caller gates on
;        tonerec[+0x1A] != 0 or part_state[+0x0A] bit 15, both false, so registers
;        +0x440/+0x480 keep the value 0 that ExtVoice_Build_SlotRegisters wrote.
; ----------------------------------------------------------------------------
ExtVoice_Alloc_StreamSlot:	; 02177Eh
	DEC 8, XSP
	PUSH QIZ
	LD (XSP + 004h), E
	LD (XSP + 006h), C
	LD (XSP + 008h), A
	AND (XSP + 004h), 03fh
	CP (XSP + 006h), 040h
	JR NC, ExtVoice_Alloc_StreamSlot_NoMatch
	CP (XSP + 008h), 01ah
	JR C, ExtVoice_Alloc_StreamSlot_Search

ExtVoice_Alloc_StreamSlot_NoMatch:
	LD A, (XSP + 004h)
	EXTZ WA
	SLL 8, WA
	LD HL, WA
	OR HL, 00ffh
	JRL T, ExtVoice_Alloc_StreamSlot_Return

ExtVoice_Alloc_StreamSlot_Search:
	LD A, (XSP + 004h)
	AND A, 01fh
	EXTZ WA
	LDA XBC, 0F48Ch:24
	LD A, (XBC + WA)
	LD QIZL, A
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 0F4ACh:24
	LD A, (XBC + WA)
	LD (XSP + 002h), A
	LD A, (XSP + 006h)
	EXTZ WA
	MULS_WA 00ch
	LDA XBC, 24E6h
	LDA XBC, XBC + WA
	LD A, QIZL
	EXTZ WA
	INC 8, WA
	LD A, (XBC + WA)
	LD QIZH, A
	CP QIZH, 0c0h
	JR NC, ExtVoice_Alloc_StreamSlot_FallbackFB
	LD A, QIZH
	EXTZ WA
	MULS_WA 005h
	LDA XBC, 2126h
	LDA XBC, XBC + WA
	LD A, (XBC + 002h)
	CP A, (XSP + 008h)
	JR NZ, ExtVoice_Alloc_StreamSlot_FallbackFB
	LD A, (XBC + 003h)
	CP A, (XSP + 002h)
	JR NZ, ExtVoice_Alloc_StreamSlot_FallbackFB
	LD A, QIZH
	LD E, A
	EXTZ DE
	LD A, QIZL
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR ExtVoice_Fold_SlotNumber
	LD C, L
	EXTZ BC
	LD A, (XSP + 004h)
	SET 7, A
	EXTZ WA
	SLL 8, WA
	LD HL, WA
	OR HL, BC
	JRL T, ExtVoice_Alloc_StreamSlot_Return

ExtVoice_Alloc_StreamSlot_FallbackFB:
	BIT 5, (XSP + 004h)
	JR Z, ExtVoice_Alloc_StreamSlot_TryNoteSourceTable
	LD A, QIZL
	EXTZ WA
	CALR ExtVoice_Lookup_SlotFallback
	LD QIZH, L
	LD A, QIZH
	CP A, 0c0h
	JR NC, ExtVoice_Alloc_StreamSlot_FallbackFB_Inactive
	LD A, QIZH
	LD L, A
	EXTZ HL
	LD A, (XSP + 008h)
	LD C, A
	EXTZ BC
	LD A, (XSP + 002h)
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR VoiceSlot_UpdateNoteSource
	LD A, (XSP + 006h)
	LD L, A
	EXTZ HL
	LD A, QIZL
	LD C, A
	EXTZ BC
	LD A, QIZH
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR VoiceState_SwapSlot_Guarded
	LD A, QIZH
	LD E, A
	EXTZ DE
	LD A, QIZL
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR ExtVoice_Fold_SlotNumber
	JRL T, ExtVoice_Alloc_StreamSlot_PackResult

ExtVoice_Alloc_StreamSlot_FallbackFB_Inactive:
	LD_L 0ffh
	JRL T, ExtVoice_Alloc_StreamSlot_PackResult

ExtVoice_Alloc_StreamSlot_TryNoteSourceTable:
	LD A, (XSP + 002h)
	EXTZ WA
	LD DE, WA
	LD A, (XSP + 008h)
	EXTZ WA
	MULS_WA 01bh
	LDA XBC, 1E4Dh
	EXTS XWA
	ADD XWA, XBC
	LD BC, DE
	EXTZ XBC
	ADD XBC, XWA
	LD A, (XBC)
	LD QIZH, A
	CP QIZH, 0c0h
	JR NC, ExtVoice_Alloc_StreamSlot_FallbackFA
	LD A, (XSP + 006h)
	LD L, A
	EXTZ HL
	LD A, QIZL
	LD C, A
	EXTZ BC
	LD A, QIZH
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR VoiceState_SwapSlot_Guarded
	LD A, QIZH
	LD E, A
	EXTZ DE
	LD A, QIZL
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR ExtVoice_Fold_SlotNumber
	SET 7, (XSP + 004h)
	JR T, ExtVoice_Alloc_StreamSlot_PackResult

ExtVoice_Alloc_StreamSlot_FallbackFA:
	LD A, QIZL
	EXTZ WA
	CALR ExtVoice_Lookup_SlotFallback
	LD QIZH, L
	LD A, QIZH
	CP A, 0c0h
	JR NC, ExtVoice_Alloc_StreamSlot_FA_Inactive
	LD A, QIZH
	LD L, A
	EXTZ HL
	LD A, (XSP + 008h)
	LD C, A
	EXTZ BC
	LD A, (XSP + 002h)
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR VoiceSlot_UpdateNoteSource
	LD A, (XSP + 006h)
	LD L, A
	EXTZ HL
	LD A, QIZL
	LD C, A
	EXTZ BC
	LD A, QIZH
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR VoiceState_SwapSlot_Guarded
	LD A, QIZH
	LD E, A
	EXTZ DE
	LD A, QIZL
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR ExtVoice_Fold_SlotNumber
	JR T, ExtVoice_Alloc_StreamSlot_PackResult

ExtVoice_Alloc_StreamSlot_FA_Inactive:
	LD_L 0ffh

ExtVoice_Alloc_StreamSlot_PackResult:
	LD C, L
	EXTZ BC
	LD A, (XSP + 004h)
	EXTZ WA
	SLL 8, WA
	LD HL, WA
	OR HL, BC

ExtVoice_Alloc_StreamSlot_Return:
	POP QIZ
	INC 8, XSP
	RET

