Voice_BuildOutputList:
	LDA XSP, XSP - 12
	PUSH QIZ
	CPL E
	LD (XSP + 008h), E
	AND C, (XSP + 008h)
	LD (XSP + 006h), C
	EXTZ WA
	MULS_WA 01bh
	LDA XBC, 1E4Dh
	EXTS XWA
	ADD XWA, XBC
	LD (XSP + 002h), XWA
	LDA XWA, 27E9h
	LD (XSP + 00ah), XWA
	LD QIZL, 0
	CP QIZL, 01bh
	JR NC, Voice_BuildOutputList_Return

Voice_BuildOutputList_Loop:
	LD A, QIZL
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 002h)
	LD E, (XWA + BC)
	LD A, E
	CP A, 0c0h
	JR NC, Voice_BuildOutputList_Next
	LD A, QIZL
	EXTZ WA
	LDA XBC, 0F4ECh:24
	LD A, (XBC + WA)
	LD QIZH, A
	AND A, (XSP + 008h)
	CP A, (XSP + 006h)
	JR NZ, Voice_BuildOutputList_Next
	LD A, QIZH
	AND A, 01fh
	EXTZ WA
	LDA XBC, 0F48Ch:24
	LD C, (XBC + WA)
	LD A, E
	EXTZ WA
	EXTZ BC
	CALR ExtVoice_Fold_SlotNumber
	LD C, L
	EXTZ BC
	LD A, QIZH
	EXTZ WA
	SLL 8, WA
	LD DE, WA
	OR DE, BC
	LD XWA, (XSP + 00ah)
	LD (XWA+), DE
	LD (XSP + 00ah), XWA

Voice_BuildOutputList_Next:
	INC 1, QIZL
	CP QIZL, 01bh
	JR C, Voice_BuildOutputList_Loop

Voice_BuildOutputList_Return:
	LD XWA, (XSP + 00ah)
	LDW (XWA), 0ffffh
	LDA XHL, 27E9h
	POP QIZ
	LDA XSP, XSP + 00ch
	RET

