Voice_AdvanceSlotIterator:
	DEC 2, XSP
	PUSH XIZ
	LD_C 030h
	MUL BC, A
	LD IZ, BC
	LD (XSP + 004h), IZ
	ADDW (XSP + 004h), 0030h
	CP IZ, (XSP + 004h)
	JR NC, Voice_AdvanceSlotIterator_Return

Voice_AdvanceSlotIterator_Loop:
	LD WA, IZ
	MUL_WA 005h
	LDA XBC, 212Ah
	EXTZ XWA
	ADD XWA, XBC
	CP (XWA), 040h
	JR ULE, Voice_AdvanceSlotIterator_Next
	LD WA, IZ
	MUL_WA 005h
	LDA XBC, 2128h
	EXTZ XWA
	ADD XWA, XBC
	CP (XWA), 01ah
	JR Z, Voice_AdvanceSlotIterator_Next
	LD A, IZL
	EXTZ WA
	LD QIZ, WA
	LD A, IZL
	EXTZ WA
	CALR Quad_Decode_A_To_L
	LD C, L
	EXTZ BC
	LD WA, QIZ
	LD DE, BC
	LD BC, 001ah
	CALR VoiceSlot_UpdateNoteSource

Voice_AdvanceSlotIterator_Next:
	INC 1, IZ
	CP IZ, (XSP + 004h)
	JR C, Voice_AdvanceSlotIterator_Loop

Voice_AdvanceSlotIterator_Return:
	POP XIZ
	INC 2, XSP
	RET

DList_Unlink_SelfLink:
	LD XDE, (XWA)
	LD XBC, (XWA + 004h)
	LD (XBC), XDE
	LD (XDE + 004h), XBC
	LD (XWA), XWA
	LD (XWA + 004h), XWA
	RET

DList_InsertAfter_Offsets0:
	LD XHL, (XWA)
	LD XDE, (XWA + 004h)
	LD (XDE), XHL
	LD (XHL + 004h), XDE
	LD XDE, (XBC + 004h)
	LD (XDE), XWA
	LD (XBC + 004h), XWA
	LD (XWA), XBC
	LD (XWA + 004h), XDE
	RET

; ----------------------------------------------------------------------------
; Voice_List_MoveToPool - Move a voice node between voice-pool priority lists
; Entry: XWA = pointer to the voice node
;        XBC = destination pool block
;        E   = destination priority class (0..6)
; Exit:  none
; Notes: Head address = pool + 0x02 + 4*key, which is exactly the seven dwords
;        Voice_Reset_Engine zeroes in each 0x1E-byte pool block.
;        Unlinks the node from its current (node+0x1d, node+0x21) list using the
;        link pair at node+0x00/+0x04, links it into the destination list, then
;        records node+0x1d = XBC and node+0x21 = E.
; ----------------------------------------------------------------------------
Voice_List_MoveToPool:	; 021C83h
	DEC 6, XSP
	PUSH XIZ
	LD (XSP + 004h), E
	LD (XSP + 006h), XBC
	LD XIZ, XWA
	LD XDE, (XIZ + 01dh)
	LD C, (XIZ + 021h)
	LD A, C
	EXTZ WA
	SLA 2, WA
	INC 2, WA
	CP (XDE + WA), XIZ
	JR NZ, VoiceNode_PriorityList_InsertOrLink
	CP (XIZ), XIZ
	JR Z, VoiceNode_PriorityList_SelfLink
	LD A, C
	EXTZ WA
	SLA 2, WA
	LD BC, WA
	INC 2, BC
	LD XWA, (XIZ)
	LD (XDE + BC), XWA
	JR T, VoiceNode_PriorityList_InsertOrLink

VoiceNode_PriorityList_SelfLink:
	LD A, C
	EXTZ WA
	SLA 2, WA
	LD BC, WA
	INC 2, BC
	LD XWA, 0
	LD (XDE + BC), XWA

VoiceNode_PriorityList_InsertOrLink:
	LD A, (XSP + 004h)
	EXTZ WA
	SLA 2, WA
	LD BC, WA
	INC 2, BC
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + BC)
	OR XWA, XWA
	JR NZ, VoiceNode_PriorityList_Insert
	LD A, (XSP + 004h)
	EXTZ WA
	SLA 2, WA
	LD BC, WA
	INC 2, BC
	LD XWA, (XSP + 006h)
	LD (XWA + BC), XIZ
	LD XWA, XIZ
	CALR DList_Unlink_SelfLink
	JR T, VoiceNode_PriorityList_Return

VoiceNode_PriorityList_Insert:
	LD A, (XSP + 004h)
	EXTZ WA
	SLA 2, WA
	LD DE, WA
	INC 2, DE
	LD XWA, XIZ
	LD XBC, (XSP + 006h)
	LD XBC, (XBC + DE)
	CALR DList_InsertAfter_Offsets0

VoiceNode_PriorityList_Return:
	LD XWA, (XSP + 006h)
	LD (XIZ + 01dh), XWA
	LD A, (XSP + 004h)
	LD (XIZ + 021h), A
	POP XIZ
	INC 6, XSP
	RET

DList_Unlink_SelfLink_Offsets8:
	LD XDE, (XWA + 008h)
	LD XBC, (XWA + 00ch)
	LD (XBC + 008h), XDE
	LD (XDE + 00ch), XBC
	LD (XWA + 008h), XWA
	LD (XWA + 00ch), XWA
	RET

DList_InsertAfter_Offsets8:
	LD XHL, (XWA + 008h)
	LD XDE, (XWA + 00ch)
	LD (XDE + 008h), XHL
	LD (XHL + 00ch), XDE
	LD XDE, (XBC + 00ch)
	LD (XDE + 008h), XWA
	LD (XBC + 00ch), XWA
	LD (XWA + 008h), XBC
	LD (XWA + 00ch), XDE
	RET

; ----------------------------------------------------------------------------
; Voice_List_MoveToPartList - Move a voice node between the per-part allocation lists
; Entry: XWA = pointer to the voice node
;        XBC = destination part-allocation descriptor (0x1349 + p*0x0C)
;        E   = destination list index (0 or 1)
; Exit:  none
; Notes: Head address = descriptor + 0x04 + 4*index.  Uses the SECOND link pair
;        of the node (node+0x08/+0x0C) and records node+0x18 = XBC,
;        node+0x1c = E.  A node is therefore on two lists at once: one keyed by
;        voice pool + priority, one keyed by part.
; ----------------------------------------------------------------------------
Voice_List_MoveToPartList:	; 021D59h
	DEC 6, XSP
	PUSH XIZ
	LD (XSP + 004h), E
	LD (XSP + 006h), XBC
	LD XIZ, XWA
	LD XDE, (XIZ + 018h)
	LD C, (XIZ + 01ch)
	LD A, C
	EXTZ WA
	SLA 2, WA
	INC 4, WA
	CP (XDE + WA), XIZ
	JR NZ, VoiceNode_SecondList_InsertOrLink
	CP (XIZ + 008h), XIZ
	JR Z, VoiceNode_SecondList_SelfLink
	LD A, C
	EXTZ WA
	SLA 2, WA
	LD BC, WA
	INC 4, BC
	LD XWA, (XIZ + 008h)
	LD (XDE + BC), XWA
	JR T, VoiceNode_SecondList_InsertOrLink

VoiceNode_SecondList_SelfLink:
	LD A, C
	EXTZ WA
	SLA 2, WA
	LD BC, WA
	INC 4, BC
	LD XWA, 0
	LD (XDE + BC), XWA

VoiceNode_SecondList_InsertOrLink:
	LD A, (XSP + 004h)
	EXTZ WA
	SLA 2, WA
	LD BC, WA
	INC 4, BC
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + BC)
	OR XWA, XWA
	JR NZ, VoiceNode_SecondList_Insert
	LD A, (XSP + 004h)
	EXTZ WA
	SLA 2, WA
	LD BC, WA
	INC 4, BC
	LD XWA, (XSP + 006h)
	LD (XWA + BC), XIZ
	LD XWA, XIZ
	CALR DList_Unlink_SelfLink_Offsets8
	JR T, VoiceNode_SecondList_Return

VoiceNode_SecondList_Insert:
	LD A, (XSP + 004h)
	EXTZ WA
	SLA 2, WA
	LD DE, WA
	INC 4, DE
	LD XWA, XIZ
	LD XBC, (XSP + 006h)
	LD XBC, (XBC + DE)
	CALR DList_InsertAfter_Offsets8

VoiceNode_SecondList_Return:
	LD XWA, (XSP + 006h)
	LD (XIZ + 018h), XWA
	LD A, (XSP + 004h)
	LD (XIZ + 01ch), A
	POP XIZ
	INC 6, XSP
	RET

; ----------------------------------------------------------------------------
; DList_Unlink_SelfLink_Offsets16 - Unlink a voice node from the third (age) chain
; Entry: XWA = pointer to the voice node
; Exit:  none
; Notes: Operates on the link pair node+0x10 / node+0x14 and leaves the node
;        self-referential.  INFERRED that this chain is the allocation-age order;
;        MEASURED only that it is a third, independent doubly-linked chain.
; ----------------------------------------------------------------------------
DList_Unlink_SelfLink_Offsets16:	; 021E02h
	LD XDE, (XWA + 010h)
	LD XBC, (XWA + 014h)
	LD (XBC + 010h), XDE
	LD (XDE + 014h), XBC
	LD (XWA + 010h), XWA
	LD (XWA + 014h), XWA
	RET

; ----------------------------------------------------------------------------
; DList_Relink_Adjacent_Offsets16 - Move a voice node to the tail of the third (age) chain
; Entry: XWA = pointer to the voice node
;        XBC = chain anchor
; Exit:  none
; Notes: Unlinks node+0x10/+0x14 from its current position and inserts it before
;        XBC.  Same caveat as DList_Unlink_SelfLink_Offsets16.
; ----------------------------------------------------------------------------
DList_Relink_Adjacent_Offsets16:	; 021E15h
	LD XHL, (XWA + 010h)
	LD XDE, (XWA + 014h)
	LD (XDE + 010h), XHL
	LD (XHL + 014h), XDE
	LD XDE, (XBC + 014h)
	LD (XDE + 010h), XWA
	LD (XBC + 014h), XWA
	LD (XWA + 010h), XBC
	LD (XWA + 014h), XDE
	RET

; ----------------------------------------------------------------------------
; Voice_Retire_ToFreePool - Return a voice node to the free pool and update the pool accounting
; Entry: XWA = pointer to the voice node
; Exit:  none
; Notes: No-op if node+0x22 bit0 (already free) is set.  Otherwise:
;          if node.pool(+0x1d).count != 0: count--        <- the OLD pool
;          Voice_List_MoveToPool(node, VOICE_POOL_FREE 0x132B, 6)
;          Voice_List_MoveToPartList(node, VOICE_PARTPOOL_FREE 0x1481, 1)
;          DList_Unlink_SelfLink_Offsets16(node)
;          node+0x22 = 0x01 (FREE), node+0x25 = 0
;          if node.pool(+0x1d).count < node.pool.quota: count++   <- the NEW pool
;        The decrement reads node+0x1d BEFORE the move and the increment AFTER,
;        so together they are a single 'transfer one voice from pool A to pool B'
;        accounting step - which is what proves pool+0x00 = quota and
;        pool+0x01 = current occupancy.
;        0x132B is pool index 17 (0x112D + 17*0x1E) and 0x1481 is part-descriptor
;        index 26 (0x1349 + 26*0x0C): the free lists are the last entry of each
;        array, which is why both quota tables end with two 0x40 entries.
; ----------------------------------------------------------------------------
Voice_Retire_ToFreePool:	; 021E31h
	PUSH XIZ
	LD XIZ, XWA
	BIT 0, (XIZ + 022h)
	JR NZ, Voice_Retire_ToFreePool_Return
	LD XWA, (XIZ + 01dh)
	CP (XWA + 001h), 000h
	JR Z, Voice_Retire_ToFreePool_InsertLists
	LD XWA, (XIZ + 01dh)
	DEC 1, (XWA + 001h)

Voice_Retire_ToFreePool_InsertLists:
	LDA XWA, 132Bh
	LD XBC, XWA
	LD XWA, XIZ
	LD DE, 6
	CALR Voice_List_MoveToPool
	LDA XWA, 1481h
	LD XBC, XWA
	LD XWA, XIZ
	LD DE, 1
	CALR Voice_List_MoveToPartList
	LD XWA, XIZ
	CALR DList_Unlink_SelfLink_Offsets16
	LD (XIZ + 022h), 001h
	LD (XIZ + 025h), 000h
	LD XWA, (XIZ + 01dh)
	LD XBC, XWA
	LD A, (XWA + 001h)
	CP A, (XBC)
	JR NC, Voice_Retire_ToFreePool_Return
	LD XWA, (XIZ + 01dh)
	INC 1, (XWA + 001h)

Voice_Retire_ToFreePool_Return:
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; Voice_Demote_Decayed - Move a decayed voice node to priority class 1 (preferred steal victim)
; Entry: XWA = pointer to the voice node
; Exit:  none
; Notes: No-op if node+0x22 bits 1:0 are already set.  Otherwise clears bits 3:2,
;        sets bit1 and re-files the node into its current pool at priority 6.
;        Called by Voice_Manager_PollBank when the chip reports the voice's
;        envelope level has fallen below 0x80.
; ----------------------------------------------------------------------------
Voice_Demote_Decayed:	; 021E83h
	LD C, (XWA + 022h)
	AND C, 003h
	RET NZ
	AND (XWA + 022h), 0f3h
	SET 1, (XWA + 022h)
	LD XBC, XWA
	LD XDE, (XWA + 01dh)
	LD XWA, XBC
	LD XBC, XDE
	LD DE, 6
	CALR Voice_List_MoveToPool
	RET

; ----------------------------------------------------------------------------
; Voice_Reprioritise - Re-file a voice node after its polled level changed
; Entry: XWA = pointer to the voice node (VOICE_NODE_BASE 0x148D + ch*0x27)
; Exit:  none
; Notes: Returns immediately if node+0x22 bit7 (command-held) is set.
;        If the polled level node+0x25 < 0x80 -> Voice_Demote_Decayed.
;        Otherwise, if node+0x22 bit3 is set, advance the stage flags
;        (RES 3 / SET 2) and re-file the node into its own pool at priority
;        node+0x26 (the per-voice key loaded at allocation).
;        This is the general 'levels changed' service (10 call sites), NOT a
;        note-off command (notes/audit/kn5000-audit-voicelife.md S1.4).
; ----------------------------------------------------------------------------
Voice_Reprioritise:	; 021EA1h
	BIT 7, (XWA + 022h)
	RET NZ
	CP (XWA + 025h), 080h
	JR C, Voice_Demote_Decayed
	BIT 3, (XWA + 022h)
	RET Z
	RES 3, (XWA + 022h)
	SET 2, (XWA + 022h)
	LD C, (XWA + 026h)
	LD E, C
	EXTZ DE
	LD XBC, XWA
	LD XHL, (XWA + 01dh)
	LD XWA, XBC
	LD XBC, XHL
	CALR Voice_List_MoveToPool
	RET

; ----------------------------------------------------------------------------
; Voice_Reset_Engine - Reset the whole voice engine: silence IC303 and rebuild the allocator
; Entry: A = allocation mode (0 = mode A quotas/bindings, non-zero = mode B)
; Exit:  none; all 64 channels silenced and all allocator state reinitialised
; Notes: Seven steps, in order:
;        1. Scan the four words of TONEGEN_ACTIVE_PREV (0x292E).  If ANY bank
;           still shows sounding voices, panic-silence all 64 channels with the
;           pair +0x840 = 0xA200, +0x800 = 0xA280 (Voice_Reset_Engine_PhaseA_Body is that loop's
;           body label, not a separate routine), then write +0x0C0 = 0x0000 and
;           +0x000 = 0x7E00 for all 64.
;        2. Seed the 18 voice pools at 0x112D (stride 0x1E): pool.quota from
;           Voice_Pool_Quota_ModeA / _ModeB, pool.count = 0, and the SEVEN
;           priority-list heads at +0x02 .. +0x1D zeroed.
;        3. Seed the 27 part-allocation descriptors at 0x1349 (stride 0x0C):
;           descriptor.pool from Voice_Part_PoolPtr_ModeA / the 0x00F597 table,
;           and the two list heads at +0x04 / +0x08 zeroed.
;        4. Initialise all 64 voice nodes at 0x148D (stride 0x27): node+0x24 =
;           channel, the three link pairs (+0/+4, +8/+0xC, +0x10/+0x14) made
;           self-referential, node+0x22 = 0, node+0x18 = 0x1349, node+0x1c = 1,
;           node+0x1d = 0x112D, node+0x21 = 6, node+0x25 = 0.
;        5. Retire every node with Voice_Retire_ToFreePool.
;        6. Zero TONEGEN_ACTIVE_PREV (0x292E) and TONEGEN_HOLD_MASK (0x2936).
;        7. Tail call VoiceState_FullReset.
;        Callers: boot (A = 0, asm L38142) and the mode switch Voice_SetPolyphonyMode.
;        CORRECTION: notes/kn5000-envelope-engine.md described this routine as an
;        envelope-state initialiser copying 'seven-stage accumulators'.  The seven
;        dwords it zeroes are the seven PRIORITY-LIST HEADS of a voice pool - see
;        Voice_List_MoveToPool, whose head offset is 2 + 4*key for key 0..6.
; ----------------------------------------------------------------------------
Voice_Reset_Engine:	; 021ECBh
	DEC 4, XSP
	PUSH XIZ
	LD (XSP + 006h), A
	LD (XSP + 004h), 000h
	CP (XSP + 004h), 004h
	JR NC, Voice_Reset_Engine_PhaseA

Voice_Reset_Engine_FindStart:
	LD A, (XSP + 004h)
	EXTZ WA
	ADD WA, WA
	LDA XBC, 292Eh
	CPW (XBC + WA), 0000h
	JR NZ, Voice_Reset_Engine_PhaseA
	INC 1, (XSP + 004h)
	CP (XSP + 004h), 004h
	JR C, Voice_Reset_Engine_FindStart

Voice_Reset_Engine_PhaseA:
	CP (XSP + 004h), 004h
	JR NC, Voice_Reset_Engine_PhaseB
	LD (XSP + 004h), 000h
	CP (XSP + 004h), 040h
	JR NC, Voice_Reset_Engine_PhaseB

Voice_Reset_Engine_PhaseA_Body:
	RES 7, (P6)
	LD A, (XSP + 004h)
	EXTZ WA
	ADD WA, 0840h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a200h
	JR T, Voice_Reset_Engine_PhaseA_Nop

Voice_Reset_Engine_PhaseA_Nop:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD A, (XSP + 004h)
	EXTZ WA
	ADD WA, 0800h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a280h
	JR T, Voice_Reset_Engine_PhaseA_Nop2

Voice_Reset_Engine_PhaseA_Nop2:
	NOP
	NOP
	NOP
	INC 1, (XSP + 004h)
	CP (XSP + 004h), 040h
	JR C, Voice_Reset_Engine_PhaseA_Body

Voice_Reset_Engine_PhaseB:
	CP (XSP + 004h), 004h
	JR NC, Voice_Reset_Engine_PhaseC
	LD (XSP + 004h), 000h
	CP (XSP + 004h), 040h
	JR NC, Voice_Reset_Engine_PhaseC

Voice_Reset_Engine_PhaseB_Body:
	RES 7, (P6)
	LD A, (XSP + 004h)
	ADD A, 0c0h
	EXTZ WA
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0000h
	JR T, Voice_Reset_Engine_PhaseB_Nop

Voice_Reset_Engine_PhaseB_Nop:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD A, (XSP + 004h)
	EXTZ WA
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 7e00h
	JR T, Voice_Reset_Engine_PhaseB_Nop2

Voice_Reset_Engine_PhaseB_Nop2:
	NOP
	NOP
	NOP
	INC 1, (XSP + 004h)
	CP (XSP + 004h), 040h
	JR C, Voice_Reset_Engine_PhaseB_Body

Voice_Reset_Engine_PhaseC:
	LD (XSP + 004h), 000h
	CP (XSP + 004h), 012h
	JRL NC, ChanStruct_Init_Loop

CmdTable_InitEntry_Loop:
	CP (XSP + 006h), 000h
	JR NZ, CmdTable_InitEntry_AltPtr
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 01eh
	LD DE, WA
	LDA XHL, 112Dh
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 0F507h:24
	LD A, (XBC + WA)
	LD (XHL + DE), A
	JR T, CmdTable_InitEntry_ZeroFields

CmdTable_InitEntry_AltPtr:
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 01eh
	LD DE, WA
	LDA XHL, 112Dh
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 0F519h:24
	LD A, (XBC + WA)
	LD (XHL + DE), A

CmdTable_InitEntry_ZeroFields:
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 01eh
	LDA XBC, 112Eh
	LD (XBC + WA), 000h
	LD_E 000h
	CP E, 7
	JR NC, CmdTable_InitEntry_Next

CmdTable_InitEntry_ZeroLoop:
	LD A, E
	EXTZ WA
	SLA 2, WA
	LD HL, WA
	INC 2, HL
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 01eh
	LDA XBC, 112Dh
	LDA XBC, XBC + WA
	LD XWA, 0
	LD (XBC + HL), XWA
	INC 1, E
	CP E, 7
	JR C, CmdTable_InitEntry_ZeroLoop

CmdTable_InitEntry_Next:
	INC 1, (XSP + 004h)
	CP (XSP + 004h), 012h
	JRL C, CmdTable_InitEntry_Loop

ChanStruct_Init_Loop:
	LD (XSP + 004h), 000h
	CP (XSP + 004h), 01bh
	JRL NC, VoiceNode_Init_Loop

ChanStruct_Init_Entry:
	CP (XSP + 006h), 000h
	JR NZ, ChanStruct_Init_Entry_AltPtr
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 00ch
	LD DE, WA
	LDA XHL, 1349h
	LD A, (XSP + 004h)
	EXTZ WA
	SLA 2, WA
	LDA XBC, 0F52Bh:24
	LD XWA, (XBC + WA)
	LD (XHL + DE), XWA
	JR T, ChanStruct_Init_ZeroSub

ChanStruct_Init_Entry_AltPtr:
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 00ch
	LD DE, WA
	LDA XHL, 1349h
	LD A, (XSP + 004h)
	EXTZ WA
	SLA 2, WA
	LDA XBC, 0F597h:24
	LD XWA, (XBC + WA)
	LD (XHL + DE), XWA

ChanStruct_Init_ZeroSub:
	LD_E 000h
	CP E, 2
	JR NC, ChanStruct_Init_Next

ChanStruct_Init_ZeroLoop:
	LD A, E
	EXTZ WA
	SLA 2, WA
	LD HL, WA
	INC 4, HL
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 00ch
	LDA XBC, 1349h
	LDA XBC, XBC + WA
	LD XWA, 0
	LD (XBC + HL), XWA
	INC 1, E
	CP E, 2
	JR C, ChanStruct_Init_ZeroLoop

ChanStruct_Init_Next:
	INC 1, (XSP + 004h)
	CP (XSP + 004h), 01bh
	JRL C, ChanStruct_Init_Entry

VoiceNode_Init_Loop:
	LD (XSP + 004h), 000h
	CP (XSP + 004h), 040h
	JR NC, Voice_Retire_ToFreePool_All

VoiceNode_Init_Body:
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 027h
	LDA XBC, 148Dh
	LDA XIZ, XBC + WA
	LD A, (XSP + 004h)
	LD (XIZ + 024h), A
	LD (XIZ), XIZ
	LD (XIZ + 004h), XIZ
	LD (XIZ + 008h), XIZ
	LD (XIZ + 00ch), XIZ
	LD (XIZ + 010h), XIZ
	LD (XIZ + 014h), XIZ
	LD (XIZ + 022h), 000h
	LDA XWA, 1349h
	LD (XIZ + 018h), XWA
	LD (XIZ + 01ch), 001h
	LDA XWA, 112Dh
	LD (XIZ + 01dh), XWA
	LD (XIZ + 021h), 006h
	LD (XIZ + 025h), 000h
	INC 1, (XSP + 004h)
	CP (XSP + 004h), 040h
	JR C, VoiceNode_Init_Body

Voice_Retire_ToFreePool_All:
	LDA XIZ, 148Dh
	LD (XSP + 004h), 000h
	CP (XSP + 004h), 040h
	JR NC, IntMask_Clear_Loop

Voice_Retire_ToFreePool_All_Loop:
	LD XWA, XIZ
	CALR Voice_Retire_ToFreePool
	LDA XIZ, XIZ + 027h
	INC 1, (XSP + 004h)
	CP (XSP + 004h), 040h
	JR C, Voice_Retire_ToFreePool_All_Loop

IntMask_Clear_Loop:
	LD (XSP + 004h), 000h
	CP (XSP + 004h), 004h
	JR NC, AudioState_Init_Return

IntMask_Clear_Body:
	LD A, (XSP + 004h)
	EXTZ WA
	ADD WA, WA
	LDA XBC, 292Eh
	LDW (XBC + WA), 0000h
	LD A, (XSP + 004h)
	EXTZ WA
	ADD WA, WA
	LDA XBC, 2936h
	LDW (XBC + WA), 0000h
	INC 1, (XSP + 004h)
	CP (XSP + 004h), 004h
	JR C, IntMask_Clear_Body

AudioState_Init_Return:
	CALR VoiceState_FullReset
	POP XIZ
	INC 4, XSP
	RET

; ----------------------------------------------------------------------------
; Voice_Manager_PollBank - Per-tick voice manager: poll one bank of 16 channels and reclaim voices
; Entry: none
; Exit:  none
; Notes: Runs on the path-B half of Audio_Process_Init, one bank per call.
;        b = ++(*VOICE_POLL_BANK 0x1128) & 3
;        now  = ToneGen_Read_Register(b) | TONEGEN_HOLD_MASK[b]
;        edge = (now ^ TONEGEN_ACTIVE_PREV[b]) & TONEGEN_ACTIVE_PREV[b]
;        TONEGEN_ACTIVE_PREV[b] = now
;        For each of the 16 channels ch = 16b + i:
;          edge bit i set and node+0x22 bit0 clear (voice not already free) ->
;              Voice_Retire_ToFreePool, ToneGen_SilenceChannel(ch),
;              Voice_ScanSlots_ReassignSources(ch)     <- the 'was sounding, now silent' teardown
;          else, when node+0x22 & 0x81 == 0 ->
;              node+0x25 = (read(0x0180+ch) & 0x3FFF) >> 5   (bits 12:5)
;              if node+0x25 < 0x80 and node+0x22 bit2: Voice_Demote_Decayed
;        Finishes with Voice_AdvanceSlotIterator(b).
;        MEASURED: the chip's own active bitmap is the SOLE trigger for reclaim;
;        a captured 0x7E00 teardown followed a status read returning 0 by 56 us
;        (notes/audit/kn5000-audit-voicelife.md S1.5).
;        Voice_Manager_PollBank_SlotLoop is this routine's per-channel loop body, not an entry.
;        ToneGen_Read_Register (asm L11479) writes the 0x100000 register-address
;        latch and reads 0x100000 back; it is the only IC303 readback in the payload.
; ----------------------------------------------------------------------------
Voice_Manager_PollBank:	; 02219Fh
	DEC 6, XSP
	PUSH XIZ
	INC 1, (1128h)
	AND (1128h), 003h
	LD A, (1128h)
	EXTZ WA
	CALR ToneGen_Read_Register
	LD A, (1128h)
	EXTZ WA
	ADD WA, WA
	LDA XBC, 2936h
	LD DE, (XBC + WA)
	OR DE, HL
	LD A, (1128h)
	EXTZ WA
	LD HL, WA
	ADD HL, HL
	LDA XIX, 292Eh
	LD A, (1128h)
	EXTZ WA
	ADD WA, WA
	LDA XBC, 292Eh
	LD (XSP + 004h), DE
	LD WA, (XBC + WA)
	XOR (XSP + 004h), WA
	LD WA, (XIX + HL)
	AND (XSP + 004h), WA
	LD A, (1128h)
	EXTZ WA
	ADD WA, WA
	LDA XBC, 292Eh
	LD (XBC + WA), DE
	LD A, (1128h)
	SLL 4, A
	LD (XSP + 008h), A
	EXTZ WA
	MULS_WA 027h
	LDA XBC, 148Dh
	LDA XIZ, XBC + WA
	LDW (XSP + 006h), 0001h
	CPW (XSP + 006h), 0000h
	JR Z, Voice_Manager_PollBank_Return

Voice_Manager_PollBank_SlotLoop:
	LD WA, (XSP + 004h)
	AND WA, (XSP + 006h)
	JR Z, Voice_Manager_PollBank_DecayCheck
	BIT 0, (XIZ + 022h)
	JR NZ, Voice_Manager_PollBank_DecayCheck
	LD XWA, XIZ
	CALR Voice_Retire_ToFreePool
	LD A, (XSP + 008h)
	EXTZ WA
	CALL ToneGen_SilenceChannel
	LD A, (XSP + 008h)
	EXTZ WA
	CALR Voice_ScanSlots_ReassignSources
	JR T, Voice_Manager_PollBank_Next

Voice_Manager_PollBank_DecayCheck:
	LD A, (XIZ + 022h)
	AND A, 081h
	JR NZ, Voice_Manager_PollBank_Next
	LD A, (XSP + 008h)
	EXTZ WA
	ADD WA, 0180h
	CALR ToneGen_Read_Register
	AND HL, 3fffh
	SRL 5, HL
	LD A, L
	LD (XIZ + 025h), A
	CP (XIZ + 025h), 080h
	JR NC, Voice_Manager_PollBank_Next
	BIT 2, (XIZ + 022h)
	JR Z, Voice_Manager_PollBank_Next
	LD XWA, XIZ
	CALR Voice_Demote_Decayed

Voice_Manager_PollBank_Next:
	INC 1, (XSP + 008h)
	LDA XIZ, XIZ + 027h
	LD WA, (XSP + 006h)
	ADD (XSP + 006h), WA
	JR NZ, Voice_Manager_PollBank_SlotLoop

Voice_Manager_PollBank_Return:
	LD A, (1128h)
	EXTZ WA
	CALR Voice_AdvanceSlotIterator
	POP XIZ
	INC 6, XSP
	RET

; ----------------------------------------------------------------------------
; Voice_Find_Candidate - Pick the voice node to (re)use for a new note
; Entry: XWA = part-allocation descriptor (0x1349 + p*0x0C)
;        XBC = priority-order byte list, terminated by 0xFF
; Exit:  XHL = the chosen node, or 0 when nothing is available
; Notes: If the override word at 0x1345 is non-zero it is returned unchanged.
;        Otherwise each byte b of the order list is tried in turn: bit7 set means
;        'look in the GLOBAL pool' (pool index 16, head array 0x130F) at class
;        b & 0x7F, bit7 clear means 'look in this part's own pool' at class b.
;        The first non-empty list head wins - so the byte list IS the stealing
;        policy.  MEASURED (asm); the musical ordering it encodes is INFERRED.
; ----------------------------------------------------------------------------
Voice_Find_Candidate:	; 02229Ah
	LD XDE, (1345h)
	OR XDE, XDE
	JR Z, Voice_Find_Candidate_Walk
	LD XHL, (1345h)
	RET

Voice_Find_Candidate_Walk:
	LDA XDE, 112Dh
	LDA XDE, XDE + 01e2h
	LD XWA, (XWA)
	LDA XHL, XWA + 002h
	CP (XBC), 0ffh
	JR Z, NoteChain_FindNode_NotFound

Voice_Find_Candidate_Secondary:
	BIT 7, (XBC)
	JR Z, Voice_Find_Candidate_Primary
	LD A, (XBC)
	RES 7, A
	LD IXL, A
	EXTZ WA
	SLA 2, WA
	LD XWA, (XDE + WA)
	OR XWA, XWA
	JR Z, Voice_Find_Candidate_Advance
	LD A, IXL
	EXTZ WA
	SLA 2, WA
	LD XHL, (XDE + WA)
	RET

Voice_Find_Candidate_Primary:
	LD A, (XBC)
	EXTZ WA
	SLA 2, WA
	LD XWA, (XHL + WA)
	OR XWA, XWA
	JR Z, Voice_Find_Candidate_Advance
	LD A, (XBC)
	EXTZ WA
	SLA 2, WA
	LD XHL, (XHL + WA)
	RET

Voice_Find_Candidate_Advance:
	INC 1, XBC
	CP (XBC), 0ffh
	JR NZ, Voice_Find_Candidate_Secondary

NoteChain_FindNode_NotFound:
	LD XHL, 0
	RET

NoteChain_FindNode_B:
	INC 2, XWA
	LD XDE, XWA
	LDA XWA, 0F603h:24
	LD XBC, XWA
	CP (XBC), 0ffh
	JR Z, NoteChain_FindNode_B_NotFound

NoteChain_FindNode_B_Walk:
	LD A, (XBC)
	EXTZ WA
	SLA 2, WA
	LD XWA, (XDE + WA)
	OR XWA, XWA
	JR Z, NoteChain_FindNode_B_Advance
	LD A, (XBC)
	EXTZ WA
	SLA 2, WA
	LD XHL, (XDE + WA)
	RET

NoteChain_FindNode_B_Advance:
	INC 1, XBC
	CP (XBC), 0ffh
	JR NZ, NoteChain_FindNode_B_Walk

NoteChain_FindNode_B_NotFound:
	LD XHL, 0
	RET

; ----------------------------------------------------------------------------
; Voice_Allocate_Nodes - Allocate and bind voice nodes for one note-on command
; Entry: XWA = pointer to the note-on command block
; Exit:  none; up to four voice nodes are bound to the note
; Notes: part = (cmd[0] & 0x1F00) >> 8, must be < 0x1A (26); the part's
;        allocation descriptor is VOICE_PARTPOOL_BASE 0x1349 + part*0x0C.
;        For each of the four partial slots whose cmd[2+i] bit7 is set:
;          class descriptor = 0x00F633 + (cmd[2+i] & 0x0F)*6
;              {+0 = pointer to a priority-order byte list, +4 = pool list key,
;               +5 = the per-voice priority stored in node+0x26}
;          node = Voice_Find_Candidate(descriptor, order list)
;          old pool.count--
;          node+0x23 = key (cmd[0] & 0x7F), node+0x25 = 0xFF, node+0x26 = tbl+5
;          node+0x22 = 0x88 and TONEGEN_HOLD_MASK bit SET   (command-held voice)
;             or node+0x22 = 0x08, HOLD bit CLEARED and TONEGEN_ACTIVE_PREV bit
;             SET (an ordinary voice, whose lifetime the chip then owns)
;          Voice_List_MoveToPool(node, descriptor.pool, tbl+4)
;          Voice_List_MoveToPartList(node, descriptor, 0)
;        Touches no IC303 register: allocation is pure firmware-side list surgery
;        (notes/audit/kn5000-audit-voicelife.md S1.7, S4.5).
; ----------------------------------------------------------------------------
Voice_Allocate_Nodes:	; 022340h
	LDA XSP, XSP - 010h
	PUSH XIZ
	LD (XSP + 010h), XWA
	LD XWA, (XSP + 010h)
	BIT 6, (XWA + 006h)
	JR NZ, Voice_Allocate_Nodes_SlotLoop
	LD XWA, 0
	LD (1129h), XWA

Voice_Allocate_Nodes_SlotLoop:
	LD XWA, (XSP + 010h)
	LD WA, (XWA)
	AND WA, 1f00h
	SRL 8, WA
	LD QIZH, A
	CP QIZH, 01ah
	JRL NC, Voice_Allocate_Nodes_AllInactive
	LD XWA, (XSP + 010h)
	CALR RingBuf_CheckOffset_ClearFlags
	LD A, QIZH
	EXTZ WA
	MULS_WA 00ch
	LDA XBC, 1349h
	EXTS XWA
	ADD XWA, XBC
	LD (XSP + 004h), XWA
	LD (XSP + 00ch), 000h
	CP (XSP + 00ch), 004h
	JRL NC, Voice_Allocate_Nodes_Return

Voice_Allocate_Nodes_ProcessSlot:
	LD A, (XSP + 00ch)
	EXTZ WA
	LD BC, WA
	INC 2, BC
	LD XWA, (XSP + 010h)
	BIT 7, (XWA + BC)
	JRL Z, Voice_Allocate_Nodes_SlotInactive
	LD A, (XSP + 00ch)
	EXTZ WA
	LD BC, WA
	INC 2, BC
	LD XWA, (XSP + 010h)
	LD A, (XWA + BC)
	AND A, 00fh
	EXTZ WA
	MULS_WA 006h
	LDA XBC, 0F633h:24
	EXTS XWA
	ADD XWA, XBC
	LD (XSP + 008h), XWA
	LD XBC, (XWA)
	LD XWA, (XSP + 004h)
	CALR Voice_Find_Candidate
	LD XIZ, XHL
	LD XWA, XIZ
	OR XWA, XWA
	JRL Z, Voice_Allocate_Nodes_SlotNoNode
	LD A, (XIZ + 024h)
	LD (XSP + 00eh), A
	LD XWA, (XIZ + 01dh)
	CP (XWA + 001h), 000h
	JR Z, Voice_Allocate_Nodes_ActivateNode
	LD XWA, (XIZ + 01dh)
	DEC 1, (XWA + 001h)

Voice_Allocate_Nodes_ActivateNode:
	LD XWA, (XSP + 010h)
	LD WA, (XWA)
	AND WA, 007fh
	LD (XIZ + 023h), A
	LD (XIZ + 025h), 0ffh
	LD XWA, (XSP + 008h)
	LD A, (XWA + 005h)
	LD (XIZ + 026h), A
	LD A, (XSP + 00ch)
	EXTZ WA
	LD BC, WA
	INC 6, BC
	LD XWA, (XSP + 010h)
	BIT 7, (XWA + BC)
	JR Z, Voice_Allocate_Nodes_Retrigger
	LD (XIZ + 022h), 088h
	LD A, (XSP + 00eh)
	AND A, 00fh
	LD DE, 1
	AND A, 00fh
	JR Z, Voice_Allocate_Nodes_RetriggerActive
	SLL A, DE

Voice_Allocate_Nodes_RetriggerActive:
	LD A, (XSP + 00eh)
	SRL 4, A
	EXTZ WA
	ADD WA, WA
	LDA XBC, 2936h
	OR (XBC + WA), DE
	JR T, Voice_Allocate_Nodes_UpdateLists

Voice_Allocate_Nodes_Retrigger:
	LD (XIZ + 022h), 008h
	LD A, (XSP + 00eh)
	AND A, 00fh
	LD BC, 1
	AND A, 00fh
	JR Z, Voice_Allocate_Nodes_RetriggerMask
	SLL A, BC

Voice_Allocate_Nodes_RetriggerMask:
	LD WA, BC
	CPL WA
	LD DE, WA
	LD A, (XSP + 00eh)
	SRL 4, A
	EXTZ WA
	ADD WA, WA
	LDA XBC, 2936h
	AND (XBC + WA), DE
	LD A, (XSP + 00eh)
	AND A, 00fh
	LD DE, 1
	AND A, 00fh
	JR Z, Voice_Allocate_Nodes_RetriggerOrMask
	SLL A, DE

Voice_Allocate_Nodes_RetriggerOrMask:
	LD A, (XSP + 00eh)
	SRL 4, A
	EXTZ WA
	ADD WA, WA
	LDA XBC, 292Eh
	OR (XBC + WA), DE

Voice_Allocate_Nodes_UpdateLists:
	LD XWA, (XSP + 008h)
	LD E, (XWA + 004h)
	LD XWA, XIZ
	LD XBC, (XSP + 004h)
	LD XBC, (XBC)
	CALR Voice_List_MoveToPool
	LD XWA, XIZ
	LD XBC, (XSP + 004h)
	LD DE, 0
	CALR Voice_List_MoveToPartList
	LD XWA, (1129h)
	OR XWA, XWA
	JR Z, Voice_Allocate_Nodes_SetGlobalHead
	LD XWA, XIZ
	LD XBC, (1129h)
	CALR DList_Relink_Adjacent_Offsets16
	JR T, Voice_Allocate_Nodes_AdvancePriority

Voice_Allocate_Nodes_SetGlobalHead:
	LD (1129h), XIZ
	LD XWA, XIZ
	CALR DList_Unlink_SelfLink_Offsets16

Voice_Allocate_Nodes_AdvancePriority:
	LD XWA, (XIZ + 01dh)
	LD XBC, XWA
	LD A, (XWA + 001h)
	CP A, (XBC)
	JR NC, Voice_Allocate_Nodes_WalkNext
	LD XWA, (XIZ + 01dh)
	INC 1, (XWA + 001h)
	JR T, Voice_Allocate_Nodes_WriteSlot

Voice_Allocate_Nodes_WalkNext:
	LD XWA, (XIZ + 01dh)
	CALR NoteChain_FindNode_B
	LD XIZ, XHL
	LD XWA, XIZ
	OR XWA, XWA
	JR Z, Voice_Allocate_Nodes_WriteSlot
	LDA XWA, 130Dh
	LD XBC, XWA
	LD A, (XIZ + 021h)
	LD E, A
	EXTZ DE
	LD XWA, XIZ
	CALR Voice_List_MoveToPool
	LD XWA, (XIZ + 01dh)
	INC 1, (XWA + 001h)
	SET 4, (XIZ + 022h)

Voice_Allocate_Nodes_WriteSlot:
	LD A, (XSP + 00eh)
	EXTZ WA
	CALR Voice_ScanSlots_ReassignSources
	LD A, (XSP + 00ch)
	EXTZ WA
	LD DE, WA
	ADD DE, 000ah
	LD XWA, (XSP + 010h)
	LD C, (XSP + 00eh)
	LD (XWA + DE), C
	JR T, Voice_Allocate_Nodes_SlotNext

Voice_Allocate_Nodes_SlotNoNode:
	LD A, (XSP + 00ch)
	EXTZ WA
	LD BC, WA
	ADD BC, 000ah
	LD XWA, (XSP + 010h)
	LD (XWA + BC), 0ffh
	JR T, Voice_Allocate_Nodes_SlotNext

Voice_Allocate_Nodes_SlotInactive:
	LD A, (XSP + 00ch)
	EXTZ WA
	LD BC, WA
	ADD BC, 000ah
	LD XWA, (XSP + 010h)
	LD (XWA + BC), 0ffh

Voice_Allocate_Nodes_SlotNext:
	INC 1, (XSP + 00ch)
	CP (XSP + 00ch), 004h
	JRL C, Voice_Allocate_Nodes_ProcessSlot
	JR T, Voice_Allocate_Nodes_Return

Voice_Allocate_Nodes_AllInactive:
	LD (XSP + 00ch), 000h
	CP (XSP + 00ch), 004h
	JR NC, Voice_Allocate_Nodes_Return

Voice_Allocate_Nodes_AllInactive_Loop:
	LD A, (XSP + 00ch)
	EXTZ WA
	LD BC, WA
	ADD BC, 000ah
	LD XWA, (XSP + 010h)
	LD (XWA + BC), 0ffh
	INC 1, (XSP + 00ch)
	CP (XSP + 00ch), 004h
	JR C, Voice_Allocate_Nodes_AllInactive_Loop

Voice_Allocate_Nodes_Return:
	POP XIZ
	LDA XSP, XSP + 010h
	RET

; ----------------------------------------------------------------------------
; Voice_Clear_HoldBit - Drop a channel's software keep-alive and re-evaluate its priority
; Entry: A = channel number (0..63)
; Exit:  falls through into Voice_Reprioritise with XWA = the node
; Notes: node+0x22 bit7 cleared, then TONEGEN_HOLD_MASK[ch >> 4] &= ~(1 << (ch & 15)).
;        TONEGEN_HOLD_MASK (0x2936) is ORed into the chip's active bitmap by
;        Voice_Manager_PollBank, so while a channel's bit is set the voice can
;        never be reclaimed however quiet the chip says it is.  Clearing it hands
;        the voice's remaining lifetime back to the chip.
;        Tail-calls Voice_Reprioritise (JRL T) with XWA = 0x148D + ch*0x27.
; ----------------------------------------------------------------------------
Voice_Clear_HoldBit:	; 022587h
	LD C, A
	LD A, C
	EXTZ WA
	MULS_WA 027h
	LDA XDE, 14AFh
	RES 7, (XDE + WA)
	LD A, C
	AND A, 00fh
	LD DE, 1
	AND A, 00fh
	JR Z, Voice_Clear_HoldBit_ApplyMask
	SLL A, DE

Voice_Clear_HoldBit_ApplyMask:
	LD WA, DE
	CPL WA
	LD HL, WA
	LD A, C
	SRL 4, A
	EXTZ WA
	ADD WA, WA
	LDA XDE, 2936h
	AND (XDE + WA), HL
	LD A, C
	EXTZ WA
	MULS_WA 027h
	LDA XBC, 148Dh
	EXTS XWA
	ADD XWA, XBC
	JRL T, Voice_Reprioritise

VoiceSlot_NoteOff:
	PUSH XIZ
	CP A, 040h
	JR NC, VoiceSlot_NoteOff_Return
	EXTZ WA
	MULS_WA 027h
	LDA XBC, 148Dh
	LDA XIZ, XBC + WA
	LD XWA, XIZ
	LD XBC, (XIZ + 018h)
	LD DE, 1
	CALR Voice_List_MoveToPartList
	LD XWA, XIZ
	CALR Voice_Reprioritise
	CP XIZ, (XIZ + 010h)
	JR Z, VoiceSlot_NoteOff_Return
	LD XWA, XIZ
	CALR DList_Unlink_SelfLink_Offsets16

VoiceSlot_NoteOff_Return:
	POP XIZ
	RET

OutputBuf_Flush_A:
	LD XHL, XBC
	OR XHL, XHL
	JR Z, OutputBuf_Flush_A_Done
	LD XIY, XHL

OutputBuf_Flush_A_Loop:
	CP (XSP + 004h), 000h
	JR NZ, OutputBuf_Flush_A_Emit
	CP (XIY + 023h), E
	JR NZ, OutputBuf_Flush_A_Next

OutputBuf_Flush_A_Emit:
	LD XIX, (XWA)
	LD C, (XIY + 024h)
	LD (XIX), C
	LD XBC, 1
	ADD (XWA), XBC

OutputBuf_Flush_A_Next:
	LD XIY, (XIY + 008h)
	CP XIY, XHL
	JR NZ, OutputBuf_Flush_A_Loop

OutputBuf_Flush_A_Done:
	LD XWA, (XWA)
	LD (XWA), 0ffh
	RETD 0002h

OutputBuf_Flush_B:
	DEC 8, XSP
	PUSH XIZ
	LD (XSP + 008h), XWA
	OR XBC, XBC
	JR Z, OutputBuf_Flush_B_Done
	LD XIZ, XBC

OutputBuf_Flush_B_Loop:
	CP (XSP + 010h), 000h
	JR NZ, OutputBuf_Flush_B_Emit
	CP (XIZ + 023h), E
	JR NZ, OutputBuf_Flush_B_Next

OutputBuf_Flush_B_Emit:
	LD XWA, XIZ
	LD XBC, (XIZ + 018h)
	LD DE, 1
	CALR Voice_List_MoveToPartList
	LD XWA, XIZ
	CALR Voice_Reprioritise
	LD XWA, (XSP + 008h)
	LD XBC, (XWA)
	LD A, (XIZ + 024h)
	LD (XBC), A
	LD XWA, (XSP + 008h)
	LD XBC, 1
	ADD (XWA), XBC
	CP XIZ, (XIZ + 010h)
	JR Z, OutputBuf_Flush_B_Done
	LD XWA, (XIZ + 010h)
	LD (XSP + 004h), XWA
	LD XWA, XIZ
	CALR DList_Unlink_SelfLink_Offsets16
	LD XIZ, (XSP + 004h)
	JR T, OutputBuf_Flush_B_Emit

OutputBuf_Flush_B_Next:
	LD XIZ, (XIZ + 008h)
	CP XIZ, XBC
	JR NZ, OutputBuf_Flush_B_Loop

OutputBuf_Flush_B_Done:
	LD XWA, (XSP + 008h)
	LD XWA, (XWA)
	LD (XWA), 0ffh
	POP XIZ
	INC 8, XSP
	RETD 0002h

NoteOn_RoutePacket:
	LDA XSP, XSP - 010h
	PUSH XIZ
	LD BC, (XWA + 003h)
	AND BC, 007fh
	LD (XSP + 00eh), C
	LD BC, (XWA + 001h)
	AND BC, 007fh
	LD (XSP + 00ch), C
	LDA XBC, XWA + 005h
	LD (XSP + 010h), XBC
	LD BC, (XWA + 003h)
	AND BC, 1f00h
	JR Z, NoteOn_RoutePacket_Targeted
	LDA XIZ, 148Dh
	LD_E 000h
	CP E, 040h
	JR NC, NoteOn_RoutePacket_BroadcastDone

NoteOn_RoutePacket_BroadcastLoop:
	BIT 0, (XIZ + 022h)
	JR NZ, NoteOn_RoutePacket_BroadcastNext
	LD XBC, (XSP + 010h)
	LD XWA, 1
	ADD (XSP + 010h), XWA
	LD A, (XIZ + 024h)
	LD (XBC), A

NoteOn_RoutePacket_BroadcastNext:
	LDA XIZ, XIZ + 027h
	INC 1, E
	CP E, 040h
	JR C, NoteOn_RoutePacket_BroadcastLoop

NoteOn_RoutePacket_BroadcastDone:
	LD XWA, (XSP + 010h)
	LD (XWA), 0ffh
	JRL T, NoteOn_RoutePacket_Return

NoteOn_RoutePacket_Targeted:
	LD BC, (XWA + 001h)
	AND BC, 1f00h
	SRL 8, BC
	LD L, C
	EXTZ BC
	MULS_BC 000ch
	LDA XDE, 134Dh
	EXTS XBC
	ADD XBC, XDE
	LD (XSP + 004h), XBC
	LD C, L
	EXTZ BC
	MULS_BC 000ch
	LDA XDE, 1351h
	EXTS XBC
	ADD XBC, XDE
	LD (XSP + 008h), XBC
	CP L, 01ah
	JRL NC, NoteOn_RoutePacket_InvalidChannel
	BIT 7, (XWA)
	JR Z, NoteOn_RoutePacket_Targeted_SecondaryOnly
	LD WA, (XWA + 003h)
	AND WA, 007fh
	JR Z, NoteOn_RoutePacket_Targeted_NoteZero
	LD XWA, (XSP + 004h)
	LD XWA, (XWA)
	OR XWA, XWA
	JR Z, NoteOn_RoutePacket_Targeted_Done
	LD XWA, (XSP + 004h)
	LD XIZ, (XWA)

NoteOn_RoutePacket_Targeted_Loop:
	LD A, (XSP + 00ch)
	LD E, A
	EXTZ DE
	LD A, (XSP + 00eh)
	EXTZ WA
	PUSH WA
	LDA XWA, XSP + 012h
	LD XBC, (XSP + 006h)
	LD XBC, (XBC)
	CALR OutputBuf_Flush_B
	LD XWA, (XSP + 004h)
	LD XWA, (XWA)
	OR XWA, XWA
	JR Z, NoteOn_RoutePacket_Targeted_Done
	LD XWA, (XSP + 004h)
	CP (XWA), XIZ
	JR NZ, NoteOn_RoutePacket_Targeted_Loop

NoteOn_RoutePacket_Targeted_Done:
	LD XWA, (XSP + 010h)
	LD (XWA), 0ffh
	JRL T, NoteOn_RoutePacket_Return

NoteOn_RoutePacket_Targeted_NoteZero:
	LD A, (XSP + 00ch)
	LD E, A
	EXTZ DE
	LD A, (XSP + 00eh)
	EXTZ WA
	PUSH WA
	LDA XWA, XSP + 012h
	LD XBC, (XSP + 006h)
	LD XBC, (XBC)
	CALR OutputBuf_Flush_B
	JRL T, NoteOn_RoutePacket_Return

NoteOn_RoutePacket_Targeted_SecondaryOnly:
	BIT 6, (XWA)
	JR Z, NoteOn_RoutePacket_Targeted_BothLists_BitB
	LD A, (XSP + 00ch)
	LD E, A
	EXTZ DE
	LD A, (XSP + 00eh)
	EXTZ WA
	PUSH WA
	LDA XWA, XSP + 012h
	LD XBC, (XSP + 00ah)
	LD XBC, (XBC)
	CALR OutputBuf_Flush_A
	JR T, NoteOn_RoutePacket_Return

NoteOn_RoutePacket_Targeted_BothLists_BitB:
	LD BC, (XWA + 003h)
	BIT 7, BC
	JR Z, NoteOn_RoutePacket_Targeted_PrimaryOnly_BitA
	LD A, (XSP + 00ch)
	LD E, A
	EXTZ DE
	LD A, (XSP + 00eh)
	EXTZ WA
	PUSH WA
	LDA XWA, XSP + 012h
	LD XBC, (XSP + 006h)
	LD XBC, (XBC)
	CALR OutputBuf_Flush_A
	LD A, (XSP + 00ch)
	LD E, A
	EXTZ DE
	LD A, (XSP + 00eh)
	EXTZ WA
	PUSH WA
	LDA XWA, XSP + 012h
	LD XBC, (XSP + 00ah)
	LD XBC, (XBC)
	CALR OutputBuf_Flush_A
	JR T, NoteOn_RoutePacket_Return

NoteOn_RoutePacket_Targeted_PrimaryOnly_BitA:
	LD WA, (XWA + 001h)
	BIT 7, WA
	JR Z, NoteOn_RoutePacket_Targeted_SecondaryOnly_B
	LD A, (XSP + 00ch)
	LD E, A
	EXTZ DE
	LD A, (XSP + 00eh)
	EXTZ WA
	PUSH WA
	LDA XWA, XSP + 012h
	LD XBC, (XSP + 006h)
	LD XBC, (XBC)
	CALR OutputBuf_Flush_A
	JR T, NoteOn_RoutePacket_Return

NoteOn_RoutePacket_Targeted_SecondaryOnly_B:
	LD A, (XSP + 00ch)
	LD E, A
	EXTZ DE
	LD A, (XSP + 00eh)
	EXTZ WA
	PUSH WA
	LDA XWA, XSP + 012h
	LD XBC, (XSP + 00ah)
	LD XBC, (XBC)
	CALR OutputBuf_Flush_A
	JR T, NoteOn_RoutePacket_Return

NoteOn_RoutePacket_InvalidChannel:
	LD XWA, (XSP + 010h)
	LD (XWA), 0ffh

NoteOn_RoutePacket_Return:
	POP XIZ
	LDA XSP, XSP + 010h
	RET

; ----------------------------------------------------------------------------
; Velocity_Select_Split_Zone - pick the velocity layer q from a 3-byte split record
; Entry: A = note velocity, XBC = velocity-split record (3 split bytes)
; Exit:  L = q, 0..3.  q = 0 is the SOFTEST layer
; Notes: v = A & 0x7F; q = 0 if v <= rec[0], 1 if v <= rec[1], 2 if v <= rec[2],
;        else 3.  The chosen q indexes the pre-computed 4-entry SET-descriptor array
;        at part_struct + 0x76 + 0x25*slot + 4*q (see WaveSel_Cache_SetDescPtr), so
;        velocity selects a DIFFERENT SAMPLE, not merely a level.  MEASURED:
;        notes/kn5000-variant-model.md 3.1/3.2.
; ----------------------------------------------------------------------------
Velocity_Select_Split_Zone:		; 022824h
	RES 7, A
	CP A, (XBC)
	JR ULE, Velocity_Select_Split_Zone_Level0
	CP A, (XBC + 001h)
	JR ULE, Velocity_Select_Split_Zone_Level1
	CP A, (XBC + 002h)
	JR ULE, Velocity_Select_Split_Zone_Level2
	LD_L 003h
	JR T, Velocity_Select_Split_Zone_Return

Velocity_Select_Split_Zone_Level2:
	LD_L 002h
	JR T, Velocity_Select_Split_Zone_Return

Velocity_Select_Split_Zone_Level1:
	LD_L 001h
	JR T, Velocity_Select_Split_Zone_Return

Velocity_Select_Split_Zone_Level0:
	LD_L 000h

Velocity_Select_Split_Zone_Return:
	RET

; ----------------------------------------------------------------------------
; Velocity_Select_Split_Zone_Alt - byte-identical twin of Velocity_Select_Split_Zone
; Entry: A = note velocity, XBC = velocity-split record
; Exit:  L = q, 0..3
; Notes: Same code, separate entry point used by the other note-on chains.  MEASURED.
; ----------------------------------------------------------------------------
Velocity_Select_Split_Zone_Alt:		; 022844h
	RES 7, A
	CP A, (XBC)
	JR ULE, Velocity_Select_Split_Zone_Alt_Level0
	CP A, (XBC + 001h)
	JR ULE, Velocity_Select_Split_Zone_Alt_Level1
	CP A, (XBC + 002h)
	JR ULE, Velocity_Select_Split_Zone_Alt_Level2
	LD_L 003h
	JR T, Velocity_Select_Split_Zone_Alt_Return

Velocity_Select_Split_Zone_Alt_Level2:
	LD_L 002h
	JR T, Velocity_Select_Split_Zone_Alt_Return

Velocity_Select_Split_Zone_Alt_Level1:
	LD_L 001h
	JR T, Velocity_Select_Split_Zone_Alt_Return

Velocity_Select_Split_Zone_Alt_Level0:
	LD_L 000h

Velocity_Select_Split_Zone_Alt_Return:
	RET

VoiceDispatch_OpaqueData:
	db 0D8h, 012h, 0D8h, 009h, 047h, 000h, 0F2h, 08Fh
	db 030h, 004h, 031h, 0D3h, 007h, 0E4h, 0E0h, 020h
	db 0D8h, 0CCh, 0C0h, 000h, 0D8h, 0CFh, 0C0h, 000h
	db 066h, 01Ch, 0D8h, 0CFh, 080h, 000h, 066h, 012h
	db 0D8h, 0CFh, 040h, 000h, 066h, 008h, 0D8h, 0D8h
	db 0B0h, 0FEh, 027h, 000h, 068h, 00Ah, 027h, 001h
	db 068h, 006h, 027h, 002h, 068h, 002h, 027h, 003h
	db 00Eh

Instrument_LookupProgram_HiNibble:
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 04136Eh
	LD XBC, (XDE + BC)
	LD C, (XBC + 02ah)
	AND C, 0f0h
	SRL 4, C
	EXTZ WA
	MULS_WA 011fh
	LD DE, WA
	LDA XHL, 0413D5h
	LD A, C
	EXTZ WA
	LDA XBC, 011ACFh
	LD A, (XBC + WA)
	LD (XHL + DE), A
	RET

Instrument_LookupProgram_LoNibble:
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 04136Eh
	LD XBC, (XDE + BC)
	LD C, (XBC + 02ah)
	AND C, 00fh
	EXTZ WA
	MULS_WA 011fh
	LD DE, WA
	LDA XHL, 0413D5h
	LD A, C
	EXTZ WA
	LDA XBC, 011ACFh
	LD A, (XBC + WA)
	LD (XHL + DE), A
	RET

BitTest_Bit0_L:
	BIT 0, A
	JR Z, BitTest_Bit0_L_Clear
	LD_L 001h
	RET

BitTest_Bit0_L_Clear:
	LD_L 000h
	RET

BitTest_Mode2_L:
	BIT 1, A
	JR Z, BitTest_Mode2_L_Bit1Clear
	LD_L 000h
	RET

BitTest_Mode2_L_Bit1Clear:
	BIT 0, A
	JR Z, BitTest_Mode2_L_AllClear
	LD_L 001h
	RET

BitTest_Mode2_L_AllClear:
	LD_L 000h
	RET

BitTest_Bit0_L_v2:
	BIT 0, A
	JR Z, BitTest_Bit0_L_v2_Clear
	LD_L 001h
	RET

BitTest_Bit0_L_v2_Clear:
	LD_L 000h
	RET

BitTest_Mode2_L_v2:
	BIT 1, A
	JR Z, BitTest_Mode2_L_v2_Bit1Clear
	LD_L 000h
	RET

BitTest_Mode2_L_v2_Bit1Clear:
	BIT 0, A
	JR Z, BitTest_Mode2_L_v2_AllClear
	LD_L 001h
	RET

BitTest_Mode2_L_v2_AllClear:
	LD_L 000h
	RET

; ----------------------------------------------------------------------------
; Pitch_Get_Patch_Octave_Shift - per-patch octave transpose from tone record byte +0x29
; Entry: WA = part index, C = tone record byte +0x29
; Exit:  HL = signed offset in 1/256 semitone (0 when disabled)
; Notes: Returns 0 when ToneGen_GlobalFlags bit 1 is set.  Otherwise indexes
;        Patch_OctaveShift_Table with (C & 0x0F) and returns sext(byte) << 8.
;        CORRECTION to notes/audit/kn5000-audit-pitch.md 1.2, which calls this a
;        "per-patch key shift": the 16 table entries are A0 AC B8 C4 D0 DC E8 F4 00 0C
;        18 24 30 3C 48 54 = -96,-84,...,0,...,+84 semitones, i.e. exact OCTAVE steps
;        (12 semitones), index 8 = no shift.  MEASURED (ROM bytes, this pass).
;        For part indices 0x10..0x19 a 10-entry offset table at 0xF693 dispatches
;        relative to Pitch_Get_Patch_Octave_Shift_JumpTable; 9 of the 10 offsets are 0 and one (part 0x14) is 4,
;        and both targets reach the same table lookup.
; ----------------------------------------------------------------------------
Pitch_Get_Patch_Octave_Shift:		; 02294Eh
	LD DE, (041343h)
	BIT 1, DE
	JR Z, Pitch_Get_Patch_Octave_Shift_Dispatch
	LD HL, 0
	JR T, Pitch_Get_Patch_Octave_Shift_Return

Pitch_Get_Patch_Octave_Shift_Dispatch:
	EXTZ WA
	SUB WA, 0010h
	CP WA, 0
	JR LT, Pitch_Get_Patch_Octave_Shift_Fallback
	CP WA, 0009h
	JR GT, Pitch_Get_Patch_Octave_Shift_Fallback
	ADD WA, WA
	LDA XIX, 0F693h:24
	LD WA, (XIX + WA)
	LDA XIX, Pitch_Get_Patch_Octave_Shift_JumpTable:24
	JP T, XIX + WA

Pitch_Get_Patch_Octave_Shift_JumpTable:
	db 0DBh
	db 0A8h
	db 068h
	db 016h

Pitch_Get_Patch_Octave_Shift_Fallback:
	AND C, 00fh
	LD A, C
	EXTZ WA
	LDA XBC, 011ACFh
	LD L, (XBC + WA)
	EXTS HL
	SLA 8, HL

Pitch_Get_Patch_Octave_Shift_Return:
	RET

; ----------------------------------------------------------------------------
; Pitch_Clamp_Into_Range - clamp a log pitch into [kmin,kmax] (no octave folding)
; Entry: WA = log pitch, C = kmin key, E = kmax key
; Exit:  HL = clamped log pitch
; Notes: First saturates a bit-15 value exactly like Pitch_Saturate_15bit (<= 0xC000
;        unsigned -> 0x7FFF, else -> 0), then clamps to [(C<<8)+0x80,(E<<8)+0x80].
;        Used when the partial has reduced or fixed key follow (blk[+0x06]&7 != 0),
;        where folding by octaves would defeat the programmed ratio.  MEASURED.
; ----------------------------------------------------------------------------
Pitch_Clamp_Into_Range:		; 02299Dh
	LD HL, WA
	BIT 0fh, WA
	JR Z, Pitch_Clamp_Into_Range_CompareLo
	CP HL, 0c000h
	JR LE, Pitch_Clamp_Into_Range_Clamp7FFF
	LD HL, 0
	JR T, Pitch_Clamp_Into_Range_CompareLo

Pitch_Clamp_Into_Range_Clamp7FFF:
	LD HL, 7fffh

Pitch_Clamp_Into_Range_CompareLo:
	LD A, C
	EXTZ WA
	SLA 8, WA
	ADD WA, 0080h
	CP HL, WA
	JR GE, Pitch_Clamp_Into_Range_CompareHi
	LD A, C
	EXTZ WA
	LD HL, WA
	SLA 8, HL
	ADD HL, 0080h
	JR T, Pitch_Clamp_Into_Range_Return

Pitch_Clamp_Into_Range_CompareHi:
	LD A, E
	EXTZ WA
	SLA 8, WA
	ADD WA, 0080h
	CP HL, WA
	RET LE
	LD A, E
	EXTZ WA
	LD HL, WA
	SLA 8, HL
	ADD HL, 0080h

Pitch_Clamp_Into_Range_Return:
	RET

; ----------------------------------------------------------------------------
; Pitch_Fold_Octaves_Into_Range - fold a log pitch into [kmin,kmax] by whole octaves
; Entry: WA = log pitch (1/256 semitone), C = kmin key, E = kmax key
; Exit:  HL = folded log pitch, inside [(C<<8)+0x80 , (E<<8)+0x80]
; Notes: Two stages.  (1) while bit 15 is set, add or subtract 0x0C00 (one octave) --
;        this renormalises a 16-bit wrapped value: a slightly negative pitch is raised
;        an octave at a time, a value that overflowed past 0x7FFF is lowered.
;        (2) while below the low bound add 0x0C00; while above the high bound subtract
;        0x0C00.  Used when the partial has full key follow (blk[+0x06]&7 == 0), so a
;        key outside the SET s range plays the nearest octave of the same pitch class.
;        MEASURED.  The wrap-normalising first stage is NOT described in
;        notes/audit/kn5000-audit-pitch.md 1.2 -- read from the code this pass.
; ----------------------------------------------------------------------------
Pitch_Fold_Octaves_Into_Range:		; 0229ECh
	LD HL, WA
	JR T, PitchBend_AlignLoop_CheckSign

PitchBend_AlignLoop_CheckWrapped:
	CP HL, 0c000h
	JR LE, PitchBend_AlignLoop_SubStep
	ADD HL, 0c00h
	JR T, PitchBend_AlignLoop_CheckSign

PitchBend_AlignLoop_SubStep:
	SUB HL, 0c00h

PitchBend_AlignLoop_CheckSign:
	LD WA, HL
	BIT 0fh, WA
	JR NZ, PitchBend_AlignLoop_CheckWrapped
	JR T, PitchBend_AlignLoop_LoCheck

PitchBend_AlignLoop_AddStep:
	ADD HL, 0c00h

PitchBend_AlignLoop_LoCheck:
	LD A, C
	EXTZ WA
	SLA 8, WA
	ADD WA, 0080h
	CP HL, WA
	JR LT, PitchBend_AlignLoop_AddStep
	JR T, PitchBend_AlignLoop_HiCheck

PitchBend_AlignLoop_SubFinal:
	SUB HL, 0c00h

PitchBend_AlignLoop_HiCheck:
	LD A, E
	EXTZ WA
	SLA 8, WA
	ADD WA, 0080h
	CP HL, WA
	JR GT, PitchBend_AlignLoop_SubFinal
	RET

; ----------------------------------------------------------------------------
; WaveSel_KeyTable_Lookup - map the folded key to a zone slot of the SET
; Entry: XWA = ptrC, the SET's 128-byte note -> zone-slot table
;        BC = the folded log pitch, desc+0x06
; Exit:  L = zone slot;  the caller then reads ptrA[4 + L] to get the record index
; Notes: MEASURED.  key = (BC & 0x7F00) >> 8, i.e. the high byte of the folded
;        log pitch, which is a MIDI note number in 1/256-semitone units.
;        The SAME desc+0x06 drives pitch and wave selection, so the octave fold in
;        Pitch_Fold_Octaves_Into_Range moves both together.
;        (Named Pitch_Lookup_Zone_For_Key by the pitch/velocity pass; this routine
;        selects a WAVE zone rather than computing a pitch, so it is filed with
;        the wave-selection subsystem it is only ever called from.)
; ----------------------------------------------------------------------------
WaveSel_KeyTable_Lookup:		; 022A32h
	AND BC, 7f00h
	SRA 8, BC
	LD L, (XWA + BC)
	RET

; ----------------------------------------------------------------------------
; WaveSel_Emit_ZoneRecord_S15 - stride-15 zone-record emitter
; Entry: XBC = ptrB, DE = zone record index E, XWA = voice descriptor
; Exit:  (TG_Scratch_Reg040) = record[0];  desc+0x0F = record address
;        desc+0x01 |= 0x7000;  (WaveSel_Zone_Trim) = record[+0x0D]
; Notes: MEASURED.  Selected by SET flags bits 5/6 - which are NEVER set in this
;        ROM (census over all 487 descriptors), so this emitter is unreachable
;        with the shipped Table-Data.  Siblings: _S12, _S13, _S10, _S6, _S4.
; ----------------------------------------------------------------------------
WaveSel_Emit_ZoneRecord_S15:	; 022A3Fh
	EXTZ DE
	MULS_DE 000fh
	LDA XBC, XBC + DE
	LD (XWA + 00fh), XBC
	ORW (XWA + 001h), 7000h
	LD WA, (XBC)
	LD (0451CEh), WA
	LD WA, (XBC + 00dh)
	LD (293Eh), WA
	RET

; ----------------------------------------------------------------------------
; WaveSel_Emit_ZoneRecord_S12 - stride-12 zone-record emitter
; Entry: XBC = ptrB, DE = zone record index E, XWA = voice descriptor
; Exit:  as _S15, with pitch class 0x5000 and trim = record[+0x0A]
; Notes: MEASURED.  Unreachable with the shipped Table-Data (see _S15).
; ----------------------------------------------------------------------------
WaveSel_Emit_ZoneRecord_S12:	; 022A61h
	EXTZ DE
	MULS_DE 000ch
	LDA XBC, XBC + DE
	LD (XWA + 00fh), XBC
	ORW (XWA + 001h), 5000h
	LD WA, (XBC)
	LD (0451CEh), WA
	LD WA, (XBC + 00ah)
	LD (293Eh), WA
	RET

; ----------------------------------------------------------------------------
; WaveSel_Emit_ZoneRecord_S13 - stride-13 zone-record emitter
; Entry: XBC = ptrB, DE = zone record index E, XWA = voice descriptor
; Exit:  as _S15, with pitch class 0x3000 and trim = 0
; Notes: MEASURED.  Unreachable with the shipped Table-Data (see _S15).
; ----------------------------------------------------------------------------
WaveSel_Emit_ZoneRecord_S13:	; 022A83h
	EXTZ DE
	MULS_DE 000dh
	LDA XBC, XBC + DE
	LD (XWA + 00fh), XBC
	ORW (XWA + 001h), 3000h
	LD WA, (XBC)
	LD (0451CEh), WA
	LDW (293Eh), 0000h
	RET

; ----------------------------------------------------------------------------
; WaveSel_Emit_ZoneRecord_S10 - stride-10 zone-record emitter
; Entry: XBC = ptrB, DE = zone record index E, XWA = voice descriptor
; Exit:  as _S15, with pitch class 0x1000 and trim = 0
; Notes: MEASURED.  Unreachable with the shipped Table-Data (see _S15).
; ----------------------------------------------------------------------------
WaveSel_Emit_ZoneRecord_S10:	; 022AA4h
	EXTZ DE
	MULS_DE 000ah
	LDA XBC, XBC + DE
	LD (XWA + 00fh), XBC
	ORW (XWA + 001h), 1000h
	LD WA, (XBC)
	LD (0451CEh), WA
	LDW (293Eh), 0000h
	RET

; ----------------------------------------------------------------------------
; WaveSel_Emit_ZoneRecord_S6 - stride-6 zone-record emitter (the common one)
; Entry: XBC = ptrB, DE = zone record index E, XWA = voice descriptor
; Exit:  (TG_Scratch_Reg040) = record[0];  desc+0x0F = record address
;        desc+0x01 |= 0x4000;  (WaveSel_Zone_Trim) = record[+0x04]
; Notes: MEASURED.  Selected when SET flags bit 7 is set: 134 + 9 of the 487
;        descriptors.  Record = [+0..1] the +0x040 word, [+2..3] pitch word A,
;        [+4..5] pitch word B.
;        The 0x4000 stamped into desc+0x01 is the firmware's PITCH class and is
;        unrelated to the +0x040 class nibble - PIANO uses this emitter yet its
;        +0x040 nibble is 7.
; ----------------------------------------------------------------------------
WaveSel_Emit_ZoneRecord_S6:	; 022AC5h
	EXTZ DE
	MULS_DE 0006h
	LDA XBC, XBC + DE
	LD (XWA + 00fh), XBC
	ORW (XWA + 001h), 4000h
	LD WA, (XBC)
	LD (0451CEh), WA
	LD WA, (XBC + 004h)
	LD (293Eh), WA
	RET

; ----------------------------------------------------------------------------
; WaveSel_Emit_ZoneRecord_S4 - stride-4 zone-record emitter
; Entry: XBC = ptrB, DE = zone record index E, XWA = voice descriptor
; Exit:  (TG_Scratch_Reg040) = record[0];  desc+0x0F = record address
;        (WaveSel_Zone_Trim) = 0;  desc+0x01 is NOT touched
; Notes: MEASURED.  Selected when SET flags bit 7 is clear: 318 + 3 + 13 + 10 of
;        the 487 descriptors.  Record = [+0..1] the +0x040 word, [+2..3] pitch
;        word A.  This is the only emitter that stamps no pitch class.
; ----------------------------------------------------------------------------
WaveSel_Emit_ZoneRecord_S4:	; 022AE7h
	EXTZ DE
	SLA 2, DE
	LDA XBC, XBC + DE
	LD (XWA + 00fh), XBC
	LD WA, (XBC)
	LD (0451CEh), WA
	LDW (293Eh), 0000h
	RET

; ----------------------------------------------------------------------------
; Pitch_Saturate_15bit - saturate a wrapped log pitch to the legal 0..0x7FFF range
; Entry: WA = candidate log pitch
; Exit:  HL = WA unchanged if bit 15 clear; else 0x7FFF if WA <= 0xC000 (unsigned),
;        else 0
; Notes: This is what fixes the +0x400 register format: 15 bits at 0x100 units per
;        semitone = 128 semitones, 0xC00 per octave.  A value that wrapped just past
;        the top (0x8000..0xC000) saturates HIGH, a value that went just below zero
;        (0xC001..0xFFFF) saturates LOW.  MEASURED.
; ----------------------------------------------------------------------------
Pitch_Saturate_15bit:		; 022B02h
	LD BC, WA
	BIT 0fh, BC
	JR Z, Pitch_Saturate_15bit_Return
	CP WA, 0c000h
	JR ULE, Pitch_Saturate_15bit_Clamp7FFF
	LD WA, 0
	JR T, Pitch_Saturate_15bit_Return

Pitch_Saturate_15bit_Clamp7FFF:
	LD WA, 7fffh

Pitch_Saturate_15bit_Return:
	LD HL, WA
	RET

ClampS16_WA_To_DEBC:
	CP WA, BC
	JR LE, ClampS16_WA_To_DEBC_CheckLo
	LD WA, BC
	JR T, ClampS16_WA_To_DEBC_Return

ClampS16_WA_To_DEBC_CheckLo:
	CP WA, DE
	JR GE, ClampS16_WA_To_DEBC_Return
	LD WA, DE

ClampS16_WA_To_DEBC_Return:
	LD HL, WA
	RET

PitchBend_Scale:
	RES 7, C
	CP A, 0
	JR GE, PitchBend_Scale_Multiply
	EXTZ BC
	LDA XHL, 0FEE4h:24
	LD C, (XHL + BC)
	EXTZ BC
	CPL A
	INC 1, A

PitchBend_Scale_Multiply:
	LD IXL, A
	EXTS IX
	LD A, C
	EXTZ WA
	LDA XBC, 0FF64h:24
	LD L, (XBC + WA)
	EXTS HL
	LD WA, HL
	MULS_XWA_IX
	LD HL, WA
	LD A, E
	AND A, 00fh
	RET Z
	SRA A, HL
	RET

Detune_ScaleSymmetric:
	CP WA, 0
	JR GE, Detune_ScaleSymmetric_PosArm
	CPL WA
	INC 1, WA
	CP WA, 0032h
	JR LE, Detune_ScaleSymmetric_NegArm
	LD WA, 0032h

Detune_ScaleSymmetric_NegArm:
	EXTZ WA
	LDA XBC, 0119C8h
	LD A, (XBC + WA)
	EXTZ WA
	CPL WA
	INC 1, WA
	JR T, Detune_ScaleSymmetric_Return

Detune_ScaleSymmetric_PosArm:
	CP WA, 0032h
	JR LE, Detune_ScaleSymmetric_PosClamp
	LD WA, 0032h

Detune_ScaleSymmetric_PosClamp:
	EXTZ WA
	LDA XBC, 0119C8h
	LD A, (XBC + WA)
	EXTZ WA

Detune_ScaleSymmetric_Return:
	LD HL, WA
	RET

Detune_ScaleUnsigned:
	EXTZ WA
	LDA XBC, 0119C8h
	LD A, (XBC + WA)
	EXTZ WA
	LD HL, WA
	RET

Pan_ScaleWithVelocity:
	AND WA, 7f00h
	SRL 8, WA
	LD L, (XSP + 006h)
	EXTZ HL
	CP WA, HL
	JR ULE, Pan_ScaleWithVelocity_ClampLo
	LD A, (XSP + 006h)
	EXTZ WA
	JR T, Pan_ScaleWithVelocity_Multiply

Pan_ScaleWithVelocity_ClampLo:
	LD L, E
	EXTZ HL
	CP WA, HL
	JR NC, Pan_ScaleWithVelocity_Multiply
	LD A, E
	EXTZ WA

Pan_ScaleWithVelocity_Multiply:
	EXTZ BC
	LD DE, WA
	SUB DE, BC
	LD L, (XSP + 004h)
	EXTS HL
	LD WA, HL
	MULS_XWA_DE
	LD HL, WA
	SRA 5, HL
	RETD 0004h

; ----------------------------------------------------------------------------
; TVF_Clamp_Cutoff - clamp a cutoff value to the legal computed range
; Entry: WA = candidate value (signed)
; Exit:  HL = clamp(WA, 0, 0x78)
; Notes: The computed path can never reach 0x7F, which is why 0x7F is available as the
;        reserved "wide open / no filter" code written by TVF_Set_Bypass.  MEASURED.
; ----------------------------------------------------------------------------
TVF_Clamp_Cutoff:		; 022BF2h
	CP WA, 0078h
	JR LE, TVF_Clamp_Cutoff_CheckLo
	LD WA, 0078h
	JR T, TVF_Clamp_Cutoff_Return

TVF_Clamp_Cutoff_CheckLo:
	CP WA, 0
	JR GE, TVF_Clamp_Cutoff_Return
	LD WA, 0

TVF_Clamp_Cutoff_Return:
	LD HL, WA
	RET

; ----------------------------------------------------------------------------
; TVF_Calc_Cutoff - the per-voice filter cutoff / brightness value
; Entry: XWA = voice descriptor, BC = base cutoff, DE = velocity depth (signed),
;        (XSP+4) = key-follow depth (signed, pushed by the caller)
; Exit:  HL = cutoff, 0..0x78.  Returns with RETD 2 (pops the pushed argument)
; Notes: if veldepth != 0:
;             curve = (VP[+0x36] & 0xE0) >> 5
;             base += veldepth * sext(TVF_Velocity_Curves[curve][velocity & 0x7F]) / 32
;        if keydepth != 0:
;             k = clamp((desc[+0x08] >> 8) & 0x7F, VP[+0x3a], VP[+0x3b])
;             base += keydepth * (k - VP[+0x39]) / 32
;        base += 0x18 ; return TVF_Clamp_Cutoff(base)
;        The key used for key follow is the high byte of desc[+0x08], the ABSOLUTE
;        pitch AFTER all transposes -- not the raw played key (a refinement of
;        notes/audit/kn5000-audit-timbre.md 1.3, which says "the played note").
;        The seven curves run from -64 at velocity 0 to about 0 at velocity 127, so
;        soft playing darkens the sound.  MEASURED (9/9 live hits on +0x100).
; ----------------------------------------------------------------------------
TVF_Calc_Cutoff:		; 022C06h
	LD HL, DE
	LD XIX, (XWA + 017h)
	CP HL, 0
	JR Z, TVF_Calc_Cutoff_DepthScale
	LD E, (XIX + 036h)
	AND E, 0e0h
	SRL 5, E
	EXTZ DE
	LD IY, DE
	SLA 7, IY
	LD E, (XWA + 00ch)
	EXTZ DE
	AND DE, 007fh
	EXTZ XDE
	LDA XDE, XDE + IY
	LD XIY, 00011519h
	ADD XIY, XDE
	LD E, (XIY)
	LD IYL, E
	EXTS IY
	LD DE, HL
	MULS_XDE_IY
	LD HL, DE
	SRA 5, HL
	ADD BC, HL

TVF_Calc_Cutoff_DepthScale:
	CP (XSP + 004h), 000h
	JR Z, TVF_Calc_Cutoff_AddBaseline
	LD DE, (XWA + 008h)
	AND DE, 7f00h
	SRL 8, DE
	LD A, (XIX + 03bh)
	EXTZ WA
	CP DE, WA
	JR ULE, TVF_Calc_Cutoff_ClampHi
	LD A, (XIX + 03bh)
	LD E, A
	EXTZ DE
	JR T, TVF_Calc_Cutoff_Multiply

TVF_Calc_Cutoff_ClampHi:
	LD A, (XIX + 03ah)
	EXTZ WA
	CP DE, WA
	JR NC, TVF_Calc_Cutoff_Multiply
	LD A, (XIX + 03ah)
	LD E, A
	EXTZ DE

TVF_Calc_Cutoff_Multiply:
	LD A, (XIX + 039h)
	EXTZ WA
	SUB DE, WA
	LD A, (XSP + 004h)
	EXTS WA
	MULS_XWA_DE
	SRA 5, WA
	ADD BC, WA

TVF_Calc_Cutoff_AddBaseline:
	ADD BC, 0018h
	LD WA, BC
	CALR TVF_Clamp_Cutoff
	RETD 0002h

; ----------------------------------------------------------------------------
; TVF_Calc_Cutoff_NoKeyFollow - cutoff for the short parameter set (velocity only)
; Entry: XWA = voice descriptor, BC = base cutoff; VP = desc[+0x17]
; Exit:  HL = cutoff, 0..0x78
; Notes: depth = sext(VP[+0x10]); curve = (VP[+0x0F] & 0xE0) >> 5; the velocity term
;        is identical to TVF_Calc_Cutoff s, there is no key-follow term, then +0x18
;        and TVF_Clamp_Cutoff.  MEASURED.
; ----------------------------------------------------------------------------
TVF_Calc_Cutoff_NoKeyFollow:		; 022C99h
	LD XIX, (XWA + 017h)
	LD E, (XIX + 010h)
	LD L, E
	EXTS HL
	CP HL, 0
	JR Z, TVF_Calc_Cutoff_NoKeyFollow_AddBaseline
	LD E, (XIX + 00fh)
	AND E, 0e0h
	SRL 5, E
	EXTZ DE
	SLA 7, DE
	LD A, (XWA + 00ch)
	EXTZ WA
	AND WA, 007fh
	EXTZ XWA
	LDA XWA, XWA + DE
	LD XDE, 00011519h
	ADD XDE, XWA
	LD A, (XDE)
	LD E, A
	EXTS DE
	LD WA, HL
	MULS_XWA_DE
	LD HL, WA
	SRA 5, HL
	LD WA, HL
	ADD BC, WA

TVF_Calc_Cutoff_NoKeyFollow_AddBaseline:
	ADD BC, 0018h
	LD WA, BC
	JRL T, TVF_Clamp_Cutoff

; ----------------------------------------------------------------------------
; TVF_Bias_Clamp_Amount - bias a 7-bit TVF amount and clamp it
; Entry: WA = raw value
; Exit:  HL = min(WA + 0x18, 0x78)
; Notes: The same +0x18 bias TVF_Calc_Cutoff applies, used for the low 7 bits of the
;        +0x140 word.  MEASURED.
; ----------------------------------------------------------------------------
TVF_Bias_Clamp_Amount:		; 022CE8h
	ADD WA, 0018h
	CP WA, 0078h
	JR LE, TVF_Bias_Clamp_Amount_Return
	LD WA, 0078h

TVF_Bias_Clamp_Amount_Return:
	LD HL, WA
	RET

; ----------------------------------------------------------------------------
; TVF_Lookup_Depth_Amount - decode the +0x140 depth index into amount + sign
; Entry: A = index byte (bit 7 selects the table, bits 3:0 the record)
; Exit:  HL = (amount << 8) | sign_bit7 ; TVF_Depth_LevelTrim (0x2940) = signed trim
; Notes: Two 16 x 3-byte tables: TVF_Depth_Table_A (bit 7 clear) and
;        TVF_Depth_Table_B (bit 7 set), mirror images of each other.
;        record +0 = 0x00 or 0x80, ORed in as bit 7 of the result (the SIGN)
;        record +1 = the 7-bit AMOUNT, shifted to bits 15:8
;        record +2 = a signed LEVEL TRIM (0,-16,-13,-11,-8,-5,-3,0,...) stored in the
;                    global TVF_Depth_LevelTrim
;        NEW this pass: that global is READ BACK by the amplitude accumulator, so the
;        depth index also applies a make-up gain in the level domain.
;        notes/audit/kn5000-audit-timbre.md 1.4 records the stash but not the consumer.
;        MEASURED (18/18 live hits on +0x140).
; ----------------------------------------------------------------------------
TVF_Lookup_Depth_Amount:		; 022CF8h
	LD C, A
	AND C, 00fh
	LD E, C
	EXTZ DE
	BIT 7, A
	JR Z, TVF_Lookup_Depth_Amount_SetA
	LD WA, DE
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	LDA XWA, 011A26h
	ADD XWA, XBC
	LD A, (XWA)
	LD L, A
	EXTZ HL
	SLL 8, HL
	LD WA, DE
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	LD XWA, 00011a25h
	ADD XWA, XBC
	LD A, (XWA)
	LD IXL, A
	EXTZ IX
	LD WA, DE
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	LDA XWA, 011A27h
	ADD XWA, XBC
	LD A, (XWA)
	EXTS WA
	LD (2940h), WA
	JR T, TVF_Lookup_Depth_Amount_Return

TVF_Lookup_Depth_Amount_SetA:
	LD WA, DE
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	LDA XWA, 0119FCh
	ADD XWA, XBC
	LD A, (XWA)
	LD L, A
	EXTZ HL
	SLL 8, HL
	LD WA, DE
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	LD XWA, 000119fbh
	ADD XWA, XBC
	LD A, (XWA)
	LD IXL, A
	EXTZ IX
	LD WA, DE
	EXTZ XWA
	LD XBC, XWA
