	MULS_WA 011fh
	LDA XBC, 04137Fh
	LD A, (XBC + WA)
	EXTZ WA
	CALR BitTest_Mode2_L_v2
	JR T, Voice_Env_VelocityDispatch_Gate

Voice_Env_VelocityDispatch_ClearFlag:
	LD_L 000h

Voice_Env_VelocityDispatch_Gate:
	CP L, 0
	JRL Z, Voice_Env_ApplyVelocity_Return
	LD A, (XSP)
	EXTZ WA
	CALR Instrument_LookupProgram_HiNibble
	JRL T, Voice_Env_ApplyVelocity_Return

Voice_Env_ApplyVelocity_Type2:
	CP C, 3
	JR Z, Voice_Env_Type2_c3
	CP C, 2
	JR Z, Voice_Env_Type2_c2
	CP C, 1
	JR Z, Voice_Env_Type2_c1
	CP C, 0
	JRL NZ, Voice_Env_Type2_ClearFlag
	BIT 4, (04134Bh)
	JR Z, Voice_Env_Type2_c0_NoBit4
	LD_L 000h
	JRL T, Voice_Env_Type2_Gate

Voice_Env_Type2_c0_NoBit4:
	LD A, (04134Bh)
	EXTZ WA
	CALR BitTest_Bit0_L
	JR T, Voice_Env_Type2_Gate

Voice_Env_Type2_c1:
	BIT 4, (04134Bh)
	JR Z, Voice_Env_Type2_c1_NoBit4
	LD_L 000h
	JR T, Voice_Env_Type2_Gate

Voice_Env_Type2_c1_NoBit4:
	LD A, (04134Bh)
	EXTZ WA
	CALR BitTest_Mode2_L
	JR T, Voice_Env_Type2_Gate

Voice_Env_Type2_c2:
	LD A, (XSP)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04137Fh
	BIT 4, (XBC + WA)
	JR Z, Voice_Env_Type2_c2_Trigger
	LD_L 000h
	JR T, Voice_Env_Type2_Gate

Voice_Env_Type2_c2_Trigger:
	LD A, (XSP)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04137Fh
	LD A, (XBC + WA)
	EXTZ WA
	CALR BitTest_Bit0_L_v2
	JR T, Voice_Env_Type2_Gate

Voice_Env_Type2_c3:
	LD A, (XSP)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04137Fh
	BIT 4, (XBC + WA)
	JR Z, Voice_Env_Type2_c3_Trigger
	LD_L 000h
	JR T, Voice_Env_Type2_Gate

Voice_Env_Type2_c3_Trigger:
	LD A, (XSP)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04137Fh
	LD A, (XBC + WA)
	EXTZ WA
	CALR BitTest_Mode2_L_v2
	JR T, Voice_Env_Type2_Gate

Voice_Env_Type2_ClearFlag:
	LD_L 000h

Voice_Env_Type2_Gate:
	CP L, 0
	JR Z, Voice_Env_ApplyVelocity_Return
	LD A, (XSP)
	EXTZ WA
	CALR Instrument_LookupProgram_LoNibble

Voice_Env_ApplyVelocity_Return:
	INC 2, XSP
	RET

; ----------------------------------------------------------------------------
; Voice_Pitch_Compute - key + transposes -> absolute pitch and folded zone key
; Entry: XWA = voice descriptor (0x2942+0x47*p staging, or 0x04308E+0x47*ch live)
;        desc[+0x05] = played key | 0x80,  desc[+0x1F] = SET descriptor,
;        desc[+0x17] = 0x51-byte patch partial block,  desc[+0x23] = part struct
; Exit:  desc[+0x08] = absolute log pitch (before zone fold), desc[+0x06] = zone-folded
;        log pitch (its high byte is the key that selects the multisample zone).
;        Clobbers WA/BC/DE/HL/IZ.
; Notes: Units are 1/256 semitone throughout (0x100 per semitone, 0xC00 per octave),
;        key K enters as (K<<8)+0x80.  Accumulated in order:
;          + (Pitch_MasterTranspose)                whole semitones <<8
;          + sext(part[+0x16])<<8                   part TRANSPOSE
;          + sext(part[+0x6d])<<8                   part OCTAVE
;          + Pitch_Get_Patch_Octave_Shift(...)      patch octave, tone record byte +0x29
;          + <scale tuning>                         see below
;        -> desc[+0x08] via Pitch_Saturate_15bit.
;        SCALE TUNING source: if ToneGen_GlobalFlags bit 9 is set AND the part present
;        word (Part_PresentWord) bit 8 is set, the mode comes from the panel global
;        ScaleTune_GlobalMode; otherwise from the patch record byte +0x13.  Modes:
;          0x80 -> ScaleTune_UserOffsets[key mod 12] * 2
;          0x41 -> ScaleTune_PerKey_Offsets_41[key] (word)
;          0x42 -> ScaleTune_PerKey_Offsets_42[key] (word)
;          0x40 -> + (Pitch_ScaleTune_FlatOffset)
;          0x00 -> none
;          else -> ScaleTune_Temperament_Table[mode][key mod 12] * 2
;        Then the multisample/key-follow stage, L = partial_blk[+0x06] & 7:
;          SET[0] bit1 clear:  L==7 -> pitch := SET[+0x0c] (FIXED pitch, no key follow)
;                              else -> pitch -= (SET[+0x0b]<<8)+0x80  (SET root key)
;                                      if L: pitch >>= L             (key follow 1/2^L)
;                                      pitch += SET[+0x0c]           (SET base pitch)
;          SET[0] bit1 set:    same shape with the constant 0x4280 for root and base
;          + sext(partial_blk[+0x04])<<8            PARTIAL COARSE TRANSPOSE
;          + sext(desc[+0x27][+0x20])<<8            per-slot coarse offset
;        Finally L==0 -> Pitch_Fold_Octaves_Into_Range, L!=0 -> Pitch_Clamp_Into_Range,
;        both bounded by SET[+0x09] (kmin) and SET[+0x0a] (kmax); the result is
;        desc[+0x06], which BOTH the pitch register (+0x400) and the wave-select
;        register (+0x040, via WaveSel_KeyTable_Lookup) are derived from.
;        MEASURED end to end: notes/audit/kn5000-audit-pitch.md 1.2/1.4,
;        notes/kn5000-variant-model.md 5.1 (+0x400 reproduced 15/16 from ROM bytes).
; ----------------------------------------------------------------------------
Voice_Pitch_Compute:		; 023584h
	LDA XSP, XSP - 10
	PUSH IZ
	LD (XSP + 008h), XWA
	LD XWA, (XSP + 008h)
	LD XWA, (XWA + 01fh)
	LD (XSP + 002h), XWA
	LD XWA, (XSP + 008h)
	LD A, (XWA + 004h)
	LD (XSP + 006h), A
	LD XWA, (XSP + 008h)
	LD A, (XWA + 005h)
	LD IZL, A
	EXTZ IZ
	SLA 8, IZ
	AND IZ, 7f00h
	ADD IZ, 0080h
	ADD IZ, (041349h)
	LD XWA, (XSP + 008h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 016h)
	EXTS WA
	SLA 8, WA
	ADD IZ, WA
	LD XWA, (XSP + 008h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 06dh)
	EXTS WA
	SLA 8, WA
	ADD IZ, WA
	LD XWA, (XSP + 008h)
	LD A, (XWA + 004h)
	LD E, A
	EXTZ DE
	LD XWA, (XSP + 008h)
	LD XWA, (XWA + 013h)
	LD A, (XWA + 029h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Pitch_Get_Patch_Octave_Shift
	ADD IZ, HL
	CALL ScaleTune_Is_Global_Enabled
	CP HL, 0
	JRL Z, Voice_Pitch_Compute_Inactive
	LD A, (XSP + 006h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Ah
	LD WA, (XBC + WA)
	BIT 8, WA
	JRL Z, Voice_Pitch_ApplyPortamento
	CALL ScaleTune_Get_Global_Mode
	LD A, L
	CP A, 080h
	JR Z, Voice_Pitch_BendType_Octave
	CP A, 042h
	JR Z, Voice_Pitch_BendType_TableB
	CP A, 041h
	JR Z, Voice_Pitch_BendType_TableA
	CP A, 040h
	JR Z, Voice_Pitch_BendType_Fixed
	CP A, 0
	JRL Z, Voice_Pitch_ApplyPortamento

Voice_Pitch_BendType_Octave:
	LD XWA, (XSP + 008h)
	LD A, (XWA + 005h)
	RES 7, A
	EXTZ WA
	DIV_A 00ch
	LD A, W
	EXTZ WA
	CALL ScaleTune_Get_User_Offset
	LD A, L
	EXTS WA
	ADD WA, WA
	ADD IZ, WA
	JRL T, Voice_Pitch_ApplyPortamento

Voice_Pitch_BendType_Fixed:
	ADD IZ, (041366h)
	JRL T, Voice_Pitch_ApplyPortamento

Voice_Pitch_BendType_TableA:
	LD XWA, (XSP + 008h)
	LD A, (XWA + 005h)
	RES 7, A
	EXTZ WA
	ADD WA, WA
	LDA XBC, 0FCE4h:24
	LD WA, (XBC + WA)
	ADD IZ, WA
	JRL T, Voice_Pitch_ApplyPortamento

Voice_Pitch_BendType_TableB:
	LD XWA, (XSP + 008h)
	LD A, (XWA + 005h)
	RES 7, A
	EXTZ WA
	ADD WA, WA
	LDA XBC, 0FDE4h:24
	LD WA, (XBC + WA)
	ADD IZ, WA
	JRL T, Voice_Pitch_ApplyPortamento

Voice_Pitch_Compute_Inactive:
	LD A, (XSP + 006h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Eh
	LD XWA, (XBC + WA)
	LD L, (XWA + 013h)
	LD A, L
	CP A, 080h
	JRL Z, Voice_Pitch_ApplyPortamento
	CP A, 042h
	JR Z, Voice_Pitch_Inactive_BendType_TableB
	CP A, 041h
	JR Z, Voice_Pitch_Inactive_BendType_TableA
	CP A, 040h
	JR Z, Voice_Pitch_Inactive_BendType_Fixed
	CP A, 0
	JR NZ, Voice_Pitch_Inactive_BendType_Chromatic
	JR T, Voice_Pitch_ApplyPortamento

Voice_Pitch_Inactive_BendType_Fixed:
	ADD IZ, (041366h)
	JR T, Voice_Pitch_ApplyPortamento

Voice_Pitch_Inactive_BendType_TableA:
	LD XWA, (XSP + 008h)
	LD A, (XWA + 005h)
	RES 7, A
	EXTZ WA
	ADD WA, WA
	LDA XBC, 0FCE4h:24
	LD WA, (XBC + WA)
	ADD IZ, WA
	JR T, Voice_Pitch_ApplyPortamento

Voice_Pitch_Inactive_BendType_TableB:
	LD XWA, (XSP + 008h)
	LD A, (XWA + 005h)
	RES 7, A
	EXTZ WA
	ADD WA, WA
	LDA XBC, 0FDE4h:24
	LD WA, (XBC + WA)
	ADD IZ, WA
	JR T, Voice_Pitch_ApplyPortamento

Voice_Pitch_Inactive_BendType_Chromatic:
	LD XWA, (XSP + 008h)
	LD A, (XWA + 005h)
	RES 7, A
	EXTZ WA
	DIV_A 00ch
	LD A, W
	LD E, A
	EXTZ DE
	LD A, L
	EXTZ WA
	MULS_WA 00ch
	LDA XBC, 011B68h
	EXTS XWA
	ADD XWA, XBC
	LD A, (XWA + DE)
	EXTS WA
	ADD WA, WA
	ADD IZ, WA

Voice_Pitch_ApplyPortamento:
	LD WA, IZ
	CALR Pitch_Saturate_15bit
	LD XWA, (XSP + 008h)
	LD (XWA + 008h), HL
	LD XWA, (XSP + 008h)
	LD XWA, (XWA + 017h)
	LD L, (XWA + 006h)
	AND L, 007h
	LD XWA, (XSP + 002h)
	BIT 1, (XWA)
	JR NZ, Voice_Pitch_Portamento_Active_SubBias
	CP L, 7
	JR Z, Voice_Pitch_Portamento_Mode7_Direct
	LD XWA, (XSP + 002h)
	LD A, (XWA + 00bh)
	EXTZ WA
	SLA 8, WA
	ADD WA, 0080h
	SUB IZ, WA
	LD A, L
	AND A, 00fh
	JR Z, Voice_Pitch_Portamento_Off_AddOffset
	SRA A, IZ

Voice_Pitch_Portamento_Off_AddOffset:
	LD XWA, (XSP + 002h)
	LD WA, (XWA + 00ch)
	ADD IZ, WA
	JR T, Voice_Pitch_ApplyFineTune

Voice_Pitch_Portamento_Mode7_Direct:
	LD XWA, (XSP + 002h)
	LD IZ, (XWA + 00ch)
	JR T, Voice_Pitch_ApplyFineTune

Voice_Pitch_Portamento_Active_SubBias:
	CP L, 7
	JR Z, Voice_Pitch_Portamento_Active_SetFixed
	SUB IZ, 4280h
	LD A, L
	AND A, 00fh
	JR Z, Voice_Pitch_Portamento_Active_AddBias
	SRA A, IZ

Voice_Pitch_Portamento_Active_AddBias:
	ADD IZ, 4280h
	JR T, Voice_Pitch_ApplyFineTune

Voice_Pitch_Portamento_Active_SetFixed:
	LD IZ, 4280h

Voice_Pitch_ApplyFineTune:
	LD XWA, (XSP + 008h)
	LD XWA, (XWA + 017h)
	LD A, (XWA + 004h)
	EXTS WA
	SLA 8, WA
	ADD IZ, WA
	LD XWA, (XSP + 008h)
	LD XWA, (XWA + 027h)
	LD A, (XWA + 020h)
	EXTS WA
	SLA 8, WA
	ADD IZ, WA
	CP L, 0
	JR NZ, Voice_Pitch_ApplyFineTune_LegatoB
	LD XWA, (XSP + 002h)
	LD A, (XWA + 009h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 00ah)
	LD E, A
	EXTZ DE
	LD WA, IZ
	CALR Pitch_Fold_Octaves_Into_Range
	LD XWA, (XSP + 008h)
	LD (XWA + 006h), HL
	JR T, Voice_Pitch_Compute_Return

Voice_Pitch_ApplyFineTune_LegatoB:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 009h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 00ah)
	LD E, A
	EXTZ DE
	LD WA, IZ
	CALR Pitch_Clamp_Into_Range
	LD XWA, (XSP + 008h)
	LD (XWA + 006h), HL

Voice_Pitch_Compute_Return:
	POP IZ
	LDA XSP, XSP + 00ah
	RET

Voice_Pitch_CopyBase:
	PUSH XIZ
	LD XIZ, XWA
	LD XBC, (XIZ + 017h)
	LD XWA, (XIZ + 01fh)
	LD HL, (XWA + 00ch)
	LD (XIZ + 008h), HL
	LD A, (XBC + 003h)
	EXTS WA
	SLA 8, WA
	ADD HL, WA
	LD A, (XBC + 004h)
	EXTS WA
	ADD WA, WA
	ADD HL, WA
	LD XWA, (XIZ + 01fh)
	LD A, (XWA + 009h)
	LD C, A
	EXTZ BC
	LD XWA, (XIZ + 01fh)
	LD A, (XWA + 00ah)
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR Pitch_Fold_Octaves_Into_Range
	LD (XIZ + 006h), HL
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; WaveSel_StageB_Build_Reg040 - key zone -> the +0x040 wave-select word
; Entry: XWA = voice descriptor (0x47 bytes: Voice_Desc_Staging, indexed by
;        partial, or Voice_Desc_Table, indexed by chip voice)
; Exit:  (TG_Scratch_Reg040) = the 16-bit word destined for register +0x040
;        desc+0x0F = the selected zone record; desc+0x01 |= the pitch class
;        (WaveSel_Zone_Trim) = the record's signed pitch offset, or 0
; Notes: MEASURED.  SETp = desc+0x1F (cached by WaveSel_Cache_SetDescPtr), then
;            ptrA = (ToneDB_RelBase) + u32[SETp+1]   ; zone-slot remap table
;            ptrB = (ToneDB_RelBase) + u32[SETp+5]   ; zone record array
;            ptrC = (ToneDB_RelBase) + u32[ptrA]     ; 128-byte note->slot map
;            key  = (desc+0x06 >> 8) & 0x7F
;            E    = ptrA[4 + ptrC[key]]
;            record = ptrB + stride(SETp[0]) * E ;  word = u16[record]
;        The record stride comes from SETp[0] bits 5/6/7 -> one of six emitters.
;        MEASURED over all 487 descriptors: bits 5 and 6 are never set, so only
;        stride 6 (bit 7 set) and stride 4 actually occur.
;        The emitted word is { class = bits[15:12], entry = bits[11:0] }.  The
;        CHIP reads that class as page = class & 3 and bank = (class >> 2) & 3,
;        with entry indexing that 1 MB page's self-delimiting directory
;        (notes/kn5000-structural-validation.md 0); the firmware never splits the
;        nibble itself.
;        (Named WaveSel_Build_Reg040 by the pitch/velocity pass; the _StageB_
;        infix is added so the A1/A2/B pipeline reads in order.)
; ----------------------------------------------------------------------------
WaveSel_StageB_Build_Reg040:		; 023849h
	LDA XSP, XSP - 12
	PUSH XIZ
	LD (XSP + 12), XWA
	LD XWA, (XSP + 12)
	LD XIZ, (XWA + 31)
	LD XWA, (XIZ + 1)
	ADD XWA, (045310h)
	LD (XSP + 4), XWA
	LD XWA, (XIZ + 5)
	ADD XWA, (045310h)
	LD (XSP + 8), XWA
	LD XWA, (XSP + 4)
	LD XWA, (XWA)
	LD XDE, XWA
	ADD XDE, (045310h)
	LD XWA, (XSP + 12)
	LD BC, (XWA + 6)
	LD XWA, XDE
	CALR WaveSel_KeyTable_Lookup
	LD A, L
	EXTZ WA
	LD BC, WA
	INC 4, BC
	LD XWA, (XSP + 4)
	LD E, (XWA + BC)
	BIT 6, (XIZ)
	JR Z, Voice_Pitch_Interp_Bit7_NoB6
	BIT 7, (XIZ)
	JR Z, Voice_Pitch_Interp_Bit7_NoB5
	BIT 5, (XIZ)
	JR Z, Voice_Pitch_Interp_Bits56
	LD XBC, (XSP + 8)
	EXTZ DE
	LD XWA, (XSP + 12)
	CALR WaveSel_Emit_ZoneRecord_S15
	JR T, WaveSel_StageB_Return

Voice_Pitch_Interp_Bits56:
	LD XBC, (XSP + 8)
	EXTZ DE
	LD XWA, (XSP + 12)
	CALR WaveSel_Emit_ZoneRecord_S12
	JR T, WaveSel_StageB_Return

Voice_Pitch_Interp_Bit7_NoB5:
	BIT 5, (XIZ)
	JR Z, Voice_Pitch_Interp_Bits67
	LD XBC, (XSP + 008h)
	EXTZ DE
	LD XWA, (XSP + 00ch)
	CALR WaveSel_Emit_ZoneRecord_S13
	JR T, WaveSel_StageB_Return

Voice_Pitch_Interp_Bits67:
	LD XBC, (XSP + 008h)
	EXTZ DE
	LD XWA, (XSP + 00ch)
	CALR WaveSel_Emit_ZoneRecord_S10
	JR T, WaveSel_StageB_Return

Voice_Pitch_Interp_Bit7_NoB6:
	BIT 7, (XIZ)
	JR Z, Voice_Pitch_Interp_Base
	LD XBC, (XSP + 008h)
	EXTZ DE
	LD XWA, (XSP + 00ch)
	CALR WaveSel_Emit_ZoneRecord_S6
	JR T, WaveSel_StageB_Return

Voice_Pitch_Interp_Base:
	LD XBC, (XSP + 008h)
	EXTZ DE
	LD XWA, (XSP + 00ch)
	CALR WaveSel_Emit_ZoneRecord_S4

; ----------------------------------------------------------------------------
; WaveSel_StageB_Return - common exit of the Stage-B builder
; ----------------------------------------------------------------------------
WaveSel_StageB_Return:		; 0238F3h
	POP XIZ
	LDA XSP, XSP + 00ch
	RET

; ----------------------------------------------------------------------------
; WaveSel_StageB_Build_Reg040_Footage - drawbar/footage variant of Stage B
; Entry: XWA = voice descriptor
; Exit:  as WaveSel_StageB_Build_Reg040 (always stride 6, pitch class 0x4000)
; Notes: MEASURED.  Instead of the key table it derives the zone record index E
;        from the partial index desc+0x03:  p == 0 -> Voice_Slot_CalcAmpNibble, p < 3 ->
;        Voice_Slot_FindOctaveOffset, else u16[ part_state + 0x102 + 2*p ]; each result passes
;        through Voice_KeyIndex_Pack3Nibbles.  Shares the tail WaveSel_StageB_Store_Reg040 with
;        the main builder.  Reached from Voice_Release_Type4, for patch record type 0x60
;        (drawbar registrations) - which is why a DIGITAL DRAWBAR voice's +0x040
;        is constant across the keyboard.
; ----------------------------------------------------------------------------
WaveSel_StageB_Build_Reg040_Footage:	; 0238F8h
	DEC 4, XSP
	PUSH XIZ
	LD XIZ, XWA
	LD XWA, (XIZ + 01fh)
	LD XWA, (XWA + 005h)
	ADD XWA, (045310h)
	LD (XSP + 004h), XWA
	CP (XIZ + 003h), 000h
	JR NZ, WaveSel_StageB_Build_Reg040_Footage_StateB
	LD A, (XIZ + 004h)
	LD L, A
	EXTZ HL
	LD A, (XIZ)
	LD C, A
	EXTZ BC
	LD A, (XIZ + 003h)
	LD E, A
	EXTZ DE
	LD WA, HL
	CALL Voice_Slot_CalcAmpNibble
	LD WA, HL
	CALL Voice_KeyIndex_Pack3Nibbles
	LD WA, HL
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	ADD XBC, XBC
	ADD (XSP + 004h), XBC
	JR T, WaveSel_StageB_Store_Reg040

WaveSel_StageB_Build_Reg040_Footage_StateB:
	CP (XIZ + 003h), 003h
	JR NC, WaveSel_StageB_Build_Reg040_Footage_RoutingTable
	LD A, (XIZ + 004h)
	LD L, A
	EXTZ HL
	LD A, (XIZ)
	LD C, A
	EXTZ BC
	LD A, (XIZ + 003h)
	LD E, A
	EXTZ DE
	LD WA, HL
	CALL Voice_Slot_FindOctaveOffset
	LD WA, HL
	CALL Voice_KeyIndex_Pack3Nibbles
	LD WA, HL
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	ADD XBC, XBC
	ADD (XSP + 004h), XBC
	JR T, WaveSel_StageB_Store_Reg040

WaveSel_StageB_Build_Reg040_Footage_RoutingTable:
	LD A, (XIZ + 003h)
	EXTZ WA
	ADD WA, WA
	LD BC, WA
	ADD BC, 0102h
	LD XWA, (XIZ + 023h)
	LD HL, (XWA + BC)
	LD WA, HL
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	ADD XBC, XBC
	ADD (XSP + 004h), XBC

; ----------------------------------------------------------------------------
; WaveSel_StageB_Store_Reg040 - shared tail: publish the wave word and the trim
; Entry: stack +4 = the selected zone record, XIZ = voice descriptor
; Exit:  (TG_Scratch_Reg040) = record[0];  desc+0x0F = record address
;        desc+0x01 |= 0x4000;  (WaveSel_Zone_Trim) = record[+0x04]
; Notes: MEASURED.  Same stores as WaveSel_Emit_ZoneRecord_S6, plus a class
;        doubling gated on (ToneGen_GlobalFlags) bit 2:
;            class = (word & 0xF000) * 2 ; word = (word & 0x0FFF) | class
;        MEASURED live: ToneGen_GlobalFlags = 0x0208 there, so bit 2 is clear and
;        no doubling happens in the shipped configuration.
; ----------------------------------------------------------------------------
WaveSel_StageB_Store_Reg040:	; 02399Dh
	LD XWA, (XSP + 004h)
	LD (XIZ + 00fh), XWA
	ORW (XIZ + 001h), 4000h
	LD XWA, (XSP + 004h)
	LD WA, (XWA)
	LD (0451CEh), WA
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 004h)
	LD (293Eh), WA
	LD WA, (041343h)
	BIT 2, WA
	JR Z, WaveSel_StageB_Store_Reg040_Return
	LD WA, (0451CEh)
	AND WA, 0f000h
	ADD WA, WA
	ANDW (0451CEh), 0fffh
	OR (0451CEh), WA

WaveSel_StageB_Store_Reg040_Return:
	POP XIZ
	INC 4, XSP
	RET

Voice_Vol_ScaleVelocityWord:
	LD XBC, (1040h)
	LD XWA, XBC
	CALL FP_MulAccum64
	SRL 2, XHL
	AND XHL, 000000ffh
	LD A, L
	EXTS WA
	MULS_WA 00dh
	SRA 7, WA
	LD (041366h), WA
	RET

; ----------------------------------------------------------------------------
; Pitch_Apply_Partial_Detune - add the zone trim and the per-partial detunes
; Entry: XWA = voice descriptor, desc[+0x06] already set by Voice_Pitch_Compute
; Exit:  desc[+0x0a] = detuned log pitch; desc[+0x01] bit 10 set/cleared (BEND enable)
; Notes: desc[+0x0a] = desc[+0x06]
;                    + (WaveSel_Zone_Trim)          per-zone tuning trim, 1/256 semitone,
;                                                   deposited by the record builder that
;                                                   ran inside WaveSel_StageB_Build_Reg040
;                    + sext(partial_blk[+0x05])*2   PARTIAL FINE TRANSPOSE (x2)
;                    + sext(desc[+0x27][+0x21])     UNISON / SLOT DETUNE
;                    + (part[+0x14])                part fine tune -- MIDI PITCH BEND
;                                                   lands here (Voice_PitchBend)
;        desc[+0x01] bit 10 is set only when part[+0x0a] bit 2 AND tone record byte
;        [+0x10] bit 5 are both set; Pitch_Emit_Reg400 then adds the live bend value.
;        MEASURED: notes/audit/kn5000-audit-pitch.md 1.2.
; ----------------------------------------------------------------------------
Pitch_Apply_Partial_Detune:		; 023A05h
	LD DE, (XWA + 006h)
	ADD DE, (293Eh)
	LD XBC, (XWA + 017h)
	LD C, (XBC + 005h)
	EXTS BC
	ADD BC, BC
	ADD DE, BC
	LD XBC, (XWA + 027h)
	LD C, (XBC + 021h)
	EXTS BC
	ADD DE, BC
	LD XBC, (XWA + 023h)
	ADD DE, (XBC + 014h)
	LD (XWA + 00ah), DE
	LD XBC, (XWA + 023h)
	LD BC, (XBC + 00ah)
	BIT 2, BC
	JR Z, Pitch_Apply_Partial_Detune_ClearBit
	LD XBC, (XWA + 013h)
	BIT 5, (XBC + 010h)
	JR Z, Pitch_Apply_Partial_Detune_ClearBit
	ORW (XWA + 001h), 0400h
	RET

Pitch_Apply_Partial_Detune_ClearBit:
	ANDW (XWA + 001h), 0fbffh
	RET

; ----------------------------------------------------------------------------
; Pitch_Emit_Reg400 - final master tune / detune / bend, then ship to chip reg +0x400
; Entry: XWA = voice descriptor with desc[+0x0a] set by Pitch_Apply_Partial_Detune
; Exit:  TG_Scratch_Reg400 (0x0451DA) = saturated log pitch; HL = same value
; Notes: value = desc[+0x0a] + (Pitch_MasterFineTune)
;                            +- (part[+0x1d])  when desc[+0x27][+0x18] bit 4 is set
;                                              (bit 5 selects the sign: set = subtract)
;                            +  (Pitch_BendValue) when desc[+0x01] bit 10 is set
;        then Pitch_Saturate_15bit.  ToneGen_WriteVoiceParams ships scratch +0x0e to
;        chip register voice+0x400; ToneGen_WriteVoicePitch ships that word alone.
;        MEASURED: notes/audit/kn5000-audit-pitch.md 1.2/1.3.
; ----------------------------------------------------------------------------
Pitch_Emit_Reg400:		; 023A4Ah
	LD DE, (XWA + 00ah)
	ADD DE, (041347h)
	LD XBC, (XWA + 027h)
	LD BC, (XBC + 018h)
	BIT 4, BC
	JR Z, Voice_Pitch_Legato_StoreOutput
	LD XBC, (XWA + 027h)
	LD BC, (XBC + 018h)
	BIT 5, BC
	JR Z, Voice_Pitch_Legato_DetuneDown
	LD XBC, (XWA + 023h)
	SUB DE, (XBC + 01dh)
	JR T, Voice_Pitch_Legato_StoreOutput

Voice_Pitch_Legato_DetuneDown:
	LD XBC, (XWA + 023h)
	ADD DE, (XBC + 01dh)

Voice_Pitch_Legato_StoreOutput:
	LD WA, (XWA + 001h)
	BIT 0ah, WA
	JR Z, Voice_Pitch_Legato_StoreOutput_Return
	ADD DE, (04135Ah)

Voice_Pitch_Legato_StoreOutput_Return:
	LD WA, DE
	CALR Pitch_Saturate_15bit
	LD (0451DAh), HL
	RET

; ----------------------------------------------------------------------------
; Pitch_Apply_Zone_Trim - short form of Pitch_Apply_Partial_Detune (trim only)
; Entry: XWA = voice descriptor with desc[+0x06] set
; Exit:  desc[+0x0a] = desc[+0x06] + (WaveSel_Zone_Trim)
; Notes: No partial fine / slot detune / part fine tune terms.  Used by the short
;        (12-builder) note-on chain.  MEASURED (code read, this pass).
; ----------------------------------------------------------------------------
Pitch_Apply_Zone_Trim:		; 023A8Eh
	LD BC, (XWA + 006h)
	ADD BC, (293Eh)
	LD (XWA + 00ah), BC
	RET

Voice_Pitch_WriteOutputReg_Secondary:
	LD DE, (XWA + 00ah)
	ADD DE, (041347h)
	LD XBC, (XWA + 027h)
	LD BC, (XBC + 018h)
	BIT 4, BC
	JR Z, Voice_Pitch_Secondary_StoreOutput
	LD XBC, (XWA + 027h)
	LD BC, (XBC + 018h)
	BIT 5, BC
	JR Z, Voice_Pitch_Secondary_DetuneDown
	LD XWA, (XWA + 023h)
	SUB DE, (XWA + 01dh)
	JR T, Voice_Pitch_Secondary_StoreOutput

Voice_Pitch_Secondary_DetuneDown:
	LD XWA, (XWA + 023h)
	ADD DE, (XWA + 01dh)

Voice_Pitch_Secondary_StoreOutput:
	LD WA, DE
	CALR Pitch_Saturate_15bit
	LD (0451DAh), HL
	RET

Voice_Level_ComputeTriplet:
	LDA XSP, XSP - 16
	PUSH XIZ
	LD (XSP + 010h), XWA
	LD XWA, (XSP + 16)
	LD XIZ, (XWA + 017h)
	CP (XIZ + 007h), 000h
	JR GE, Voice_Level_Triplet_Positive
	LD A, (XIZ + 00ah)
	EXTS WA
	CPL WA
	INC 1, WA
	LD (XSP + 004h), WA
	LD A, (XIZ + 00ch)
	EXTS WA
	CPL WA
	INC 1, WA
	LD (XSP + 006h), WA
	LD A, (XIZ + 00eh)
	EXTS WA
	CPL WA
	INC 1, WA
	LD (XSP + 008h), WA
	JR T, Voice_Level_Triplet_ModByEnv

Voice_Level_Triplet_Positive:
	LD A, (XIZ + 00ah)
	EXTS WA
	LD (XSP + 004h), WA
	LD A, (XIZ + 00ch)
	EXTS WA
	LD (XSP + 006h), WA
	LD A, (XIZ + 00eh)
	EXTS WA
	LD (XSP + 008h), WA

Voice_Level_Triplet_ModByEnv:
	CP (XIZ + 011h), 000h
	JRL Z, Voice_Level_Triplet_Unmodulated
	LD A, (XIZ + 011h)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 010h)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 4
	CALR PitchBend_Scale
	CP (XIZ + 009h), 000h
	JR Z, Voice_Level_Ch1_Unmodulated
	LD DE, HL
	LD A, (XIZ + 009h)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	ADD WA, DE
	LD (XSP + 00ah), WA
	JR T, Voice_Level_Ch2_Modulated

Voice_Level_Ch1_Unmodulated:
	LD A, (XIZ + 009h)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 00ah), WA

Voice_Level_Ch2_Modulated:
	CP (XIZ + 00bh), 000h
	JR Z, Voice_Level_Ch2_Unmodulated
	LD DE, HL
	LD A, (XIZ + 00bh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	ADD WA, DE
	LD (XSP + 00ch), WA
	JR T, Voice_Level_Ch3_Modulated

Voice_Level_Ch2_Unmodulated:
	LD A, (XIZ + 00bh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 00ch), WA

Voice_Level_Ch3_Modulated:
	CP (XIZ + 00dh), 000h
	JR Z, Voice_Level_Ch3_Unmodulated
	LD A, (XIZ + 00dh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	ADD WA, HL
	LD (XSP + 00eh), WA
	JR T, Voice_Level_ApplyVelocityMod

Voice_Level_Ch3_Unmodulated:
	LD A, (XIZ + 00dh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 00eh), WA
	JR T, Voice_Level_ApplyVelocityMod

Voice_Level_Triplet_Unmodulated:
	LD A, (XIZ + 009h)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 00ah), WA
	LD A, (XIZ + 00bh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 00ch), WA
	LD A, (XIZ + 00dh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 00eh), WA

Voice_Level_ApplyVelocityMod:
	CP (XIZ + 014h), 000h
	JR Z, Voice_Level_PackAndStore
	LD A, (XIZ + 013h)
	LD C, A
	EXTZ BC
	PUSHW 007fh
	LD A, (XIZ + 014h)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 014h)
	LD WA, (XWA + 008h)
	LD DE, 0
	CALR Pan_ScaleWithVelocity
	ADD (XSP + 00ah), HL

Voice_Level_PackAndStore:
	LD WA, (XSP + 00ah)
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ah), HL
	LD WA, (XSP + 004h)
	CALR Detune_ScaleSymmetric
	LD (XSP + 004h), HL
	LD WA, (XSP + 004h)
	LD_W 000h
	LD BC, (XSP + 00ah)
	SLA 8, BC
	OR BC, WA
	LD (0451ECh), BC
	CP (XIZ + 015h), 000h
	JR Z, Voice_Level_PackAndStore_NoVelocityMod
	LD A, (XIZ + 013h)
	LD C, A
	EXTZ BC
	PUSHW 007fh
	LD A, (XIZ + 015h)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 014h)
	LD WA, (XWA + 008h)
	LD DE, 0
	CALR Pan_ScaleWithVelocity
	LD IZ, HL
	LD WA, (XSP + 00ch)
	ADD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ch), HL
	LD WA, (XSP + 00eh)
	ADD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00eh), HL
	JR T, Voice_Level_PackSideChannels

Voice_Level_PackAndStore_NoVelocityMod:
	LD WA, (XSP + 00ch)
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ch), HL
	LD WA, (XSP + 00eh)
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00eh), HL

Voice_Level_PackSideChannels:
	LD WA, (XSP + 006h)
	CALR Detune_ScaleSymmetric
	LD (XSP + 006h), HL
	LD WA, (XSP + 008h)
	CALR Detune_ScaleSymmetric
	LD (XSP + 008h), HL
	LD WA, (XSP + 006h)
	LD_W 000h
	LD BC, (XSP + 00ch)
	SLA 8, BC
	OR BC, WA
	LD (0451EEh), BC
	LD WA, (XSP + 008h)
	LD_W 000h
	LD BC, (XSP + 00eh)
	SLA 8, BC
	OR BC, WA
	LD (0451F0h), BC
	POP XIZ
	LDA XSP, XSP + 010h
	RET

; ----------------------------------------------------------------------------
; TVF_Build_Full - the TVF builder used by every stock sound (mode 1)
; Entry: XWA = voice descriptor; VP = desc[+0x17], part struct = desc[+0x23]
; Exit:  desc[+0x42] = +0x100 word, desc[+0x44] = +0x140 word
; Notes: V = TVF_Calc_Cutoff(base = VP[+0x4d] + sext(part[+0x67]),
;                            veldepth = sext(VP[+0x37]),
;                            keydepth = sext(VP[+0x3c]))
;        desc[+0x42] = ((VP[+0x4e] & 7) << 13) | 0x0400 | V
;        desc[+0x44] = TVF_Lookup_Depth_Amount(VP[+0x50]) | TVF_Bias_Clamp_Amount(VP[+0x4f])
;        Bit 10 (the 0x0400) marks "computed cutoff present"; the bypass constant
;        0x017F does not carry it.
;        REFINEMENT of notes/audit/kn5000-audit-timbre.md 1.3: when Part_PresentWord
;        bit 9 is set the +0x140 word is built from the CONSTANTS 0x48 and 0x8D
;        instead of VP[+0x4f]/VP[+0x50].  MEASURED (code read, this pass).
; ----------------------------------------------------------------------------
TVF_Build_Full:		; 023D01h
	DEC 8, XSP
	PUSH IZ
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 067h)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 04dh)
	LD IZL, A
	EXTZ IZ
	ADD IZ, BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 037h)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 002h)
	LD A, (XWA + 03ch)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 008h)
	LD BC, IZ
	CALR TVF_Calc_Cutoff
	LD IZ, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 04eh)
	EXTZ WA
	SLL 0dh, WA
	LD DE, WA
	SET 0ah, DE
	LD WA, IZ
	LD BC, WA
	OR BC, DE
	LD XWA, (XSP + 006h)
	LD (XWA + 042h), BC
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD WA, (XWA + 002h)
	BIT 9, WA
	JR Z, TVF_Build_Full_UseVoiceLUT
	LD WA, 0048h
	CALR TVF_Bias_Clamp_Amount
	LD IZ, HL
	LD WA, 008dh
	CALR TVF_Lookup_Depth_Amount
	LD WA, IZ
	LD BC, WA
	OR BC, HL
	LD XWA, (XSP + 006h)
	LD (XWA + 044h), BC
	JR T, TVF_Build_Full_Return

TVF_Build_Full_UseVoiceLUT:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 04fh)
	EXTZ WA
	CALR TVF_Bias_Clamp_Amount
	LD IZ, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 050h)
	EXTZ WA
	CALR TVF_Lookup_Depth_Amount
	LD WA, IZ
	LD BC, WA
	OR BC, HL
	LD XWA, (XSP + 006h)
	LD (XWA + 044h), BC

TVF_Build_Full_Return:
	POP IZ
	INC 8, XSP
	RET

Voice_PitchPack_Mode2:
