	PUSH IZ
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD WA, (XWA + 002h)
	BIT 9, WA
	JR Z, Voice_PitchPack_Mode2_AltPath
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 067h)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 04dh)
	LD IZL, A
	EXTZ IZ
	SUB IZ, BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 037h)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 002h)
	LD A, (XWA + 03ch)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 008h)
	LD BC, IZ
	CALR TVF_Calc_Cutoff
	LD IZ, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 04eh)
	EXTZ WA
	SLL 0dh, WA
	LD BC, WA
	SET 0ah, BC
	LD WA, IZ
	OR WA, BC
	LD BC, WA
	SET 7, BC
	LD XWA, (XSP + 006h)
	LD (XWA + 042h), BC
	LD WA, 0048h
	CALR TVF_Bias_Clamp_Amount
	LD IZ, HL
