	LD XWA, (XSP + 002h)
	LD A, (XWA + 037h)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 002h)
	LD A, (XWA + 03ch)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 008h)
	LD BC, IZ
	CALR TVF_Calc_Cutoff
	LD IZ, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 04eh)
	EXTZ WA
	SLL 0dh, WA
	LD BC, WA
	SET 0ah, BC
	LD WA, IZ
	OR WA, BC
	LD BC, WA
	SET 7, BC
	LD XWA, (XSP + 006h)
	LD (XWA + 042h), BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 04fh)
	EXTZ WA
	CALR TVF_Bias_Clamp_Amount
	LD IZ, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 050h)
