Voice_PitchPack_Mode4_Single:
	DEC 4, XSP
	PUSH XIZ
	LD (XSP + 004h), XWA
	LD XWA, (XSP + 004h)
	LD XIZ, (XWA + 017h)
	LD XWA, (XSP + 004h)
	LD XWA, (XWA + 023h)
	LD WA, (XWA + 002h)
	BIT 9, WA
	JR Z, Voice_PitchPack_Mode4_AltPath
	LD L, (XIZ + 04dh)
	EXTZ HL
	JR T, Voice_PitchPack_Mode4_Finalize

Voice_PitchPack_Mode4_AltPath:
	LD XWA, (XSP + 004h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 067h)
	EXTS WA
	LD L, (XIZ + 04dh)
	EXTZ HL
	ADD HL, WA

Voice_PitchPack_Mode4_Finalize:
	LD A, (XIZ + 037h)
	LD E, A
	EXTS DE
	LD A, (XIZ + 03ch)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 006h)
	LD BC, HL
	CALR TVF_Calc_Cutoff
	LD A, (XIZ + 04eh)
	EXTZ WA
	LD BC, WA
	SLL 0ah, BC
	LD A, (XIZ + 04eh)
	EXTZ WA
	LD DE, WA
	SLL 0dh, DE
	OR DE, BC
	LD WA, HL
	OR WA, DE
	LD BC, WA
	SET 7, BC
	LD XWA, (XSP + 004h)
	LD (XWA + 042h), BC
	SET 7, HL
	LD XWA, (XSP + 004h)
	LD (XWA + 044h), HL
	LDW (2940h), 0000h
	POP XIZ
	INC 4, XSP
	RET

Voice_PitchPack_Mode5_Dual:
	DEC 8, XSP
	PUSH XIZ
	LD (XSP + 008h), XWA
	LD XWA, (XSP + 008h)
	LD XIZ, (XWA + 017h)
	LD XWA, (XSP + 008h)
	LD XWA, (XWA + 023h)
	LD WA, (XWA + 002h)
	BIT 9, WA
	JR Z, Voice_PitchPack_Mode5_ApplyDetune
	LD A, (XIZ + 04dh)
	EXTZ WA
	LD (XSP + 004h), WA
	LD A, (XIZ + 04fh)
	EXTZ WA
	LD (XSP + 006h), WA
	JR T, Voice_PitchPack_Mode5_Finalize

Voice_PitchPack_Mode5_ApplyDetune:
	LD XWA, (XSP + 008h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 067h)
	LD C, A
	EXTS BC
	LD A, (XIZ + 04dh)
	EXTZ WA
	ADD WA, BC
	LD (XSP + 004h), WA
	LD XWA, (XSP + 008h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 067h)
	LD C, A
	EXTS BC
	LD A, (XIZ + 04fh)
	EXTZ WA
	ADD WA, BC
	LD (XSP + 006h), WA

Voice_PitchPack_Mode5_Finalize:
	LD A, (XIZ + 037h)
	LD E, A
	EXTS DE
	LD A, (XIZ + 03ch)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 00ah)
	LD BC, (XSP + 006h)
	CALR TVF_Calc_Cutoff
	LD (XSP + 004h), HL
	LD A, (XIZ + 037h)
	LD E, A
	EXTS DE
	LD A, (XIZ + 03ch)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 00ah)
	LD BC, (XSP + 008h)
	CALR TVF_Calc_Cutoff
	LD (XSP + 006h), HL
	LD A, (XIZ + 050h)
	EXTZ WA
	LD BC, WA
	SLL 0ah, BC
	LD A, (XIZ + 04eh)
	EXTZ WA
	LD DE, WA
	SLL 0dh, DE
	OR DE, BC
	LD WA, (XSP + 004h)
	OR WA, DE
	LD BC, WA
	SET 7, BC
	LD XWA, (XSP + 008h)
	LD (XWA + 042h), BC
	LD XWA, (XSP + 008h)
	LD BC, (XSP + 006h)
	LD (XWA + 044h), BC
	LDW (2940h), 0000h
	POP XIZ
	INC 8, XSP
	RET

; ----------------------------------------------------------------------------
; TVF_Build_Dispatch - select the TVF (filter/brightness) builder for this partial
; Entry: XWA = voice descriptor; partial block VP = desc[+0x17]
; Exit:  desc[+0x42] (-> chip +0x100) and desc[+0x44] (-> chip +0x140) built
; Notes: Dispatches on VP[+0x36] & 7 through the 6-entry offset table at 0xF6A7,
;        relative to the JRL block that follows: 0 -> TVF_Set_Bypass, 1 -> TVF_Build_Full,
;        2 -> Voice_PitchPack_Mode2, 3 -> Voice_PitchPack_Mode3, 4 -> Voice_PitchPack_Mode4_Single, 5 -> Voice_PitchPack_Mode5_Dual.
;        Values 6 and 7 fall through to the bypass entry.  Every stock sound in the 16
;        SOUND-GROUP defaults and the 20 PIANO variants uses mode 1.  MEASURED:
;        notes/audit/kn5000-audit-timbre.md 1.3.
; ----------------------------------------------------------------------------
TVF_Build_Dispatch:		; 024102h
	LD XBC, (XWA + 017h)
	LD C, (XBC + 036h)
	AND C, 007h
	EXTZ BC
	CP BC, 0
	JR MI, TVF_Build_Dispatch_Table
	CP BC, 5
	JR GT, TVF_Build_Dispatch_Table
	ADD BC, BC
	LDA XIX, 0F6A7h:24
	LD BC, (XIX + BC)
	LDA XIX, 02412Bh:24
	JP T, XIX + BC

TVF_Build_Dispatch_Table:
	JRL T, TVF_Set_Bypass
	JRL T, TVF_Build_Full
	JRL T, Voice_PitchPack_Mode2
	JRL T, Voice_PitchPack_Mode3
	JRL T, Voice_PitchPack_Mode4_Single
	CALR Voice_PitchPack_Mode5_Dual
	RET

; ----------------------------------------------------------------------------
; TVF_Build_Short - TVF builder for the short (12-builder) note-on chain
; Entry: XWA = voice descriptor; VP = desc[+0x17]
; Exit:  desc[+0x42] = +0x100 word, desc[+0x44] = +0x140 word
; Notes: Same register layout as TVF_Build_Full but reads the parallel parameter set
;        VP[+0x0f..+0x14]: [+0x0f] bits2:0 builder select and bits7:5 velocity curve,
;        [+0x10] velocity depth, [+0x11] base cutoff, [+0x12] -> +0x100 bits15:13,
;        [+0x13] -> +0x140 low 7 bits, [+0x14] -> depth amount index.  There is NO
;        key-follow term (TVF_Calc_Cutoff_NoKeyFollow).
;        CORRECTION: notes/audit/kn5000-audit-pitch.md 1.3 and its GAP 9 call the
;        TVF_BuildEmit_Short_Dispatch family an LFO (rate/depth/delay/waveform).  It
;        is not: it fills the SAME +0x100/+0x140 pair with the SAME cutoff+amount
;        layout, from a shorter parameter set.  MEASURED (code read, this pass).
; ----------------------------------------------------------------------------
TVF_Build_Short:		; 02413Eh
	DEC 8, XSP
	PUSH IZ
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	LD A, (XWA + 011h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 006h)
	CALR TVF_Calc_Cutoff_NoKeyFollow
	LD IZ, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 012h)
	EXTZ WA
	SLL 0dh, WA
	LD DE, WA
	SET 0ah, DE
	LD WA, IZ
	LD BC, WA
	OR BC, DE
	LD XWA, (XSP + 006h)
	LD (XWA + 042h), BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 013h)
	EXTZ WA
	CALR TVF_Bias_Clamp_Amount
	LD IZ, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 014h)
	EXTZ WA
	CALR TVF_Lookup_Depth_Amount
	LD WA, IZ
	LD BC, WA
	OR BC, HL
	LD XWA, (XSP + 006h)
	LD (XWA + 044h), BC
	POP IZ
	INC 8, XSP
	RET

Voice_PitchPack_RouteB:
	DEC 8, XSP
	PUSH IZ
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	LD A, (XWA + 011h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 006h)
	CALR TVF_Calc_Cutoff_NoKeyFollow
	LD IZ, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 012h)
	EXTZ WA
	SLL 0dh, WA
	LD BC, WA
	SET 0ah, BC
	LD WA, IZ
	OR WA, BC
	LD BC, WA
	SET 7, BC
	LD XWA, (XSP + 006h)
	LD (XWA + 042h), BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 013h)
	EXTZ WA
	CALR TVF_Bias_Clamp_Amount
	LD IZ, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 014h)
	EXTZ WA
	CALR TVF_Lookup_Depth_Amount
	LD WA, IZ
	LD BC, WA
	OR BC, HL
	LD XWA, (XSP + 006h)
	LD (XWA + 044h), BC
	POP IZ
	INC 8, XSP
	RET

Voice_PitchPack_RouteC:
	DEC 4, XSP
	PUSH XIZ
	LD (XSP + 004h), XWA
	LD XWA, (XSP + 004h)
	LD XIZ, (XWA + 017h)
	LD A, (XIZ + 011h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 004h)
	CALR TVF_Calc_Cutoff_NoKeyFollow
	LD A, (XIZ + 012h)
	EXTZ WA
	LD BC, WA
	SLL 0ah, BC
	LD A, (XIZ + 012h)
	EXTZ WA
	LD DE, WA
	SLL 0dh, DE
	OR DE, BC
	LD WA, HL
	LD BC, WA
	OR BC, DE
	LD XWA, (XSP + 004h)
	LD (XWA + 042h), BC
	LD XWA, (XSP + 004h)
	LD (XWA + 044h), HL
	LDW (2940h), 0000h
	POP XIZ
	INC 4, XSP
	RET

Voice_PitchPack_RouteD:
	DEC 4, XSP
	PUSH XIZ
	LD (XSP + 004h), XWA
	LD XWA, (XSP + 004h)
	LD XIZ, (XWA + 017h)
	LD A, (XIZ + 011h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 004h)
	CALR TVF_Calc_Cutoff_NoKeyFollow
	LD A, (XIZ + 012h)
	EXTZ WA
	LD BC, WA
	SLL 0ah, BC
	LD A, (XIZ + 012h)
	EXTZ WA
	LD DE, WA
	SLL 0dh, DE
	OR DE, BC
	LD WA, HL
	OR WA, DE
	LD BC, WA
	SET 7, BC
	LD XWA, (XSP + 004h)
	LD (XWA + 042h), BC
	SET 7, HL
	LD XWA, (XSP + 004h)
	LD (XWA + 044h), HL
	LDW (2940h), 0000h
	POP XIZ
	INC 4, XSP
	RET

Voice_PitchPack_RouteE:
	DEC 6, XSP
	PUSH XIZ
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 006h)
	LD XIZ, (XWA + 017h)
	LD A, (XIZ + 011h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 006h)
	CALR TVF_Calc_Cutoff_NoKeyFollow
	LD (XSP + 004h), HL
	LD A, (XIZ + 013h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 006h)
	CALR TVF_Calc_Cutoff_NoKeyFollow
	LD A, (XIZ + 014h)
	EXTZ WA
	LD BC, WA
	SLL 0ah, BC
	LD A, (XIZ + 012h)
	EXTZ WA
	LD DE, WA
	SLL 0dh, DE
	OR DE, BC
	LD WA, (XSP + 004h)
	OR WA, DE
	LD BC, WA
	SET 7, BC
	LD XWA, (XSP + 006h)
	LD (XWA + 042h), BC
	LD XWA, (XSP + 006h)
	LD (XWA + 044h), HL
	LDW (2940h), 0000h
	POP XIZ
	INC 6, XSP
	RET

; ----------------------------------------------------------------------------
; TVF_BuildEmit_Short_Dispatch - build AND emit +0x100/+0x140 for the short chain
; Entry: XWA = voice descriptor; VP = desc[+0x17]
; Exit:  scratch 0x0451D4 (+0x100) and 0x0451D6 (+0x140) written
; Notes: Dispatches on VP[+0x0F] & 7 through the 6-entry offset table at 0xF6B3:
;        0 -> TVF_Set_Bypass then copy, 1 -> TVF_Build_Short, 2 -> Voice_PitchPack_RouteB,
;        3 -> Voice_PitchPack_RouteC, 4 -> Voice_PitchPack_RouteD, 5 -> Voice_PitchPack_RouteE.  Unlike the long
;        chain, build and emit are one routine (no TVF_Emit_Registers step, so no
;        live controller offset).  MEASURED.
; ----------------------------------------------------------------------------
TVF_BuildEmit_Short_Dispatch:		; 024300h
	PUSH XIZ
	LD XIZ, XWA
	LD XWA, (XIZ + 017h)
	LD A, (XWA + 00fh)
	AND A, 007h
	EXTZ WA
	CP WA, 0
	JR MI, TVF_BuildEmit_Short_Dispatch_Table
	CP WA, 5
	JR GT, TVF_BuildEmit_Short_Dispatch_Table
	ADD WA, WA
	LDA XIX, 0F6B3h:24
	LD WA, (XIX + WA)
	LDA XIX, 02432Ch
	JP T, XIX + WA

TVF_BuildEmit_Short_Dispatch_Table:
	LD XWA, XIZ
	CALR TVF_Set_Bypass
	LD WA, (XIZ + 042h)
	LD (0451D4h), WA
	LD WA, (XIZ + 044h)
	LD (0451D6h), WA
	JR T, TVF_BuildEmit_Short_Dispatch_Return
	LD XWA, XIZ
	CALR TVF_Build_Short
	JR T, TVF_BuildEmit_Short_Dispatch_Return
	LD XWA, XIZ
	CALR Voice_PitchPack_RouteB
	JR T, TVF_BuildEmit_Short_Dispatch_Return
	LD XWA, XIZ
	CALR Voice_PitchPack_RouteC
	JR T, TVF_BuildEmit_Short_Dispatch_Return
	LD XWA, XIZ
	CALR Voice_PitchPack_RouteD
	JR T, TVF_BuildEmit_Short_Dispatch_Return
	LD XWA, XIZ
	CALR Voice_PitchPack_RouteE

TVF_BuildEmit_Short_Dispatch_Return:
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; TVF_Emit_Offset_Reg100 - emit with the controller offset applied to +0x100 only
; Entry: XWA = voice descriptor
; Exit:  scratch 0x0451D4 / 0x0451D6 written
; Notes: If desc[+0x27][+0x18] bit 6 is clear the words are copied unchanged.  Else
;        cut = clamp((desc[+0x42] & 0x7F) -/+ sext(part[+0x1f]), 0, 0x78), sign from
;        bit 7, and only the low 7 bits of +0x100 are replaced.  MEASURED.
; ----------------------------------------------------------------------------
TVF_Emit_Offset_Reg100:		; 024366h
	PUSH XIZ
	LD XIZ, XWA
	LD XWA, (XIZ + 027h)
	LD WA, (XWA + 018h)
	BIT 6, WA
	JR Z, Voice_Pan_Write_AsIs
	LD XWA, (XIZ + 027h)
	LD WA, (XWA + 018h)
	BIT 7, WA
	JR Z, TVF_Emit_Offset_Reg100_Positive
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 042h)
	AND BC, 007fh
	SUB BC, WA
	LD WA, BC
	JR T, TVF_Emit_Offset_Reg100_Clamp

TVF_Emit_Offset_Reg100_Positive:
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 042h)
	AND BC, 007fh
	ADD BC, WA
	LD WA, BC

TVF_Emit_Offset_Reg100_Clamp:
	CALR TVF_Clamp_Cutoff
	LD WA, (XIZ + 042h)
	AND WA, 0ff80h
	OR WA, HL
	LD (0451D4h), WA
	JR T, Voice_Pan_WriteSecondary

Voice_Pan_Write_AsIs:
	LD WA, (XIZ + 042h)
	LD (0451D4h), WA

Voice_Pan_WriteSecondary:
	LD WA, (XIZ + 044h)
	LD (0451D6h), WA
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; TVF_Emit_Offset_Both - emit with the controller offset applied to BOTH registers
; Entry: XWA = voice descriptor
; Exit:  scratch 0x0451D4 / 0x0451D6 written
; Notes: As TVF_Emit_Offset_Reg100, but the same clamped value also replaces the low
;        7 bits of the +0x140 word.  MEASURED.
; ----------------------------------------------------------------------------
TVF_Emit_Offset_Both:		; 0243CCh
	PUSH XIZ
	LD XIZ, XWA
	LD XWA, (XIZ + 027h)
	LD WA, (XWA + 018h)
	BIT 6, WA
	JR Z, Voice_Pan_WriteBoth_AsIs
	LD XWA, (XIZ + 027h)
	LD WA, (XWA + 018h)
	BIT 7, WA
	JR Z, Voice_Pan_WriteBoth_Positive
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 042h)
	AND BC, 007fh
	SUB BC, WA
	LD HL, BC
	JR T, Voice_Pan_WriteBoth_Clamp

Voice_Pan_WriteBoth_Positive:
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 042h)
	AND BC, 007fh
	ADD BC, WA
	LD HL, BC

Voice_Pan_WriteBoth_Clamp:
	LD WA, HL
	CALR TVF_Clamp_Cutoff
	LD WA, HL
	LD BC, (XIZ + 042h)
	AND BC, 0ff80h
	OR BC, WA
	LD (0451D4h), BC
	LD WA, (XIZ + 044h)
	AND WA, 0ff80h
	OR WA, HL
	LD (0451D6h), WA
	JR T, Voice_Pan_WriteBoth_Return

Voice_Pan_WriteBoth_AsIs:
	LD WA, (XIZ + 042h)
	LD (0451D4h), WA
	LD WA, (XIZ + 044h)
	LD (0451D6h), WA

Voice_Pan_WriteBoth_Return:
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; TVF_Emit_Registers - ship +0x100 / +0x140 to the scratch, with the live offset
; Entry: XWA = voice descriptor with desc[+0x42] / desc[+0x44] built
; Exit:  scratch 0x0451D4 (+0x100) and 0x0451D6 (+0x140) written
; Notes: Dispatches on VP[+0x36] & 7 through the 6-entry offset table at 0xF6BF,
;        offsets {0, 0x13, 0x13, 0x1B, 0x36, 0x3E} relative to the plain-copy case.
;        Mode 0 copies the two words unchanged; the others route through
;        TVF_Emit_Offset_Reg100 or TVF_Emit_Offset_Both, which add or subtract the
;        live controller value part[+0x1f] from the cutoff field, gated on
;        desc[+0x27][+0x18] bit 6 (enable) and bit 7 (direction), re-clamped by
;        TVF_Clamp_Cutoff.  MEASURED.
; ----------------------------------------------------------------------------
TVF_Emit_Registers:		; 024444h
	DEC 2, XSP
	PUSH XIZ
	LD XIZ, XWA
	LD XWA, (XIZ + 017h)
	LD A, (XWA + 036h)
	AND A, 007h
	EXTZ WA
	CP WA, 0
	JR MI, TVF_Emit_Registers_Table
	CP WA, 5
	JR GT, TVF_Emit_Registers_Table
	ADD WA, WA
	LDA XIX, 0F6BFh:24
	LD WA, (XIX + WA)
	LDA XIX, 024472h
	JP T, XIX + WA

TVF_Emit_Registers_Table:
	LD WA, (XIZ + 042h)
	LD (0451D4h), WA
	LD WA, (XIZ + 044h)
	LD (0451D6h), WA
	JRL T, TVF_Emit_Registers_Return
	LD XWA, XIZ
	CALR TVF_Emit_Offset_Reg100
	JRL T, TVF_Emit_Registers_Return
	LD XWA, (XIZ + 023h)
	LD WA, (XWA + 002h)
	BIT 9, WA
	JR Z, Voice_PanReg_Dispatch_Mode2_CheckBit9
	LD XWA, XIZ
	CALR TVF_Emit_Offset_Reg100
	JRL T, TVF_Emit_Registers_Return

Voice_PanReg_Dispatch_Mode2_CheckBit9:
	LD XWA, XIZ
	CALR TVF_Emit_Offset_Both
	JRL T, TVF_Emit_Registers_Return
	LD XWA, XIZ
	CALR TVF_Emit_Offset_Both
	JRL T, TVF_Emit_Registers_Return
	LD XWA, (XIZ + 027h)
	LD WA, (XWA + 018h)
	BIT 6, WA
	JRL Z, Voice_PanReg_Dispatch_Mode5_AsIs
	LD XWA, (XIZ + 027h)
	LD WA, (XWA + 018h)
	BIT 7, WA
	JR Z, Voice_PanReg_Dispatch_Mode5_Positive
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 042h)
	AND BC, 007fh
	SUB BC, WA
	LD DE, BC
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 044h)
	AND BC, 007fh
	SUB BC, WA
	LD (XSP + 004h), BC
	JR T, Voice_PanReg_Dispatch_Mode5_Finalize

Voice_PanReg_Dispatch_Mode5_Positive:
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 042h)
	AND BC, 007fh
	ADD BC, WA
	LD DE, BC
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 044h)
	AND BC, 007fh
	ADD BC, WA
	LD (XSP + 004h), BC

Voice_PanReg_Dispatch_Mode5_Finalize:
	LD WA, DE
	CALR TVF_Clamp_Cutoff
	LD WA, (XIZ + 042h)
	AND WA, 0ff80h
	OR WA, HL
	LD (0451D4h), WA
	LD WA, (XSP + 004h)
	CALR TVF_Clamp_Cutoff
	LD WA, (XIZ + 044h)
	AND WA, 0ff80h
	OR WA, HL
	LD (0451D6h), WA
	JR T, TVF_Emit_Registers_Return

Voice_PanReg_Dispatch_Mode5_AsIs:
	LD WA, (XIZ + 042h)
	LD (0451D4h), WA
	LD WA, (XIZ + 044h)
	LD (0451D6h), WA

TVF_Emit_Registers_Return:
	POP XIZ
	INC 2, XSP
	RET

Voice_PanReg_WriteDispatchB:
	DEC 2, XSP
	PUSH XIZ
	LD XIZ, XWA
	LD XWA, (XIZ + 017h)
	LD A, (XWA + 00fh)
	AND A, 007h
	EXTZ WA
	CP WA, 0
	JR MI, Voice_PanReg_WriteDispatchB_Table
	CP WA, 5
	JR GT, Voice_PanReg_WriteDispatchB_Table
	ADD WA, WA
	LDA XIX, 0F6CBh:24
	LD WA, (XIX + WA)
	LDA XIX, 024582h
	JP T, XIX + WA

Voice_PanReg_WriteDispatchB_Table:
	LD WA, (XIZ + 042h)
	LD (0451D4h), WA
	LD WA, (XIZ + 044h)
	LD (0451D6h), WA
	JRL T, Voice_PanReg_WriteDispatchB_Return
	LD XWA, XIZ
	CALR TVF_Emit_Offset_Reg100
	JRL T, Voice_PanReg_WriteDispatchB_Return
	LD XWA, (XIZ + 023h)
	LD WA, (XWA + 002h)
	BIT 9, WA
	JR Z, Voice_PanReg_DispatchB_Mode2_CheckBit9
	LD XWA, XIZ
	CALR TVF_Emit_Offset_Reg100
	JRL T, Voice_PanReg_WriteDispatchB_Return

Voice_PanReg_DispatchB_Mode2_CheckBit9:
	LD XWA, XIZ
	CALR TVF_Emit_Offset_Both
	JRL T, Voice_PanReg_WriteDispatchB_Return
	LD XWA, XIZ
	CALR TVF_Emit_Offset_Both
	JRL T, Voice_PanReg_WriteDispatchB_Return
	LD XWA, (XIZ + 027h)
	LD WA, (XWA + 018h)
	BIT 6, WA
	JRL Z, Voice_PanReg_DispatchB_Mode5_AsIs
	LD XWA, (XIZ + 027h)
	LD WA, (XWA + 018h)
	BIT 7, WA
	JR Z, Voice_PanReg_DispatchB_Mode5_Positive
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 042h)
	AND BC, 007fh
	SUB BC, WA
	LD DE, BC
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 044h)
	AND BC, 007fh
	SUB BC, WA
	LD (XSP + 004h), BC
	JR T, Voice_PanReg_DispatchB_Mode5_Finalize

Voice_PanReg_DispatchB_Mode5_Positive:
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 042h)
	AND BC, 007fh
	ADD BC, WA
	LD DE, BC
	LD XWA, (XIZ + 023h)
	LD A, (XWA + 01fh)
	EXTS WA
	LD BC, (XIZ + 044h)
	AND BC, 007fh
	ADD BC, WA
	LD (XSP + 004h), BC

Voice_PanReg_DispatchB_Mode5_Finalize:
	LD WA, DE
	CALR TVF_Clamp_Cutoff
	LD WA, (XIZ + 042h)
	AND WA, 0ff80h
	OR WA, HL
	LD (0451D4h), WA
	LD WA, (XSP + 004h)
	CALR TVF_Clamp_Cutoff
	LD WA, (XIZ + 044h)
	AND WA, 0ff80h
	OR WA, HL
	LD (0451D6h), WA
	JR T, Voice_PanReg_WriteDispatchB_Return

Voice_PanReg_DispatchB_Mode5_AsIs:
	LD WA, (XIZ + 042h)
	LD (0451D4h), WA
	LD WA, (XIZ + 044h)
	LD (0451D6h), WA

Voice_PanReg_WriteDispatchB_Return:
	POP XIZ
	INC 2, XSP
	RET

Voice_StereoLevel_Compute:
	LDA XSP, XSP - 14
	PUSH IZ
	LD (XSP + 00ch), XWA
	LD XWA, (XSP + 00ch)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	CP (XWA + 047h), 000h
	JRL Z, Voice_StereoLevel_AllUnmodulated
	LD XWA, (XSP + 002h)
	LD A, (XWA + 047h)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 00ch)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 4
	CALR PitchBend_Scale
	LD XWA, (XSP + 002h)
	CP (XWA + 03fh), 000h
	JR Z, Voice_StereoLevel_Ch1_Unmodulated
	LD DE, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 03fh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	ADD WA, DE
	LD (XSP + 006h), WA
	JR T, Voice_StereoLevel_Ch2_Modulated

Voice_StereoLevel_Ch1_Unmodulated:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 03fh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 006h), WA

Voice_StereoLevel_Ch2_Modulated:
	LD XWA, (XSP + 002h)
	CP (XWA + 041h), 000h
	JR Z, Voice_StereoLevel_Ch2_Unmodulated
	LD DE, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 041h)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	ADD WA, DE
	LD (XSP + 008h), WA
	JR T, Voice_StereoLevel_Ch3_Modulated

Voice_StereoLevel_Ch2_Unmodulated:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 041h)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 008h), WA

Voice_StereoLevel_Ch3_Modulated:
	LD XWA, (XSP + 002h)
	CP (XWA + 043h), 000h
	JR Z, Voice_StereoLevel_Ch3_Unmodulated
	LD XWA, (XSP + 002h)
	LD A, (XWA + 043h)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	ADD WA, HL
	LD (XSP + 00ah), WA
	JR T, Voice_StereoLevel_ApplyTremolo

Voice_StereoLevel_Ch3_Unmodulated:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 043h)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 00ah), WA
	JR T, Voice_StereoLevel_ApplyTremolo

Voice_StereoLevel_AllUnmodulated:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 03fh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 006h), WA
	LD XWA, (XSP + 002h)
	LD A, (XWA + 041h)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 008h), WA
	LD XWA, (XSP + 002h)
	LD A, (XWA + 043h)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 00ah), WA

Voice_StereoLevel_ApplyTremolo:
	LD XWA, (XSP + 002h)
	CP (XWA + 04ah), 000h
	JR Z, Voice_StereoLevel_PackCh1
	LD XWA, (XSP + 002h)
	LD A, (XWA + 049h)
	LD C, A
	EXTZ BC
	PUSHW 007fh
	LD XWA, (XSP + 004h)
	LD A, (XWA + 04ah)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 010h)
	LD WA, (XWA + 008h)
	LD DE, 0
	CALR Pan_ScaleWithVelocity
	ADD (XSP + 006h), HL

Voice_StereoLevel_PackCh1:
	LD WA, (XSP + 006h)
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 006h), HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 03dh)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 040h)
	EXTS WA
	ADD WA, BC
	LD BC, 0032h
	LD DE, 0ffceh
	CALR ClampS16_WA_To_DEBC
	LD WA, HL
	CALR Detune_ScaleSymmetric
	LD_H 000h
	LD WA, (XSP + 006h)
	SLA 8, WA
	OR WA, HL
	LD (0451F2h), WA
	LD XWA, (XSP + 002h)
	CP (XWA + 04bh), 000h
	JR Z, Voice_StereoLevel_ClampCh23_NoMod
	LD XWA, (XSP + 002h)
	LD A, (XWA + 049h)
	LD C, A
	EXTZ BC
	PUSHW 007fh
	LD XWA, (XSP + 004h)
	LD A, (XWA + 04bh)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 010h)
	LD WA, (XWA + 008h)
	LD DE, 0
	CALR Pan_ScaleWithVelocity
	LD IZ, HL
	LD WA, (XSP + 008h)
	ADD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 008h), HL
	LD WA, (XSP + 00ah)
	ADD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ah), HL
	JR T, Voice_StereoLevel_PackCh23

Voice_StereoLevel_ClampCh23_NoMod:
	LD WA, (XSP + 008h)
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 008h), HL
	LD WA, (XSP + 00ah)
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ah), HL

Voice_StereoLevel_PackCh23:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 03dh)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 042h)
	EXTS WA
	ADD WA, BC
	LD BC, 0032h
	LD DE, 0ffceh
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	LD WA, IZ
	CALR Detune_ScaleSymmetric
	LD IZ, HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 03dh)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 044h)
	EXTS WA
	ADD WA, BC
	LD BC, 0032h
	LD DE, 0ffceh
	CALR ClampS16_WA_To_DEBC
	LD WA, HL
	CALR Detune_ScaleSymmetric
	LD WA, IZ
	LD_W 000h
	LD BC, (XSP + 008h)
	SLA 8, BC
	OR BC, WA
	LD (0451F4h), BC
	LD_H 000h
	LD WA, (XSP + 00ah)
	SLA 8, WA
	OR WA, HL
	LD (0451F6h), WA
	POP IZ
	LDA XSP, XSP + 00eh
	RET

Voice_PortaLevel_Compute:
	LDA XSP, XSP - 12
	PUSH IZ
	LD (XSP + 00ah), XWA
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	CP (XWA + 007h), 000h
	JR GE, Voice_PortaLevel_Compute_Positive
	LD XWA, (XSP + 002h)
	LD A, (XWA + 007h)
	EXTS WA
	CPL WA
	INC 1, WA
	CALR Detune_ScaleUnsigned
	LD (XSP + 008h), HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 008h)
	EXTS WA
	CPL WA
	INC 1, WA
	CALR Detune_ScaleSymmetric
	LD (XSP + 006h), HL
	JR T, Voice_PortaLevel_ScaleAndPack

Voice_PortaLevel_Compute_Positive:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 007h)
	EXTS WA
	CALR Detune_ScaleUnsigned
	LD (XSP + 008h), HL
	LD XWA, (XSP + 002h)
	LD A, (XWA + 008h)
	EXTS WA
	CALR Detune_ScaleSymmetric
	LD (XSP + 006h), HL

Voice_PortaLevel_ScaleAndPack:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 012h)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 00ah)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 6
	CALR PitchBend_Scale
	ADD (XSP + 008h), HL
	LD WA, (XSP + 008h)
	LD BC, 007fh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 008h), HL
	LD IZ, 007fh
	LD XWA, (XSP + 002h)
	LD A, (XWA + 048h)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 00ah)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 6
	CALR PitchBend_Scale
	ADD IZ, HL
	LD WA, IZ
	LD BC, 007fh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	LD WA, IZ
	LD BC, WA
	LD_B 000h
	LD WA, (XSP + 008h)
	SLL 8, WA
	OR WA, BC
	LD (0451E2h), WA
	LD XWA, (XSP + 002h)
	LD C, (XWA + 03dh)
	LD XWA, (XSP + 002h)
	ADD C, (XWA + 03eh)
	LD A, C
	EXTS WA
	CALR Detune_ScaleSymmetric
	LD_H 000h
	LD WA, (XSP + 006h)
	SLL 8, WA
	OR WA, HL
	LD (0451EAh), WA
	POP IZ
	LDA XSP, XSP + 00ch
	RET

Voice_Level_ClearAllOutputRegs:
	LD XHL, (XWA + 017h)
	LDW (0451EAh), 0000h
	LDW (0451E2h), 0000h
	LDW (0451ECh), 0000h
	LDW (0451EEh), 0000h
	LDW (0451F0h), 0000h
	LDW (0451F2h), 0000h
	LDW (0451F4h), 0000h
	LDW (0451F6h), 0000h
	LDW (0451DCh), 0000h
	LDW (0451DEh), 0000h
	LD C, (XWA + 004h)
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 04138Eh
	CP (XDE + BC), 001h
	JR NZ, Voice_Level_ClearAllOutputRegs_Check2
	LDW (XWA + 02bh), 0000h
	JR T, Voice_Level_ClearAllOutputRegs_Store

Voice_Level_ClearAllOutputRegs_Check2:
	LD C, (XWA + 004h)
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 04138Eh
	CP (XDE + BC), 002h
	JR NZ, Voice_Level_ClearAllOutputRegs_FromTable
	LDW (XWA + 02bh), 007fh
	JR T, Voice_Level_ClearAllOutputRegs_Store

Voice_Level_ClearAllOutputRegs_FromTable:
	LD C, (XHL)
	EXTZ BC
	LD (XWA + 02bh), BC

Voice_Level_ClearAllOutputRegs_Store:
	LD WA, (XWA + 02bh)
	LD (0451D8h), WA
	LDW (0451E0h), 0000h
	RET

Voice_OpSlot_WriteParams:
	LDA XSP, XSP - 12
	PUSH XIZ
	LD (XSP + 00ch), XBC
	LD L, (XSP + 016h)
	LD C, E
	EXTZ BC
	LD IX, BC
	SLA 2, IX
	LD C, L
	EXTZ BC
	SLA 4, BC
	LD IY, BC
	ADD IY, IX
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XIX, 04136Eh
	LD XBC, (XIX + BC)
	LDA XBC, XBC + IY
	LD (XSP + 004h), XBC
	LD XBC, 0000002bh
	ADD (XSP + 004h), XBC
	LD C, L
	EXTZ BC
	MULS_BC 0009h
	LD IY, BC
	LD C, (XSP + 014h)
	EXTZ BC
	MULS_BC 001bh
	LDA XIX, 04424Eh
	EXTS XBC
	ADD XBC, XIX
	LDA XIZ, XBC + IY
	LD C, E
	EXTZ BC
	LD IX, BC
	SLA 2, IX
	LD C, L
	EXTZ BC
	SLA 4, BC
	LD IY, BC
	ADD IY, IX
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	EXTS XWA
	ADD XWA, XBC
	LDA XWA, XWA + IY
	LD (XSP + 008h), XWA
	LD XWA, 00000027h
	ADD (XSP + 008h), XWA
	CP L, 2
	JR Z, Voice_OpSlot_WriteParams_Direct
	CP E, 0
	JR NZ, Voice_OpSlot_WriteParams_Direct
	CP (0451A7h), 0f5h
	JR Z, Voice_OpSlot_WriteParams_Direct
	LD XWA, (XSP + 00ch)
	LD A, (XWA + 068h)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	ADD WA, BC
	LD BC, 007fh
	LD DE, 0
	CALR ClampS16_WA_Short
	LD (XIZ + 001h), L
	LD XWA, (XSP + 00ch)
	LD A, (XWA + 069h)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 004h)
	LD A, (XWA + 001h)
	EXTZ WA
	ADD WA, BC
	LD BC, 007fh
	LD DE, 0
	CALR ClampS16_WA_Short
	LD (XIZ + 003h), L
	LD XWA, (XSP + 00ch)
	LD A, (XWA + 06ah)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 004h)
	LD A, (XWA + 003h)
	AND A, 03fh
	EXTZ WA
	ADD WA, BC
	LD BC, 001eh
	LD DE, 0
	CALR ClampS16_WA_Short
	LD (XIZ + 007h), L
	JR T, Voice_OpSlot_ApplySustainPedal

Voice_OpSlot_WriteParams_Direct:
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	LD (XIZ + 001h), A
	LD XWA, (XSP + 004h)
	LD A, (XWA + 001h)
	LD (XIZ + 003h), A
	LD XWA, (XSP + 004h)
	LD A, (XWA + 003h)
	AND A, 03fh
	LD (XIZ + 007h), A

Voice_OpSlot_ApplySustainPedal:
	LD XWA, (XSP + 008h)
	BIT 1, (XWA)
	JR Z, Voice_OpSlot_SustainRelease_Set
	LD XWA, (XSP + 008h)
	LD A, (XWA + 003h)
	LD (XIZ + 002h), A
	LD (XIZ + 007h), 000h
	JR T, Voice_OpSlot_ApplySostenuto

Voice_OpSlot_SustainRelease_Set:
	LD (XIZ + 002h), 080h

Voice_OpSlot_ApplySostenuto:
	LD XWA, (XSP + 008h)
	BIT 3, (XWA)
	JR Z, Voice_OpSlot_SostenutoRelease_Set
	LD XWA, (XSP + 008h)
	LD A, (XWA + 002h)
	LD (XIZ + 004h), A
	LD (XIZ + 007h), 000h
	JR T, Voice_OpSlot_CopyWaveformBits

Voice_OpSlot_SostenutoRelease_Set:
	LD (XIZ + 004h), 080h

Voice_OpSlot_CopyWaveformBits:
	LD XWA, (XSP + 004h)
	BIT 7, (XWA + 002h)
	JR Z, Voice_OpSlot_ClearWaveformBit5
	SET 5, (XIZ)
	JR T, Voice_OpSlot_PackEnvelopeBits

Voice_OpSlot_ClearWaveformBit5:
	RES 5, (XIZ)

Voice_OpSlot_PackEnvelopeBits:
	LD XWA, (XSP + 004h)
	LD A, (XWA + 003h)
	AND A, 0c0h
	EXTZ WA
	SRL 6, WA
	AND (XIZ), 0fch
	OR (XIZ), A
	LD XWA, (XSP + 004h)
	LD A, (XWA + 002h)
	RES 7, A
	LD (XIZ + 005h), A
	POP XIZ
	LDA XSP, XSP + 00ch
	RETD 0004h

; ----------------------------------------------------------------------------
; ExtVoice_Build_SlotRegisters - fill scratch +0x10/+0x12 (registers +0x440/+0x480)
; Entry: XWA = voice descriptor
; Exit:  (TG_Scratch_Reg440), (TG_Scratch_Reg480) written
; Notes: MEASURED.  Clears both words FIRST, so the "no extended synthesis" case
;        is 0 by construction - which is what every ordinary PCM voice gets.
;        Three branches:
;          tonerec[+0x1A] != 0                       -> allocate, then ToneGen_WriteExtParam_600_Mute
;          tonerec[+0x1A] == 0, part+0x0A bit 15 set -> Voice_Chan_Fallback_NoWaveTable / Voice_Chan_SecondaryPitch_Trigger
;          otherwise                                 -> nothing further written
; ----------------------------------------------------------------------------
ExtVoice_Build_SlotRegisters:	; 024BE3h
	LDA XSP, XSP - 016h
	PUSH XIZ
	LD (XSP + 016h), XWA
	LDW (0451DCh), 0000h
	LDW (0451DEh), 0000h
	LD XWA, (XSP + 016h)
	LD XWA, (XWA + 023h)
	LD (XSP + 004h), XWA
	LD XWA, (XSP + 016h)
	LD XWA, (XWA + 027h)
	LD (XSP + 008h), XWA
	LD XWA, (XSP + 016h)
	LD A, (XWA + 004h)
	LD (XSP + 010h), A
	LD XWA, (XSP + 016h)
	LD A, (XWA + 003h)
	LD (XSP + 012h), A
	LD XWA, (XSP + 008h)
	CPW (XWA + 01ah), 0000h
	JRL Z, Voice_Chan_Fallback_NoWaveTable
	LD XWA, (XSP + 008h)
	LD WA, (XWA + 01ah)
	AND A, 003h
	LD (XSP + 014h), A
	EXTZ WA
	SLA 2, WA
	LD BC, WA
	ADD BC, 002bh
	LD XWA, (XSP + 016h)
	LD XWA, (XWA + 013h)
	LDA XWA, XWA + BC
	BIT 7, (XWA + 002h)
	JR Z, ExtVoice_Build_SlotRegisters_NoAlgoSelect
	LD A, (XSP + 010h)
	LD L, A
	EXTZ HL
	LD XWA, (XSP + 016h)
	LD A, (XWA)
	LD C, A
	EXTZ BC
	LD A, (XSP + 014h)
	EXTZ WA
	SET 5, WA
	LD E, A
	EXTZ DE
	LD WA, HL
	CALL ExtVoice_Alloc_StreamSlot
	LD (XSP + 00ch), HL
	LD WA, (XSP + 00ch)
	LD_W 000h
	LD (XSP + 00eh), WA
	CALL ToneGen_WriteExtParam_600_Mute
	JR T, ExtVoice_Store_SlotNumber

ExtVoice_Build_SlotRegisters_NoAlgoSelect:
	LD A, (XSP + 010h)
	LD L, A
	EXTZ HL
	LD XWA, (XSP + 016h)
	LD A, (XWA)
	LD C, A
	EXTZ BC
	LD A, (XSP + 014h)
	EXTZ WA
	LD E, A
	EXTZ DE
	LD WA, HL
	CALL ExtVoice_Alloc_StreamSlot
	LD (XSP + 00ch), HL
	LD WA, (XSP + 00ch)
	LD_W 000h
	LD (XSP + 00eh), WA

; ----------------------------------------------------------------------------
; ExtVoice_Store_SlotNumber - store the allocated slot into the +0x440 scratch
; Entry: stack local = slot number, XWA = voice descriptor
; Exit:  (TG_Scratch_Reg440) = (tonerec[+0x1A] & 0xC0) | slot, only if slot < 0x80
; Notes: MEASURED.  Also indexes a 0x1B-byte per-slot bookkeeping record at
;        ExtVoice_SlotRecords + 0x1B*slot and stores the voice's velocity
;        (desc+0x0C with bit 7 cleared) at its +0x06.
;        For ordinary voices this routine is never reached, so register +0x440
;        stays 0 - confirming that ExtVoice_Store_SlotNumber was mis-read as a wave-number
;        writer in the earlier notes.
; ----------------------------------------------------------------------------
ExtVoice_Store_SlotNumber:	; 024CABh
	LD WA, (XSP + 00eh)
	EXTZ XWA
	LD XBC, 0000001bh
	CALL FP_MulAccum64
	LDA XIZ, 04424Eh
	ADD XIZ, XHL
	LD XWA, (XSP + 016h)
	LD A, (XWA + 00ch)
	RES 7, A
	LD (XIZ + 006h), A
	CPW (XSP + 00eh), 0080h
	JRL NC, Voice_Chan_SecondaryPitch_Trigger
	LD XWA, (XSP + 008h)
	LD WA, (XWA + 01ah)
	AND WA, 00c0h
	OR WA, (XSP + 00eh)
	LD (0451DCh), WA
	LD WA, (XSP + 00ch)
	BIT 0fh, WA
	JR Z, Voice_Chan_WriteOpSlots
	LD XWA, (XSP + 004h)
	LD WA, (XWA)
	AND WA, 000ch
	JR Z, Voice_Chan_CheckPitchEnvGate

Voice_Chan_WriteOpSlots:
	LD A, (XSP + 010h)
	LD C, A
	EXTZ BC
	LD A, (XSP + 014h)
	LD E, A
	EXTZ DE
	PUSHW 0000h
	LD WA, (XSP + 010h)
	EXTZ WA
	PUSH WA
	LD WA, BC
	LD XBC, (XSP + 008h)
	CALR Voice_OpSlot_WriteParams
	LD WA, (XSP + 00eh)
	EXTZ WA
	CALR EGEnv_Compute_A_Simple
	LD (045208h), HL
	LD WA, (XSP + 00eh)
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParams_56_Alt

Voice_Chan_CheckPitchEnvGate:
	CP (XIZ + 007h), 000h
	JR Z, Voice_Chan_PitchEnvGate_CheckBit5
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 002h)
	BIT 0dh, WA
	JR NZ, Voice_Chan_PitchEnvGate_Trigger

Voice_Chan_PitchEnvGate_CheckBit5:
	BIT 5, (XIZ)
	JR Z, Voice_Chan_PitchEnvFreeRun_Check

Voice_Chan_PitchEnvGate_Trigger:
	LD (XIZ + 008h), 000h
	AND (XIZ), 0f3h
	SET 4, (XIZ)
	LDW (04520Ch), 0000h
	LD WA, (XSP + 00eh)
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParam_600
	JRL T, Voice_Chan_SecondaryPitch_Trigger

Voice_Chan_PitchEnvFreeRun_Check:
	CP (XIZ + 005h), 000h
	JR NZ, Voice_Chan_PitchEnvFreeRun_Trigger
	LD WA, (XSP + 00ch)
	BIT 0fh, WA
	JR NZ, Voice_Chan_ChokeGroup_Trigger

Voice_Chan_PitchEnvFreeRun_Trigger:
	LD A, (XIZ)
	AND A, 038h
	JR NZ, Voice_Chan_ChokeGroup_Trigger
	LD WA, (XSP + 00eh)
	EXTZ WA
	CALR EGEnv_Compute_A
	LD (04520Ch), HL
	LD WA, (XSP + 00eh)
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParam_600
	JRL T, Voice_Chan_SecondaryPitch_Trigger

Voice_Chan_ChokeGroup_Trigger:
	LD XWA, (XSP + 004h)
