Voice_Chan_Fallback_NoWaveTable:
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 00ah)
	EXTZ XWA
	BIT 0fh, WA
	JRL Z, Voice_Chan_SecondaryPitch_Trigger
	LD A, (XSP + 010h)
	LD E, A
	EXTZ DE
	LD A, (XSP + 012h)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 1
	CALL DSP_AlgoType_Dispatch3
	LD (XSP + 014h), HL
	CPW (XSP + 014h), 0000h
	JR Z, Voice_Chan_SecondaryPitch_Trigger
	LD A, (XSP + 010h)
	LD E, A
	EXTZ DE
	LD XWA, (XSP + 016h)
	LD A, (XWA)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 000dh
	CALL ExtVoice_Alloc_StreamSlot
	LD (XSP + 00ch), HL
	LD WA, (XSP + 00ch)
	LD_W 000h
	LD (XSP + 00eh), WA
	CPW (XSP + 00eh), 0080h
	JR NC, Voice_Chan_SecondaryPitch_Trigger
	LD WA, (XSP + 00eh)
	EXTZ WA
	LD BC, WA
	LD WA, 0
	CALR NoteState_ClearRecord
	LD WA, (XSP + 00ch)
	AND WA, 007fh
	OR WA, (XSP + 014h)
	LD (0451DCh), WA
	LD WA, (XSP + 00ch)
	BIT 0fh, WA
	JR Z, Voice_Chan_Fallback_WritePrecomputed
	LD XWA, (XSP + 004h)
	LD WA, (XWA)
	BIT 2, WA
	JR Z, Voice_Chan_SecondaryPitch_Trigger

Voice_Chan_Fallback_WritePrecomputed:
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 05bh)
	LD (04520Ch), WA
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 05dh)
	LD (045208h), WA
	LD WA, (XSP + 00eh)
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParams_56

Voice_Chan_SecondaryPitch_Trigger:
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 00ah)
	EXTZ XWA
	BIT 0fh, WA
	JRL Z, ExtVoice_Build_SlotRegisters_Return
	LD A, (XSP + 010h)
	LD E, A
	EXTZ DE
	LD A, (XSP + 012h)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 0
	CALL DSP_AlgoType_Dispatch3
	LD (XSP + 014h), HL
	CPW (XSP + 014h), 0000h
	JRL Z, ExtVoice_Build_SlotRegisters_Return
	LD A, (XSP + 010h)
	LD E, A
	EXTZ DE
	LD XWA, (XSP + 016h)
	LD A, (XWA)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 000ch
	CALL ExtVoice_Alloc_StreamSlot
	LD (XSP + 00ch), HL
	LD WA, (XSP + 00ch)
	LD_W 000h
	LD (XSP + 00eh), WA
	CPW (XSP + 00eh), 0080h
	JR NC, ExtVoice_Build_SlotRegisters_Return
	LD WA, (XSP + 00eh)
	OR WA, (XSP + 014h)
	LD (0451DEh), WA
	LD A, (XSP + 010h)
	EXTZ WA
	CALL AlgoType_AB_Checker
	CP L, 0
	JR NZ, Voice_Chan_SecondaryPitch_ComputeDelta
	LD WA, (XSP + 00ch)
	BIT 0fh, WA
	JR Z, Voice_Chan_SecondaryPitch_ComputeDelta
	LD XWA, (XSP + 004h)
	LD WA, (XWA)
	BIT 2, WA
	JR Z, ExtVoice_Build_SlotRegisters_Return

Voice_Chan_SecondaryPitch_ComputeDelta:
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 057h)
	LD (04520Eh), WA
	LD IZ, (04520Eh)
	EXTZ XIZ
	AND XIZ, 00001fffh
	LD XWA, (XSP + 016h)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD E, L
	EXTZ DE
	LD XWA, XIZ
	CALR EnvDepth_Cap
	SUB XIZ, XHL
	ANDW (04520Eh), 0e000h
	LD WA, IZ
	OR (04520Eh), WA
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 059h)
	LD (04520Ah), WA
	LD WA, (XSP + 00eh)
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParams_56b

ExtVoice_Build_SlotRegisters_Return:
	POP XIZ
	LDA XSP, XSP + 016h
	RET

Voice_SubVoice_ComputeAndTrigger:
	LDA XSP, XSP - 018h
	PUSH IZ
	LD (XSP + 016h), XWA
	LD XWA, (XSP + 016h)
	LD XWA, (XWA + 023h)
	LD (XSP + 002h), XWA
	LD XWA, (XSP + 016h)
	LD XWA, (XWA + 027h)
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 016h)
	LD A, (XWA + 004h)
	LD (XSP + 012h), A
	LD XWA, (XSP + 016h)
	LD C, (XWA + 003h)
	LDW (XSP + 010h), 0000h
	LD XWA, (XSP + 006h)
	CPW (XWA + 01ch), 0000h
	JRL Z, Voice1_UpdatePitch_AltEntry
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 01ch)
	AND A, 003h
	LD (XSP + 014h), A
	EXTZ WA
	SLA 2, WA
	LD BC, WA
	ADD BC, 003bh
	LD XWA, (XSP + 016h)
	LD XWA, (XWA + 013h)
	LDA XWA, XWA + BC
	BIT 7, (XWA + 002h)
	JR Z, Voice_SubVoice_Compute_NoAlgoSelect
	LD A, (XSP + 012h)
	LD L, A
	EXTZ HL
	LD XWA, (XSP + 016h)
	LD A, (XWA)
	LD C, A
	EXTZ BC
	LD A, (XSP + 014h)
	EXTZ WA
	OR WA, 0024h
