Voice_SubVoice_ResolveSlot:
	LD WA, IZ
	EXTZ XWA
	LD XBC, 0000001bh
	CALL FP_MulAccum64
	LDA XWA, 044257h
	ADD XWA, XHL
	LD (XSP + 00ah), XWA
	LD XWA, (XSP + 016h)
	LD XBC, (XSP + 00ah)
	LD A, (XWA + 00ch)
	LD (XBC + 006h), A
	CP IZ, 0040h
	JRL NC, Voice1_UpdatePitch_WriteStereoField
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 01ch)
	AND WA, 0c000h
	LD (XSP + 010h), WA
	LD WA, IZ
	SLL 8, WA
	OR (XSP + 010h), WA
	LD WA, (XSP + 00eh)
	BIT 0fh, WA
	JR Z, Voice1_UpdatePitch_WritePBend
	LD XWA, (XSP + 002h)
	LD WA, (XWA)
