Voice2_UpdatePitch:
	LDA XSP, XSP - 016h
	PUSH IZ
	LD (XSP + 014h), XWA
	LDW (0451E0h), 4400h
	LD XWA, (XSP + 014h)
	LD XWA, (XWA + 023h)
	LD (XSP + 002h), XWA
	LD XWA, (XSP + 014h)
	LD XWA, (XWA + 027h)
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 014h)
	LD A, (XWA + 004h)
	LD (XSP + 010h), A
	LD XWA, (XSP + 006h)
	CPW (XWA + 01eh), 0000h
	JRL Z, Voice2_UpdatePitch_Done
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 01eh)
	AND A, 003h
	LD (XSP + 012h), A
	EXTZ WA
	SLA 2, WA
	LD BC, WA
	ADD BC, 004bh
	LD XWA, (XSP + 014h)
	LD XWA, (XWA + 013h)
	LDA XWA, XWA + BC
	BIT 7, (XWA + 002h)
	JR Z, Voice2_UpdatePitch_NoOsc7Flag
	LD A, (XSP + 010h)
	LD L, A
	EXTZ HL
	LD XWA, (XSP + 014h)
	LD A, (XWA)
	LD C, A
	EXTZ BC
	LD A, (XSP + 012h)
	EXTZ WA
	OR WA, 0028h
	LD E, A
	EXTZ DE
	LD WA, HL
	CALL ExtVoice_Alloc_StreamSlot
	LD (XSP + 00eh), HL
	LD IZ, (XSP + 00eh)
