	SET 3, WA
	LD E, A
	EXTZ DE
	LD WA, HL
	CALL ExtVoice_Alloc_StreamSlot
	LD (XSP + 00eh), HL
	LD IZ, (XSP + 00eh)
	LD IZH, 0

Voice2_UpdatePitch_ChanEntry:
	LD WA, IZ
	EXTZ XWA
	LD XBC, 0000001bh
	CALL FP_MulAccum64
	LDA XWA, 044260h
	ADD XWA, XHL
	LD (XSP + 00ah), XWA
	LD XWA, (XSP + 014h)
	LD XBC, (XSP + 00ah)
	LD A, (XWA + 00ch)
	LD (XBC + 006h), A
	CP IZ, 0080h
	JRL NC, Voice2_UpdatePitch_Done
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 01eh)
	AND WA, 3300h
	OR WA, IZ
	OR (0451E0h), WA
	LD WA, (XSP + 00eh)
	BIT 0fh, WA
	JR Z, Voice2_UpdatePitch_WritePBend
	LD XWA, (XSP + 002h)
	LD WA, (XWA)
	AND WA, 000ch
	JR Z, Voice2_UpdatePitch_CheckSustain

Voice2_UpdatePitch_WritePBend:
	LD A, (XSP + 010h)
	LD C, A
	EXTZ BC
	LD A, (XSP + 012h)
	LD E, A
	EXTZ DE
	PUSHW 0002h
	LD A, IZL
	EXTZ WA
	PUSH WA
	LD WA, BC
	LD XBC, (XSP + 006h)
	CALR Voice_OpSlot_WriteParams
	LD A, IZL
	EXTZ WA
	CALR Voice_Freq_WriteRight
	LD WA, IZ
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParams_TypeDispatch

Voice2_UpdatePitch_CheckSustain:
	LD XWA, (XSP + 00ah)
	CP (XWA + 007h), 000h
	JR Z, Voice2_UpdatePitch_CheckBit5
	LD XWA, (XSP + 002h)
	LD WA, (XWA + 002h)
	BIT 0dh, WA
	JR NZ, Voice2_UpdatePitch_DeactivateOsc

Voice2_UpdatePitch_CheckBit5:
	LD XWA, (XSP + 00ah)
