	LDA XSP, XSP + 016h
	RET

; ----------------------------------------------------------------------------
; Level_Build_Reg0C0 - build the part-level / patch-level register (+0x0C0)
; Entry: XWA = voice descriptor; part struct = desc[+0x23], tone record = desc[+0x13]
; Exit:  scratch 0x0451D2 (+0x0C0) written
; Notes: hi = part[+0x0f]; forced to 0 when part[+0x0f] or part[+0x12] is 0, and to 0
;        when the part mode byte at 0x04134C is 6.  When nonzero:
;          hi += tone_record[+0x5c] - 0x40      per-PATCH level/brightness byte
;          hi += sext(part[+0x66])              live per-part offset
;          hi  = clamp(hi, 0, 0x7F)
;        lo = part[+0x12] (or 0x7F in the global part modes).  It is neither key- nor
;        velocity-scaled.  MEASURED (2/2 live: the Piano/Bright delta of 0x1A in
;        tone_record[+0x5c] appears exactly in the register).  POLARITY of the field
;        is NOT established -- notes/audit/kn5000-audit-timbre.md GAP 4.
; ----------------------------------------------------------------------------
Level_Build_Reg0C0:		; 0253FEh
	LD XBC, (XWA + 023h)
	CP (XBC + 00fh), 000h
	JR Z, Level_Build_Reg0C0_ZeroCoarse
	LD XBC, (XWA + 023h)
	CP (XBC + 012h), 000h
	JR Z, Level_Build_Reg0C0_ZeroCoarse
	LD C, (04134Ch)
	CP C, 6
	JR NZ, Level_Build_Reg0C0_UseCoarse
	LD DE, 0
	JR T, Level_Build_Reg0C0_ApplyDetune

Level_Build_Reg0C0_UseCoarse:
	LD XBC, (XWA + 023h)
	LD C, (XBC + 00fh)
	EXTZ BC
	LD DE, BC
	JR T, Level_Build_Reg0C0_ApplyDetune

Level_Build_Reg0C0_ZeroCoarse:
	LD XBC, (XWA + 023h)
	LD C, (XBC + 00fh)
	EXTZ BC
	LD DE, BC

Level_Build_Reg0C0_ApplyDetune:
	CP DE, 0
	JR Z, Level_Build_Reg0C0_CheckExpr
	LD XBC, (XWA + 013h)
	LD C, (XBC + 05ch)
	EXTZ BC
	SUB BC, 0040h
	ADD DE, BC
	LD XBC, (XWA + 023h)
	LD C, (XBC + 066h)
	EXTS BC
	ADD DE, BC
	JR GE, Level_Build_Reg0C0_ClampHigh
	LD DE, 0
	JR T, Level_Build_Reg0C0_ShiftLeft

Level_Build_Reg0C0_ClampHigh:
	CP DE, 007fh
	JR LE, Level_Build_Reg0C0_ShiftLeft
	LD DE, 007fh

Level_Build_Reg0C0_ShiftLeft:
	SLA 8, DE

Level_Build_Reg0C0_CheckExpr:
	LD XBC, (XWA + 023h)
	CP (XBC + 012h), 000h
	JR Z, Level_Build_Reg0C0_NoExpr
	LD C, (04134Ch)
	CP C, 6
	JR Z, Level_Build_Reg0C0_FullExpr
	CP C, 5
	JR NZ, Level_Build_Reg0C0_PartialExpr

Level_Build_Reg0C0_FullExpr:
	OR DE, 007fh
	JR T, Level_Build_Reg0C0_Write

Level_Build_Reg0C0_PartialExpr:
	LD XWA, (XWA + 023h)
	LD A, (XWA + 012h)
	EXTZ WA
	OR DE, WA
	JR T, Level_Build_Reg0C0_Write

Level_Build_Reg0C0_NoExpr:
	LD XWA, (XWA + 023h)
	LD A, (XWA + 012h)
	EXTZ WA
	OR DE, WA

Level_Build_Reg0C0_Write:
	LD (0451D2h), DE
	RET

Voice_ComputePitchBend2:
	LD XHL, (XWA + 013h)
	LD XBC, (XWA + 023h)
	CP (XBC + 00fh), 000h
	JR Z, Voice_ComputePitchBend2_ZeroCoarse
	LD XBC, (XWA + 023h)
	CP (XBC + 012h), 000h
	JR Z, Voice_ComputePitchBend2_ZeroCoarse
	LD C, (04134Ch)
	CP C, 6
	JR NZ, Voice_ComputePitchBend2_UseCoarse
	LD DE, 0
	JR T, Voice_ComputePitchBend2_ApplyDetune

Voice_ComputePitchBend2_UseCoarse:
	LD XBC, (XWA + 023h)
	LD C, (XBC + 00fh)
	EXTZ BC
	LD DE, BC
	JR T, Voice_ComputePitchBend2_ApplyDetune

Voice_ComputePitchBend2_ZeroCoarse:
	LD XBC, (XWA + 023h)
	LD C, (XBC + 00fh)
	EXTZ BC
	LD DE, BC

Voice_ComputePitchBend2_ApplyDetune:
	CP DE, 0
	JR Z, Voice_ComputePitchBend2_CheckExpr
	LD C, (XHL + 00fh)
	EXTZ BC
	SUB BC, 0040h
	ADD DE, BC
	JR GE, Voice_ComputePitchBend2_ClampHigh
	LD DE, 0
	JR T, Voice_ComputePitchBend2_ShiftLeft

Voice_ComputePitchBend2_ClampHigh:
	CP DE, 007fh
	JR LE, Voice_ComputePitchBend2_ShiftLeft
	LD DE, 007fh

Voice_ComputePitchBend2_ShiftLeft:
	SLA 8, DE

Voice_ComputePitchBend2_CheckExpr:
	LD XBC, (XWA + 023h)
	CP (XBC + 012h), 000h
	JR Z, Voice_ComputePitchBend2_NoExpr
	LD C, (04134Ch)
	CP C, 6
	JR Z, Voice_ComputePitchBend2_FullExpr
	CP C, 5
	JR NZ, Voice_ComputePitchBend2_PartialExpr

Voice_ComputePitchBend2_FullExpr:
	OR DE, 007fh
	JR T, Voice_ComputePitchBend2_Write

Voice_ComputePitchBend2_PartialExpr:
	LD XWA, (XWA + 023h)
	LD A, (XWA + 012h)
	EXTZ WA
	OR DE, WA
	JR T, Voice_ComputePitchBend2_Write

Voice_ComputePitchBend2_NoExpr:
	LD XWA, (XWA + 023h)
	LD A, (XWA + 012h)
	EXTZ WA
	OR DE, WA

Voice_ComputePitchBend2_Write:
	LD (0451D2h), DE
	RET

; ----------------------------------------------------------------------------
; Voice_Apply_GateRouting - OR the per-part bus/routing bits into a group-0/bank-0 command word
; Entry: A  = part index
;        BC = command word to be routed
; Exit:  HL = the routed command word
; Notes: Reads the part flag byte at 0x04138D + part*0x11F.
;        Low nibble: 0 -> OR 0x0E00, 2 -> AND 0xF1FF then SET bit9, 1 -> leave.
;        High nibble: 0 -> OR 0x7000, 0x20 -> AND 0x8FFF then SET bit12,
;        0x10 -> leave.  Only bits 9-12 are ever touched, so a command word can
;        never be turned into the note-on strobe 0x81xx (MEASURED, exhaustive).
; ----------------------------------------------------------------------------
Voice_Apply_GateRouting:	; 02552Ah
	LD E, A
	EXTZ DE
	MULS_DE 011fh
	LDA XHL, 04138Dh
	LD E, (XHL + DE)
	AND E, 00fh
	CP E, 1
	JR Z, Voice_Apply_GateRouting_HighNibble
	CP E, 2
	JR Z, Voice_Apply_GateRouting_Mode2
	CP E, 0
	JR NZ, Voice_Apply_GateRouting_HighNibble
	OR BC, 0e00h
	JR T, Voice_Apply_GateRouting_HighNibble

Voice_Apply_GateRouting_Mode2:
	AND BC, 0f1ffh
	SET 9, BC

Voice_Apply_GateRouting_HighNibble:
	EXTZ WA
	MULS_WA 011fh
	LDA XDE, 04138Dh
	LD A, (XDE + WA)
	AND A, 0f0h
	CP A, 010h
	JR Z, Voice_Apply_GateRouting_Done
	CP A, 020h
	JR Z, Voice_Apply_GateRouting_Mode2High
	CP A, 0
	JR NZ, Voice_Apply_GateRouting_Done
	OR BC, 7000h
	JR T, Voice_Apply_GateRouting_Done

Voice_Apply_GateRouting_Mode2High:
	AND BC, 8fffh
	SET 0ch, BC

Voice_Apply_GateRouting_Done:
	LD HL, BC
	RET

; ----------------------------------------------------------------------------
; Voice_Build_GateCommand - Build the group-0/bank-0 command word for a voice with a partial block
; Entry: XWA = pointer to the voice slot
; Exit:  slot+0x2d = the command word; HL = same value
; Notes: word = {command[15:9], flag[8], magnitude[7:0]}
;        magnitude = 0x00FF - 4*(partial_block[0] & 0x3F)   (partial_block =
;        slot+0x17); bit8 is SET whenever partial_block[0] != 0, so bit8 set
;        <=> magnitude < 0xFF.
;        Base command is 0xFE00 when part_struct[+0x12] != 0 and the global
;        release mode at 0x04134C is 0, 5 or 6, else 0xF000.
;        Voice_Apply_GateRouting then ORs the bus/routing bits 9-12.
;        MEASURED (asm) - the low byte is NOT a linear amplitude: every rhythm
;        voice is commanded with magnitude 0x00 yet must sound
;        (notes/audit/kn5000-audit-amplitude.md S1.5, GAP 1).
; ----------------------------------------------------------------------------
Voice_Build_GateCommand:	; 025589h
	PUSH XIZ
	LD XIZ, XWA
	LD XWA, (XIZ + 017h)
	LD A, (XWA)
	EXTZ WA
	AND WA, 003fh
	SLL 2, WA
	LD BC, 00ffh
	SUB BC, WA
	LD XWA, (XIZ + 017h)
	CP (XWA), 000h
	JR Z, Voice_Build_GateCommand_CheckExpr
	SET 8, BC

Voice_Build_GateCommand_CheckExpr:
	LD XWA, (XIZ + 023h)
	CP (XWA + 012h), 000h
	JR Z, Voice_Build_GateCommand_NoExpr
	LD A, (04134Ch)
	CP A, 6
	JR Z, Voice_Build_GateCommand_FullExpr
	CP A, 5
	JR Z, Voice_Build_GateCommand_FullExpr
	CP A, 0
	JR NZ, Voice_Build_GateCommand_PartialExpr

Voice_Build_GateCommand_FullExpr:
	LD WA, BC
	OR WA, 0fe00h
	LD (XIZ + 02dh), WA
	JR T, Voice_Build_GateCommand_ApplyMode

Voice_Build_GateCommand_PartialExpr:
	LD WA, BC
	OR WA, 0f000h
	LD (XIZ + 02dh), WA
	JR T, Voice_Build_GateCommand_ApplyMode

Voice_Build_GateCommand_NoExpr:
	LD WA, BC
	OR WA, 0f000h
	LD (XIZ + 02dh), WA

Voice_Build_GateCommand_ApplyMode:
	LD A, (XIZ + 004h)
	EXTZ WA
	LD BC, (XIZ + 02dh)
	CALR Voice_Apply_GateRouting
	LD (XIZ + 02dh), HL
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; Voice_Build_GateCommand_NoPartial - Build the group-0/bank-0 command word for a voice with no partial block
; Entry: XWA = pointer to the voice slot
; Exit:  slot+0x2d = the command word; HL = same value
; Notes: Same as Voice_Build_GateCommand but the magnitude field is left at
;        0x00 (bare 0xFE00 / 0xF000), then routed by Voice_Apply_GateRouting.
; ----------------------------------------------------------------------------
Voice_Build_GateCommand_NoPartial:	; 0255F3h
	PUSH XIZ
	LD XIZ, XWA
	LD XWA, (XIZ + 013h)
	LD XWA, (XIZ + 023h)
	CP (XWA + 012h), 000h
	JR Z, Voice_Build_GateCommand_NoPartial_NoExpr
	LD A, (04134Ch)
	CP A, 6
	JR Z, Voice_Build_GateCommand_NoPartial_FullExpr
	CP A, 5
	JR Z, Voice_Build_GateCommand_NoPartial_FullExpr
	CP A, 0
	JR NZ, Voice_Build_GateCommand_NoPartial_PartialExpr

Voice_Build_GateCommand_NoPartial_FullExpr:
	LDW (XIZ + 02dh), 0fe00h
	JR T, Voice_Build_GateCommand_NoPartial_ApplyMode

Voice_Build_GateCommand_NoPartial_PartialExpr:
	LDW (XIZ + 02dh), 0f000h
	JR T, Voice_Build_GateCommand_NoPartial_ApplyMode

Voice_Build_GateCommand_NoPartial_NoExpr:
	LDW (XIZ + 02dh), 0f000h

Voice_Build_GateCommand_NoPartial_ApplyMode:
	LD A, (XIZ + 004h)
	EXTZ WA
	LD BC, (XIZ + 02dh)
	CALR Voice_Apply_GateRouting
	LD (XIZ + 02dh), HL
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; Voice_Calc_LevelPair_PatchAtk - Build the four EG segment words; attack rate taken from the patch
; Entry: XWA = pointer to the voice slot
; Exit:  slot+0x3c and TONEGEN_REG_SCRATCH+0x18 written; further segment words
;        built from tone-record fields +0x29/+0x2b/+0x34
; Notes: Identical shape to Voice_Calc_LevelPair_FixedAtk except that the
;        ATK segment's rate is Voice_EnvRate_Lookup[rec+0x28] instead of the
;        literal 0x7F - i.e. this is the path that makes slow-attack patches
;        possible.  MEASURED, notes/audit/kn5000-eg-calibration.md S1.1.
; ----------------------------------------------------------------------------
Voice_Calc_LevelPair_PatchAtk:	; 025636h
	LDA XSP, XSP - 14
	PUSH XIZ
	LD (XSP + 00eh), XWA
	LD XWA, (XSP + 00eh)
	LD XWA, (XWA + 017h)
	LD (XSP + 004h), XWA
	LD XWA, (XSP + 00eh)
	LD XWA, (XWA + 01fh)
	LD (XSP + 00ah), XWA
	LD XWA, (XSP + 00eh)
	LD XBC, (XWA + 023h)
	LD XWA, (XSP + 00eh)
	LD XWA, (XWA + 013h)
	BIT 4, (XWA + 010h)
	JR Z, Voice_Calc_LevelPair_PatchAtk_SetInvFlag
	LD XWA, (XSP + 00eh)
	ANDW (XWA + 001h), 7fffh
	JR T, Voice_Calc_LevelPair_PatchAtk_ApplyKeyTrack

Voice_Calc_LevelPair_PatchAtk_SetInvFlag:
	LD XWA, (XSP + 00eh)
	ORW (XWA + 001h), 8000h

Voice_Calc_LevelPair_PatchAtk_ApplyKeyTrack:
	LD A, (XBC + 06bh)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 004h)
	LD A, (XWA + 027h)
	EXTZ WA
	ADD WA, BC
	LD BC, 0064h
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	LD A, IZL
	EXTZ WA
	LDA XBC, 011899h
	LD A, (XBC + WA)
	EXTZ WA
	LD IZ, WA
	LD XWA, (XSP + 004h)
	CP (XWA + 033h), 000h
	JR Z, Voice_Calc_LevelPair_PatchAtk_NoOscLFO
	LD XWA, (XSP + 004h)
	LD A, (XWA + 030h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 004h)
	LD A, (XWA + 031h)
	LD E, A
	EXTZ DE
	LD XWA, (XSP + 004h)
	LD A, (XWA + 032h)
	EXTZ WA
	PUSH WA
	LD XWA, (XSP + 006h)
	LD A, (XWA + 033h)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 012h)
	LD WA, (XWA + 008h)
	CALR Pan_ScaleWithVelocity
	LD (XSP + 008h), HL
	LD XWA, (XSP + 004h)
	CP (XWA + 02eh), 000h
	JR Z, Voice_Calc_LevelPair_PatchAtk_NoLFO
	LD XWA, (XSP + 004h)
	LD A, (XWA + 02eh)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 00eh)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 4
	CALR PitchBend_Scale
	LD QIZ, HL
	LD WA, IZ
	ADD WA, (XSP + 008h)
	ADD WA, QIZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	JR T, Voice_Calc_LevelPair_PatchAtk_CheckMax

Voice_Calc_LevelPair_PatchAtk_NoLFO:
	LD WA, IZ
	ADD WA, (XSP + 008h)
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	JR T, Voice_Calc_LevelPair_PatchAtk_CheckMax

Voice_Calc_LevelPair_PatchAtk_NoOscLFO:
	LD XWA, (XSP + 004h)
	CP (XWA + 02eh), 000h
	JR Z, Voice_Calc_LevelPair_PatchAtk_CheckMax
	LD XWA, (XSP + 004h)
	LD A, (XWA + 02eh)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 00eh)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 4
	CALR PitchBend_Scale
	LD QIZ, HL
	LD WA, IZ
	ADD WA, QIZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL

Voice_Calc_LevelPair_PatchAtk_CheckMax:
	LD XWA, (XSP + 00ah)
	BIT 0, (XWA)
	JR Z, Voice_Calc_LevelPair_PatchAtk_WriteDSP
	LD WA, IZ
	CP WA, 00ffh
	JR NZ, Voice_Calc_LevelPair_PatchAtk_WriteDSP
	DEC 1, IZ

Voice_Calc_LevelPair_PatchAtk_WriteDSP:
	LD XWA, (XSP + 004h)
	LD A, (XWA + 028h)
	EXTZ WA
	LDA XBC, 011963h
	LD A, (XBC + WA)
	EXTZ WA
	LD_W 000h
	LD BC, IZ
	SLA 8, BC
	OR BC, WA
	LD (0451E4h), BC
	LD XWA, (XSP + 00eh)
	LD (XWA + 03ch), BC
	LD XWA, (XSP + 004h)
	LD A, (XWA + 029h)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 00ah), WA
	LD XWA, (XSP + 004h)
	LD A, (XWA + 02bh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD (XSP + 00ch), WA
	LD XWA, (XSP + 004h)
	CP (XWA + 034h), 000h
	JRL Z, Voice_Calc_LevelPair_PatchAtk_NoDepth2
	LD XWA, (XSP + 004h)
	LD A, (XWA + 030h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 004h)
	LD A, (XWA + 031h)
	LD E, A
	EXTZ DE
	LD XWA, (XSP + 004h)
	LD A, (XWA + 032h)
	EXTZ WA
	PUSH WA
	LD XWA, (XSP + 006h)
	LD A, (XWA + 034h)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 012h)
	LD WA, (XWA + 008h)
	CALR Pan_ScaleWithVelocity
	LD (XSP + 008h), HL
	LD XWA, (XSP + 004h)
	CP (XWA + 02fh), 000h
	JR Z, Voice_Calc_LevelPair_PatchAtk_NoModDepth
	LD XWA, (XSP + 004h)
	LD A, (XWA + 02fh)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 00eh)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 4
	CALR PitchBend_Scale
	LD QIZ, HL
	LD WA, (XSP + 00ah)
	ADD WA, (XSP + 008h)
	ADD WA, QIZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ah), HL
	LD WA, (XSP + 00ch)
	ADD WA, (XSP + 008h)
	ADD WA, QIZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ch), HL
	JR T, Voice_Calc_LevelPair_PatchAtk_WriteChans

Voice_Calc_LevelPair_PatchAtk_NoModDepth:
	LD WA, (XSP + 00ah)
	ADD WA, (XSP + 008h)
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ah), HL
	LD WA, (XSP + 00ch)
	ADD WA, (XSP + 008h)
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ch), HL
	JR T, Voice_Calc_LevelPair_PatchAtk_WriteChans

Voice_Calc_LevelPair_PatchAtk_NoDepth2:
	LD XWA, (XSP + 004h)
	CP (XWA + 02fh), 000h
	JR Z, Voice_Calc_LevelPair_PatchAtk_WriteChans
	LD XWA, (XSP + 004h)
	LD A, (XWA + 02fh)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 00eh)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 4
	CALR PitchBend_Scale
	LD QIZ, HL
	LD WA, (XSP + 00ah)
	ADD WA, QIZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ah), HL
	LD WA, (XSP + 00ch)
	ADD WA, QIZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ch), HL

Voice_Calc_LevelPair_PatchAtk_WriteChans:
	LD XWA, (XSP + 004h)
	LD A, (XWA + 02ah)
	EXTZ WA
	LDA XBC, 011963h
	LD A, (XBC + WA)
	EXTZ WA
	LD HL, WA
	LD WA, 4
	CP HL, 4
	JR LT, Voice_Calc_LevelPair_PatchAtk_ClampDepth
	LD WA, HL

Voice_Calc_LevelPair_PatchAtk_ClampDepth:
	LD HL, WA
	LD XWA, (XSP + 004h)
	LD A, (XWA + 02ch)
	EXTZ WA
	LDA XBC, 011963h
	LD A, (XBC + WA)
	EXTZ WA
	LD DE, WA
	LD WA, HL
	LD_W 000h
	LD BC, (XSP + 00ah)
	SLA 8, BC
	OR BC, WA
	LD XWA, (XSP + 00eh)
	LD (XWA + 03eh), BC
	LD WA, DE
	LD_W 000h
	LD BC, (XSP + 00ch)
	SLA 8, BC
	OR BC, WA
	LD XWA, (XSP + 00eh)
	LD (XWA + 040h), BC
	POP XIZ
	LDA XSP, XSP + 00eh
	RET

Voice_WriteChPanShift:
	DEC 8, XSP
	PUSH IZ
	LD (XSP + 004h), C
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 027h)
	LD WA, (XWA + 018h)
	BIT 8, WA
	JRL Z, Voice_WriteChPanShift_Passthrough
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 040h)
	AND WA, 00ffh
	JRL Z, Voice_WriteChPanShift_Passthrough
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 027h)
	LD WA, (XWA + 018h)
	BIT 9, WA
	JR Z, Voice_WriteChPanShift_AddShift
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 020h)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 03eh)
	AND WA, 007fh
	LD (XSP + 002h), WA
	SUB (XSP + 002h), BC
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 020h)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 040h)
	AND WA, 007fh
	LD IZ, WA
	SUB IZ, BC
	JR T, Voice_WriteChPanShift_ClampAndWrite

Voice_WriteChPanShift_AddShift:
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 020h)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 03eh)
	AND WA, 007fh
	LD (XSP + 002h), WA
	ADD (XSP + 002h), BC
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 020h)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 040h)
	AND WA, 007fh
	LD IZ, WA
	ADD IZ, BC

Voice_WriteChPanShift_ClampAndWrite:
	LD WA, (XSP + 002h)
	LD BC, 007fh
	LD DE, 4
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 002h), HL
	LD WA, IZ
	LD BC, 007fh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	CP (XSP + 004h), 000h
	JR Z, Voice_WriteChPanShift_NoChanFlag
	LD WA, IZ
	SET 0fh, WA
	LD (0451E8h), WA
	JR T, Voice_WriteChPanShift_WriteL

Voice_WriteChPanShift_NoChanFlag:
	LD WA, IZ
	LD_W 000h
	LD BC, WA
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 040h)
	LD_A 000h
	OR WA, BC
	LD (0451E8h), WA

Voice_WriteChPanShift_WriteL:
	LD WA, (XSP + 002h)
	LD_W 000h
	LD BC, WA
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 03eh)
	LD_A 000h
	OR WA, BC
	LD (0451E6h), WA
	JR T, Voice_WriteChPanShift_Done

Voice_WriteChPanShift_Passthrough:
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 03eh)
	LD (0451E6h), WA
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 040h)
	LD (0451E8h), WA

Voice_WriteChPanShift_Done:
	POP IZ
	INC 8, XSP
	RET

; ----------------------------------------------------------------------------
; Voice_Calc_LevelPair_FixedAtk - Build the four EG segment words for a voice; attack rate hard-coded
; Entry: XWA = pointer to the voice slot
; Exit:  slot+0x3c/+0x3e/+0x40/+0x46 and TONEGEN_REG_SCRATCH+0x18 written;
;        slot+0x01 bit15 set
; Notes: Segment word = (target_level << 8) | (flag << 7) | rate[6:0].
;        slot+0x3c = ATK/PEAK   = (PEAK << 8) | 0x7F  <- rate literal at asm
;        L19399, i.e. the maximum ramp speed; PEAK comes from
;        Voice_PeakLevel_Fader_Lookup (0x011899) indexed by partial_block+0x08,
;        optionally key-followed via PitchBend_Scale when partial_block+0x0e != 0.
;        slot+0x3e = DECAY1/SUST1 = (LVL[+0x09] << 8) | max(RATE[+0x0a], 4)
;        slot+0x40 = DECAY2/SUST2 = (LVL[+0x0b] << 8) | RATE[+0x0c], the rate
;        present only when desc+0x0d bit5 is set (else rate 0 = HOLD).
;        slot+0x46 = RELEASE level = LVL[+0x0d].
;        LVL = Voice_Level_Fader_Lookup (0x0118FE), RATE = Voice_EnvRate_Lookup
;        (0x011963).  Voice_Calc_LevelPair_FixedAtk_WriteLevel is an inner join point of this routine, not
;        a separate entry.  MEASURED, notes/audit/kn5000-eg-calibration.md S1.1.
; ----------------------------------------------------------------------------
Voice_Calc_LevelPair_FixedAtk:	; 025A35h
	LDA XSP, XSP - 12
	PUSH IZ
	LD (XSP + 00ah), XWA
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 013h)
	LD (XSP + 002h), XWA
