	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ch), HL
	JR T, Voice_Calc_LevelPair_Mono_WriteChDepth

Voice_Calc_LevelPair_Mono_NoModDepth:
	LD WA, (XSP + 00ah)
	ADD WA, (XSP + 008h)
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ah), HL
	LD WA, (XSP + 00ch)
	ADD WA, (XSP + 008h)
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ch), HL
	JR T, Voice_Calc_LevelPair_Mono_WriteChDepth

Voice_Calc_LevelPair_Mono_NoDepth2:
	LD XWA, (XSP + 004h)
	CP (XWA + 02fh), 000h
	JR Z, Voice_Calc_LevelPair_Mono_WriteChDepth
	LD XWA, (XSP + 004h)
	LD A, (XWA + 02fh)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 00eh)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 4
	CALR PitchBend_Scale
	LD IZ, HL
	LD WA, (XSP + 00ah)
	ADD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ah), HL
	LD WA, (XSP + 00ch)
	ADD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD (XSP + 00ch), HL

Voice_Calc_LevelPair_Mono_WriteChDepth:
	LD XWA, (XSP + 004h)
	LD A, (XWA + 02ah)
	EXTZ WA
	LDA XBC, 011963h
	LD A, (XBC + WA)
	EXTZ WA
	LD HL, WA
	LD WA, 4
	CP HL, 4
	JR LT, Voice_Calc_LevelPair_Mono_WriteCh2
	LD WA, HL

Voice_Calc_LevelPair_Mono_WriteCh2:
	LD HL, WA
	LD XWA, (XSP + 004h)
	LD A, (XWA + 02ch)
	EXTZ WA
	LDA XBC, 011963h
	LD A, (XBC + WA)
	EXTZ WA
	LD DE, WA
	LD WA, HL
	LD_W 000h
	LD BC, (XSP + 00ah)
	SLA 8, BC
	OR BC, WA
	LD (0451E6h), BC
	LD WA, DE
	LD_W 000h
	LD BC, (XSP + 00ch)
	SLA 8, BC
	OR BC, WA
	LD (0451E8h), BC
	POP XIZ
	LDA XSP, XSP + 00eh
	RET

Voice_InterpolatePanCurve:
	LD HL, (XWA + 008h)
	AND HL, 7f00h
	SRA 8, HL
	LD A, (XBC + 01eh)
	EXTZ WA
	CP HL, WA
	JR GE, Voice_InterpolatePanCurve_HighCheck
	LD A, (XBC + 01fh)
	EXTZ WA
	CP HL, WA
	JR GE, Voice_InterpolatePanCurve_LowRange
	LD HL, 0fe00h
	JR T, Voice_InterpolatePanCurve_Done

Voice_InterpolatePanCurve_LowRange:
	LD A, (XBC + 01fh)
	LD E, A
	EXTZ DE
	LD A, (XBC + 01eh)
	EXTZ WA
	LD IX, WA
	SUB IX, DE
	LD A, (XBC + 01eh)
	EXTZ WA
	SUB WA, HL
	MULS_WA 0ffc0h
	LD HL, WA
	EXTS XWA
	DIVS XWA, IX
	LD HL, WA
	JR T, Voice_InterpolatePanCurve_Done

Voice_InterpolatePanCurve_HighCheck:
	LD A, (XBC + 020h)
	EXTZ WA
	CP HL, WA
	JR LE, Voice_InterpolatePanCurve_Zero
	LD A, (XBC + 021h)
	EXTZ WA
	CP HL, WA
	JR LE, Voice_InterpolatePanCurve_HighRange
	LD HL, 0fe00h
	JR T, Voice_InterpolatePanCurve_Done

Voice_InterpolatePanCurve_HighRange:
	LD A, (XBC + 020h)
	LD E, A
	EXTZ DE
	LD A, (XBC + 021h)
	EXTZ WA
	LD IX, WA
	SUB IX, DE
	LD A, (XBC + 020h)
	EXTZ WA
	LD BC, HL
	SUB BC, WA
	LD WA, BC
	MULS_WA 0ffc0h
	LD HL, WA
	EXTS XWA
	DIVS XWA, IX
	LD HL, WA
	JR T, Voice_InterpolatePanCurve_Done

Voice_InterpolatePanCurve_Zero:
	LD HL, 0

Voice_InterpolatePanCurve_Done:
	RET

Voice_InterpolateNoteCurve:
	LD A, (XWA + 00ch)
	LD L, A
	EXTZ HL
	AND HL, 007fh
	LD A, (XBC + 022h)
	EXTZ WA
	CP HL, WA
	JR GE, Voice_InterpolateNoteCurve_HighCheck
	LD A, (XBC + 023h)
	EXTZ WA
	CP HL, WA
	JR GE, Voice_InterpolateNoteCurve_LowRange
	LD HL, 0fe00h
	JR T, Voice_InterpolateNoteCurve_Done

Voice_InterpolateNoteCurve_LowRange:
	LD A, (XBC + 023h)
	LD E, A
	EXTZ DE
	LD A, (XBC + 022h)
	EXTZ WA
	LD IX, WA
	SUB IX, DE
	LD A, (XBC + 022h)
	EXTZ WA
	SUB WA, HL
	MULS_WA 0ffc0h
	LD HL, WA
	EXTS XWA
	DIVS XWA, IX
	LD HL, WA
	JR T, Voice_InterpolateNoteCurve_Done

Voice_InterpolateNoteCurve_HighCheck:
	LD A, (XBC + 024h)
	EXTZ WA
	CP HL, WA
	JR LE, Voice_InterpolateNoteCurve_Zero
	LD A, (XBC + 025h)
	EXTZ WA
	CP HL, WA
	JR LE, Voice_InterpolateNoteCurve_HighRange
	LD HL, 0fe00h
	JR T, Voice_InterpolateNoteCurve_Done

Voice_InterpolateNoteCurve_HighRange:
	LD A, (XBC + 024h)
	LD E, A
	EXTZ DE
	LD A, (XBC + 025h)
	EXTZ WA
	LD IX, WA
	SUB IX, DE
	LD A, (XBC + 024h)
	EXTZ WA
	LD BC, HL
	SUB BC, WA
	LD WA, BC
	MULS_WA 0ffc0h
	LD HL, WA
	EXTS XWA
	DIVS XWA, IX
	LD HL, WA
	JR T, Voice_InterpolateNoteCurve_Done

Voice_InterpolateNoteCurve_Zero:
	LD HL, 0

Voice_InterpolateNoteCurve_Done:
	RET

Voice_ComputePitch:
	DEC 8, XSP
	PUSH IZ
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	LD XWA, (XSP + 006h)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	BIT 7, BC
	JR Z, Voice_ComputePitch_CheckSysExTune
	LD XWA, (XSP + 006h)
	ORW (XWA + 001h), 0800h

Voice_ComputePitch_CheckSysExTune:
	AND BC, 007fh
	LD WA, (041343h)
	BIT 0, WA
	JR NZ, Voice_ComputePitch_SysExTable
	LD XWA, (XSP + 002h)
	CP (XWA + 019h), 0e0h
	JR NZ, Voice_ComputePitch_CheckAltTune

Voice_ComputePitch_SysExTable:
	LD WA, BC
	EXTZ XWA
	LD XBC, 00011c96h
	ADD XBC, XWA
	LD A, (XBC)
	EXTZ WA
	LD IZ, WA
	SUB IZ, 000ch
	JRL T, Voice_ComputePitch_ApplyLFO

Voice_ComputePitch_CheckAltTune:
	LD WA, (041343h)
	BIT 1, WA
	JR Z, Voice_ComputePitch_NormalTune
	LD WA, BC
	EXTZ XWA
	LD XBC, 00011c96h
	ADD XBC, XWA
	LD A, (XBC)
	EXTZ WA
	LD IZ, WA
	SUB IZ, 000ch
	JR T, Voice_ComputePitch_ApplyLFO

Voice_ComputePitch_NormalTune:
	LD XWA, (XSP + 002h)
	CP (XWA + 018h), 000h
	JR GE, Voice_ComputePitch_PortaPositive
	LD WA, BC
	EXTZ XWA
	LD XBC, 0000fee4h
	ADD XBC, XWA
	LD A, (XBC)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 019h)
	LD E, A
	EXTZ DE
	LD WA, BC
	LD BC, DE
	CALR Voice_Colour_LookupIndex
	SUB HL, 00d0h
	LD XWA, (XSP + 002h)
	LD A, (XWA + 018h)
	EXTS WA
	CPL WA
	LD BC, WA
	INC 1, BC
	LD WA, HL
	MULS XWA, BC
	LD HL, WA
	JR T, Voice_ComputePitch_PortaScale

Voice_ComputePitch_PortaPositive:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 019h)
	LD E, A
	EXTZ DE
	LD WA, BC
	LD BC, DE
	CALR Voice_Colour_LookupIndex
	SUB HL, 00d0h
	LD XWA, (XSP + 002h)
	LD A, (XWA + 018h)
	LD C, A
	EXTS BC
	LD WA, HL
	MULS XWA, BC
	LD HL, WA

Voice_ComputePitch_PortaScale:
	SRA 5, HL
	LD IZ, HL
	ADD IZ, 00d8h

Voice_ComputePitch_ApplyLFO:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 01ah)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 01bh)
	LD E, A
	EXTZ DE
	LD XWA, (XSP + 002h)
	LD A, (XWA + 01ch)
	EXTZ WA
	PUSH WA
	LD XWA, (XSP + 004h)
	LD A, (XWA + 01dh)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 00ah)
	LD WA, (XWA + 008h)
	CALR Voice_Colour_ClampUpper
	ADD IZ, HL
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 02bh)
	AND WA, 007fh
	EXTZ XWA
	LD XBC, 00011a4fh
	ADD XBC, XWA
	LD A, (XBC)
	EXTS WA
	ADD IZ, WA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 00fh)
	LD A, (XWA + 003h)
	EXTS WA
	ADD IZ, WA
	LD XWA, (045314h)
	ADD IZ, (XWA + 00e0h)
	ADD IZ, (2940h)
	LD XWA, (XSP + 006h)
	LD XBC, (XSP + 002h)
	CALR Voice_InterpolatePanCurve
	ADD IZ, HL
	LD XWA, (XSP + 006h)
	LD XBC, (XSP + 002h)
	CALR Voice_InterpolateNoteCurve
	ADD IZ, HL
	LD XWA, (XSP + 002h)
	BIT 7, (XWA)
	JR Z, Voice_ComputePitch_WriteDone
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 011eh)
	EXTZ WA
	ADD IZ, WA

Voice_ComputePitch_WriteDone:
	LD XWA, (XSP + 006h)
	LD (XWA + 00dh), IZ
	LD XWA, (XSP + 006h)
	LDW (XWA + 033h), 0000h
	POP IZ
	INC 8, XSP
	RET

Voice_ComputePitch_InlineData:
	db 0DAh, 0F0h, 069h, 004h, 0DAh, 088h, 068h, 006h
	db 0D9h, 0F0h, 062h, 002h, 0D9h, 088h, 0D8h, 08Bh
	db 00Eh

Voice_ComputePitch_Mono:
	DEC 4, XSP
	PUSH XIZ
	LD (XSP + 004h), XWA
	LD XWA, (XSP + 004h)
	LD XIZ, (XWA + 017h)
	LD XWA, (XSP + 004h)
	LD A, (XWA + 00ch)
	LD E, A
	EXTZ DE
	AND DE, 007fh
	LD WA, (041343h)
	BIT 0, WA
	JR NZ, Voice_ComputePitch_Mono_SysExTable
	CP (XIZ + 007h), 0e0h
	JR NZ, Voice_ComputePitch_Mono_CheckAltTune

Voice_ComputePitch_Mono_SysExTable:
	LD WA, DE
	EXTZ XWA
	LD XBC, 00011c96h
	ADD XBC, XWA
	LD A, (XBC)
	EXTZ WA
	LD HL, WA
	SUB HL, 000ch
	JR T, Voice_ComputePitch_Mono_ApplyLFO

Voice_ComputePitch_Mono_CheckAltTune:
	LD WA, (041343h)
	BIT 1, WA
	JR Z, Voice_ComputePitch_Mono_CheckPorta
	LD WA, DE
	EXTZ XWA
	LD XBC, 00011c96h
	ADD XBC, XWA
	LD A, (XBC)
	EXTZ WA
	LD HL, WA
	SUB HL, 000ch

Voice_ComputePitch_Mono_CheckPorta:
	CP (XIZ + 006h), 000h
	JR GE, Voice_ComputePitch_Mono_PortaPositive
	LD WA, DE
	EXTZ XWA
	LD XBC, 0000fee4h
	ADD XBC, XWA
	LD A, (XBC)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 007h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_Colour_LookupIndex
	SUB HL, 00d0h
	LD A, (XIZ + 006h)
	EXTS WA
	CPL WA
	LD BC, WA
	INC 1, BC
	LD WA, HL
	MULS XWA, BC
	LD HL, WA
	JR T, Voice_ComputePitch_Mono_PortaScale

Voice_ComputePitch_Mono_PortaPositive:
	LD A, (XIZ + 007h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_Colour_LookupIndex
	SUB HL, 00d0h
	LD A, (XIZ + 006h)
	LD C, A
	EXTS BC
	LD WA, HL
	MULS XWA, BC
	LD HL, WA

Voice_ComputePitch_Mono_PortaScale:
	SRA 5, HL
	ADD HL, 00d8h

Voice_ComputePitch_Mono_ApplyLFO:
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 02bh)
	AND WA, 007fh
	EXTZ XWA
	LD XBC, 00011a4fh
	ADD XBC, XWA
	LD A, (XBC)
	EXTS WA
	ADD HL, WA
	LD XWA, (XSP + 004h)
	LD XWA, (XWA + 00fh)
	LD A, (XWA + 003h)
	EXTS WA
	ADD HL, WA
	LD XWA, (045314h)
	ADD HL, (XWA + 00e0h)
	ADD HL, (2940h)
	LD XWA, (XSP + 004h)
	LD (XWA + 00dh), HL
	LD XWA, (XSP + 004h)
	LDW (XWA + 033h), 0000h
	POP XIZ
	INC 4, XSP
	RET

Voice_ApplyPortamento:
	LD DE, (XWA + 00dh)
	LD XBC, (XWA + 017h)
	CP (XBC + 017h), 000h
	JR Z, Voice_ApplyPortamento_NoChanDetune
	LD XBC, (XWA + 017h)
	LD C, (XBC + 017h)
	EXTZ BC
	SUB BC, 0064h
	ADD DE, BC
	JR T, Voice_ApplyPortamento_ApplyDetune

Voice_ApplyPortamento_NoChanDetune:
	SUB DE, 0200h

Voice_ApplyPortamento_ApplyDetune:
	LD XBC, (XWA + 027h)
	LD C, (XBC + 022h)
	EXTS BC
	ADD DE, BC
	LD BC, (041343h)
	BIT 1, BC
	JR Z, Voice_ApplyPortamento_Done
	CP (XWA + 004h), 001h
	JR UGT, Voice_ApplyPortamento_HighNote
	LD XBC, (XWA + 023h)
	SUB DE, (XBC + 010h)
	DEC 8, DE
	JR T, Voice_ApplyPortamento_Done

Voice_ApplyPortamento_HighNote:
	SUB DE, 0010h

Voice_ApplyPortamento_Done:
	LD BC, DE
	JRL T, Voice_Build_OutputLevel

Voice_ApplyPortamento2:
	LD XBC, (XWA + 017h)
	LD DE, (XWA + 00dh)
	CP (XBC + 005h), 000h
	JR Z, Voice_ApplyPortamento2_NoChanDetune
	LD C, (XBC + 005h)
	EXTZ BC
	SUB BC, 0064h
	ADD DE, BC
	JR T, Voice_ApplyPortamento2_ApplyDetune

Voice_ApplyPortamento2_NoChanDetune:
	SUB DE, 0200h

Voice_ApplyPortamento2_ApplyDetune:
	LD BC, (041343h)
	BIT 1, BC
	JR Z, Voice_ApplyPortamento2_Done
	LD XBC, (XWA + 023h)
	SUB DE, (XBC + 010h)
	LD XBC, (XWA + 023h)
	SUB DE, (XBC + 00ch)
	LD HL, 0fe00h
	LD XBC, (XWA + 023h)
	LD BC, (XBC + 00ch)
	CP BC, 0fe00h
	JR Z, Voice_ApplyPortamento2_AddVibrato
	LD XBC, (XWA + 023h)
	LD BC, (XBC + 00ch)
	SRA 2, BC
	LD HL, BC

Voice_ApplyPortamento2_AddVibrato:
	ADD DE, HL

Voice_ApplyPortamento2_Done:
	LD BC, DE
	JRL T, Voice_Build_OutputLevel

Voice_WriteChPitchWithVib:
	DEC 2, XSP
	PUSH XIZ
	EXTZ BC
	MULS_BC 0047h
	LDA XDE, 0430ADh
	LD XBC, (XDE + BC)
	BIT 3, (XBC)
	JR Z, Voice_WriteChPitchWithVib_Done
	LD C, (XBC + 00eh)
	LD (XSP + 004h), C
	EXTZ BC
	LDA XDE, 011AE8h
	LD C, (XDE + BC)
	EXTZ BC
	SLL 8, BC
	SET 7, BC
	LD (0451F8h), BC
	LD C, (XSP + 004h)
	EXTZ BC
	LDA XDE, 011AE8h
	LD C, (XDE + BC)
	EXTZ BC
	SLL 8, BC
	LD (0451FAh), BC
	EXTZ WA
	CALL Voice_Query_PartVoices
	LDA XWA, XHL + 005h
	LD XIZ, XWA
	CP (XIZ), 040h
	JR NC, Voice_WriteChPitchWithVib_Done

Voice_WriteChPitchWithVib_Loop:
	LD A, (XIZ)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 0430ADh
	LD XBC, (XBC + WA)
	LD A, (XSP + 004h)
	CP A, (XBC + 00eh)
	JR NZ, Voice_WriteChPitchWithVib_NextSlot
	LD A, (XIZ)
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteLevelPair

Voice_WriteChPitchWithVib_NextSlot:
	INC 1, XIZ
	CP (XIZ), 040h
	JR C, Voice_WriteChPitchWithVib_Loop

Voice_WriteChPitchWithVib_Done:
	POP XIZ
	INC 2, XSP
	RET

; ----------------------------------------------------------------------------
; Voice_Calc_LevelPair_EGA - Compute a voice's level pair into the register scratch block
; Entry: XWA = pointer to the voice slot
; Exit:  TONEGEN_REG_SCRATCH+0x2C/0x2E written; shipped later by ToneGen_WriteLevelBurst
; Notes: i = clamp(partial_block[+0x2d] + (int8)tone_rec[+0x6c], 0, 100)
;        IZ = Voice_Level_Fader_Lookup[i]   (0x0118FE, param 0..100 -> level)
;        if tone_rec[+0x0a] bit0 and !(slot+0x01 bit8):
;            IZ = min(IZ, LVL[Voice_LevelCap_Lookup[tone_rec[+0x18]]])
;        if partial_block[+0x35] != 0: IZ += velocity scaling (Pan_ScaleWithVelocity),
;            then clamp to 0..255 (Voice_Clamp_Byte_HL).
;        Result is packed (IZ << 8) | flag and stored to the two scratch
;        words that become IC303 registers +0x800 / +0x840.
;        MEASURED: the key-up recomputation of the EGA pair was captured
;        bit-exact as 0x8B80 / 0x8B00 for IZ = 0x8B
;        (notes/audit/kn5000-audit-amplitude.md S1.3, S1.6).
; ----------------------------------------------------------------------------
Voice_Calc_LevelPair_EGA:	; 026769h
	DEC 8, XSP
	PUSH IZ
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 06ch)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 02dh)
	EXTZ WA
	ADD WA, BC
	LD BC, 0064h
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	LD A, IZL
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD IZ, WA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD WA, (XWA + 00ah)
	BIT 0, WA
	JR Z, Voice_Calc_LevelPair_EGA_ApplyLFO
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 001h)
	BIT 8, WA
	JR NZ, Voice_Calc_LevelPair_EGA_ApplyLFO
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 018h)
	EXTZ WA
	LDA XBC, 011ADFh
	LD A, (XBC + WA)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	CP WA, IZ
	JR GT, Voice_Calc_LevelPair_EGA_ApplyLFO
	LD IZ, WA

Voice_Calc_LevelPair_EGA_ApplyLFO:
	LD XWA, (XSP + 002h)
	CP (XWA + 035h), 000h
	JR Z, Voice_Calc_LevelPair_EGA_WriteDSP
	LD XWA, (XSP + 002h)
	LD A, (XWA + 030h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 031h)
	LD E, A
	EXTZ DE
	LD XWA, (XSP + 002h)
	LD A, (XWA + 032h)
	EXTZ WA
	PUSH WA
	LD XWA, (XSP + 004h)
	LD A, (XWA + 035h)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 00ah)
	LD WA, (XWA + 008h)
	CALR Pan_ScaleWithVelocity
	ADD IZ, HL
	LD WA, IZ
	CALR Voice_Clamp_Byte_HL
	LD IZ, HL

Voice_Calc_LevelPair_EGA_WriteDSP:
	LD WA, IZ
	SLA 8, WA
	SET 7, WA
	LD (0451F8h), WA
	LD WA, IZ
	SLA 8, WA
	LD (0451FAh), WA
	POP IZ
	INC 8, XSP
	RET

; ----------------------------------------------------------------------------
; Voice_Stage_EnvSegments - Copy a voice's DECAY1/SUST1 and DECAY2/SUST2 segment words to the scratch
; Entry: XWA = pointer to the voice slot
; Exit:  TONEGEN_REG_SCRATCH+0x1A = slot+0x3e, +0x1C = slot+0x40
; Notes: Feeds ToneGen_WriteEnvSegments, which ships them to IC303 +0x840 and
;        +0x880.
; ----------------------------------------------------------------------------
Voice_Stage_EnvSegments:	; 02684Ah
	LD BC, (XWA + 03eh)
	LD (0451E6h), BC
	LD WA, (XWA + 040h)
	LD (0451E8h), WA
	RET

Voice_WriteVolume_SetFlag:
	LD BC, (XWA + 040h)
	SET 7, BC
	LD (0451F8h), BC
	LD WA, (XWA + 040h)
	LD (0451FAh), WA
	RET

Voice_ComputeVolume_CappedLFO:
	DEC 8, XSP
	PUSH IZ
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD WA, (XWA + 00ah)
	BIT 0, WA
	JR Z, Voice_ComputeVolume_CappedLFO_UseOscMax
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 018h)
	EXTZ WA
	LDA XBC, 011ADFh
	LD A, (XBC + WA)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD IZ, WA
	LD XWA, (XSP + 002h)
	LD A, (XWA + 02dh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD BC, IZ
	CP BC, WA
	JR ULE, Voice_ComputeVolume_CappedLFO_ApplyLFO
	LD XWA, (XSP + 002h)
	LD A, (XWA + 02dh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD IZ, WA
	JR T, Voice_ComputeVolume_CappedLFO_ApplyLFO

Voice_ComputeVolume_CappedLFO_UseOscMax:
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 010dh)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 02dh)
	EXTZ WA
	ADD WA, BC
	LD BC, 0064h
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	LD A, IZL
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD IZ, WA

Voice_ComputeVolume_CappedLFO_ApplyLFO:
	LD XWA, (XSP + 002h)
	CP (XWA + 035h), 000h
	JR Z, Voice_ComputeVolume_CappedLFO_WriteDSP
	LD XWA, (XSP + 002h)
	LD A, (XWA + 030h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 031h)
	LD E, A
	EXTZ DE
	LD XWA, (XSP + 002h)
	LD A, (XWA + 032h)
	EXTZ WA
	PUSH WA
	LD XWA, (XSP + 004h)
	LD A, (XWA + 035h)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 00ah)
	LD WA, (XWA + 008h)
	CALR Pan_ScaleWithVelocity
	ADD IZ, HL
	LD WA, IZ
	CALR Voice_Clamp_Byte_HL
	LD IZ, HL

Voice_ComputeVolume_CappedLFO_WriteDSP:
	LD WA, IZ
	SLA 8, WA
	SET 7, WA
	LD (0451F8h), WA
	LD WA, IZ
	SLA 8, WA
	LD (0451FAh), WA
	POP IZ
	INC 8, XSP
	RET

; ----------------------------------------------------------------------------
; Voice_Calc_LevelPair_EGB - Compute a voice's level pair into the register scratch block
; Entry: XWA = pointer to the voice slot
; Exit:  TONEGEN_REG_SCRATCH+0x30/0x32 written; shipped later by ToneGen_WriteLevelBurst
; Notes: i = clamp(partial_block[+0x2d] + (int8)tone_rec[+0x6c], 0, 100)
;        IZ = Voice_Level_Fader_Lookup[i]   (0x0118FE, param 0..100 -> level)
;        if tone_rec[+0x0a] bit0 and !(slot+0x01 bit8):
;            IZ = min(IZ, LVL[Voice_LevelCap_Lookup[tone_rec[+0x18]]])
;        if partial_block[+0x35] != 0: IZ += velocity scaling (Pan_ScaleWithVelocity),
;            then clamp to 0..255 (Voice_Clamp_Byte_HL).
;        Result is packed (IZ << 8) | flag and stored to the two scratch
;        words that become IC303 registers +0x900 / +0x940.
;        MEASURED: the key-up recomputation of the EGA pair was captured
;        bit-exact as 0x8B80 / 0x8B00 for IZ = 0x8B
;        (notes/audit/kn5000-audit-amplitude.md S1.3, S1.6).
; ----------------------------------------------------------------------------
Voice_Calc_LevelPair_EGB:	; 026975h
	DEC 8, XSP
	PUSH IZ
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	LD A, (XWA + 00fh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD IZ, WA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD WA, (XWA + 00ah)
	BIT 0, WA
	JR Z, Voice_Calc_LevelPair_EGB_ApplyLFO
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 018h)
	EXTZ WA
	LDA XBC, 011ADFh
	LD A, (XBC + WA)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	CP WA, IZ
	JR GT, Voice_Calc_LevelPair_EGB_ApplyLFO
	LD IZ, WA

Voice_Calc_LevelPair_EGB_ApplyLFO:
	LD XWA, (XSP + 002h)
	CP (XWA + 016h), 000h
	JR Z, Voice_Calc_LevelPair_EGB_NoLFO
	LD XWA, (XSP + 002h)
	LD A, (XWA + 013h)
	LD C, A
	EXTZ BC
	PUSHW 007fh
	LD XWA, (XSP + 004h)
	LD A, (XWA + 016h)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 00ah)
	LD WA, (XWA + 008h)
	LD DE, 0
	CALR Pan_ScaleWithVelocity
	ADD IZ, HL
	LD XWA, (XSP + 002h)
	CP (XWA + 011h), 000h
	JR Z, Voice_Calc_LevelPair_EGB_NoKeyTrack
	LD XWA, (XSP + 002h)
	LD A, (XWA + 011h)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 006h)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 4
	CALR PitchBend_Scale
	ADD IZ, HL
	LD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	JR T, Voice_Calc_LevelPair_EGB_WriteDSP

Voice_Calc_LevelPair_EGB_NoKeyTrack:
	LD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	JR T, Voice_Calc_LevelPair_EGB_WriteDSP

Voice_Calc_LevelPair_EGB_NoLFO:
	LD XWA, (XSP + 002h)
	CP (XWA + 011h), 000h
	JR Z, Voice_Calc_LevelPair_EGB_WriteDSP
	LD XWA, (XSP + 002h)
	LD A, (XWA + 011h)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 006h)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 4
	CALR PitchBend_Scale
	ADD IZ, HL
	LD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL

Voice_Calc_LevelPair_EGB_WriteDSP:
	LD XWA, (XSP + 002h)
	CP (XWA + 007h), 000h
	JR GE, Voice_Calc_LevelPair_EGB_PositiveDetune
	LD XWA, (XSP + 002h)
	LD A, (XWA + 010h)
	EXTS WA
	CPL WA
	INC 1, WA
	CALR Detune_ScaleSymmetric
	JR T, Voice_Calc_LevelPair_EGB_WriteResult

Voice_Calc_LevelPair_EGB_PositiveDetune:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 010h)
	EXTS WA
	CALR Detune_ScaleSymmetric

Voice_Calc_LevelPair_EGB_WriteResult:
	LD_H 000h
	LD WA, IZ
	SLA 8, WA
	OR WA, HL
	LD (0451FCh), WA
	LD (0451FEh), WA
	POP IZ
	INC 8, XSP
	RET

; ----------------------------------------------------------------------------
; Voice_Calc_LevelPair_EGC - Compute a voice's level pair into the register scratch block
; Entry: XWA = pointer to the voice slot
; Exit:  TONEGEN_REG_SCRATCH+0x34/0x36 written; shipped later by ToneGen_WriteLevelBurst
; Notes: i = clamp(partial_block[+0x2d] + (int8)tone_rec[+0x6c], 0, 100)
;        IZ = Voice_Level_Fader_Lookup[i]   (0x0118FE, param 0..100 -> level)
;        if tone_rec[+0x0a] bit0 and !(slot+0x01 bit8):
;            IZ = min(IZ, LVL[Voice_LevelCap_Lookup[tone_rec[+0x18]]])
;        if partial_block[+0x35] != 0: IZ += velocity scaling (Pan_ScaleWithVelocity),
;            then clamp to 0..255 (Voice_Clamp_Byte_HL).
;        Result is packed (IZ << 8) | flag and stored to the two scratch
;        words that become IC303 registers +0x9C0 / +0xA00.
;        MEASURED: the key-up recomputation of the EGA pair was captured
;        bit-exact as 0x8B80 / 0x8B00 for IZ = 0x8B
;        (notes/audit/kn5000-audit-amplitude.md S1.3, S1.6).
; ----------------------------------------------------------------------------
Voice_Calc_LevelPair_EGC:	; 026AAAh
	DEC 8, XSP
	PUSH IZ
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	LD A, (XWA + 045h)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	LD IZ, WA
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD WA, (XWA + 00ah)
	BIT 0, WA
	JR Z, Voice_Calc_LevelPair_EGC_ApplyLFO
	LD XWA, (XSP + 006h)
	LD XWA, (XWA + 023h)
	LD A, (XWA + 018h)
	EXTZ WA
	LDA XBC, 011ADFh
	LD A, (XBC + WA)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	CP WA, IZ
	JR GT, Voice_Calc_LevelPair_EGC_ApplyLFO
	LD IZ, WA

Voice_Calc_LevelPair_EGC_ApplyLFO:
	LD XWA, (XSP + 002h)
	CP (XWA + 04ch), 000h
	JR Z, Voice_Calc_LevelPair_EGC_NoLFO
	LD XWA, (XSP + 002h)
	LD A, (XWA + 049h)
	LD C, A
	EXTZ BC
	PUSHW 007fh
	LD XWA, (XSP + 004h)
	LD A, (XWA + 04ch)
	EXTS WA
	PUSH WA
	LD XWA, (XSP + 00ah)
	LD WA, (XWA + 008h)
	LD DE, 0
	CALR Pan_ScaleWithVelocity
	ADD IZ, HL
	LD XWA, (XSP + 002h)
	CP (XWA + 047h), 000h
	JR Z, Voice_Calc_LevelPair_EGC_NoKeyTrack
	LD XWA, (XSP + 002h)
	LD A, (XWA + 047h)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 006h)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 4
	CALR PitchBend_Scale
	ADD IZ, HL
	LD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	JR T, Voice_Calc_LevelPair_EGC_WriteDSP

Voice_Calc_LevelPair_EGC_NoKeyTrack:
	LD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL
	JR T, Voice_Calc_LevelPair_EGC_WriteDSP

Voice_Calc_LevelPair_EGC_NoLFO:
	LD XWA, (XSP + 002h)
	CP (XWA + 047h), 000h
	JR Z, Voice_Calc_LevelPair_EGC_WriteDSP
	LD XWA, (XSP + 002h)
	LD A, (XWA + 047h)
	LD E, A
	EXTS DE
	LD XWA, (XSP + 006h)
	LD A, (XWA + 00ch)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD DE, 4
	CALR PitchBend_Scale
	ADD IZ, HL
	LD WA, IZ
	LD BC, 00ffh
	LD DE, 0
	CALR ClampS16_WA_To_DEBC
	LD IZ, HL

Voice_Calc_LevelPair_EGC_WriteDSP:
	LD XWA, (XSP + 002h)
	LD A, (XWA + 03dh)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 002h)
	LD A, (XWA + 046h)
	EXTS WA
	ADD WA, BC
	LD BC, 0032h
	LD DE, 0ffceh
	CALR ClampS16_WA_To_DEBC
	LD WA, HL
	CALR Detune_ScaleSymmetric
	LD_H 000h
	LD WA, IZ
	SLA 8, WA
	OR WA, HL
	LD (045200h), WA
	LD (045202h), WA
	POP IZ
	INC 8, XSP
	RET

; ----------------------------------------------------------------------------
; Voice_Calc_LevelPair_Silence - Stage a silencing level set: zero the EGB/EGC pairs, hold EGA
; Entry: XWA = pointer to the voice slot
; Exit:  TONEGEN_REG_SCRATCH+0x30/+0x32/+0x34/+0x36 = 0;
;        +0x2C = (slot+0x46 << 8) | 0x0080, +0x2E = (slot+0x46 << 8)
; Notes: slot+0x46 is the RELEASE target level built by
;        Voice_Calc_LevelPair_FixedAtk.  MEASURED consequence: the firmware
;        silences a voice by zeroing the two *send* pairs, NOT by zeroing the
;        +0x800 level - so +0x800 is not the mute control
;        (notes/audit/kn5000-audit-amplitude.md S1.4).
; ----------------------------------------------------------------------------
Voice_Calc_LevelPair_Silence:	; 026BDCh
	LDW (0451FCh), 0000h
	LDW (0451FEh), 0000h
	LD C, (XWA + 046h)
	EXTZ BC
	SLL 8, BC
	SET 7, BC
	LD (0451F8h), BC
	LD A, (XWA + 046h)
	EXTZ WA
	SLL 8, WA
	LD (0451FAh), WA
	LDW (045200h), 0000h
	LDW (045202h), 0000h
	RET

Voice_WriteVolume_OrPan:
	LD XBC, (XWA + 013h)
	LD XWA, (XWA + 017h)
	BIT 5, (XBC + 00dh)
	JR Z, Voice_WriteVolume_OrPan_Muted
	LD A, (XWA + 00dh)
	EXTZ WA
	LDA XBC, 0118FEh
	LD A, (XBC + WA)
	EXTZ WA
	SLL 8, WA
	LD (0451FAh), WA
	SET 7, WA
	LD (0451F8h), WA
	RET

Voice_WriteVolume_OrPan_Muted:
	LDW (0451F8h), 0080h
	LDW (0451FAh), 0000h
	RET

Voice_AdvanceLFOPhase:
	LD C, (XWA)
	AND C, 01ch
	CP C, 008h
	JR Z, Voice_AdvanceLFOPhase_Triangle
	CP C, 010h
	JR NZ, Voice_AdvanceLFOPhase_Idle
	LDA XBC, XWA + 008h
	INC 1, (XBC)
	LD C, (XBC)
	CP C, (XWA + 007h)
	JR C, Voice_AdvanceLFOPhase_IncDone
	LD (XWA + 008h), 000h
	RES 4, (XWA)
	SET 3, (XWA)

Voice_AdvanceLFOPhase_IncDone:
	LD HL, 0
	JR T, Voice_AdvanceLFOPhase_Done

Voice_AdvanceLFOPhase_Triangle:
	LDA XBC, XWA + 008h
	INC 1, (XBC)
	LD C, (XBC)
	CP C, (XWA + 007h)
	JR NC, Voice_AdvanceLFOPhase_TriangleReset
	LD L, (XWA + 008h)
	EXTZ HL
	SLL 8, HL
	LD A, (XWA + 007h)
	LD C, A
	EXTZ BC
	LD WA, HL
	EXTZ XWA
	DIV XWA, BC
	LD HL, WA
	JR T, Voice_AdvanceLFOPhase_Done

Voice_AdvanceLFOPhase_TriangleReset:
	LD (XWA + 008h), 000h
	RES 3, (XWA)
	SET 2, (XWA)
	LD HL, 0100h
	JR T, Voice_AdvanceLFOPhase_Done

Voice_AdvanceLFOPhase_Idle:
	LD HL, 0

Voice_AdvanceLFOPhase_Done:
	RET

Voice_UpdateAllLFO:
	PUSH XIZ
	LD IZ, 0
	CP IZ, 0080h
	JR NC, Voice_UpdateAllLFO_Loop2

Voice_UpdateAllLFO_Loop1:
	LD WA, IZ
	EXTZ XWA
	LD XBC, 0000001bh
	CALL FP_MulAccum64
	LDA XBC, 04424Eh
	ADD XBC, XHL
	LD A, (XBC)
	AND A, 018h
	JR Z, Voice_UpdateAllLFO_NextSlot1
	LD XWA, XBC
	CALR Voice_AdvanceLFOPhase
	LD QIZ, HL
	CP QIZ, 0
	JR Z, Voice_UpdateAllLFO_NextSlot1
	LD A, IZL
	EXTZ WA
	CALR EGEnv_Compute_A
	LD (04520Ch), HL
	CP QIZ, 0100h
	JR Z, Voice_UpdateAllLFO_DispatchVoice1
	LD HL, (04520Ch)
	EXTZ XHL
	AND XHL, 00001fffh
	LD BC, QIZ
	EXTZ XBC
	LD XWA, XHL
	CALL FP_MulAccum64
	ANDW (04520Ch), 0e000h
	SRL 8, XHL
	OR (04520Ch), HL

Voice_UpdateAllLFO_DispatchVoice1:
	LD WA, IZ
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParam_600

Voice_UpdateAllLFO_NextSlot1:
	INC 1, IZ
	CP IZ, 0080h
	JR C, Voice_UpdateAllLFO_Loop1

Voice_UpdateAllLFO_Loop2:
	LD IZ, 0
	CP IZ, 0040h
	JR NC, Voice_UpdateAllLFO_Loop3

Voice_UpdateAllLFO_Loop2_Body:
	LD WA, IZ
	EXTZ XWA
	LD XBC, 0000001bh
	CALL FP_MulAccum64
	LDA XWA, 044257h
	ADD XWA, XHL
	LD XBC, XWA
	LD A, (XBC)
	AND A, 018h
	JR Z, Voice_UpdateAllLFO_NextSlot2
	LD XWA, XBC
	CALR Voice_AdvanceLFOPhase
	LD QIZ, HL
	CP QIZ, 0
	JR Z, Voice_UpdateAllLFO_NextSlot2
	LD A, IZL
	EXTZ WA
	CALR EGEnv_Compute_B
	LD (045204h), HL
	CP QIZ, 0100h
	JR Z, Voice_UpdateAllLFO_DispatchVoice2
	LD HL, (045204h)
	EXTZ XHL
	AND XHL, 00001fffh
	LD BC, QIZ
	EXTZ XBC
	LD XWA, XHL
	CALL FP_MulAccum64
	ANDW (045204h), 0e000h
	SRL 8, XHL
	OR (045204h), HL

Voice_UpdateAllLFO_DispatchVoice2:
	LD WA, IZ
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParam_1C0_Single

Voice_UpdateAllLFO_NextSlot2:
	INC 1, IZ
	CP IZ, 0040h
	JR C, Voice_UpdateAllLFO_Loop2_Body

Voice_UpdateAllLFO_Loop3:
	LD IZ, 0
	CP IZ, 0080h
	JRL NC, Voice_UpdateAllLFO_Done

Voice_UpdateAllLFO_Loop3_Body:
	LD WA, IZ
	EXTZ XWA
	LD XBC, 0000001bh
	CALL FP_MulAccum64
	LDA XWA, 044260h
	ADD XWA, XHL
	LD XBC, XWA
	LD A, (XBC)
	AND A, 018h
	JR Z, Voice_UpdateAllLFO_NextSlot3
	LD XWA, XBC
	CALR Voice_AdvanceLFOPhase
	LD QIZ, HL
	CP QIZ, 0
	JR Z, Voice_UpdateAllLFO_NextSlot3
	LD A, IZL
	EXTZ WA
	CALR Voice_Freq_WriteLeft
	CP QIZ, 0100h
	JR Z, Voice_UpdateAllLFO_DispatchVoice3
	CP IZ, 0040h
	JR NC, Voice_UpdateAllLFO_DispatchGroup3_High
	LD HL, (045204h)
	EXTZ XHL
	AND XHL, 00001fffh
	LD BC, QIZ
	EXTZ XBC
	LD XWA, XHL
	CALL FP_MulAccum64
	ANDW (045204h), 0e000h
	SRL 8, XHL
	OR (045204h), HL
	JR T, Voice_UpdateAllLFO_DispatchVoice3

Voice_UpdateAllLFO_DispatchGroup3_High:
	LD HL, (04520Eh)
	EXTZ XHL
	AND XHL, 00001fffh
	LD BC, QIZ
	EXTZ XBC
	LD XWA, XHL
	CALL FP_MulAccum64
	ANDW (04520Eh), 0e000h
	SRL 8, XHL
	OR (04520Eh), HL

Voice_UpdateAllLFO_DispatchVoice3:
	LD WA, IZ
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParam_TypeDispatch_Single

Voice_UpdateAllLFO_NextSlot3:
	INC 1, IZ
	CP IZ, 0080h
	JRL C, Voice_UpdateAllLFO_Loop3_Body

Voice_UpdateAllLFO_Done:
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; Voice_Step_AmpDelay - Per-tick step of a voice's AMPLITUDE-domain delay counter
; Entry: XWA = pointer to the voice slot (VOICE_SLOT_BASE 0x04308E + ch*0x47)
; Exit:  none (slot+0x2f updated in place); IZ/XWA clobbered
; Notes: Called once per audio tick by Audio_Tick_ServiceVoices_A/_B for every
;        channel whose slot+0x2f has bit15 or bit7 set.
;        slot+0x2f layout: bit15 = coarse-active, bits 14:8 = coarse count,
;        bit7 = fine-active, bits 6:0 = fine count.
;        COARSE branch (bit15): IZ -= 0x100; when bits 14:8 hit 0 it ships the
;        gate/command word slot+0x2d through ToneGen_WriteSingleReg, calls
;        Voice_Clear_HoldBit and clears bit15.
;        FINE branch (bit7): IZ -= 1; when bits 6:0 hit 0 it calls
;        Voice_Reload_Levels once and clears bit7 -> the counter DISARMS.
;        MEASURED CORRECTION: bit15 of slot+0x2f is never set anywhere in the
;        v142 payload (seeded as a byte at asm L27198-27200, only ever ORed
;        with 0x0080 by Voice_ParamInit L29374), so the COARSE branch is dead
;        code in this build and this routine is a ONE-SHOT delay, not a ramp.
;        It is NOT a per-tick level ramp: notes/kn5000-envelope-engine.md S2
;        claimed a level rewrite every tick; the register capture in
;        notes/audit/kn5000-audit-amplitude.md S1.6 shows one write per note.
; ----------------------------------------------------------------------------
Voice_Step_AmpDelay:	; 026E5Bh
	DEC 4, XSP
	PUSH IZ
	LD (XSP + 002h), XWA
	LD XWA, (XSP + 002h)
	LD IZ, (XWA + 02fh)
	LD WA, IZ
	EXTZ XWA
	BIT 0fh, WA
	JR Z, Voice_Step_AmpDelay_CheckRelease
	SUB IZ, 0100h
	LD WA, IZ
	AND WA, 7f00h
	JR NZ, Voice_Step_AmpDelay_CheckRelease
	LD XWA, (XSP + 002h)
	LD A, (XWA)
	EXTZ WA
	LD XBC, (XSP + 002h)
	LD BC, (XBC + 02dh)
	CALL ToneGen_WriteSingleReg
	LD XWA, (XSP + 002h)
	LD A, (XWA)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	RES 0fh, IZ

Voice_Step_AmpDelay_CheckRelease:
	BIT 7, IZ
	JR Z, Voice_Step_AmpDelay_StoreDone
	DEC 1, IZ
	LD WA, IZ
	AND WA, 007fh
	JR NZ, Voice_Step_AmpDelay_StoreDone
	LD XWA, (XSP + 002h)
	LD A, (XWA)
	EXTZ WA
	CALL Voice_Reload_Levels
	AND IZ, 007fh

Voice_Step_AmpDelay_StoreDone:
	LD XWA, (XSP + 002h)
	LD (XWA + 02fh), IZ
	POP IZ
	INC 4, XSP
	RET

; ----------------------------------------------------------------------------
; Voice_Step_ExprRamp - Per-tick step of a voice's second (expression) envelope domain
; Entry: XWA = pointer to the voice slot
; Exit:  none (slot+0x31 and slot+0x33 updated in place)
; Notes: State word slot+0x31: bit15 = armed (the gate tested by
;        Audio_Tick_ServiceVoices_B), bits 14:12 = phase, bits 6:0 = a kill
;        countdown.  Merged each tick with the rate byte slot+0x35.
;        Writes IC303 register +0x180+ch through ToneGen_WriteExprReg, taking
;        the value from slot+0x2b (or, for part expression modes 1/2 selected
;        by the byte at 0x04138E + part*0x11F, an alternate packing).
;        Phase 0x1000 accumulates slot+0x38 and phase 0x4000 accumulates
;        slot+0x36 into the signed accumulator slot+0x33; the floor is 0xFF00
;        (= -256).  Reaching the floor clamps slot+0x33 and calls
;        Voice_Clear_HoldBit + Voice_Reload_Levels; otherwise it emits the
;        pair +0x840 = 0xFF00 / +0x800 = 0xFF80 and re-gates via
;        ToneGen_WriteVoiceParams_Ext / ToneGen_WriteVoiceParams_Ext2.
;        Countdown value 1 in bits 6:0 emits the kill pair +0x840 = 0xA200 /
;        +0x800 = 0xA280 (the same pair Voice_Reset_Engine uses).
;        MEASURED for the register traffic and the state-word fields;
;        INFERRED for the musical meaning of the three phases.
; ----------------------------------------------------------------------------
Voice_Step_ExprRamp:	; 026EC3h
	DEC 6, XSP
	PUSH IZ
	LD (XSP + 004h), XWA
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 031h)
	LD (XSP + 002h), WA
	AND WA, 007fh
	JRL NZ, Voice_Step_ExprRamp_ActiveCount
	LD XWA, (XSP + 004h)
	LD A, (XWA + 035h)
	EXTZ WA
	OR (XSP + 002h), WA
	XORW (XSP + 002h), 0800h
	LD WA, (XSP + 002h)
	BIT 0bh, WA
	JRL Z, Voice_Step_ExprRamp_ZeroState
	LD XWA, (XSP + 004h)
	LD A, (XWA + 004h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04138Eh
	CP (XBC + WA), 001h
	JR NZ, Voice_Step_ExprRamp_ModeCheck2
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	LD XBC, (XSP + 004h)
	LD BC, (XBC + 02bh)
	CALL ToneGen_WriteExprReg
	JR T, Voice_Step_ExprRamp_DispatchMode

Voice_Step_ExprRamp_ModeCheck2:
	LD XWA, (XSP + 004h)
	LD A, (XWA + 004h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04138Eh
	CP (XBC + WA), 002h
	JR NZ, Voice_Step_ExprRamp_ModeDefault
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	LD XBC, (XSP + 004h)
	LD BC, (XBC + 02bh)
	CALL ToneGen_WriteExprReg
	JR T, Voice_Step_ExprRamp_DispatchMode

Voice_Step_ExprRamp_ModeDefault:
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	LD L, A
	EXTZ HL
	LD XWA, (XSP + 004h)
	LD XWA, (XWA + 027h)
	LD A, (XWA + 024h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 02bh)
	AND WA, 0ff80h
	LD DE, WA
	OR DE, BC
	LD WA, HL
	LD BC, DE
	CALL ToneGen_WriteExprReg
	JR T, Voice_Step_ExprRamp_DispatchMode

Voice_Step_ExprRamp_ZeroState:
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	LD XBC, (XSP + 004h)
	LD BC, (XBC + 02bh)
	CALL ToneGen_WriteExprReg

Voice_Step_ExprRamp_DispatchMode:
	LD WA, (XSP + 002h)
	AND WA, 7000h
	CP WA, 1000h
	JRL Z, Voice_Step_ExprRamp_Release_Start
	CP WA, 2000h
	JRL Z, Voice_Step_ExprRamp_Descend_Tick
	CP WA, 4000h
	JRL NZ, Voice_Step_ExprRamp_NullMode
	LD XWA, (XSP + 004h)
	LD IZ, (XWA + 036h)
	LD XWA, (XSP + 004h)
	ADD IZ, (XWA + 033h)
	CP IZ, 0ff00h
	JR GT, Voice_Step_ExprRamp_Ascend_Tick
	LD XWA, (XSP + 004h)
	LDW (XWA + 033h), 0ff00h
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	CALL Voice_Reload_Levels
	ANDW (XSP + 002h), 6fffh
	JRL T, Voice_Step_ExprRamp_StoreDone

Voice_Step_ExprRamp_Ascend_Tick:
	RES 7, (P6)
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0840h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0ff00h
	JR T, Voice_Step_ExprRamp_Ascend_Tick2

Voice_Step_ExprRamp_Ascend_Tick2:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0800h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0ff80h
	JR T, Voice_Step_ExprRamp_Ascend_ClampFloor

Voice_Step_ExprRamp_Ascend_ClampFloor:
	NOP
	NOP
	NOP
	LD XWA, (XSP + 004h)
	CP IZ, (XWA + 03ah)
	JR GE, Voice_Step_ExprRamp_Ascend_WritePitch
	LD XWA, (XSP + 004h)
	LD IZ, (XWA + 03ah)
	RES 6, (XSP + 003h)
	SET 5, (XSP + 003h)

Voice_Step_ExprRamp_Ascend_WritePitch:
	LD XWA, (XSP + 004h)
	LD (XWA + 033h), IZ
	LD XWA, (XSP + 004h)
	CALR Voice_ApplyPortamento
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	LDA XBC, 0451CCh
	LD XDE, (XSP + 004h)
	CALL ToneGen_WriteVoiceParams_Ext
	JRL T, Voice_Step_ExprRamp_StoreDone

Voice_Step_ExprRamp_Descend_Tick:
	RES 7, (P6)
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0840h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0ff00h
	JR T, Voice_Step_ExprRamp_Descend_Tick2

Voice_Step_ExprRamp_Descend_Tick2:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0800h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0ff80h
	JR T, Voice_Step_ExprRamp_Descend_WritePitch

Voice_Step_ExprRamp_Descend_WritePitch:
	NOP
	NOP
	NOP
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	LD XBC, (XSP + 004h)
	CALL ToneGen_WriteVoiceParams_Ext2
	JRL T, Voice_Step_ExprRamp_StoreDone

Voice_Step_ExprRamp_Release_Start:
	LD XWA, (XSP + 004h)
	LD IZ, (XWA + 038h)
	LD XWA, (XSP + 004h)
	ADD IZ, (XWA + 033h)
	CP IZ, 0ff00h
	JR GT, Voice_Step_ExprRamp_Release_Tick
	LD XWA, (XSP + 004h)
	LDW (XWA + 033h), 0ff00h
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	CALL Voice_Reload_Levels
	ANDW (XSP + 002h), 6fffh
	JRL T, Voice_Step_ExprRamp_StoreDone

Voice_Step_ExprRamp_Release_Tick:
	RES 7, (P6)
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0840h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0ff00h
	JR T, Voice_Step_ExprRamp_Release_Tick2

Voice_Step_ExprRamp_Release_Tick2:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0800h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0ff80h
	JR T, Voice_Step_ExprRamp_Release_WritePitch

Voice_Step_ExprRamp_Release_WritePitch:
	NOP
	NOP
	NOP
	LD XWA, (XSP + 004h)
	LD (XWA + 033h), IZ
	LD XWA, (XSP + 004h)
	CALR Voice_ApplyPortamento
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	LDA XBC, 0451CCh
	LD XDE, (XSP + 004h)
	CALL ToneGen_WriteVoiceParams_Ext
	JR T, Voice_Step_ExprRamp_StoreDone

Voice_Step_ExprRamp_NullMode:
	LDW (XSP + 002h), 0000h
	JR T, Voice_Step_ExprRamp_StoreDone

Voice_Step_ExprRamp_ActiveCount:
	LD WA, (XSP + 002h)
	AND WA, 007fh
	CP WA, 1
	JR NZ, Voice_Step_ExprRamp_CountDecrement
	RES 7, (P6)
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0840h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a200h
	JR T, Voice_Step_ExprRamp_CountTick

Voice_Step_ExprRamp_CountTick:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0800h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a280h
	JR T, Voice_Step_ExprRamp_CountTick2

Voice_Step_ExprRamp_CountTick2:
	NOP
	NOP
	NOP
	DECW 1, (XSP + 002h)
	JR T, Voice_Step_ExprRamp_StoreDone

Voice_Step_ExprRamp_CountDecrement:
	DECW 1, (XSP + 002h)

Voice_Step_ExprRamp_StoreDone:
	LD XWA, (XSP + 004h)
	LD BC, (XSP + 002h)
	LD (XWA + 031h), BC
	POP IZ
	INC 6, XSP
	RET

; ----------------------------------------------------------------------------
; Pitch_Bend_Ramp_Tick - advance the panel BEND / auto-bend ramp by one tick
; Entry: None (state in ToneGen_GlobalFlags and Pitch_BendRampPhase)
; Exit:  Pitch_BendValue updated; ToneGen_GlobalFlags state bits advanced
; Notes: ToneGen_GlobalFlags bit 11 arms the ramp (phase := 1, value := 2*curve[0],
;        flags -> clear bit 11, set bits 10 and 12); bit 12 counts the hold; bit 13
;        runs the ramp, stepping Pitch_BendRampPhase and setting
;        Pitch_BendValue = sext(Pitch_Bend_Curve_Table[phase]) * 2 (1/256 semitone).
;        Bit 10 of the flags is the "bend active" bit that Pitch_Emit_Reg400 tests via
;        desc[+0x01] bit 10.  MEASURED.
; ----------------------------------------------------------------------------
Pitch_Bend_Ramp_Tick:		; 0271BCh
	LD WA, (041343h)
	BIT 0bh, WA
	JR Z, Pitch_Bend_Ramp_Tick_Bit12
	INCW 1, (04135Ch)
	LD A, (011C7Ch)
	EXTS WA
	ADD WA, WA
	LD (04135Ah), WA
	ANDW (041343h), 0f7ffh
	ORW (041343h), 1400h
	RET

Pitch_Bend_Ramp_Tick_Bit12:
	LD WA, (041343h)
	BIT 0ch, WA
	JR Z, Pitch_Bend_Ramp_Tick_Bit13Check
	INCW 1, (04135Ch)
	ANDW (041343h), 0fbffh
	RET

Pitch_Bend_Ramp_Tick_Bit13Check:
	LD WA, (041343h)
	BIT 0dh, WA
	JRL Z, Pitch_Bend_Ramp_Tick_ClearMode
	LD WA, (041343h)
	BIT 0eh, WA
	JR Z, Pitch_Bend_Ramp_Tick_Bit14Clear
	INCW 2, (04135Ch)
	LD WA, (04135Ch)
	EXTZ XWA
	LD XBC, 00011c7ch
	ADD XBC, XWA
	LD A, (XBC)
	EXTS WA
	ADD WA, WA
	LD (04135Ah), WA
	ORW (041343h), 0400h
	JR T, Pitch_Bend_Ramp_Tick_CheckCounter

Pitch_Bend_Ramp_Tick_Bit14Clear:
	LD WA, (041343h)
	EXTZ XWA
	BIT 0fh, WA
	JR Z, Pitch_Bend_Ramp_Tick_ZeroPitch
	INCW 1, (04135Ch)
	LD WA, (04135Ch)
	EXTZ XWA
	LD XBC, 00011c7ch
	ADD XBC, XWA
	LD A, (XBC)
	EXTS WA
	ADD WA, WA
	LD (04135Ah), WA
	ORW (041343h), 0400h
	JR T, Pitch_Bend_Ramp_Tick_CheckCounter

Pitch_Bend_Ramp_Tick_ZeroPitch:
	LDW (04135Ah), 0000h
	ORW (041343h), 0400h

Pitch_Bend_Ramp_Tick_CheckCounter:
	CPW (04135Ah), 0000h
	RET NZ
	ANDW (041343h), 1fffh
	LDW (04135Ch), 0000h
	ORW (041343h), 0400h
	RET

Pitch_Bend_Ramp_Tick_ClearMode:
	ANDW (041343h), 0fbffh
	RET

Voice_InitVoiceState:
	LDW (0451CEh), 0000h
	LD BC, (041360h)
	LD (0451DAh), BC
	LDW (0451ECh), 0000h
	LDW (0451EEh), 0000h
	LDW (0451F0h), 0000h
	LDW (0451D4h), 017fh
	LDW (0451D6h), 7f7fh
	LDW (0451F2h), 0000h
	LDW (0451F4h), 0000h
	LDW (0451F6h), 0000h
	LDW (0451E2h), 0000h
	LDW (0451EAh), 0000h
	LDW (0451DCh), 0000h
	LDW (0451DEh), 0000h
	LDW (0451D8h), 0040h
	LDW (0451E0h), 0000h
	LDW (0451D2h), 0000h
	LDW (0451E4h), 0ff7fh
	LD BC, (041362h)
	LD (0451E6h), BC
	LD BC, (041362h)
	LD (0451E8h), BC
	LD BC, (041364h)
	ADD BC, BC
	LDA XDE, 010764h
	LD BC, (XDE + BC)
	ADD BC, BC
	LD (0451D0h), BC
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 0430BBh
	LDW (XBC + WA), 0f000h
	RET

Voice_TickNoteDecay:
	LDA XSP, XSP - 14
	PUSH QIZ
	CP (04135Eh), 000h
	JR Z, Voice_TickNoteDecay_Done
	DEC 1, (04135Fh)
	CP (04135Fh), 000h
	JR NZ, Voice_TickNoteDecay_Done
	LDA XWA, XSP + 002h
	CALL Voice_SetPanning
	CP (XSP + 00ch), 040h
	JR NC, Voice_TickNoteDecay_Reload
	LD A, (XSP + 00ch)
	LD QIZH, A
	EXTZ WA
	CALR Voice_InitVoiceState
	LD A, QIZH
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteVoiceParams
	LD A, QIZH
	LD L, A
	EXTZ HL
	LD A, QIZH
	EXTZ WA
	MULS_WA 047h
	LD BC, WA
	LDA XDE, 0430BBh
	LD WA, HL
	LD BC, (XDE + BC)
	CALL ToneGen_WriteSingleReg

Voice_TickNoteDecay_Reload:
	DEC 1, (04135Eh)
	LD (04135Fh), 004h

Voice_TickNoteDecay_Done:
	POP QIZ
	LDA XSP, XSP + 00eh
	RET

Voice_LoadPitchTable_Ch:
	DEC 8, XSP
	PUSH IZ
	LD (XSP + 006h), C
	LD (XSP + 008h), A
	LD A, (XSP + 008h)
	EXTZ WA
	LD BC, 1
	CALL DSP_AlgoType_Dispatch2
	EXTZ XHL
	LD A, (XSP + 006h)
	LD XBC, 0
	LD C, A
	LD XWA, XHL
	CALL FP_MulAccum64
	SRL 8, XHL
	CP XHL, 0000002ch
	JR NC, Voice_LoadPitchTable_Ch_NoClamp
	LDW (045208h), 002ch
	LD A, (XSP + 008h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 0413C5h
	LDW (XBC + WA), 002ch
	JR T, Voice_LoadPitchTable_Ch_ScanLoop

Voice_LoadPitchTable_Ch_NoClamp:
	LD WA, HL
	LD (045208h), WA
	LD A, (XSP + 008h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 0413C5h
	LD (XBC + WA), HL

Voice_LoadPitchTable_Ch_ScanLoop:
	LD A, (XSP + 008h)
	EXTZ WA
	LD BC, 1
	CALL DSP_AlgoType_Dispatch1
	EXTZ XHL
	LD A, (XSP + 006h)
	EXTZ WA
	LDA XBC, 010DCEh
	LD A, (XBC + WA)
	LD XBC, 0
	LD C, A
	LD XWA, XHL
	CALL FP_MulAccum64
	SRL 8, XHL
	LD WA, HL
	LD (04520Ch), WA
	LD A, (XSP + 008h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 0413C3h
	LD (XBC + WA), HL
	LD A, (XSP + 008h)
	EXTZ WA
	LD BC, 000dh
	LD DE, 0
	CALL Voice_BuildOutputList
	LD (XSP + 002h), XHL
	LD IZ, 0
	JR T, Voice_LoadPitchTable_Ch_LoopCheck

Voice_LoadPitchTable_Ch_LoopBody:
	LD WA, IZ
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, (XSP + 002h)
	LD WA, (XWA)
	LD_W 000h
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParams_56
	INC 1, IZ

Voice_LoadPitchTable_Ch_LoopCheck:
	LD WA, IZ
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, (XSP + 002h)
	LD WA, (XWA)
	AND WA, 00ffh
	CP WA, 0080h
	JR C, Voice_LoadPitchTable_Ch_LoopBody
	POP IZ
	INC 8, XSP
	RET

Voice_LoadPitchTable_All:
	DEC 8, XSP
	LD (XSP + 006h), A
	LD A, (XSP + 006h)
	EXTZ WA
	LD BC, 1
	CALL DSP_AlgoType_Dispatch2
	LD (045208h), HL
	LD A, (XSP + 006h)
	EXTZ WA
	LD BC, 1
	CALL DSP_AlgoType_Dispatch1
	LD (04520Ch), HL
	LD A, (XSP + 006h)
	EXTZ WA
	LD BC, 000dh
	LD DE, 0
	CALL Voice_BuildOutputList
	LD (XSP), XHL
	LDW (XSP + 004h), 0000h
	JR T, Voice_LoadPitchTable_All_LoopCheck

Voice_LoadPitchTable_All_LoopBody:
	LD WA, (XSP + 004h)
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, (XSP)
	LD WA, (XWA)
	LD_W 000h
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParams_56
	INCW 1, (XSP + 004h)

Voice_LoadPitchTable_All_LoopCheck:
	LD WA, (XSP + 004h)
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, (XSP)
	LD WA, (XWA)
