Voice_LoadFilterTable_All_LoopCheck:
	LD WA, (XSP + 004h)
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, (XSP)
	LD WA, (XWA)
	AND WA, 00ffh
	CP WA, 0080h
	JR C, Voice_LoadFilterTable_All_LoopBody
	INC 8, XSP
	RET

Voice_LoadToneTable_Ch:
	LDA XSP, XSP - 10
	LD (XSP + 006h), C
	LD (XSP + 008h), A
	LD A, (XSP + 008h)
	EXTZ WA
	CALL DSP_ChanFreq_WritePacket2
	EXTZ XHL
	LD A, (XSP + 006h)
	LD XBC, 0
	LD C, A
	LD XWA, XHL
	CALL FP_MulAccum64
	SRL 8, XHL
	CP XHL, 0000001ch
	JR NC, Voice_LoadToneTable_Ch_NoClamp
	LDW (045206h), 001ch
	LD A, (XSP + 008h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 0413C9h
	LDW (XBC + WA), 001ch
	JR T, Voice_LoadToneTable_Ch_ScanLoop

Voice_LoadToneTable_Ch_NoClamp:
	LD WA, HL
	LD (045206h), WA
	LD A, (XSP + 008h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 0413C9h
	LD (XBC + WA), HL

Voice_LoadToneTable_Ch_ScanLoop:
	LD A, (XSP + 008h)
	EXTZ WA
	LD BC, 0010h
	LD DE, 0
	CALL Voice_BuildOutputList
	LD (XSP), XHL
	LDW (XSP + 004h), 0000h
	JR T, Voice_LoadToneTable_Ch_LoopCheck

Voice_LoadToneTable_Ch_LoopBody:
	LD WA, (XSP + 004h)
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, (XSP)
	LD WA, (XWA)
	LD_W 000h
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParams_15_Alt
	INCW 1, (XSP + 004h)

Voice_LoadToneTable_Ch_LoopCheck:
	LD WA, (XSP + 004h)
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, (XSP)
	LD WA, (XWA)
	AND WA, 00ffh
	CP WA, 0040h
	JR C, Voice_LoadToneTable_Ch_LoopBody
	LDA XSP, XSP + 00ah
	RET

Voice_LoadToneTable_All:
	DEC 8, XSP
	LD (XSP + 006h), A
	LD A, (XSP + 006h)
	EXTZ WA
	CALL DSP_ChanFreq_WritePacket2
	LD (045206h), HL
	LD A, (XSP + 006h)
	EXTZ WA
	LD BC, 0010h
	LD DE, 0
	CALL Voice_BuildOutputList
	LD (XSP), XHL
	LDW (XSP + 004h), 0000h
	JR T, Voice_LoadToneTable_All_LoopCheck

Voice_LoadToneTable_All_LoopBody:
	LD WA, (XSP + 004h)
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, (XSP)
	LD WA, (XWA)
	LD_W 000h
	LDA XBC, 0451CCh
	CALL ToneGen_WriteExtParams_15_Alt
	INCW 1, (XSP + 004h)

Voice_LoadToneTable_All_LoopCheck:
	LD WA, (XSP + 004h)
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, (XSP)
	LD WA, (XWA)
	AND WA, 00ffh
	CP WA, 0040h
	JR C, Voice_LoadToneTable_All_LoopBody
	INC 8, XSP
	RET

Voice_ToneTableRamp_Up:
	DEC 4, XSP
	PUSH XIZ
	LD XIZ, XBC
	LD (XSP + 006h), A
	CP (XIZ + 064h), 04fh
	JR C, Voice_ToneTableRamp_Up_Increment
	SET 3, (XIZ + 063h)
	LD A, (XSP + 006h)
	EXTZ WA
	CALR Voice_LoadPitchTable_All
	JR T, Voice_ToneTableRamp_Up_CheckFilter

Voice_ToneTableRamp_Up_Increment:
	INC 1, (XIZ + 064h)
	RES 3, (XIZ + 063h)
	LD A, (XIZ + 064h)
	LD (XSP + 004h), A
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 010D64h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadPitchTable_Ch

Voice_ToneTableRamp_Up_CheckFilter:
	CP (XIZ + 065h), 096h
	JR C, Voice_ToneTableRamp_Up_FilterIncrement
	LD A, (XSP + 006h)
	EXTZ WA
	CALR Voice_LoadFilterTable_All
	LD A, (XSP + 006h)
	EXTZ WA
	CALR Voice_LoadToneTable_All
	JR T, Voice_ToneTableRamp_Up_Done

Voice_ToneTableRamp_Up_FilterIncrement:
	INC 1, (XIZ + 065h)
	RES 3, (XIZ + 063h)
	LD A, (XIZ + 065h)
	EXTZ WA
	DIV_A 006h
	LD (XSP + 004h), A
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 010DB4h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadFilterTable_Ch
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 010DB4h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadToneTable_Ch

Voice_ToneTableRamp_Up_Done:
	POP XIZ
	INC 4, XSP
	RET

Voice_ToneTableRamp_Down:
	DEC 4, XSP
	PUSH XIZ
	LD XIZ, XBC
	LD (XSP + 006h), A
	CP (XIZ + 064h), 000h
	JR NZ, Voice_ToneTableRamp_Down_Decrement
	SET 4, (XIZ + 063h)
	JR T, Voice_ToneTableRamp_Down_CheckFilter

Voice_ToneTableRamp_Down_Decrement:
	DEC 1, (XIZ + 064h)
	RES 4, (XIZ + 063h)
	LD A, (XIZ + 064h)
	SRL 1, A
	LD (XSP + 004h), A
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 010DB4h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadPitchTable_Ch

Voice_ToneTableRamp_Down_CheckFilter:
	CP (XIZ + 065h), 000h
	JR Z, Voice_ToneTableRamp_Down_Done
	DEC 1, (XIZ + 065h)
	RES 4, (XIZ + 063h)
	LD A, (XIZ + 065h)
	EXTZ WA
	DIV_A 005h
	LD (XSP + 004h), A
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 010DB4h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadFilterTable_Ch
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 010DB4h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadToneTable_Ch

Voice_ToneTableRamp_Down_Done:
	POP XIZ
	INC 4, XSP
	RET

Voice_ToneTableApply_Pitch:
	DEC 6, XSP
	PUSH QIZ
	LD (XSP + 002h), XBC
	LD (XSP + 006h), A
	LD XWA, (XSP + 002h)
	AND (XWA + 063h), 0e7h
	LD XWA, (XSP + 002h)
	LD A, (XWA + 064h)
	EXTZ WA
	LDA XBC, 010D64h
	LD L, (XBC + WA)
	LD QIZH, 019h
	JR T, Voice_ToneTableApply_Pitch_Loop

Voice_ToneTableApply_Pitch_Decrement:
	DEC 1, QIZH

Voice_ToneTableApply_Pitch_Loop:
	LD A, QIZH
	EXTZ WA
	LDA XBC, 010DB4h
	CP L, (XBC + WA)
	JR C, Voice_ToneTableApply_Pitch_Decrement
	LD XWA, (XSP + 002h)
	LD C, QIZH
	LD (XWA + 064h), C
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, L
	EXTZ WA
	LDA XBC, 010D64h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadPitchTable_Ch
	LD XWA, (XSP + 002h)
	LD L, (XWA + 065h)
	LD A, L
	EXTZ WA
	DIV_A 006h
	LD L, A
	LD QIZH, L
	LD A, L
	MUL_A 005h
	LD L, A
	LD XWA, (XSP + 002h)
	LD (XWA + 065h), L
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, QIZH
	EXTZ WA
	LDA XBC, 010DB4h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadFilterTable_Ch
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, QIZH
	EXTZ WA
	LDA XBC, 010DB4h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadToneTable_Ch
	POP QIZ
	INC 6, XSP
	RET

Voice_ToneTableApply_Filter:
	DEC 6, XSP
	PUSH QIZ
	LD (XSP + 002h), XBC
	LD (XSP + 006h), A
	LD XWA, (XSP + 002h)
	AND (XWA + 063h), 0e7h
	LD XWA, (XSP + 002h)
	LD A, (XWA + 064h)
	SRL 1, A
	EXTZ WA
	LDA XBC, 010DB4h
	LD E, (XBC + WA)
	LD QIZH, 0
	JR T, Voice_ToneTableApply_Filter_Loop

Voice_ToneTableApply_Filter_Increment:
	INC 1, QIZH

Voice_ToneTableApply_Filter_Loop:
	LD A, QIZH
	EXTZ WA
	LDA XBC, 010D64h
	CP E, (XBC + WA)
	JR UGT, Voice_ToneTableApply_Filter_Increment
	LD XWA, (XSP + 002h)
	LD C, QIZH
	LD (XWA + 064h), C
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, QIZH
	EXTZ WA
	LDA XBC, 010DB4h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadPitchTable_Ch
	LD XWA, (XSP + 002h)
	LD E, (XWA + 065h)
	LD A, E
	EXTZ WA
	DIV_A 005h
	LD E, A
	LD QIZH, E
	LD A, E
	MUL_A 006h
	LD E, A
	LD XWA, (XSP + 002h)
	LD (XWA + 065h), E
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, QIZH
	EXTZ WA
	LDA XBC, 010DB4h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadFilterTable_Ch
	LD A, (XSP + 006h)
	LD E, A
	EXTZ DE
	LD A, QIZH
	EXTZ WA
	LDA XBC, 010DB4h
	LD C, (XBC + WA)
	LD WA, DE
	CALR Voice_LoadToneTable_Ch
	POP QIZ
	INC 6, XSP
	RET

; ----------------------------------------------------------------------------
; Audio_Tick_ServiceVoices_A - Audio-tick pass A: service every voice's amplitude-domain counter
; Entry: none
; Exit:  none
; Notes: Called by Audio_Process_Init on even ticks (toggle 0x041342).
;        Builds the list of live channels with Voice_Query_AllChannels, then for
;        every channel index in it (slot = VOICE_SLOT_BASE + n*0x47):
;          if part_struct(slot+0x23)+0x0a bit15 is SET  (delayed-release mode)
;               and slot+0x2f & 0x8080 -> Voice_Step_AmpDelay(slot)
;          else if slot+0x2f & 0x8080 -> Voice_Clear_HoldBit(ch),
;               Voice_Reload_Levels(ch), slot+0x2f = 0    (immediate release)
;        Pass A does NOT touch the expression domain.
; ----------------------------------------------------------------------------
Audio_Tick_ServiceVoices_A:	; 027A46h
	DEC 4, XSP
	PUSH XIZ
	CALR Voice_UpdateAllLFO
	CALL Voice_Query_AllChannels
	LDA XWA, XHL + 005h
	LD (XSP + 004h), XWA
	CP (XWA), 040h
	JR NC, Audio_Tick_ServiceVoices_A_Done

Audio_Tick_ServiceVoices_A_Loop:
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	LDA XIZ, XBC + WA
	LD XWA, (XIZ + 023h)
	LD WA, (XWA + 00ah)
	EXTZ XWA
	BIT 0fh, WA
	JR Z, Audio_Tick_ServiceVoices_A_ClearSlot
	LD WA, (XIZ + 02fh)
	EXTZ XWA
	AND XWA, 00008080h
	JR Z, Audio_Tick_ServiceVoices_A_NextSlot
	LD XWA, XIZ
	CALR Voice_Step_AmpDelay
	JR T, Audio_Tick_ServiceVoices_A_NextSlot

Audio_Tick_ServiceVoices_A_ClearSlot:
	LD WA, (XIZ + 02fh)
	EXTZ XWA
	AND XWA, 00008080h
	JR Z, Audio_Tick_ServiceVoices_A_NextSlot
	LD A, (XIZ)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	LD A, (XIZ)
	EXTZ WA
	CALL Voice_Reload_Levels
	LDW (XIZ + 02fh), 0000h

Audio_Tick_ServiceVoices_A_NextSlot:
	LD XWA, 1
	ADD (XSP + 004h), XWA
	LD XWA, (XSP + 004h)
	CP (XWA), 040h
	JR C, Audio_Tick_ServiceVoices_A_Loop

Audio_Tick_ServiceVoices_A_Done:
	POP XIZ
	INC 4, XSP
	RET

; ----------------------------------------------------------------------------
; Audio_Tick_ServiceVoices_B - Audio-tick pass B: pitch bend plus both envelope domains
; Entry: none
; Exit:  none
; Notes: Called by Audio_Process_Init on odd ticks, after Voice_Manager_PollBank.
;        Per live channel, in order:
;          slot+0x01 bit10 -> recompute pitch (Pitch_Emit_Reg400) and ship +0x400
;              through ToneGen_WriteVoicePitch;
;          then the same delayed/immediate split as pass A on slot+0x2f, plus the
;              expression domain: slot+0x31 bit15 -> Voice_Step_ExprRamp, or the
;              immediate Voice_Clear_HoldBit / Voice_Reload_Levels / slot+0x31 = 0.
; ----------------------------------------------------------------------------
Audio_Tick_ServiceVoices_B:	; 027AC4h
	DEC 4, XSP
	PUSH XIZ
	CALR Voice_TickNoteDecay
	CALR Pitch_Bend_Ramp_Tick
	LD WA, (041343h)
	BIT 0ah, WA
	JRL Z, Audio_Tick_ServiceVoices_B_LoopB_Start
	CALL Voice_Query_AllChannels
	LDA XWA, XHL + 005h
	LD (XSP + 004h), XWA
	CP (XWA), 040h
	JRL NC, Audio_Tick_ServiceVoices_B_ScanLFO

Audio_Tick_ServiceVoices_B_LoopA:
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	LDA XIZ, XBC + WA
	LD WA, (XIZ + 001h)
	BIT 0ah, WA
	JR Z, Audio_Tick_ServiceVoices_B_CheckPortaA
	LD XWA, XIZ
	CALR Pitch_Emit_Reg400
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteVoicePitch

Audio_Tick_ServiceVoices_B_CheckPortaA:
	LD XWA, (XIZ + 023h)
	LD WA, (XWA + 00ah)
	EXTZ XWA
	BIT 0fh, WA
	JR Z, Audio_Tick_ServiceVoices_B_ClearNoteOffA
	LD WA, (XIZ + 02fh)
	EXTZ XWA
	AND XWA, 00008080h
	JR Z, Audio_Tick_ServiceVoices_B_CheckPortamento2A
	LD XWA, XIZ
	CALR Voice_Step_AmpDelay
	JR T, Audio_Tick_ServiceVoices_B_NextSlotA

Audio_Tick_ServiceVoices_B_CheckPortamento2A:
	LD WA, (XIZ + 031h)
	EXTZ XWA
	BIT 0fh, WA
	JR Z, Audio_Tick_ServiceVoices_B_NextSlotA
	LD XWA, XIZ
	CALR Voice_Step_ExprRamp
	JR T, Audio_Tick_ServiceVoices_B_NextSlotA

Audio_Tick_ServiceVoices_B_ClearNoteOffA:
	LD WA, (XIZ + 02fh)
	EXTZ XWA
	AND XWA, 00008080h
	JR Z, Audio_Tick_ServiceVoices_B_ClearPorta2A
	LD A, (XIZ)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	LD A, (XIZ)
	EXTZ WA
	CALL Voice_Reload_Levels
	LDW (XIZ + 02fh), 0000h
	JR T, Audio_Tick_ServiceVoices_B_NextSlotA

Audio_Tick_ServiceVoices_B_ClearPorta2A:
	LD WA, (XIZ + 031h)
	EXTZ XWA
	BIT 0fh, WA
	JR Z, Audio_Tick_ServiceVoices_B_NextSlotA
	LD A, (XIZ)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	LD A, (XIZ)
	EXTZ WA
	CALL Voice_Reload_Levels
	LDW (XIZ + 031h), 0000h

Audio_Tick_ServiceVoices_B_NextSlotA:
	LD XWA, 1
	ADD (XSP + 004h), XWA
	LD XWA, (XSP + 004h)
	CP (XWA), 040h
	JRL C, Audio_Tick_ServiceVoices_B_LoopA
	JRL T, Audio_Tick_ServiceVoices_B_ScanLFO

Audio_Tick_ServiceVoices_B_LoopB_Start:
	CALL Voice_Query_AllChannels
	LDA XWA, XHL + 005h
	LD (XSP + 004h), XWA
	CP (XWA), 040h
	JRL NC, Audio_Tick_ServiceVoices_B_ScanLFO

Audio_Tick_ServiceVoices_B_LoopB:
	LD XWA, (XSP + 004h)
	LD A, (XWA)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	LDA XIZ, XBC + WA
	LD XWA, (XIZ + 023h)
	LD WA, (XWA + 00ah)
	EXTZ XWA
	BIT 0fh, WA
	JR Z, Audio_Tick_ServiceVoices_B_ClearNoteOffB
	LD WA, (XIZ + 02fh)
	EXTZ XWA
	AND XWA, 00008080h
	JR Z, Audio_Tick_ServiceVoices_B_CheckPortamento2B
	LD XWA, XIZ
	CALR Voice_Step_AmpDelay
	JR T, Audio_Tick_ServiceVoices_B_NextSlotB

Audio_Tick_ServiceVoices_B_CheckPortamento2B:
	LD WA, (XIZ + 031h)
	EXTZ XWA
	BIT 0fh, WA
	JR Z, Audio_Tick_ServiceVoices_B_NextSlotB
	LD XWA, XIZ
	CALR Voice_Step_ExprRamp
	JR T, Audio_Tick_ServiceVoices_B_NextSlotB

Audio_Tick_ServiceVoices_B_ClearNoteOffB:
	LD WA, (XIZ + 02fh)
	EXTZ XWA
	AND XWA, 00008080h
	JR Z, Audio_Tick_ServiceVoices_B_ClearPorta2B
	LD A, (XIZ)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	LD A, (XIZ)
	EXTZ WA
	CALL Voice_Reload_Levels
	LDW (XIZ + 02fh), 0000h
	JR T, Audio_Tick_ServiceVoices_B_NextSlotB

Audio_Tick_ServiceVoices_B_ClearPorta2B:
	LD WA, (XIZ + 031h)
	EXTZ XWA
	BIT 0fh, WA
	JR Z, Audio_Tick_ServiceVoices_B_NextSlotB
	LD A, (XIZ)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	LD A, (XIZ)
	EXTZ WA
	CALL Voice_Reload_Levels
	LDW (XIZ + 031h), 0000h

Audio_Tick_ServiceVoices_B_NextSlotB:
	LD XWA, 1
	ADD (XSP + 004h), XWA
	LD XWA, (XSP + 004h)
	CP (XWA), 040h
	JRL C, Audio_Tick_ServiceVoices_B_LoopB

Audio_Tick_ServiceVoices_B_ScanLFO:
	LD QIZH, 0
	CP QIZH, 01ah
	JR NC, Audio_Tick_ServiceVoices_B_Done

Audio_Tick_ServiceVoices_B_LFOLoopBody:
	LD A, QIZH
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	LDA XBC, XBC + WA
	LD A, (XBC + 063h)
	BIT 0, A
	JR Z, Audio_Tick_ServiceVoices_B_LFONextSlot
	BIT 1, A
	JR Z, Audio_Tick_ServiceVoices_B_LFO_CheckRampDown
	BIT 2, A
	JR Z, Audio_Tick_ServiceVoices_B_LFO_ApplyFilter
	BIT 3, A
	JR NZ, Audio_Tick_ServiceVoices_B_LFONextSlot
	LD A, QIZH
	EXTZ WA
	CALR Voice_ToneTableRamp_Up
	JR T, Audio_Tick_ServiceVoices_B_LFONextSlot

Audio_Tick_ServiceVoices_B_LFO_ApplyFilter:
	SET 2, (XBC + 063h)
	LD A, QIZH
	EXTZ WA
	CALR Voice_ToneTableApply_Filter
	JR T, Audio_Tick_ServiceVoices_B_LFONextSlot

Audio_Tick_ServiceVoices_B_LFO_CheckRampDown:
	BIT 2, A
	JR NZ, Audio_Tick_ServiceVoices_B_LFO_RampDown
	BIT 4, A
	JR NZ, Audio_Tick_ServiceVoices_B_LFONextSlot
	LD A, QIZH
	EXTZ WA
	CALR Voice_ToneTableRamp_Down
	JR T, Audio_Tick_ServiceVoices_B_LFONextSlot

Audio_Tick_ServiceVoices_B_LFO_RampDown:
	RES 2, (XBC + 063h)
	LD A, QIZH
	EXTZ WA
	CALR Voice_ToneTableApply_Pitch

Audio_Tick_ServiceVoices_B_LFONextSlot:
	INC 1, QIZH
	CP QIZH, 01ah
	JR C, Audio_Tick_ServiceVoices_B_LFOLoopBody

Audio_Tick_ServiceVoices_B_Done:
	POP XIZ
	INC 4, XSP
	RET

Voice_SetLFO_ActiveFlag:
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Ah
	ORW (XBC + WA), 2000h
	RET

Voice_ClearLFO_ActiveFlag:
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Ah
	ANDW (XBC + WA), 0dfffh
	RET

Voice_DSP_OutputConfig:
	db 0BFh, 0F6h, 037h, 0BFh, 006h, 043h, 0BFh, 008h
	db 041h, 08Fh, 006h, 03Fh, 000h, 06Eh, 06Eh, 08Fh
	db 008h, 021h, 0C9h, 08Dh, 0DAh, 012h, 08Fh, 006h
	db 021h, 0C9h, 08Bh, 0D9h, 012h, 0DAh, 088h, 01Dh
	db 0D2h, 037h, 003h, 0F2h, 00Eh, 052h, 004h, 053h
	db 08Fh, 008h, 021h, 0C9h, 08Dh, 0DAh, 012h, 08Fh
	db 006h, 021h, 0D8h, 012h, 0D8h, 0CEh, 00Ch, 000h
	db 0C9h, 08Bh, 0D9h, 012h, 0DAh, 088h, 0DAh, 0A8h
	db 01Dh, 08Eh, 01Ah, 002h, 0B7h, 063h, 0BFh, 004h
	db 002h, 000h, 000h, 068h, 019h, 09Fh, 004h, 020h
	db 0E8h, 012h, 0E8h, 080h, 0A7h, 080h, 090h, 020h
	db 020h, 000h, 0F2h, 0CCh, 051h, 004h, 031h, 01Dh
	db 0B3h, 0DBh, 002h, 09Fh, 004h, 061h, 09Fh, 004h
	db 020h, 0E8h, 012h, 0E8h, 080h, 0A7h, 080h, 090h
