Voice_CC_SetVolume:
	CP C, 0
	JR Z, VoiceCC_SetVolume_Mute
	LD DE, (041343h)
	BIT 0, DE
	JR Z, VoiceCC_SetVolume_Bit1Set
	EXTZ WA
	MULS_WA 011fh
	LD DE, WA
	LDA XHL, 041374h
	LD A, C
	EXTZ WA
	ADD WA, WA
	LDA XBC, 011D16h
	LD WA, (XBC + WA)
	LD (XHL + DE), WA
	RET

VoiceCC_SetVolume_Bit1Set:
	LD DE, (041343h)
	BIT 1, DE
	JR Z, VoiceCC_SetVolume_RawSub
	EXTZ WA
	MULS_WA 011fh
	LD DE, WA
	LDA XHL, 041374h
	LD A, C
	EXTZ WA
	ADD WA, WA
	LDA XBC, 011D16h
	LD WA, (XBC + WA)
	LD (XHL + DE), WA
	RET

VoiceCC_SetVolume_RawSub:
	EXTZ WA
	MULS_WA 011fh
	LD DE, WA
	LDA XHL, 041374h
	LD A, C
	EXTZ WA
	SUB WA, 007fh
	LD (XHL + DE), WA
	RET

VoiceCC_SetVolume_Mute:
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041374h
	LDW (XBC + WA), 0fe00h
	RET

Voice_CC_SetPan:
	EXTZ WA
	MULS_WA 011fh
	LDA XDE, 041376h
	LD (XDE + WA), C
	RET

Voice_CC_SetExpression:
	CP C, 0
	JR Z, VoiceCC_SetExpression_Mute
	LD DE, (041343h)
	BIT 0, DE
	JR Z, VoiceCC_SetExpression_Bit1Set
	EXTZ WA
	MULS_WA 011fh
	LD DE, WA
	LDA XHL, 041378h
	LD A, C
	EXTZ WA
	ADD WA, WA
	LDA XBC, 011D16h
	LD WA, (XBC + WA)
	LD (XHL + DE), WA
	RET

VoiceCC_SetExpression_Bit1Set:
	LD DE, (041343h)
	BIT 1, DE
	JR Z, VoiceCC_SetExpression_RawSub
	EXTZ WA
	MULS_WA 011fh
	LD DE, WA
	LDA XHL, 041378h
	LD A, C
	EXTZ WA
	ADD WA, WA
	LDA XBC, 011D16h
	LD WA, (XBC + WA)
	LD (XHL + DE), WA
	RET

VoiceCC_SetExpression_RawSub:
	EXTZ WA
	MULS_WA 011fh
	LD DE, WA
	LDA XHL, 041378h
	LD A, C
	EXTZ WA
	SUB WA, 007fh
	LD (XHL + DE), WA
	RET

VoiceCC_SetExpression_Mute:
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041378h
	LDW (XBC + WA), 0fe00h
	RET

Voice_CC_SetSustain:
	CP C, 0
	JR Z, VoiceCC_SetSustain_ClearBit
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041372h
	ORW (XBC + WA), 0001h
	RET

VoiceCC_SetSustain_ClearBit:
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041372h
	ANDW (XBC + WA), 0fffeh
	RET

Voice_CC_SetSostenuto:
	EXTZ WA
	MULS_WA 011fh
	LDA XDE, 041377h
	LD (XDE + WA), C
	RET

Voice_CC_SetSoftPedal:
	EXTZ WA
	MULS_WA 011fh
	LDA XDE, 04137Ah
	LD (XDE + WA), C
	RET

Voice_CC_SetSostenutoFlag:
	CP C, 0
	JR Z, VoiceCC_SetSostenuto_ClearFlag
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041372h
	ORW (XBC + WA), 4000h
	RET

VoiceCC_SetSostenuto_ClearFlag:
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041372h
	ANDW (XBC + WA), 0bfffh
	RET

Voice_CC_SetPortamentoRate:
	EXTZ WA
	MULS_WA 011fh
	LDA XDE, 04137Bh
	LD (XDE + WA), C
	RET

Voice_CC_SetPortamentoDepth:
	LD E, C
	EXTZ DE
	SUB DE, 0080h
	ADD DE, DE
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04137Ch
	LD (XBC + WA), DE
	RET

Voice_CC_SetPortamentoTime:
	LD E, C
	SUB E, 040h
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04137Eh
	LD (XBC + WA), E
	RET

Voice_CC_SetModWheelRange:
	db 0CBh, 0D8h, 066h, 013h, 0D8h, 012h, 0D8h, 009h
	db 01Fh, 001h, 0F2h, 072h, 013h, 004h, 031h, 0D3h
	db 007h, 0E4h, 0E0h, 03Eh, 002h, 000h, 00Eh, 0D8h
	db 012h, 0D8h, 009h, 01Fh, 001h, 0F2h, 072h, 013h
	db 004h, 031h, 0D3h, 007h, 0E4h, 0E0h, 03Ch, 0FDh
	db 0FFh, 00Eh

Voice_CC_SetReverbDepth:
	EXTZ WA
	MULS_WA 011fh
	LDA XDE, 04137Fh
	LD (XDE + WA), C
	RET

Voice_CC_SetChorusEnable:
	CP C, 0
	JR Z, VoiceCC_SetChorus_ClearBit
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041372h
	ORW (XBC + WA), 0004h
	RET

VoiceCC_SetChorus_ClearBit:
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041372h
	ANDW (XBC + WA), 0fffbh
	RET

Voice_CC_SetChorusDepth:
	EXTZ WA
	MULS_WA 011fh
	LDA XDE, 041380h
	LD (XDE + WA), C
	RET

Voice_CC_SetDelayDepth:
	EXTZ WA
	MULS_WA 011fh
	LDA XDE, 04138Dh
	LD (XDE + WA), C
	RET

Voice_CC_SetDelayEnable:
	CP C, 0
	JR Z, VoiceCC_SetDelay_ClearBit
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Ah
	ORW (XBC + WA), 0100h
	RET

VoiceCC_SetDelay_ClearBit:
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Ah
	ANDW (XBC + WA), 0feffh
	RET

Voice_CC_SetDelayFeedback:
	EXTZ WA
	MULS_WA 011fh
	LDA XDE, 04138Eh
	LD (XDE + WA), C
	RET

Voice_SetPolyphonyMode:
	PUSH QIZ
	CP A, 1
	JR NZ, Voice_SetPolyphonyMode_Else
	ORW (041343h), 0001h
	LD WA, 1
	CALL Voice_Reset_Engine
	JR T, Voice_SetPolyphonyMode_Apply

Voice_SetPolyphonyMode_Else:
	ANDW (041343h), 0fffeh
	LD WA, 0
	CALL Voice_Reset_Engine

Voice_SetPolyphonyMode_Apply:
	CALL VoiceSlot_ClearAll
	LD QIZH, 0
	CP QIZH, 00fh
	JR UGT, Voice_SetPolyphonyMode_LoopExit

Voice_SetPolyphonyMode_LoopBody:
	LD A, QIZH
	EXTZ WA
	CALR Voice_PerVoice_PortamentoPitchUpdate
	INC 1, QIZH
	CP QIZH, 00fh
	JR ULE, Voice_SetPolyphonyMode_LoopBody

Voice_SetPolyphonyMode_LoopExit:
	POP QIZ
	RET

VoiceCC_Stub_Ret1:
	RET

VoiceCC_Stub_Ret2:
	RET

Voice_SetMasterTune:
	SUB A, 040h
	ADD A, A
	EXTS WA
	LD (041347h), WA
	RET

Voice_SetPitchBendRange:
	EXTS WA
	SLA 8, WA
	LD (041349h), WA
	RET

Voice_SetKeyShiftEnable:
	CP A, 0
	JR Z, Voice_SetKeyShiftRange
	LD WA, (041343h)
	BIT 0ch, WA
	RET NZ
	ORW (041343h), 0800h
	LDW (04135Ch), 0000h
	RET

Voice_SetKeyShiftRange:
	LD WA, (041343h)
	BIT 0ch, WA
	RET Z
	LD WA, (041343h)
	EXTZ XWA
	AND XWA, 0ffff2fffh
	SET 0dh, WA
	CPW (04135Ch), 0014h
	JR ULE, Voice_SetKeyShiftRange_BranchA
	SET 0fh, WA
	JR T, Voice_SetKeyShiftRange_BranchB

Voice_SetKeyShiftRange_BranchA:
	SET 0eh, WA

Voice_SetKeyShiftRange_BranchB:
	LD (041343h), WA
	LDW (04135Ch), 0000h
	RET

Voice_SetParam_04134D:
	LD (04134Dh), A
	RET

; ----------------------------------------------------------------------------
; ScaleTune_Get_Global_Mode - read the panel-wide scale-tuning mode
; Entry: None
; Exit:  L = ScaleTune_GlobalMode  (0x00 none, 0x40 flat offset, 0x41/0x42 per-key
;        tables, 0x80 user scale, anything else = a temperament table row)
; Notes: MEASURED.
; ----------------------------------------------------------------------------
ScaleTune_Get_Global_Mode:		; 028B96h
	LD L, (04134Dh)
	RET

Voice_SetRhythmMode:
	BIT 3, A
	JR Z, Voice_SetRhythmMode_BranchA
	LD (04135Eh), 003h
	JR T, Voice_SetRhythmMode_BranchB

Voice_SetRhythmMode_BranchA:
	LD (04135Eh), 001h

Voice_SetRhythmMode_BranchB:
	LD (04135Fh), 001h
	LD C, A
	AND C, 0f0h
	SRL 4, C
	EXTZ BC
	ADD BC, BC
	LDA XDE, 0F6F3h:24
	LD BC, (XDE + BC)
	LD (041360h), BC
	BIT 2, A
	JR Z, Voice_SetRhythmMode_BranchC
	LDW (041362h), 8000h
	JR T, Voice_SetRhythmMode_BranchD

Voice_SetRhythmMode_BranchC:
	LDW (041362h), 0a000h

Voice_SetRhythmMode_BranchD:
	AND A, 003h
	SLL 3, A
	LD C, A
	LD_A 0c8h
	SUB A, C
	EXTZ WA
	LD (041364h), WA
	RET

Voice_SetParam_04134B:
	LD (04134Bh), A
	RET

Voice_SetCCMaxFlag:
	CP A, 07fh
	JR NZ, Voice_SetCCMaxFlag_Clear
	ORW (041343h), 0002h
	RET

Voice_SetCCMaxFlag_Clear:
	ANDW (041343h), 0fffdh
	RET

Voice_WriteChannelAssign:
	EXTZ WA
	ADD WA, 000ch
	LDA XDE, 041342h
	SUB C, 080h
	LD (XDE + WA), C
	RET

; ----------------------------------------------------------------------------
; ScaleTune_Get_User_Offset - one entry of the 12-note user scale
; Entry: WA = pitch class 0..11 (key mod 12, 0 = C)
; Exit:  L = signed offset; the caller doubles it (unit = 2/256 semitone = 0.78 cent)
; Notes: Reads ScaleTune_UserOffsets = 0x041342 + 0x0C + pitch class = 0x04134E..59.
;        MEASURED.
; ----------------------------------------------------------------------------
ScaleTune_Get_User_Offset:		; 028C28h
	EXTZ WA
	ADD WA, 000ch
	LDA XBC, 041342h
	LD L, (XBC + WA)
	RET

Voice_AllVoices_UpdateVelocity:
	DEC 2, XSP
	PUSH XIZ
	AND A, 00fh
	LD (04134Ch), A
	LD (XSP + 004h), 000h
	CP (XSP + 004h), 01ah
	JRL NC, Voice_AllVoices_UpdateVelocity_Exit

Voice_AllVoices_UpdateVelocity_LoopStart:
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041372h
	LD WA, (XBC + WA)
	BIT 1, WA
	JRL Z, Voice_AllVoices_UpdateVelocity_InnerStep
	LD A, (XSP + 004h)
	EXTZ WA
	CALL Voice_Query_PartVoices
	LDA XWA, XHL + 005h
	LD XIZ, XWA
	CP (XIZ), 040h
	JRL NC, Voice_AllVoices_UpdateVelocity_InnerStep

Voice_AllVoices_UpdateVelocity_InnerLoop:
	LD A, (XIZ)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 043092h
	LD A, (XBC + WA)
	LD (XSP + 004h), A
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Eh
	LD XWA, (XBC + WA)
	LD A, (XWA + 010h)
	AND A, 0c0h
	CP A, 080h
	JR Z, Voice_AllVoices_UpdateVelocity_TypeB
	CP A, 0c0h
	JR Z, Voice_AllVoices_UpdateVelocity_TypeA
	CP A, 040h
	JR Z, Voice_AllVoices_UpdateVelocity_TypeA
	CP A, 0
	JR NZ, Voice_AllVoices_UpdateVelocity_NextOuter

Voice_AllVoices_UpdateVelocity_TypeA:
	LD A, (XIZ)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	EXTS XWA
	ADD XWA, XBC
	CALL Level_Build_Reg0C0
	LD A, (XIZ)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	EXTS XWA
	ADD XWA, XBC
	CALL Voice_Build_GateCommand
	JR T, Voice_AllVoices_UpdateVelocity_NextOuter

Voice_AllVoices_UpdateVelocity_TypeB:
	LD A, (XIZ)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	EXTS XWA
	ADD XWA, XBC
	CALL Voice_ComputePitchBend2
	LD A, (XIZ)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	EXTS XWA
	ADD XWA, XBC
	CALL Voice_Build_GateCommand_NoPartial

Voice_AllVoices_UpdateVelocity_NextOuter:
	LD A, (XIZ)
	EXTZ WA
	CALL ToneGen_ReadPitch_AndScale
	INC 1, XIZ
	CP (XIZ), 040h
	JRL C, Voice_AllVoices_UpdateVelocity_InnerLoop

Voice_AllVoices_UpdateVelocity_InnerStep:
	INC 1, (XSP + 004h)
	CP (XSP + 004h), 01ah
	JRL C, Voice_AllVoices_UpdateVelocity_LoopStart

Voice_AllVoices_UpdateVelocity_Exit:
	POP XIZ
	INC 2, XSP
	RET

Voice_SetMonoMode:
	CP A, 0
	JR NZ, Voice_SetMonoMode_Clear
	ORW (041343h), 0200h
	RET

Voice_SetMonoMode_Clear:
	ANDW (041343h), 0fdffh
	RET

; ----------------------------------------------------------------------------
; ScaleTune_Is_Global_Enabled - is scale tuning taken from the panel or from the patch?
; Entry: None
; Exit:  HL = ToneGen_GlobalFlags & 0x0200 (nonzero = use the global mode)
; Notes: When zero, Voice_Pitch_Compute reads the mode from the PATCH RECORD byte
;        +0x13 instead.  MEASURED (this branch is not described in the audit note).
; ----------------------------------------------------------------------------
ScaleTune_Is_Global_Enabled:		; 028D42h
	LD HL, (041343h)
	AND HL, 0200h
	RET

; ----------------------------------------------------------------------------
; Pitch_Refresh_Sounding_Voices - re-ship +0x400 for a part s currently sounding voices
; Entry: XWA = pointer to a voice-number list; the list starts at XWA+5 and is
;        terminated by the first entry >= 0x40
; Exit:  Chip register +0x400 rewritten for every listed voice whose descriptor
;        selects it
; Notes: For each voice it reads Voice_Desc_Table[ch][+0x01] & 0x3C and acts only on
;        the values 0x04, 0x08, 0x10, 0x20; then calls Pitch_Emit_Reg400 followed by
;        the single-register write.  Called after a master-TUNE change and from the
;        MIDI control-change handler.  MEASURED.
; ----------------------------------------------------------------------------
Pitch_Refresh_Sounding_Voices:		; 028D4Ch
	DEC 4, XSP
	PUSH XIZ
	LDA XBC, 04308Eh
	LD (XSP + 004h), XBC
	INC 5, XWA
	LD XIZ, XWA
	CP (XIZ), 040h
	JR NC, Pitch_Refresh_Sounding_Voices_Exit

Pitch_Refresh_Sounding_Voices_LoopBody:
	LD A, (XIZ)
	EXTZ WA
	MULS_WA 047h
	LD BC, WA
	LD XWA, (XSP + 004h)
	EXTS XBC
	ADD XBC, XWA
	LD WA, (XBC + 001h)
	AND WA, 003ch
	CP WA, 0010h
	JR Z, Pitch_Refresh_Sounding_Voices_BranchB
	CP WA, 0020h
	JR Z, Pitch_Refresh_Sounding_Voices_BranchA
	CP WA, 0008h
	JR Z, Pitch_Refresh_Sounding_Voices_BranchA
	CP WA, 4
	JR NZ, Pitch_Refresh_Sounding_Voices_LoopStep

Pitch_Refresh_Sounding_Voices_BranchA:
	LD XWA, XBC
	CALL Pitch_Emit_Reg400
	LD A, (XIZ)
	EXTZ WA
	LDA XBC, 0451CCh
	CALR ToneGen_WriteVoice_Long
	JR T, Pitch_Refresh_Sounding_Voices_LoopStep

Pitch_Refresh_Sounding_Voices_BranchB:
	LD XWA, XBC
	CALL Voice_Pitch_WriteOutputReg_Secondary
	LD A, (XIZ)
	EXTZ WA
	LDA XBC, 0451CCh
	CALR ToneGen_WriteVoice_Long

Pitch_Refresh_Sounding_Voices_LoopStep:
	INC 1, XIZ
	CP (XIZ), 040h
	JR C, Pitch_Refresh_Sounding_Voices_LoopBody

Pitch_Refresh_Sounding_Voices_Exit:
	POP XIZ
	INC 4, XSP
	RET

Voice_AllVoices_WriteAmplitude:
	DEC 4, XSP
	PUSH XIZ
	LDA XBC, 04308Eh
	LD (XSP + 004h), XBC
	INC 5, XWA
	LD XIZ, XWA
	CP (XIZ), 040h
	JR NC, Voice_AllVoices_WriteAmplitude_Exit

Voice_AllVoices_WriteAmplitude_LoopBody:
	LD A, (XIZ)
	EXTZ WA
	MULS_WA 047h
	LD BC, WA
	LD XWA, (XSP + 004h)
	EXTS XBC
	ADD XBC, XWA
	LD WA, (XBC + 001h)
	AND WA, 003ch
	CP WA, 0010h
	JR Z, Voice_AllVoices_WriteAmplitude_BranchB
	CP WA, 0020h
	JR Z, Voice_AllVoices_WriteAmplitude_BranchA
	CP WA, 0008h
	JR Z, Voice_AllVoices_WriteAmplitude_BranchA
	CP WA, 4
	JR NZ, Voice_AllVoices_WriteAmplitude_LoopStep

Voice_AllVoices_WriteAmplitude_BranchA:
	LD XWA, XBC
	CALL Voice_ApplyPortamento
	JR T, Voice_AllVoices_WriteAmplitude_LoopStep

Voice_AllVoices_WriteAmplitude_BranchB:
	LD XWA, XBC
	CALL Voice_ApplyPortamento2

Voice_AllVoices_WriteAmplitude_LoopStep:
	LD A, (XIZ)
	EXTZ WA
	LDA XBC, 0451CCh
	CALR ToneGen_WriteVoice_Short
	INC 1, XIZ
	CP (XIZ), 040h
	JR C, Voice_AllVoices_WriteAmplitude_LoopBody

Voice_AllVoices_WriteAmplitude_Exit:
	POP XIZ
	INC 4, XSP
	RET

Voice_AllNotes_SustainRetrigger:
	LDA XSP, XSP - 10
	PUSH XIZ
	LD (XSP + 00ch), C
	LDA XBC, 04308Eh
	LD (XSP + 004h), XBC
	INC 5, XWA
	LD (XSP + 008h), XWA
	CP (XWA), 040h
	JRL NC, Voice_AllNotes_SustainRetrigger_Exit

Voice_AllNotes_SustainRetrigger_LoopBody:
	LD XWA, (XSP + 008h)
	LD A, (XWA)
	EXTZ WA
	MULS_WA 047h
	LD BC, WA
	LD XWA, (XSP + 004h)
	LDA XIZ, XWA + BC
	LD WA, (XIZ + 001h)
	AND WA, 003ch
	CP WA, 0010h
	JRL Z, Voice_AllNotes_SustainRetrigger_BranchF
	CP WA, 0020h
	JR Z, Voice_AllNotes_SustainRetrigger_BranchA
	CP WA, 0008h
	JR Z, Voice_AllNotes_SustainRetrigger_BranchA
	CP WA, 4
	JRL NZ, Voice_AllNotes_SustainRetrigger_LoopStep

Voice_AllNotes_SustainRetrigger_BranchA:
	LD WA, (XIZ + 001h)
	EXTZ XWA
	BIT 0fh, WA
	JR NZ, Voice_AllNotes_SustainRetrigger_BranchB
	LD XWA, (XIZ + 023h)
	LD WA, (XWA + 00ah)
	BIT 0, WA
	JR NZ, Voice_AllNotes_SustainRetrigger_BranchD

Voice_AllNotes_SustainRetrigger_BranchB:
	LD WA, (XIZ + 001h)
	BIT 8, WA
	JR Z, Voice_AllNotes_SustainRetrigger_BranchC
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGA
	LD XWA, (XSP + 008h)
	LD A, (XWA)
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteSegRegs_SameLevel
	LD XWA, (XSP + 008h)
	LD A, (XWA)
	EXTZ WA
	LD BC, (XIZ + 02dh)
	CALR ToneGen_WriteVoice_Direct
	LD XWA, (XSP + 008h)
	LD A, (XWA)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	ANDW (XIZ + 001h), 0feffh
	JRL T, Voice_AllNotes_SustainRetrigger_LoopStep

Voice_AllNotes_SustainRetrigger_BranchC:
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGA
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGB
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGC
	LD XWA, (XSP + 008h)
	LD A, (XWA)
	EXTZ WA
	LDA XBC, 0451CCh
	CALR ToneGen_WriteVoice_6Words
	JR T, Voice_AllNotes_SustainRetrigger_LoopStep

Voice_AllNotes_SustainRetrigger_BranchD:
	LD WA, (XIZ + 001h)
	BIT 8, WA
	JR Z, Voice_AllNotes_SustainRetrigger_BranchE
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGA
	LD XWA, (XSP + 008h)
	LD A, (XWA)
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteSegRegs_SameLevel
	LD XWA, (XSP + 008h)
	LD A, (XWA)
	EXTZ WA
	LD BC, (XIZ + 02dh)
	CALR ToneGen_WriteVoice_Direct
	LD XWA, (XSP + 008h)
	LD A, (XWA)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	ANDW (XIZ + 001h), 0feffh
	JR T, Voice_AllNotes_SustainRetrigger_LoopStep

Voice_AllNotes_SustainRetrigger_BranchE:
	LD WA, (XIZ + 040h)
	AND WA, 00ffh
	JR NZ, Voice_AllNotes_SustainRetrigger_LoopStep
	LD XWA, XIZ
	CALL Voice_WriteVolume_SetFlag
	LD XWA, (XSP + 008h)
	LD A, (XWA)
	EXTZ WA
	LDA XBC, 0451CCh
	CALR ToneGen_WriteNote2ch
	JR T, Voice_AllNotes_SustainRetrigger_LoopStep

Voice_AllNotes_SustainRetrigger_BranchF:
	CP (XSP + 00ch), 000h
	JR Z, Voice_AllNotes_SustainRetrigger_LoopStep
	LD XWA, XIZ
	CALL Voice_WriteVolume_OrPan
	LD XWA, (XSP + 008h)
	LD A, (XWA)
	EXTZ WA
	LDA XBC, 0451CCh
	CALR ToneGen_WriteNote2ch

Voice_AllNotes_SustainRetrigger_LoopStep:
	LD XWA, 1
	ADD (XSP + 008h), XWA
	LD XWA, (XSP + 008h)
	CP (XWA), 040h
	JRL C, Voice_AllNotes_SustainRetrigger_LoopBody

Voice_AllNotes_SustainRetrigger_Exit:
	POP XIZ
	LDA XSP, XSP + 00ah
	RET

