Voice_ModWheel_Apply:
	LDA XSP, XSP - 10
	PUSH XIZ
	LD (XSP + 00ah), C
	LD (XSP + 00ch), A
	LD A, (XSP + 00ch)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Eh
	LD XWA, (XBC + WA)
	LD A, (XWA + 010h)
	AND A, 0c0h
	CP A, 080h
	JR Z, Voice_ModWheel_Apply_StereoLoopA
	CP A, 040h
	JR Z, Voice_ModWheel_Apply_StereoPath
	CP A, 0c0h
	JR Z, Voice_ModWheel_Apply_StereoPath
	CP A, 0
	JRL NZ, Voice_ModWheel_Apply_Exit

Voice_ModWheel_Apply_StereoPath:
	LDW (XSP + 008h), 0000h
	CPW (XSP + 008h), 0002h
	JRL NC, Voice_ModWheel_Apply_Exit

Voice_ModWheel_Apply_PolyPath:
	LD A, (XSP + 00ch)
	LD IYL, A
	EXTZ IY
	LD A, (XSP + 00ah)
	LD IXL, A
	EXTZ IX
	LD A, (XSP + 00ch)
	EXTZ WA
	MULS_WA 011fh
	LD DE, WA
	LDA XHL, 04136Eh
	LD WA, (XSP + 008h)
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	ADD XBC, 00000017h
	LD XIZ, XBC
	ADD XIZ, (XHL + DE)
	LD WA, IY
	LD BC, IX
	LD XDE, XIZ
	CALR AudioChannel_Dispatch
	INCW 1, (XSP + 008h)
	CPW (XSP + 008h), 0002h
	JR C, Voice_ModWheel_Apply_PolyPath
	JR T, Voice_ModWheel_Apply_Exit

Voice_ModWheel_Apply_StereoLoopA:
	LD A, (XSP + 00ch)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Eh
	LD XWA, (XBC + WA)
	LD (XSP + 004h), XWA
	LDW (XSP + 008h), 0000h
	CPW (XSP + 008h), 0002h
	JR NC, Voice_ModWheel_Apply_Exit

Voice_ModWheel_Apply_StereoLoopB:
	LD A, (XSP + 00ch)
	LD IXL, A
	EXTZ IX
	LD A, (XSP + 00ah)
	LD L, A
	EXTZ HL
	LD WA, (XSP + 008h)
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	ADD XBC, 00000015h
	LD XDE, XBC
	ADD XDE, (XSP + 004h)
	LD WA, IX
	LD BC, HL
	CALR AudioChannel_Dispatch
	INCW 1, (XSP + 008h)
	CPW (XSP + 008h), 0002h
	JR C, Voice_ModWheel_Apply_StereoLoopB

Voice_ModWheel_Apply_Exit:
	POP XIZ
	LDA XSP, XSP + 00ah
	RET

