	LD E, A
	EXTZ DE
	LD A, (XSP)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetSostenutoFlag
	LD A, (XSP + 002h)
	EXTZ WA
	LD BC, 1
	CALL AlgoType_StateWrite
	LD A, (XSP + 002h)
	LD E, A
	EXTZ DE
	LD A, (XSP)
	LD C, A
	EXTZ BC
	LD WA, DE
