	RET

Voice_PortamentoSlots_WriteHW:
	DEC 6, XSP
	LD (XSP + 004h), A
	LD A, (XSP + 004h)
	EXTZ WA
	CALL Voice_AllocateForRelease
	LD A, (XSP + 004h)
	EXTZ WA
	CALL Voice_SetLFO_ActiveFlag
	LD A, (XSP + 004h)
	EXTZ WA
	CALL Voice_Query_PartVoices
	LDA XWA, XHL + 005h
	LD (XSP), XWA
	CP (XWA), 040h
	JRL NC, Voice_PortamentoSlots_WriteHW_Exit

Voice_PortamentoSlots_WriteHW_LoopBody:
	LD XWA, (XSP)
	LD A, (XWA)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Fh
	LD WA, (XBC + WA)
	AND WA, 003ch
	CP WA, 0008h
	JR Z, Voice_PortamentoSlots_WriteHW_BranchSkip
	CP WA, 0020h
	JR Z, Voice_PortamentoSlots_WriteHW_NopCont1
	CP WA, 0010h
	JR Z, Voice_PortamentoSlots_WriteHW_NopCont1
	CP WA, 4
	JRL NZ, Voice_PortamentoSlots_WriteHW_LoopStep

Voice_PortamentoSlots_WriteHW_NopCont1:
	RES 7, (P6)
	LD XWA, (XSP)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0840h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a200h
	JR T, Voice_PortamentoSlots_WriteHW_NopCont2

Voice_PortamentoSlots_WriteHW_NopCont2:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD XWA, (XSP)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0800h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a280h
	JR T, Voice_PortamentoSlots_WriteHW_NopCont3

Voice_PortamentoSlots_WriteHW_NopCont3:
	NOP
	NOP
	NOP
	JR T, Voice_PortamentoSlots_WriteHW_LoopStep

Voice_PortamentoSlots_WriteHW_BranchSkip:
	RES 7, (P6)
	LD XWA, (XSP)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0840h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a200h
	JR T, Voice_PortamentoSlots_WriteHW_NopCont4

Voice_PortamentoSlots_WriteHW_NopCont4:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD XWA, (XSP)
	LD A, (XWA)
	EXTZ WA
	ADD WA, 0800h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a280h
	JR T, Voice_PortamentoSlots_WriteHW_NopCont5

Voice_PortamentoSlots_WriteHW_NopCont5:
	NOP
	NOP
	NOP

Voice_PortamentoSlots_WriteHW_LoopStep:
	LD XWA, 1
	ADD (XSP), XWA
	LD XWA, (XSP)
	CP (XWA), 040h
	JRL C, Voice_PortamentoSlots_WriteHW_LoopBody

Voice_PortamentoSlots_WriteHW_Exit:
	INC 6, XSP
	RET

; ===========================================================================
; Voice_CtrlChange - Process MIDI Control Change messages
; ===========================================================================
; Entry: XWA = pointer to 4-byte CC data:
;        +0 = status byte (0xBn where n=channel)
;        +1 = channel number (0-25)
;        +2 = controller number
;        +3 = controller value
; Exit:  Voice parameters updated based on CC number
; Notes: Handles standard MIDI CCs: Mod Wheel(1), Volume(7), Pan(10),
;        Expression(11), Sustain(64), Sostenuto(91), Soft(93), Portamento(94)
;        Plus proprietary CCs in 0x91-0x9D range for effects depth
; ===========================================================================
Voice_CtrlChange:
	PUSH XIZ
	LD XIZ, XWA
	CP (XIZ + 001h), 01ah
	JRL NC, Voice_CC_Exit
	LD A, (XIZ + 002h)
	CP A, 09dh
	JRL Z, Voice_CC_9D
	CP A, 09ch
	JRL Z, Voice_CC_9C
	CP A, 09bh
	JRL Z, Voice_CC_9B
	CP A, 097h
	JRL Z, Voice_CC_97
	CP A, 095h
	JRL Z, Voice_CC_95
	CP A, 091h
	JRL Z, Voice_CC_91
	CP A, 05eh
	JRL Z, Voice_CC_Portamento
	CP A, 05dh
	JRL Z, Voice_CC_Soft
	CP A, 05bh
	JRL Z, Voice_CC_Sostenuto
	CP A, 040h
	JRL Z, Voice_CC_Sustain
	CP A, 00bh
	JRL Z, Voice_CC_Expression
	CP A, 00ah
	JR Z, Voice_CC_Pan
	CP A, 7
	JR Z, Voice_CC_Volume
	CP A, 1
	JR Z, Voice_CC_ModWheel
	EXTZ WA
	SUB WA, 0078h
	CP WA, 0
	JRL LT, Voice_CC_Exit
	CP WA, 000ah
	JRL GT, Voice_CC_Exit
	ADD WA, WA
	LDA XIX, 0F739h:24
	LD WA, (XIX + WA)
	LDA XIX, 02A306h
	JP T, XIX + WA

Voice_CC_ModWheel:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_ModWheel_Apply
	JRL T, Voice_CC_Exit

Voice_CC_Volume:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetVolume
	LD A, (XIZ + 001h)
	EXTZ WA
	CALL Voice_Query_PartVoices
	LD XWA, XHL
	CALR Voice_AllVoices_WriteAmplitude
	JRL T, Voice_CC_Exit

Voice_CC_Pan:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetPan
	LD A, (XIZ + 001h)
	EXTZ WA
	CALL EnvTranspose_UpdateLoop
	JRL T, Voice_CC_Exit

Voice_CC_Expression:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetExpression
	LD A, (XIZ + 001h)
	EXTZ WA
	CALL Voice_Query_PartVoices
	LD XWA, XHL
	CALR Voice_AllVoices_WriteAmplitude
	JRL T, Voice_CC_Exit

Voice_CC_Sustain:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetSustain
	LD A, (XIZ + 001h)
	EXTZ WA
	CALL Voice_AllocateForSustain
	LD XWA, XHL
	LD BC, 0
	CALR Voice_AllNotes_SustainRetrigger
	JRL T, Voice_CC_Exit

Voice_CC_Sostenuto:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetSostenuto
	JRL T, Voice_CC_Exit

Voice_CC_Soft:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetSoftPedal
	JRL T, Voice_CC_Exit

Voice_CC_Portamento:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_Portamento_OnHandler
	JRL T, Voice_CC_Exit
	LD A, (XIZ + 001h)
	EXTZ WA
	CALR Voice_PortamentoSlots_WriteHW
	JRL T, Voice_CC_Exit
	LD A, (XIZ + 001h)
	EXTZ WA
	CALL Voice_NoteState_Clear
	JRL T, Voice_CC_Exit
	LD A, (XIZ + 001h)
	EXTZ WA
	CALL Voice_SetLFO_ActiveFlag
	LD A, (XIZ + 001h)
	EXTZ WA
	CALL Voice_AllocateForRelease
	LD XWA, XHL
	CALL Voice_ParamInit
	JRL T, Voice_CC_Exit
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetPortamentoRate
	JRL T, Voice_CC_Exit
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetPortamentoDepth
	LD A, (XIZ + 001h)
	EXTZ WA
	CALL Voice_Query_PartVoices
	LD XWA, XHL
	CALR Pitch_Refresh_Sounding_Voices
	JRL T, Voice_CC_Exit
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetPortamentoTime
	JR T, Voice_CC_Exit

Voice_CC_91:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetReverbDepth
	JR T, Voice_CC_Exit

Voice_CC_95:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetChorusEnable
	JR T, Voice_CC_Exit

Voice_CC_97:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetChorusDepth
	JR T, Voice_CC_Exit

Voice_CC_9B:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetDelayDepth
	JR T, Voice_CC_Exit

Voice_CC_9C:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetDelayEnable
	JR T, Voice_CC_Exit

Voice_CC_9D:
	LD A, (XIZ + 001h)
	LD E, A
	EXTZ DE
	LD A, (XIZ + 003h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Voice_CC_SetDelayFeedback

Voice_CC_Exit:
	POP XIZ
	RET

Voice_ChanPressure:
	LDA XSP, XSP - 10
	PUSH QIZ
	LD (XSP + 008h), XWA
	LD XWA, (XSP + 008h)
	CP (XWA + 001h), 01ah
	JRL NC, Voice_ChanPressure_Exit
	LD XWA, (XSP + 008h)
	LD A, (XWA + 001h)
	LD (XSP + 006h), A
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Eh
	LD XWA, (XBC + WA)
	LD A, (XWA + 010h)
	AND A, 0c0h
	CP A, 080h
	JR Z, Voice_ChanPressure_MonoLoopStart
	CP A, 040h
	JR Z, Voice_ChanPressure_StereoLoopStart
	CP A, 0c0h
	JR Z, Voice_ChanPressure_StereoLoopStart
	CP A, 0
	JRL NZ, Voice_ChanPressure_Exit

Voice_ChanPressure_StereoLoopStart:
	LD A, (XSP + 006h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Eh
	LD XWA, (XBC + WA)
	LD (XSP + 002h), XWA
	LD QIZH, 0
	CP QIZH, 2
	JRL NC, Voice_ChanPressure_Exit

Voice_ChanPressure_StereoLoopBody:
	LD A, (XSP + 006h)
	LD IXL, A
	EXTZ IX
	LD XWA, (XSP + 008h)
	LD A, (XWA + 003h)
	LD L, A
	EXTZ HL
	LD A, QIZH
	EXTZ WA
	MULS_WA 003h
	LD BC, WA
	ADD BC, 0023h
	LD XWA, (XSP + 002h)
	LDA XDE, XWA + BC
	LD WA, IX
	LD BC, HL
	CALR AudioChannel_Dispatch
	INC 1, QIZH
	CP QIZH, 2
	JR C, Voice_ChanPressure_StereoLoopBody
	JR T, Voice_ChanPressure_Exit

Voice_ChanPressure_MonoLoopStart:
	LD A, (XSP + 006h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Eh
	LD XWA, (XBC + WA)
	LD (XSP + 002h), XWA
	LD QIZH, 0
	CP QIZH, 2
	JR NC, Voice_ChanPressure_Exit

Voice_ChanPressure_MonoLoopBody:
	LD A, (XSP + 006h)
	LD IXL, A
	EXTZ IX
	LD XWA, (XSP + 008h)
	LD A, (XWA + 003h)
	LD L, A
	EXTZ HL
	LD A, QIZH
	EXTZ WA
	MULS_WA 003h
	LD BC, WA
	ADD BC, 0021h
	LD XWA, (XSP + 002h)
	LDA XDE, XWA + BC
	LD WA, IX
	LD BC, HL
	CALR AudioChannel_Dispatch
	INC 1, QIZH
	CP QIZH, 2
	JR C, Voice_ChanPressure_MonoLoopBody

Voice_ChanPressure_Exit:
	POP QIZ
	LDA XSP, XSP + 00ah
	RET

Voice_PitchBend:
	CP (XWA + 001h), 01ah
	RET NC
	LD E, (XWA + 001h)
	LD C, (XWA + 003h)
	EXTZ BC
	SLL 7, BC
	LD A, (XWA + 002h)
	EXTZ WA
	EXTZ XWA
	SET 0fh, WA
	OR BC, WA
	LD A, E
	EXTZ WA
	MULS_WA 011fh
	LDA XHL, 04136Eh
	LD XWA, (XHL + WA)
	LD A, (XWA + 010h)
	AND A, 0c0h
	CP A, 080h
	JR Z, Voice_PitchBend_BranchB
	CP A, 040h
	JR Z, Voice_PitchBend_BranchA
	CP A, 0c0h
	JR Z, Voice_PitchBend_BranchA
	CP A, 0
	RET NZ

Voice_PitchBend_BranchA:
	LD L, E
	EXTZ HL
	LD A, E
	EXTZ WA
	MULS_WA 011fh
	LDA XDE, 04136Eh
	LD XWA, (XDE + WA)
	LDA XDE, XWA + 014h
	LD WA, HL
	JRL T, AudioChannel_Dispatch

Voice_PitchBend_BranchB:
	LD A, E
	EXTZ WA
	MULS_WA 011fh
	LDA XHL, 04136Eh
	LD XHL, (XHL + WA)
	LD A, E
	EXTZ WA
	LDA XDE, XHL + 012h
	JRL T, AudioChannel_Dispatch

Voice_AllVoices_PortamentoReset:
	PUSH XIZ
	LD QIZH, 0
	CP QIZH, 01ah
	JR NC, Voice_AllVoices_PortamentoReset_NopCont1

Voice_AllVoices_PortamentoReset_LoopBody:
	LD A, QIZH
	EXTZ WA
	CALL Voice_NoteState_Clear
	INC 1, QIZH
	CP QIZH, 01ah
	JR C, Voice_AllVoices_PortamentoReset_LoopBody

Voice_AllVoices_PortamentoReset_NopCont1:
	CALL Voice_Query_AllChannels
	LDA XWA, XHL + 005h
	LD XIZ, XWA
	CP (XIZ), 040h
	JR NC, Voice_AllVoices_PortamentoReset_Exit

Voice_AllVoices_PortamentoReset_NopCont2:
	RES 7, (P6)
	LD A, (XIZ)
	EXTZ WA
	ADD WA, 0840h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a200h
	JR T, Voice_AllVoices_PortamentoReset_NopCont3

Voice_AllVoices_PortamentoReset_NopCont3:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD A, (XIZ)
	EXTZ WA
	ADD WA, 0800h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a280h
	JR T, Voice_AllVoices_PortamentoReset_LoopStep

Voice_AllVoices_PortamentoReset_LoopStep:
	NOP
	NOP
	NOP
	INC 1, XIZ
	CP (XIZ), 040h
	JR C, Voice_AllVoices_PortamentoReset_NopCont2

Voice_AllVoices_PortamentoReset_Exit:
	POP XIZ
	RET

Voice_SetPitchBendRangeAndApply:
	EXTS WA
	CALR Voice_SetMasterTune
	CALL Voice_Query_AllChannels
	LD XWA, XHL
	JRL T, Pitch_Refresh_Sounding_Voices
	EXTZ WA
	CALR Voice_SetKeyShiftEnable
	CALL Voice_Query_AllChannels
	LD XWA, XHL
	JRL T, Pitch_Refresh_Sounding_Voices

Voice_PerVoice_PortamentoPitchUpdate:
	DEC 2, XSP
	LD (XSP), A
	LD A, (XSP)
	EXTZ WA
	CALL Voice_NoteState_Clear
	LD A, (XSP)
	EXTZ WA
	CALL Voice_SetLFO_ActiveFlag
	LD A, (XSP)
	LD L, A
	EXTZ HL
	LD A, (XSP)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041381h
	LD A, (XBC + WA)
	LD IXL, A
	EXTZ IX
	LD A, (XSP)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041382h
	LD A, (XBC + WA)
	LD E, A
	EXTZ DE
	LD WA, HL
	LD BC, IX
	CALL WaveSel_Rebuild_PartCaches
	LD A, (XSP)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Eh
	LD XWA, (XBC + WA)
	LD A, (XWA + 010h)
	AND A, 0c0h
	CP A, 080h
	JR Z, Voice_PerVoice_PortamentoPitchUpdate_Exit
	CP A, 040h
	JR Z, Voice_PerVoice_PortamentoPitchUpdate_BranchB
	CP A, 0c0h
	JR Z, Voice_PerVoice_PortamentoPitchUpdate_BranchA
	CP A, 0
	JR NZ, Voice_PerVoice_PortamentoPitchUpdate_Exit

Voice_PerVoice_PortamentoPitchUpdate_BranchA:
	LD A, (XSP)
	EXTZ WA
	CALL VoiceSlot_FullInit
	JR T, Voice_PerVoice_PortamentoPitchUpdate_Exit

Voice_PerVoice_PortamentoPitchUpdate_BranchB:
	LD A, (XSP)
	EXTZ WA
	CALL Voice_PortamentoTargets_SetAll
	LD A, (XSP)
	EXTZ WA
	CALL VoiceSlot_AltInit

Voice_PerVoice_PortamentoPitchUpdate_Exit:
	INC 2, XSP
	RET

Voice_AllVoices_PortamentoUpdate:
	PUSH QIZ
	LD QIZH, 0
	CP QIZH, 01ah
	JR NC, Voice_AllVoices_PortamentoUpdate_Exit

Voice_AllVoices_PortamentoUpdate_LoopBody:
	LD A, QIZH
	EXTZ WA
	CALR Voice_PerVoice_PortamentoPitchUpdate
	INC 1, QIZH
	CP QIZH, 01ah
	JR C, Voice_AllVoices_PortamentoUpdate_LoopBody

Voice_AllVoices_PortamentoUpdate_Exit:
	POP QIZ
	RET

Voice_SystemMsg:
	LD C, (XWA + 002h)
	CP C, 099h
	JRL Z, Voice_SystemMsg_DispatchEntry2
	CP C, 092h
	JRL Z, Voice_SystemMsg_DispatchEntry1
	CP C, 091h
	JR Z, Voice_SystemMsg_DispatchEntry0
	CP C, 009h
	JR Z, Voice_SystemMsg_DispatchTable
	EXTZ BC
	SUB BC, 0080h
	CP BC, 0
	RET LT
	CP BC, 7
	JR LE, Voice_SystemMsg_DispatchJump
	SUB BC, 001bh
	CP BC, 0008h
	RET LT
	CP BC, 0016h
	RET GT

Voice_SystemMsg_DispatchJump:
	ADD BC, BC
	LDA XIX, 0F74Fh:24
	LD BC, (XIX + BC)
	LDA XIX, 02A7FCh
	JP T, XIX + BC

Voice_SystemMsg_DispatchTable:
	LD A, (XWA + 003h)
	EXTZ WA
	JRL T, Voice_SetPolyphonyMode
	LD A, (XWA + 003h)
	EXTZ WA
	JRL T, VoiceCC_Stub_Ret1
	LD A, (XWA + 003h)
	EXTZ WA
	JRL T, VoiceCC_Stub_Ret2
	LD A, (XWA + 003h)
	JRL T, Voice_SetPitchBendRangeAndApply
	LD A, (XWA + 003h)
	JRL T, Voice_SetPitchBendRange
	LD A, (XWA + 003h)
	EXTZ WA
	JRL T, Voice_SetKeyShiftEnable
	LD A, (XWA + 003h)
	EXTZ WA
	JRL T, Voice_SetParam_04134D
	LD A, (XWA + 003h)
	EXTZ WA
	JRL T, Voice_SetRhythmMode

Voice_SystemMsg_DispatchEntry0:
	LD A, (XWA + 003h)
	EXTZ WA
	JRL T, Voice_SetParam_04134B

Voice_SystemMsg_DispatchEntry1:
	JRL T, Voice_AllVoices_PortamentoUpdate

Voice_SystemMsg_DispatchEntry2:
	LD A, (XWA + 003h)
	EXTZ WA
	JRL T, Voice_SetCCMaxFlag
	JRL T, Voice_AllVoices_PortamentoReset
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 0
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 1
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 2
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 3
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 4
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 5
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 6
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 7
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 0008h
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 0009h
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 000ah
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	LD BC, WA
	LD WA, 000bh
	JRL T, Voice_WriteChannelAssign
	LD A, (XWA + 003h)
	EXTZ WA
	JRL T, Voice_AllVoices_UpdateVelocity
	LD A, (XWA + 003h)
	EXTZ WA
	JRL T, Voice_SetMonoMode
	RET

Voice_ResetAllControllers:
	PUSH QIZ
	LD QIZH, 0
	CP QIZH, 01ah
	JRL NC, Voice_ResetAllControllers_PostLoop

Voice_ResetAllControllers_LoopBody:
	LD A, QIZH
	EXTZ WA
	LD BC, 0
	CALR Voice_ModWheel_Apply
	LD A, QIZH
	EXTZ WA
	LD BC, 007fh
	CALR Voice_CC_SetVolume
	LD A, QIZH
	EXTZ WA
	LD BC, 0040h
	CALR Voice_CC_SetPan
	LD A, QIZH
	EXTZ WA
	LD BC, 007fh
	CALR Voice_CC_SetExpression
	LD A, QIZH
	EXTZ WA
	LD BC, 0
	CALR Voice_CC_SetSustain
