	LD WA, (XBC + WA)
	SRL 8, WA
	ADD WA, 000ch
	CP WA, 0024h
	JR C, Voice_Slot_CalcAmpNibble_BranchA
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD HL, (XHL + WA)
	JR T, Voice_Slot_CalcAmpNibble_Exit

Voice_Slot_CalcAmpNibble_BranchA:
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD BC, (XHL + WA)
	AND BC, 000fh
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD WA, (XHL + WA)
	SRL 4, WA
	AND WA, 000fh
	CP BC, WA
	JR NC, Voice_Slot_CalcAmpNibble_BranchB
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD HL, (XHL + WA)
	AND HL, 0ff0h
	JR T, Voice_Slot_CalcAmpNibble_Exit

Voice_Slot_CalcAmpNibble_BranchB:
	SLL 4, BC
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD HL, (XHL + WA)
	AND HL, 0f00h
	OR HL, BC

Voice_Slot_CalcAmpNibble_Exit:
	RET

Voice_Slot_FindOctaveOffset:
	EXTZ WA
	MULS_WA 011fh
	LDA XHL, 041368h
	LDA XIX, XHL + WA
	LDA XIX, XIX + 0102h
	LD_L 000h
	LD A, C
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 043094h
	LD WA, (XBC + WA)
	SRL 8, WA
	SUB WA, 000ch
	CP WA, 0054h
	JR C, Voice_Slot_FindOctaveOffset_BranchB

Voice_Slot_FindOctaveOffset_BranchA:
	SUB WA, 000ch
	INC 1, L
	CP WA, 0054h
	JR NC, Voice_Slot_FindOctaveOffset_BranchA

Voice_Slot_FindOctaveOffset_BranchB:
	CP L, 0
	JR NZ, Voice_Slot_FindOctaveOffset_BranchC
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD HL, (XIX + WA)
	JRL T, Voice_Slot_FindOctaveOffset_Exit

Voice_Slot_FindOctaveOffset_BranchC:
	CP L, 1
	JR NZ, Voice_Slot_FindOctaveOffset_BranchD
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD HL, (XIX + WA)
	LD_H 000h
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD BC, (XIX + WA)
	SRL 4, BC
	AND BC, 000fh
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD WA, (XIX + WA)
	SRL 8, WA
	AND WA, 000fh
	CP BC, WA
	RET NC
	SLL 4, WA
	AND HL, 000fh
	OR HL, WA
	JR T, Voice_Slot_FindOctaveOffset_Exit

Voice_Slot_FindOctaveOffset_BranchD:
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD HL, (XIX + WA)
	AND HL, 000fh
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD BC, (XIX + WA)
	SRL 4, BC
	AND BC, 000fh
	LD A, E
	EXTZ WA
	ADD WA, WA
	LD WA, (XIX + WA)
	SRL 8, WA
	AND WA, 000fh
	CP HL, BC
	JR NC, Voice_Slot_FindOctaveOffset_BranchF
	CP BC, WA
	JR NC, Voice_Slot_FindOctaveOffset_BranchE
	LD HL, WA
	JR T, Voice_Slot_FindOctaveOffset_Exit

Voice_Slot_FindOctaveOffset_BranchE:
	LD HL, BC
	JR T, Voice_Slot_FindOctaveOffset_Exit

Voice_Slot_FindOctaveOffset_BranchF:
	CP HL, WA
	RET NC
	LD HL, WA

Voice_Slot_FindOctaveOffset_Exit:
	RET

Voice_KeyIndex_Pack3Nibbles:
	LD HL, WA
	SRL 8, HL
	AND HL, 000fh
	LD BC, HL
	MUL_BC 0051h
	LD HL, BC
	LD BC, WA
	SRL 4, BC
	AND BC, 000fh
	MUL_BC 0009h
	ADD HL, BC
	AND WA, 000fh
	ADD HL, WA
	RET

Voice_Slot_LoadPitchOffset_A:
	LD XBC, (XWA + 023h)
	LD BC, (XBC + 010eh)
	ADD (XWA + 00dh), BC
	RET

Voice_Slot_LoadPitchOffset_B:
	LD XBC, (XWA + 023h)
	LD BC, (XBC + 0110h)
	ADD (XWA + 00dh), BC
	RET

Voice_Slot_ApplyPortamentoDelta:
	DEC 8, XSP
	PUSH XIZ
	LD (XSP + 008h), XWA
	LD XWA, (XSP + 008h)
	LD XIZ, (XWA + 023h)
	LD A, (XIZ + 010ah)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 008h)
	ADD (XWA + 00dh), BC
	BIT 7, (XIZ + 0118h)
	JR Z, Voice_Slot_ApplyPortamentoDelta_BranchA
	EI 6
	LD XWA, (1040h)
	LD (XIZ + 0114h), XWA
	EI 0
	JRL T, Voice_Slot_ApplyPortamentoDelta_Exit

Voice_Slot_ApplyPortamentoDelta_BranchA:
	EI 6
	LD XWA, (1040h)
	LD (XSP + 004h), XWA
	LD XWA, (XIZ + 0114h)
	SUB (XSP + 004h), XWA
	EI 0
	LD XWA, (XSP + 004h)
	CP XWA, 00007fffh
	JR ULE, Voice_Slot_ApplyPortamentoDelta_BranchB
	LD XWA, 00007fffh
	LD (XSP + 004h), XWA

Voice_Slot_ApplyPortamentoDelta_BranchB:
	LD A, (XIZ + 010bh)
	LD C, A
	EXTS BC
	LD XWA, (XSP + 008h)
	LD XWA, (XWA + 017h)
	LD A, (XWA + 029h)
	LD E, A
	EXTZ DE
	ADD DE, BC
	LD WA, 0064h
	CP DE, 0064h
	JR GT, Voice_Slot_ApplyPortamentoDelta_BranchC
	LD WA, DE

Voice_Slot_ApplyPortamentoDelta_BranchC:
	LD DE, WA
	LD WA, 0
	CP DE, 0
	JR LT, Voice_Slot_ApplyPortamentoDelta_BranchD
	LD WA, DE

Voice_Slot_ApplyPortamentoDelta_BranchD:
	LD DE, WA
	ADD WA, WA
	LDA XBC, 0F7E6h:24
	LD WA, (XBC + WA)
	EXTZ XWA
	LD XBC, (XSP + 004h)
	CALL FP_MulAccum64
	LD XWA, XHL
	SRL 0ah, XWA
	CP XWA, 00000fffh
	JR ULE, Voice_Slot_ApplyPortamentoDelta_BranchE
	LD XWA, (XSP + 008h)
	LDW (XWA + 00dh), 0c000h
	JR T, Voice_Slot_ApplyPortamentoDelta_Exit

Voice_Slot_ApplyPortamentoDelta_BranchE:
	LD BC, WA
	LD XWA, (XSP + 008h)
	SUB (XWA + 00dh), BC

Voice_Slot_ApplyPortamentoDelta_Exit:
	POP XIZ
	INC 8, XSP
	RET

Voice_Slot_ApplyPitchJitter:
	DEC 4, XSP
	PUSH IZ
	LD (XSP + 002h), XWA
	EI 6
	LD XWA, (1040h)
	LD IZ, WA
	AND IZ, 0007h
	EI 0
	LD XWA, (XSP + 002h)
	ADD (XWA), IZ
	POP IZ
	INC 4, XSP
	RET

Voice_Slot_ComputePitch:
	LDA XSP, XSP - 12
	PUSH IZ
	LD (XSP + 00ah), XWA
	LD XWA, (XSP + 00ah)
	LD XBC, (XWA + 023h)
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 017h)
	LD (XSP + 002h), XWA
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 01fh)
	LD (XSP + 006h), XWA
	LD XWA, (XSP + 00ah)
	LD A, (XWA + 005h)
	RES 7, A
	LD IZL, A
	EXTZ IZ
	SLA 8, IZ
	ADD IZ, 0080h
	ADD IZ, (XBC + 0112h)
	ADD IZ, (041349h)
	LD A, (XBC + 016h)
	EXTS WA
	SLA 8, WA
	ADD IZ, WA
	LD A, (XBC + 06dh)
	EXTS WA
	SLA 8, WA
	ADD IZ, WA
	LD WA, IZ
	CALL Pitch_Saturate_15bit
	LD XWA, (XSP + 00ah)
	LD (XWA + 008h), HL
	LD XWA, (XSP + 006h)
	LD A, (XWA + 00bh)
	EXTZ WA
	SLA 8, WA
	ADD WA, 0080h
	SUB IZ, WA
	LD XWA, (XSP + 006h)
	LD WA, (XWA + 00ch)
	ADD IZ, WA
	LD XWA, (XSP + 002h)
	LD A, (XWA + 003h)
	EXTS WA
	SLA 8, WA
	ADD IZ, WA
	LD XWA, (XSP + 002h)
	LD A, (XWA + 004h)
	EXTS WA
	ADD IZ, WA
	LD XWA, (XSP + 006h)
	LD A, (XWA + 009h)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 006h)
	LD A, (XWA + 00ah)
	LD E, A
	EXTZ DE
	LD WA, IZ
	CALL Pitch_Fold_Octaves_Into_Range
	LD XWA, (XSP + 00ah)
	LD (XWA + 006h), HL
	POP IZ
	LDA XSP, XSP + 00ch
	RET

Voice_Pitch_ClampRange:
	CP WA, DE
	JR GE, Voice_Pitch_ClampRange_Hi
	LD WA, DE
	JR T, Voice_Pitch_ClampRange_Lo

Voice_Pitch_ClampRange_Hi:
	CP WA, BC
	JR LE, Voice_Pitch_ClampRange_Lo
	LD WA, BC

Voice_Pitch_ClampRange_Lo:
	LD HL, WA
	RET

; ----------------------------------------------------------------------------
; ToneGen_SilenceChannel - Free one IC303 channel
; Entry: A = channel number (0..63)
; Exit:  none
; Notes: Writes +0x0C0 + ch = 0x0000, then +0x000 + ch = 0x7E00.
;        0x7E00 is the 'voice free' command; its only sources are this routine,
;        the panic loop inside Voice_Reset_Engine and the boot self-test
;        (notes/audit/kn5000-audit-voicelife.md S4.2).
; ----------------------------------------------------------------------------
ToneGen_SilenceChannel:	; 02B4A1h
	DEC 2, XSP
	LD (XSP), A
	RES 7, (P6)
	LD A, (XSP)
	ADD A, 0c0h
	EXTZ WA
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0000h
	JR T, ToneGen_SilenceChannel_NopCont1

ToneGen_SilenceChannel_NopCont1:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD A, (XSP)
	EXTZ WA
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 7e00h
	JR T, ToneGen_SilenceChannel_NopCont2

ToneGen_SilenceChannel_NopCont2:
	NOP
	NOP
	NOP
	INC 2, XSP
	RET

; ----------------------------------------------------------------------------
; Voice_Build_Register_Set - run the 17 parameter builders and burst one chip voice
; Entry: A = chip voice number 0..63
; Exit:  All 0x2C bytes of the parameter scratch at 0x0451CC filled and shipped to the
;        chip by ToneGen_WriteVoiceParams
; Notes: The descriptor it works on is Voice_Desc_Table[A] = 0x04308E + 0x47*A, i.e.
;        the LIVE per-chip-voice copy -- NOT the 0x2942 staging array.  The note-on
;        path memcpy s 0x47 bytes from Voice_Desc_Staging[p] into it first.
;        CORRECTION: notes/kn5000-variant-model.md 4.1 records only the 0x2942 array.
;        Builder order: WaveSel_StageB_Build_Reg040, Pitch_Apply_Partial_Detune,
;        Pitch_Emit_Reg400, Voice_Level_ComputeTriplet, TVF_Build_Dispatch, TVF_Emit_Registers,
;        Voice_StereoLevel_Compute, Voice_PortaLevel_Compute, ExtVoice_Build_SlotRegisters, Voice_SubVoice_ComputeAndTrigger, Voice2_UpdatePitch,
;        Level_Build_Reg0C0, Voice_Build_GateCommand, Voice_Calc_LevelPair_PatchAtk, Voice_WriteChPanShift, Voice_ComputePitch,
;        Voice_ApplyPortamento.  MEASURED.
; ----------------------------------------------------------------------------
Voice_Build_Register_Set:		; 02B4E3h
	DEC 2, XSP
	PUSH XIZ
	LD (XSP + 004h), A
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	LDA XIZ, XBC + WA
	LD XWA, XIZ
	CALL WaveSel_StageB_Build_Reg040
	LD XWA, XIZ
	CALL Pitch_Apply_Partial_Detune
	LD XWA, XIZ
	CALL Pitch_Emit_Reg400
	LD XWA, XIZ
	CALL Voice_Level_ComputeTriplet
	LD XWA, XIZ
	CALL TVF_Build_Dispatch
	LD XWA, XIZ
	CALL TVF_Emit_Registers
	LD XWA, XIZ
	CALL Voice_StereoLevel_Compute
	LD XWA, XIZ
	CALL Voice_PortaLevel_Compute
	LD XWA, XIZ
	CALL ExtVoice_Build_SlotRegisters
	LD XWA, XIZ
	CALL Voice_SubVoice_ComputeAndTrigger
	LD XWA, XIZ
	CALL Voice2_UpdatePitch
	LD XWA, XIZ
	CALL Level_Build_Reg0C0
	LD XWA, XIZ
	CALL Voice_Build_GateCommand
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_PatchAtk
	LD XWA, XIZ
	LD BC, 0
	CALL Voice_WriteChPanShift
	LD XWA, XIZ
	CALL Voice_ComputePitch
	LD XWA, XIZ
	CALL Voice_ApplyPortamento
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteVoiceParams
	POP XIZ
	INC 2, XSP
	RET

Voice_Allocate_Typed:
	LDA XSP, XSP - 018h
	PUSH QIZ
	LD (XSP + 012h), DE
	LD (XSP + 014h), C
	LD (XSP + 016h), XWA
	LD A, (XSP + 026h)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 2942h
	EXTS XWA
	ADD XWA, XBC
	LD (XSP + 002h), XWA
	LD WA, (XSP + 01eh)
	LD E, A
	EXTZ DE
	LD WA, (XSP + 01eh)
	SRL 8, WA
	LD C, A
	EXTZ BC
	LD WA, DE
	CALL ToneDB_Find_ToneRecord
	LD A, (XSP + 024h)
	LD C, A
	EXTZ BC
	LD A, (XSP + 014h)
	LD E, A
	EXTZ DE
	LD XWA, XHL
	CALL ToneDB_Find_SubToneRecord
	LD (XSP + 006h), XHL
	LD XWA, (XSP + 006h)
	LD A, (XWA + 00dh)
	EXTZ WA
	AND WA, (XSP + 012h)
	JRL Z, Voice_Allocate_Typed_ExitA
	LD A, (XSP + 026h)
	EXTZ WA
	MULS_WA 015h
	LD BC, WA
	ADD BC, 0010h
	LD XWA, (XSP + 006h)
	LDA XWA, XWA + BC
	LD (XSP + 00ah), XWA
	LD A, (XSP + 026h)
	LD C, A
	EXTZ BC
	LD A, (XSP + 024h)
	LD E, A
	EXTZ DE
	LD A, (XSP + 014h)
	EXTZ WA
	PUSH WA
	LD WA, BC
	LD XBC, (XSP + 00ch)
	CALL WaveSel_StageA1_FromToneSlot
	LD (XSP + 00eh), XHL
	LD A, (XSP + 022h)
	EXTZ WA
	LD XBC, (XSP + 00eh)
	CALL Velocity_Select_Split_Zone_Alt
	LD QIZH, L
	LD A, QIZH
	EXTZ WA
	LD XBC, (XSP + 00eh)
	CALL WaveSel_StageA2_FromVelZone
	LD A, QIZH
	SLL 6, A
	OR A, 012h
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 002h)
	LD (XWA + 001h), BC
	LD XBC, (XSP + 002h)
	LD A, (XSP + 026h)
	LD (XBC + 003h), A
	LD XBC, (XSP + 002h)
	LD A, (XSP + 014h)
	LD (XBC + 004h), A
	LD C, (XSP + 024h)
	SET 7, C
	LD XWA, (XSP + 002h)
	LD (XWA + 005h), C
	LD XBC, (XSP + 002h)
	LD A, (XSP + 022h)
	LD (XBC + 00ch), A
	LD A, (XSP + 014h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	LDA XBC, XBC + WA
	LD XWA, (XSP + 002h)
	LD (XWA + 023h), XBC
	LD A, (XSP + 026h)
	EXTZ WA
	MULS_WA 025h
	LD DE, WA
	ADD DE, 006eh
	LD A, (XSP + 014h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	EXTS XWA
	ADD XWA, XBC
	LDA XBC, XWA + DE
	LD XWA, (XSP + 002h)
	LD (XWA + 027h), XBC
	LD XWA, (XSP + 002h)
	LD XBC, (XSP + 006h)
	LD (XWA + 013h), XBC
	LD XWA, (XSP + 002h)
	LD XBC, (XSP + 00ah)
	LD (XWA + 017h), XBC
	LD XWA, (XSP + 002h)
	LD XBC, (XSP + 00eh)
	LD (XWA + 01bh), XBC
	LD XWA, (XSP + 002h)
	LD (XWA + 01fh), XHL
	LD XWA, (XSP + 002h)
	CALL Voice_Pitch_CopyBase
	LD A, (XSP + 026h)
	EXTZ WA
	LD BC, WA
	INC 2, BC
	LD E, (XSP + 020h)
	SET 7, E
	LD XWA, (XSP + 016h)
	LD (XWA + BC), E
	JR T, Voice_Allocate_Typed_ExitB

Voice_Allocate_Typed_ExitA:
	LD A, (XSP + 026h)
	EXTZ WA
	LD BC, WA
	INC 2, BC
	LD XWA, (XSP + 016h)
	LD (XWA + BC), 000h

Voice_Allocate_Typed_ExitB:
	LD A, (XSP + 026h)
	EXTZ WA
	LD BC, WA
	INC 6, BC
	LD XWA, (XSP + 016h)
	LD (XWA + BC), 000h
	POP QIZ
	LDA XSP, XSP + 018h
	RETD 000ah

; ----------------------------------------------------------------------------
; Voice_Build_Partial_Descriptor - build one partial s staging voice descriptor
; Entry: XWA = note-on scratch, C = part index, DE = partial present mask (1/2/4/8),
;        stack: [+0x20] velocity, [+0x22] note, [+0x24] source slot a4,
;        [+0x26] destination slot p
; Exit:  Voice_Desc_Staging[p] filled; returns without touching it if the partial is
;        absent
; Notes: Skips immediately when (Part_PresentWord & DE) == 0.  Then
;          VSEL = *(part_struct + 0x6E + 0x25*a4 + 0x04)
;          q    = Velocity_Select_Split_Zone(velocity, VSEL)
;          blk  = *(part_struct + 0x6E + 0x25*a4 + 0x00)   0x51-byte partial block
;          SETp = *(part_struct + 0x76 + 0x25*a4 + 4*q)    velocity-selected SET
;        and writes desc[+0x01] = (q<<6)|0x04, [+0x03] = p, [+0x04] = part,
;        [+0x05] = note|0x80, [+0x0c] = velocity, [+0x13] = patch record,
;        [+0x17] = blk, [+0x1b] = VSEL, [+0x1f] = SETp, [+0x23] = part struct,
;        [+0x27] = part_struct + 0x6E + 0x25*p, then calls Voice_Pitch_Compute.
;        Passing a4 != p is how the synthesised UNISON layer reuses partial 0 s wave
;        and split with slot 1 s own detune sub-struct.
;        When ToneGen_GlobalFlags bit 1 is set the velocity is boosted by +0x28 on
;        part 0 and +0x0C on part 1 (clamped to 0x7F) AFTER the split decision.
;        Notes >= 0x78 take a separate path that is only taken when SET[0] bit 1 is
;        set; otherwise the partial is dropped.  MEASURED.
; ----------------------------------------------------------------------------
Voice_Build_Partial_Descriptor:		; 02B717h
	LDA XSP, XSP - 016h
	PUSH XIZ
	LD (XSP + 014h), C
	LD (XSP + 016h), XWA
	LD A, (XSP + 014h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Ah
	LD WA, (XBC + WA)
	AND WA, DE
	JRL Z, Voice_Build_Partial_Descriptor_ExitA
	LD A, (XSP + 024h)
	EXTZ WA
	MULS_WA 025h
	LD DE, WA
	ADD DE, 006eh
	LD A, (XSP + 014h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	EXTS XWA
	ADD XWA, XBC
	LDA XWA, XWA + DE
	LD XWA, (XWA + 004h)
	LD (XSP + 008h), XWA
	LD A, (XSP + 020h)
	EXTZ WA
	LD XBC, (XSP + 008h)
	CALL Velocity_Select_Split_Zone
	LD A, (XSP + 024h)
	EXTZ WA
	MULS_WA 025h
	LD DE, WA
	ADD DE, 006eh
	LD A, (XSP + 014h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	EXTS XWA
	ADD XWA, XBC
	LD XWA, (XWA + DE)
	LD (XSP + 004h), XWA
	LD A, L
	EXTZ WA
	LD BC, WA
	SLA 2, BC
	LD A, (XSP + 024h)
	EXTZ WA
	MULS_WA 025h
	LD DE, WA
	ADD DE, BC
	LD A, (XSP + 014h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	EXTS XWA
	ADD XWA, XBC
	LDA XWA, XWA + DE
	LD XWA, (XWA + 076h)
	LD (XSP + 00ch), XWA
	LD A, (XSP + 026h)
	EXTZ WA
	MULS_WA 025h
	LD DE, WA
	ADD DE, 006eh
	LD A, (XSP + 014h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	EXTS XWA
	ADD XWA, XBC
	LDA XWA, XWA + DE
	LD (XSP + 010h), XWA
	CP (XSP + 022h), 078h
	JR C, Voice_Build_Partial_Descriptor_BranchB
	LD XWA, (XSP + 00ch)
	BIT 1, (XWA)
	JR Z, Voice_Build_Partial_Descriptor_BranchA
	LD C, (XSP + 022h)
	SUB C, 078h
	LD XWA, (XSP + 00ch)
	ADD C, (XWA + 00bh)
	LD E, C
	LD A, (XSP + 014h)
	LD C, A
	EXTZ BC
	PUSHW 0000h
	LD A, E
	EXTZ WA
	PUSH WA
	LD A, (XSP + 024h)
	EXTZ WA
	PUSH WA
	PUSHW 0003h
	LD XWA, (XSP + 014h)
	PUSHW (XWA + 00ch)
	LD XWA, (XSP + 020h)
	LD DE, 1
	CALR Voice_Allocate_Typed
	JRL T, Voice_Build_Partial_Descriptor_ExitB

Voice_Build_Partial_Descriptor_BranchA:
	LD A, (XSP + 026h)
	EXTZ WA
	LD BC, WA
	INC 2, BC
	LD XWA, (XSP + 016h)
	LD (XWA + BC), 000h
	LD A, (XSP + 026h)
	EXTZ WA
	LD BC, WA
	INC 6, BC
	LD XWA, (XSP + 016h)
	LD (XWA + BC), 000h
	JRL T, Voice_Build_Partial_Descriptor_ExitB

Voice_Build_Partial_Descriptor_BranchB:
	LD A, (XSP + 026h)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 2942h
	LDA XIZ, XBC + WA
	SLL 6, L
	SET 2, L
	LD A, L
	EXTZ WA
	LD (XIZ + 001h), WA
