; ----------------------------------------------------------------------------
; Voice_Build_Four_Partials - build up to four partial descriptors for one note-on
; Entry: XWA = note-on scratch, C = part index, E = velocity; note on the stack
; Exit:  scratch[0] = (note<<8)|velocity|0x80; Voice_Desc_Staging[0..3] filled for
;        every present partial
; Notes: Calls Voice_Build_Partial_Descriptor four times with the masks 1, 2, 4, 8.
;        The first two calls test Part_PresentWord bits 14 and 15 (the unison cross
;        flags set by Partial_Build_Present_Word) to decide whether the SOURCE slot a4
;        differs from the DESTINATION slot p: when it does, the twin reuses the other
;        partial s wave, split record and SET while taking its own slot s detune
;        sub-struct, so the two voices differ only in +0x400.  MEASURED:
;        notes/kn5000-variant-model.md 4.1/4.2.
; ----------------------------------------------------------------------------
Voice_Build_Four_Partials:		; 02BA2Ch
	LDA XSP, XSP - 10
	PUSH XIZ
	LD (XSP + 006h), E
	LD (XSP + 008h), C
	LD (XSP + 00ah), XWA
	LD A, (XSP + 006h)
	LD C, A
	EXTZ BC
	LD A, (XSP + 008h)
	EXTZ WA
	SLL 8, WA
	OR WA, BC
	LD BC, WA
	SET 7, BC
	LD XWA, (XSP + 00ah)
	LD (XWA), BC
	LD A, (XSP + 008h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Ah
	LD WA, (XBC + WA)
	BIT 0eh, WA
	JR Z, Voice_Build_Four_Partials_BranchA
	LD A, (XSP + 008h)
	LD C, A
	EXTZ BC
	PUSHW 0000h
	PUSHW 0001h
	LD A, (XSP + 00ah)
	EXTZ WA
	PUSH WA
	LD A, (XSP + 018h)
	EXTZ WA
	PUSH WA
	PUSHW 0000h
	LD XWA, (XSP + 014h)
	LD DE, 1
	CALR Voice_Build_Partial_Descriptor
	JR T, Voice_Build_Four_Partials_BranchB

Voice_Build_Four_Partials_BranchA:
	LD A, (XSP + 008h)
	LD C, A
	EXTZ BC
	PUSHW 0000h
	PUSHW 0000h
	LD A, (XSP + 00ah)
	EXTZ WA
	PUSH WA
	LD A, (XSP + 018h)
	EXTZ WA
	PUSH WA
	PUSHW 0000h
	LD XWA, (XSP + 014h)
	LD DE, 1
	CALR Voice_Build_Partial_Descriptor

Voice_Build_Four_Partials_BranchB:
	LD A, (XSP + 008h)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Ah
	LD WA, (XBC + WA)
	EXTZ XWA
	BIT 0fh, WA
	JR Z, Voice_Build_Four_Partials_BranchC
	LD A, (XSP + 008h)
	LD C, A
	EXTZ BC
	PUSHW 0001h
	PUSHW 0000h
	LD A, (XSP + 00ah)
	EXTZ WA
	PUSH WA
	LD A, (XSP + 018h)
	EXTZ WA
	PUSH WA
	PUSHW 0001h
	LD XWA, (XSP + 014h)
	LD DE, 2
	CALR Voice_Build_Partial_Descriptor
	JR T, Voice_Build_Four_Partials_BranchD

Voice_Build_Four_Partials_BranchC:
	LD A, (XSP + 008h)
	LD C, A
	EXTZ BC
	PUSHW 0001h
	PUSHW 0001h
	LD A, (XSP + 00ah)
	EXTZ WA
	PUSH WA
	LD A, (XSP + 018h)
	EXTZ WA
	PUSH WA
	PUSHW 0001h
	LD XWA, (XSP + 014h)
	LD DE, 2
	CALR Voice_Build_Partial_Descriptor

Voice_Build_Four_Partials_BranchD:
	LD A, (XSP + 008h)
	LD C, A
	EXTZ BC
	PUSHW 0002h
	PUSHW 0002h
	LD A, (XSP + 00ah)
	EXTZ WA
	PUSH WA
	LD A, (XSP + 018h)
	EXTZ WA
	PUSH WA
	PUSHW 0005h
	LD XWA, (XSP + 014h)
	LD DE, 4
	CALR Voice_Build_Partial_Descriptor
	LD A, (XSP + 008h)
	LD C, A
	EXTZ BC
	PUSHW 0003h
	PUSHW 0003h
	LD A, (XSP + 00ah)
	EXTZ WA
	PUSH WA
	LD A, (XSP + 018h)
	EXTZ WA
	PUSH WA
	PUSHW 0003h
	LD XWA, (XSP + 014h)
	LD DE, 0008h
	CALR Voice_Build_Partial_Descriptor
	LD XWA, (XSP + 00ah)
	CALL Voice_Allocate_Nodes
	LD (XSP + 004h), 000h
	CP (XSP + 004h), 004h
	JRL NC, Voice_Build_Four_Partials_Exit

Voice_Build_Four_Partials_SlotLoop:
	LD A, (XSP + 004h)
	EXTZ WA
	LD BC, WA
	ADD BC, 000ah
	LD XWA, (XSP + 00ah)
	CP (XWA + BC), 040h
	JRL NC, Voice_Build_Four_Partials_BranchK
	LD A, (XSP + 004h)
	EXTZ WA
	LD BC, WA
	ADD BC, 000ah
	LD XWA, (XSP + 00ah)
	LD E, (XWA + BC)
	CP (XSP + 006h), 078h
	JR C, Voice_Build_Four_Partials_AltSlotPath
	LD A, E
	EXTZ WA
	MULS_WA 047h
	LD HL, WA
	LDA XIZ, 04308Eh
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 2942h
	LDA XIY, XBC + WA
	LDA XIX, XIZ + HL
	LD BC, 0023h
	LDIRW_95
	LDI
	JRL T, Voice_Build_Four_Partials_BranchI

Voice_Build_Four_Partials_AltSlotPath:
	LD A, E
	EXTZ WA
	MULS_WA 047h
	LD HL, WA
	LDA XIZ, 04308Eh
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 2942h
	LDA XIY, XBC + WA
	LDA XIX, XIZ + HL
	LD BC, 0023h
	LDIRW_95
	LDI
	LD A, E
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	LD (XBC + WA), E
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 2971h
	LD HL, (XBC + WA)
	CP HL, 0
	JR Z, Voice_Build_Four_Partials_BranchE
	LD WA, HL
	SLL 8, WA
	EXTZ XWA
	SET 0fh, WA
	OR HL, WA
	JR T, Voice_Build_Four_Partials_BranchF

Voice_Build_Four_Partials_BranchE:
	LD HL, 0

Voice_Build_Four_Partials_BranchF:
	LD A, E
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 0430BDh
	LD (XBC + WA), HL
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 2973h
