VoiceAllocate_DataTable_02CD14:
	db 03Eh, 0F1h, 05Eh, 02Ah, 036h, 0B6h, 000h, 000h
	db 0D8h, 012h, 0D8h, 0EEh, 008h, 0D8h, 031h, 007h
	db 0BEh, 001h, 050h, 0BEh, 003h, 002h, 07Fh, 000h
	db 0EEh, 088h, 01Dh, 091h, 026h, 002h, 0EEh, 08Bh
