; ----------------------------------------------------------------------------
; Voice_Query_AllChannels - Build the list of all live channels for the audio-tick service passes
; Entry: none
; Exit:  XHL = pointer to the query block at 0x2A5E; +5 onwards is a byte list of
;        channel indices terminated by a value >= 0x40
; Notes: Fills the query descriptor 0x2A5E with {mode = 0, key = 0x0000,
;        mask = 0x1FFF} and runs NoteOn_RoutePacket over it.  Used by both
;        Audio_Tick_ServiceVoices_A and _B.
; ----------------------------------------------------------------------------
Voice_Query_AllChannels:	; 02CD55h
	PUSH XIZ
	LDA XIZ, 2A5Eh
	LD (XIZ), 000h
	LDW (XIZ + 001h), 0000h
	LDW (XIZ + 003h), 1fffh
	LD XWA, XIZ
	CALL NoteOn_RoutePacket
	LD XHL, XIZ
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; Voice_Reload_Levels - Recompute and re-ship a voice's level registers (segment reload)
; Entry: A = channel number (0..63)
; Exit:  none; the voice's level registers are rewritten
; Notes: Ten call sites.  This is the general 'the levels changed' service, NOT
;        a note-off command (notes/audit/kn5000-audit-voicelife.md S1.4).
;        slot+0x05 bit7 is cleared on entry.  Then:
;          slot+0x01 bit8 set -> Voice_Calc_LevelPair_EGA,
;              ToneGen_WriteSegRegs_SameLevel, ToneGen_WriteSingleReg(slot+0x2d),
;              Voice_Clear_HoldBit, then clear bit8;
;          bit8 clear -> Voice_Calc_LevelPair_EGA/EGB/EGC then the six-write
;              burst ToneGen_WriteLevelBurst.
;        When slot+0x01 bit15 is clear AND the part word part_struct+0x0a bit0
;        (SUSTAIN PEDAL) is set, the mirror pair at Voice_Reload_Levels_BranchC/Voice_Reload_Levels_BranchD is
;        used instead.  Voice_Reload_Levels_BranchB is an inner branch target, not an entry.
; ----------------------------------------------------------------------------
Voice_Reload_Levels:	; 02CD71h
	DEC 2, XSP
	PUSH XIZ
	LD (XSP + 004h), A
	LD A, (XSP + 004h)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	LDA XIZ, XBC + WA
	RES 7, (XIZ + 005h)
	LD WA, (XIZ + 001h)
	EXTZ XWA
	BIT 0fh, WA
	JR NZ, Voice_Reload_Levels_BranchA
	LD XWA, (XIZ + 023h)
	LD WA, (XWA + 00ah)
	BIT 0, WA
	JR NZ, Voice_Reload_Levels_BranchC

Voice_Reload_Levels_BranchA:
	LD WA, (XIZ + 001h)
	BIT 8, WA
	JR Z, Voice_Reload_Levels_BranchB
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGA
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteSegRegs_SameLevel
	LD A, (XSP + 004h)
	EXTZ WA
	LD BC, (XIZ + 02dh)
	CALL ToneGen_WriteSingleReg
	LD A, (XSP + 004h)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	ANDW (XIZ + 001h), 0feffh
	JR T, Voice_Reload_Levels_Exit

Voice_Reload_Levels_BranchB:
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGA
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGB
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGC
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteLevelBurst
	JR T, Voice_Reload_Levels_Exit

Voice_Reload_Levels_BranchC:
	LD WA, (XIZ + 001h)
	BIT 8, WA
	JR Z, Voice_Reload_Levels_BranchD
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGA
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteSegRegs_SameLevel
	LD A, (XSP + 004h)
	EXTZ WA
	LD BC, (XIZ + 02dh)
	CALL ToneGen_WriteSingleReg
	LD A, (XSP + 004h)
	EXTZ WA
	CALL Voice_Clear_HoldBit
	ANDW (XIZ + 001h), 0feffh
	JR T, Voice_Reload_Levels_Exit

Voice_Reload_Levels_BranchD:
	LD XWA, XIZ
	CALL Voice_Stage_EnvSegments
	LD A, (XSP + 004h)
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteEnvSegments

Voice_Reload_Levels_Exit:
	POP XIZ
	INC 2, XSP
	RET

Voice_Cut:
	DEC 8, XSP
	PUSH XIZ
	LD (XSP + 00ah), A
	LD A, (XSP + 00ah)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	LDA XIZ, XBC + WA
	LD XWA, (XIZ + 023h)
	LD (XSP + 004h), XWA
	RES 7, (XIZ + 005h)
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 00ah)
	LD (XSP + 008h), WA
	CP (XIZ + 003h), 003h
	JR NZ, Voice_Cut_BranchA
	LD XWA, (XSP + 004h)
	ANDW (XWA + 00ah), 0fffeh

Voice_Cut_BranchA:
	LD WA, (XIZ + 001h)
	EXTZ XWA
	BIT 0fh, WA
	JR NZ, Voice_Cut_BranchB
	LD XWA, (XIZ + 023h)
	LD WA, (XWA + 00ah)
	BIT 0, WA
	JR NZ, Voice_Cut_Exit

Voice_Cut_BranchB:
	CP (XIZ + 003h), 003h
	JR NC, Voice_Cut_BranchC
	LD XWA, XIZ
	CALL Voice_ComputeVolume_CappedLFO
	JR T, Voice_Cut_BranchD

Voice_Cut_BranchC:
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGA

Voice_Cut_BranchD:
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGB
	LD XWA, XIZ
	CALL Voice_Calc_LevelPair_EGC
	LD A, (XSP + 00ah)
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteLevelBurst

Voice_Cut_Exit:
	LD XWA, (XSP + 004h)
	LD BC, (XSP + 008h)
	LD (XWA + 00ah), BC
	POP XIZ
	INC 8, XSP
	RET

Voice_ReleaseSingle:
	DEC 2, XSP
	LD (XSP), A
	LD A, (XSP)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	EXTS XWA
	ADD XWA, XBC
	RES 7, (XWA + 005h)
	CP (XWA + 046h), 000h
	JR Z, Voice_ReleaseSingle_Exit
	CALL Voice_Calc_LevelPair_Silence
	LD A, (XSP)
	EXTZ WA
	LDA XBC, 0451CCh
	CALL ToneGen_WriteLevelBurst

Voice_ReleaseSingle_Exit:
	INC 2, XSP
	RET

Voice_ParamInit:
	DEC 4, XSP
	PUSH XIZ
	INC 5, XWA
	LD XIZ, XWA
	LDA XWA, 04308Eh
	LD (XSP + 004h), XWA
	CP (XIZ), 040h
	JR NC, Voice_ParamInit_LoopStep

Voice_ParamInit_LoopBody:
	LD A, (XIZ)
	EXTZ WA
	MULS_WA 047h
	LD BC, WA
	LD XWA, (XSP + 004h)
	EXTS XBC
	ADD XBC, XWA
	LD WA, (XBC + 001h)
	AND WA, 003ch
	CP WA, 0020h
	JR Z, Voice_ParamInit_BranchE
	CP WA, 0010h
	JR Z, Voice_ParamInit_BranchD
	CP WA, 0008h
	JR Z, Voice_ParamInit_BranchC
	CP WA, 4
	JR NZ, Voice_ParamInit_BranchF
	CPW (XBC + 02fh), 0000h
	JR Z, Voice_ParamInit_BranchA
	ORW (XBC + 02fh), 0080h
	JR T, Voice_ParamInit_BranchF

Voice_ParamInit_BranchA:
	CPW (XBC + 031h), 00ffh
	JR Z, Voice_ParamInit_BranchB
	ANDW (XBC + 031h), 9fffh
	ORW (XBC + 031h), 1000h
	JR T, Voice_ParamInit_BranchF

Voice_ParamInit_BranchB:
	LD A, (XIZ)
	EXTZ WA
	CALR Voice_Reload_Levels
	JR T, Voice_ParamInit_BranchF

Voice_ParamInit_BranchC:
	LD A, (XIZ)
	EXTZ WA
	CALR Voice_Cut
	JR T, Voice_ParamInit_BranchF

Voice_ParamInit_BranchD:
	LD A, (XIZ)
	EXTZ WA
	CALR Voice_ReleaseSingle
	JR T, Voice_ParamInit_BranchF

Voice_ParamInit_BranchE:
	LD A, (XIZ)
	EXTZ WA
	CALR Voice_Reload_Levels

Voice_ParamInit_BranchF:
	INC 1, XIZ
	CP (XIZ), 040h
	JR C, Voice_ParamInit_LoopBody

Voice_ParamInit_LoopStep:
	POP XIZ
	INC 4, XSP
	RET

; ===========================================================================
; Voice_NoteOn - Process MIDI Note On messages
; ===========================================================================
; Entry: XWA = pointer to 4-byte note data:
;        +0 = status byte (0x9n where n=channel)
;        +1 = channel number (0-25)
;        +2 = note number (0-127)
;        +3 = velocity (0-127, 0 = note off)
; Exit:  Voice allocated and parameters set for new note
; Notes: Allocates voice slot, sets pitch via Voice_SetPitch
;        Sets velocity via Voice_SetVelocity
;        Velocity 0 triggers note-off via Voice_NoteOff
; ===========================================================================
Voice_NoteOn:
	DEC 2, XSP
	PUSH XIZ
	LD XIZ, XWA
	CP (XIZ + 001h), 01ah
	JR GE, Voice_NoteOn_Exit
	LD A, (XIZ)
	AND A, 007h
	LD (XSP + 004h), A
	LD A, (XIZ + 003h)
	RES 7, A
	CP A, 0
	JR Z, Voice_NoteOn_ZeroVelocity
	LD A, (XIZ)
	AND A, 008h
	CALL RingBuf_SetOffsetLo
	LD L, (XIZ + 001h)
	LD C, (XIZ + 002h)
	LD E, (XIZ + 003h)
	LD A, (XSP + 004h)
	EXTZ WA
	PUSH WA
	LD A, L
	CALR Voice_SetVelocity
	LD L, (XIZ + 001h)
	LD C, (XIZ + 002h)
	LD E, (XIZ + 003h)
	LD A, (XSP + 004h)
	EXTZ WA
	PUSH WA
	LD A, L
	CALR Voice_SetPitch
	JR T, Voice_NoteOn_Exit

Voice_NoteOn_ZeroVelocity:
	LD A, (XIZ + 001h)
	LD C, (XIZ + 002h)
	CALR Voice_Allocate
	LD XWA, XHL
	CALR Voice_ParamInit
	LD L, (XIZ + 001h)
	LD C, (XIZ + 002h)
	LD E, (XIZ + 003h)
	LD A, (XSP + 004h)
	EXTZ WA
	PUSH WA
	LD A, L
	CALR Voice_NoteOff

Voice_NoteOn_Exit:
	POP XIZ
	INC 2, XSP
	RET

Voice_SetPanning:
	PUSH XIZ
	LD XIZ, XWA
	LD WA, (041360h)
	SRL 8, WA
	OR WA, 1480h
	LD (XIZ), WA
	LD (XIZ + 002h), 080h
	LD (XIZ + 006h), 000h
	LD (XIZ + 003h), 000h
	LD (XIZ + 004h), 000h
	LD (XIZ + 005h), 000h
	LD XWA, XIZ
	CALL Voice_Allocate_Nodes
	CP (XIZ + 00ah), 040h
	JR NC, Voice_SetPanning_Exit
	LD A, (XIZ + 00ah)
	EXTZ WA
	MULS_WA 047h
	LDA XBC, 04308Eh
	LDA XBC, XBC + WA
	LD WA, (041360h)
	LD (XBC + 008h), WA
	LD WA, (041360h)
