VoiceAlloc_CheckAndInit:
	DEC 2, XSP
	LD (XSP), A
	LD A, (0451A4h)
	CP A, (XSP)
	JRL NZ, VoiceAlloc_CheckAndInit_Return
	CP (XSP), 002h
	JR ULE, VoiceAlloc_SetFlagBit0
	LD A, (XSP)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	LD WA, (XBC + WA)
	AND WA, 0003h
	CP WA, 3
	JRL NZ, VoiceAlloc_CheckAndInit_Return

