DSP_EffectStateQuery:
	EXTZ WA
	MULS_WA 011fh
	LDA XDE, 041368h
	LD WA, (XDE + WA)
	BIT 0, WA
	JR Z, DSP_EffectStateQuery_WriteZero
	LD (XBC), 001h
	JR T, DSP_EffectStateQuery_SetResult

DSP_EffectStateQuery_WriteZero:
	LD (XBC), 000h

DSP_EffectStateQuery_SetResult:
	LD HL, 1
	RET

DSP_AdjustVoiceParams:
	LDA XSP, XSP - 10
	PUSH XIZ
	LD (XSP + 00ah), XWA
	LD A, (0451A6h)
	SLA 2, A
	EXTS WA
	LD (XSP + 004h), WA
	LD A, (0451ABh)
	SLA 2, A
	EXTS WA
	LD (XSP + 006h), WA
	LD A, (0451ACh)
	SLA 2, A
	EXTS WA
	LD (XSP + 008h), WA
	LD QIZ, 0
	CP QIZ, 4
	JRL NC, DSP_AdjustVoiceParams_Vibrato

DSP_AdjustVoiceParams_SlotLoop:
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	ADD XHL, 0000006eh
	ADD XHL, (XSP + 00ah)
	LD XWA, (XHL)
	LD A, (XWA + 036h)
	AND A, 007h
	CP A, 5
	JR Z, DSP_AdjustVoiceParams_Type5
	CP A, 4
	JR Z, DSP_AdjustVoiceParams_Type1to4
	CP A, 3
	JR Z, DSP_AdjustVoiceParams_Type1to4
	CP A, 2
	JR Z, DSP_AdjustVoiceParams_Type1to4
	CP A, 1
	JRL NZ, DSP_AdjustVoiceParams_ReverbChorus

DSP_AdjustVoiceParams_Type1to4:
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	ADD XHL, 0000006eh
	ADD XHL, (XSP + 00ah)
	LD XWA, (XHL)
	LD A, (XWA + 04dh)
	EXTZ WA
	ADD WA, (XSP + 004h)
	CALL TVF_Clamp_Cutoff
	LD IZ, HL
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	ADD XHL, 0000006eh
	ADD XHL, (XSP + 00ah)
	LD XWA, (XHL)
	LD C, IZL
	LD (XWA + 04dh), C
	JRL T, DSP_AdjustVoiceParams_ReverbChorus

DSP_AdjustVoiceParams_Type5:
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	ADD XHL, 0000006eh
	ADD XHL, (XSP + 00ah)
	LD XWA, (XHL)
	LD A, (XWA + 04dh)
	EXTZ WA
	ADD WA, (XSP + 004h)
	CALL TVF_Clamp_Cutoff
	LD IZ, HL
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	ADD XHL, 0000006eh
	ADD XHL, (XSP + 00ah)
	LD XWA, (XHL)
	LD C, IZL
	LD (XWA + 04dh), C
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	ADD XHL, 0000006eh
	ADD XHL, (XSP + 00ah)
	LD XWA, (XHL)
	LD A, (XWA + 04fh)
	EXTZ WA
	ADD WA, (XSP + 004h)
	CALL TVF_Clamp_Cutoff
	LD IZ, HL
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	ADD XHL, 0000006eh
	ADD XHL, (XSP + 00ah)
	LD XWA, (XHL)
	LD C, IZL
	LD (XWA + 04fh), C

DSP_AdjustVoiceParams_ReverbChorus:
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	ADD XHL, 0000006eh
	ADD XHL, (XSP + 00ah)
	LD XWA, (XHL)
	LD A, (XWA + 027h)
	EXTZ WA
	ADD WA, (XSP + 006h)
	LD BC, 00ffh
	LD DE, 0
	CALL ClampS16_WA_To_DEBC
	LD IZ, HL
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	ADD XHL, 0000006eh
	ADD XHL, (XSP + 00ah)
	LD XWA, (XHL)
	LD C, IZL
	LD (XWA + 027h), C
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	ADD XHL, 0000006eh
	ADD XHL, (XSP + 00ah)
	LD XWA, (XHL)
	LD A, (XWA + 02dh)
	EXTZ WA
	ADD WA, (XSP + 008h)
	LD BC, 00ffh
	LD DE, 0
	CALL ClampS16_WA_To_DEBC
	LD IZ, HL
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	ADD XHL, 0000006eh
	ADD XHL, (XSP + 00ah)
	LD XWA, (XHL)
	LD C, IZL
	LD (XWA + 02dh), C
	INC 1, QIZ
	CP QIZ, 4
	JRL C, DSP_AdjustVoiceParams_SlotLoop

DSP_AdjustVoiceParams_Vibrato:
	CP (0451A7h), 0f5h
	JR Z, DSP_AdjustVoiceParams_Filter
	LD A, (0451A7h)
	SLA 1, A
	LD C, A
	EXTS BC
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD A, (XWA + 02bh)
	EXTZ WA
	ADD WA, BC
	LD BC, 007fh
	LD DE, 0
	CALL ClampS16_WA_Short
	LD IZ, HL
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD C, IZL
	LD (XWA + 02bh), C
	LD A, (0451A7h)
	SLA 1, A
	LD C, A
	EXTS BC
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD A, (XWA + 03bh)
	EXTZ WA
	ADD WA, BC
	LD BC, 007fh
	LD DE, 0
	CALL ClampS16_WA_Short
	LD IZ, HL
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD C, IZL
	LD (XWA + 03bh), C

DSP_AdjustVoiceParams_Filter:
	LD A, (0451A8h)
	SLA 1, A
	LD C, A
	EXTS BC
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD A, (XWA + 02ch)
	EXTZ WA
	ADD WA, BC
	LD BC, 007fh
	LD DE, 0
	CALL ClampS16_WA_Short
	LD IZ, HL
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD C, IZL
	LD (XWA + 02ch), C
	LD A, (0451A8h)
	SLA 1, A
	LD C, A
	EXTS BC
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD A, (XWA + 03ch)
	EXTZ WA
	ADD WA, BC
	LD BC, 007fh
	LD DE, 0
	CALL ClampS16_WA_Short
	LD IZ, HL
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD C, IZL
	LD (XWA + 03ch), C
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD A, (XWA + 02eh)
	AND A, 03fh
	LD IZL, A
	EXTZ IZ
	LD A, (0451A9h)
	SLA 1, A
	EXTS WA
	ADD WA, IZ
	LD BC, 001eh
	LD DE, 0
	CALL ClampS16_WA_Short
	LD IZ, HL
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	AND (XWA + 02eh), 0c0h
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD C, IZL
	OR (XWA + 02eh), C
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD A, (XWA + 03eh)
	AND A, 03fh
	LD IZL, A
	EXTZ IZ
	LD A, (0451A9h)
	SLA 1, A
	EXTS WA
	ADD WA, IZ
	LD BC, 001eh
	LD DE, 0
	CALL ClampS16_WA_Short
	LD IZ, HL
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	AND (XWA + 03eh), 0c0h
	LD XWA, (XSP + 00ah)
	LD XWA, (XWA + 006h)
	LD C, IZL
	OR (XWA + 03eh), C
	POP XIZ
	LDA XSP, XSP + 00ah
	RET

DSP_AlgoSelect:
	DEC 8, XSP
	PUSH XIZ
	LD (XSP + 004h), XDE
	LD (XSP + 008h), BC
	LD (XSP + 00ah), A
	CPW (XSP + 008h), 0028h
	JR NC, DSP_AlgoSelect_InvalidParam
	LD A, (XSP + 00ah)
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041368h
	LDA XIZ, XBC + WA
	LD WA, (XIZ)
	BIT 0, WA
	JR NZ, DSP_AlgoSelect_AlreadyAllocated
	ORW (XIZ), 0001h
	LD A, (XSP + 00ah)
	EXTZ WA
	CALR VoiceParam_FullSetup
	LD A, (XSP + 00ah)
	LD L, A
	EXTZ HL
	LD A, (XIZ + 019h)
	LD C, A
	EXTZ BC
	LD A, (XIZ + 01ah)
	LD E, A
	EXTZ DE
	LD WA, HL
	CALL WaveSel_Rebuild_PartCaches

DSP_AlgoSelect_AlreadyAllocated:
	LD WA, (XIZ)
	BIT 0, WA
	JR Z, DSP_AlgoSelect_WriteAndDispatch
	LD XWA, XIZ
	CALR DSP_AdjustVoiceParams

DSP_AlgoSelect_WriteAndDispatch:
	LD A, (XSP + 00ah)
	EXTZ WA
	LD BC, (XSP + 008h)
	CALL DSP_WriteAlgoBuffer
	LD WA, 00ffh
	LD BC, 00ffh
	CALL DSP_VoiceState_Dispatch
	LD XWA, (XSP + 004h)
	LD (XWA), 000h
	JR T, DSP_AlgoSelect_Return

DSP_AlgoSelect_InvalidParam:
	LD XWA, (XSP + 004h)
	LD (XWA), 002h

DSP_AlgoSelect_Return:
	LD HL, 1
	POP XIZ
	INC 8, XSP
	RET

DSP_MixSendConfig:
	PUSH XIZ
	LD XIZ, XDE
	CALL ToneDB_Find_ToneRecord
	LD XBC, XHL
	LD HL, 0011h
	LD DE, 0
	CP DE, HL
	JR NC, DSP_MixSendConfig_Return

DSP_MixSendConfig_CopyLoop:
	LD A, (XBC+)
	LD (XIZ+), A
	INC 1, DE
	CP DE, HL
	JR C, DSP_MixSendConfig_CopyLoop

DSP_MixSendConfig_Return:
	POP XIZ
	RET

