DSP_VoiceParamReadWrite:
	LDA XSP, XSP - 14
	PUSH XIZ
	LD (XSP + 00ah), XDE
	LD (XSP + 00eh), BC
	LD (XSP + 010h), WA
	LDW (XSP + 008h), 0000h
	LD WA, (XSP + 010h)
	EXTZ XWA
	LD XBC, 0000011fh
	CALL FP_MulAccum64
	LD XWA, 00041368h
	ADD XWA, XHL
	LD WA, (XWA)
	BIT 0, WA
	JR Z, DSP_VoiceParam_MultiSlot
	LD WA, (XSP + 00eh)
	EXTZ XWA
	ADD XWA, 000001d8h
	LD XBC, 00044fceh
	ADD XBC, XWA
	LD XWA, (XSP + 00ah)
	LD C, (XBC)
	LD (XWA), C
	JRL T, DSP_VoiceParamReadWrite_Return

DSP_VoiceParam_MultiSlot:
	LDW (XSP + 006h), 0000h
	CPW (XSP + 006h), 0004h
	JR NC, DSP_VoiceParam_MultiSlot_CheckResult

DSP_VoiceParam_MultiSlot_LoopBody:
	LD WA, (XSP + 006h)
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	LD XIZ, XHL
	ADD XIZ, 0000006eh
	LD WA, (XSP + 010h)
	EXTZ XWA
	LD XBC, 0000011fh
	CALL FP_MulAccum64
	LD XWA, 00041368h
	ADD XWA, XHL
	ADD XWA, XIZ
	LD XWA, (XWA)
	LD A, (XWA + 006h)
	AND A, 0c0h
	JR NZ, DSP_VoiceParam_MultiSlot_LoopNext
	LD WA, (XSP + 006h)
	EXTZ XWA
	LD XBC, 00000025h
	CALL FP_MulAccum64
	LD XIZ, XHL
	ADD XIZ, 0000006eh
	LD WA, (XSP + 010h)
	EXTZ XWA
	LD XBC, 0000011fh
	CALL FP_MulAccum64
	LD XWA, 00041368h
	ADD XWA, XHL
	ADD XWA, XIZ
	LD XWA, (XWA)
	BIT 5, (XWA + 006h)
	JR NZ, DSP_VoiceParam_MultiSlot_LoopNext
	INCW 1, (XSP + 008h)

DSP_VoiceParam_MultiSlot_LoopNext:
	INCW 1, (XSP + 006h)
	CPW (XSP + 006h), 0004h
