DSP_SetVoiceCoefficients:
	LDA XSP, XSP - 10
	PUSH XIZ
	LD (XSP + 008h), XDE
	LD (XSP + 00ch), C
	LD XIZ, 0
	LD XBC, 0
	LD (XSP + 004h), XBC
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 041381h
	LD C, (XDE + BC)
	LD E, C
	EXTZ DE
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041382h
	LD A, (XBC + WA)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALL ToneDB_Find_ToneRecord
	LD A, (XSP + 00ch)
	EXTZ WA
	ADD WA, WA
	ADD WA, 0027h
	LD A, (XHL + WA)
	LD C, A
	EXTZ BC
	LD A, (XSP + 00ch)
	EXTZ WA
	ADD WA, WA
	ADD WA, 0027h
	EXTS XWA
	ADD XWA, XHL
	LD A, (XWA + 001h)
	LD IXL, A
	EXTZ IX
	LD WA, IX
	AND WA, 0020h
	CP WA, 0020h
	JR Z, DSP_SetCoeff_DirectLookup
	CP WA, 0
	JR NZ, DSP_SetCoeff_CopyLoop
	AND BC, 007fh
	LD DE, IX
	AND DE, 001fh
	LD WA, IX
	AND WA, 00c0h
	CP WA, 00c0h
	JR Z, DSP_SetCoeff_LoadTableBase
	CP WA, 0080h
	JR Z, DSP_SetCoeff_LoadTableBase
	CP WA, 0040h
	JR Z, DSP_SetCoeff_LoadTableBase
	CP WA, 0
	JR NZ, DSP_SetCoeff_ComputeIndex

DSP_SetCoeff_LoadTableBase:
	LD XWA, (045314h)
	LD XWA, (XWA + 07ch)
	LD (XSP + 004h), XWA

DSP_SetCoeff_ComputeIndex:
	LD WA, DE
	SLL 7, WA
	ADD WA, BC
	ADD WA, WA
	EXTZ XWA
	ADD XWA, (XSP + 004h)
	ADD XWA, (045310h)
	LD XWA, (XWA)
	LD BC, WA
	LD XWA, (045314h)
	LD XWA, (XWA + 00b0h)
	LD (XSP + 004h), XWA
	LD XIZ, (045310h)
	ADD XIZ, (XSP + 004h)
	LD WA, BC
	MUL_WA 0ah
	ADD XIZ, XWA
	JR T, DSP_SetCoeff_CopyLoop

DSP_SetCoeff_DirectLookup:
	LD A, (XSP + 00ch)
	LD C, A
	EXTZ BC
	LD XWA, XHL
	LD DE, 00ffh
	CALL ToneDB_Find_SubToneRecord
	LD XIZ, XHL

DSP_SetCoeff_CopyLoop:
	LD HL, 000ah
	LD DE, 0
	CP DE, HL
	JR NC, DSP_SetCoeff_Return

DSP_SetCoeff_CopyLoop_Body:
	LD XWA, (XSP + 008h)
	LD C, (XIZ+)
	LD (XWA+), C
	LD (XSP + 008h), XWA
	INC 1, DE
	CP DE, HL
	JR C, DSP_SetCoeff_CopyLoop_Body

DSP_SetCoeff_Return:
	POP XIZ
	LDA XSP, XSP + 00ah
	RET

