Voice_ParamFinalize:
	PUSH XIZ
	LD XIZ, XWA
	LD A, (XIZ)
	AND A, 007h
	BIT 3, (XIZ)
	JRL Z, VoiceParamFinalize_SecondaryDispatch
	EXTZ WA
	CP WA, 0
	JRL MI, VoiceParamFinalize_Return
	CP WA, 7
	JRL GT, VoiceParamFinalize_Return
	ADD WA, WA
	LDA XIX, 0FB2Eh:24
	LD WA, (XIX + WA)
	LDA XIX, ToneCmd_DispatchTable_Body
	JP T, XIX + WA

