	JR NZ, DSP_SlotParam_Write_Slot4_Path
	EXTZ WA
	MULS_WA 011fh
	LD BC, WA
	LDA XDE, 0413D4h
	LD A, (0451ACh)
	SLA 2, A
	LD (XDE + BC), A
	RET

DSP_SlotParam_Write_Slot4_Path:
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 0413D4h
	LD (XBC + WA), 000h
	RET

Voice_ActiveFlag_Set:
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 041368h
	ANDW (XDE + BC), 0fffch
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 041368h
	ORW (XDE + BC), 0004h
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Ch
	LD (XBC + WA), 000h
	RET

Voice_NoteState_Clear:
	LD BC, (041343h)
	BIT 0, BC
	RET NZ
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 041385h
	LDW (XDE + BC), 0000h
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 041387h
	LD (XDE + BC), 000h
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 041388h
	LD (XDE + BC), 000h
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 041383h
	LD (XDE + BC), 040h
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 041384h
	LD (XDE + BC), 040h
	LD IX, 0
	CP IX, 4
	RET NC

Voice_NoteState_InnerLoopA:
	LD HL, 0
	CP HL, 3
	JR NC, Voice_NoteState_Epilogue

Voice_NoteState_InnerLoopB:
	LD BC, IX
	EXTZ XBC
	LD XDE, XBC
	SLL 2, XDE
	LD BC, HL
	EXTZ XBC
	SLL 4, XBC
	LD XIY, XBC
	ADD XIY, XDE
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 041368h
	EXTS XBC
	ADD XBC, XDE
	ADD XBC, XIY
	LD (XBC + 029h), 000h
	LD BC, IX
	EXTZ XBC
	LD XDE, XBC
	SLL 2, XDE
	LD BC, HL
	EXTZ XBC
	SLL 4, XBC
	LD XIY, XBC
	ADD XIY, XDE
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XDE, 041368h
	EXTS XBC
	ADD XBC, XDE
	ADD XBC, XIY
	LD (XBC + 02ah), 000h
	INC 1, HL
	CP HL, 3
	JR C, Voice_NoteState_InnerLoopB

Voice_NoteState_Epilogue:
	INC 1, IX
	CP IX, 4
	JR C, Voice_NoteState_InnerLoopA
	RET

VoiceSlot_FullInit:
	DEC 4, XSP
	PUSH IZ
	LD (XSP + 004h), A
	LD A, (XSP + 004h)
	EXTZ WA
	LD BC, 0
	CALR AlgoType_StateWrite
	LD A, (XSP + 004h)
	EXTZ WA
	CALR Voice_ActiveFlag_CheckAndLoad
	LD A, (XSP + 004h)
	EXTZ WA
	CALR DSP_SlotParam_Write_Slot0
	LD A, (XSP + 004h)
	EXTZ WA
	CALR DSP_SlotParam_Write_Slot1
	LD A, (XSP + 004h)
	EXTZ WA
	CALR DSP_SlotParam_Write_Slot2
	LD A, (XSP + 004h)
	EXTZ WA
	CALR DSP_SlotParam_Write_Slot3
	LD A, (XSP + 004h)
	EXTZ WA
	CALR DSP_SlotParam_Write_Slot4
	LD A, (XSP + 004h)
	EXTZ WA
	CALR Partial_Build_Present_Word
	LD A, (XSP + 004h)
	EXTZ WA
	CALR EnvTranspose_UpdateLoop
	LDW (XSP + 002h), 0000h
	CPW (XSP + 002h), 0003h
	JR NC, VoiceSlot_FullInit_Epilogue

VoiceSlot_FullInit_Loop1:
	LD IZ, 0
	CP IZ, 4
	JR NC, VoiceSlot_FullInit_Loop2

VoiceSlot_FullInit_Loop1Next:
	LD A, (XSP + 004h)
	LD L, A
	EXTZ HL
	LD WA, (XSP + 002h)
	LD C, A
	EXTZ BC
	LD A, IZL
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR AlgoFlag_Write_Bit3
	LD A, (XSP + 004h)
	LD L, A
	EXTZ HL
	LD WA, (XSP + 002h)
	LD C, A
	EXTZ BC
	LD A, IZL
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR AlgoFlag_Write
	INC 1, IZ
	CP IZ, 4
	JR C, VoiceSlot_FullInit_Loop1Next

VoiceSlot_FullInit_Loop2:
	LD IZ, 0
	CP IZ, 4
	JR NC, VoiceSlot_FullInit_Loop3

VoiceSlot_FullInit_Loop2Next:
	LD A, (XSP + 004h)
	LD L, A
	EXTZ HL
	LD A, IZL
	LD C, A
	EXTZ BC
	LD WA, (XSP + 002h)
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR EFF_RoutingInit
	INC 1, IZ
	CP IZ, 4
	JR C, VoiceSlot_FullInit_Loop2Next

VoiceSlot_FullInit_Loop3:
	INCW 1, (XSP + 002h)
	CPW (XSP + 002h), 0003h
	JR C, VoiceSlot_FullInit_Loop1

VoiceSlot_FullInit_Epilogue:
	LD A, (XSP + 004h)
	EXTZ WA
	CALR VoiceNoteParam_UpdateLoop
	POP IZ
	INC 4, XSP
	RET

VoiceSlot_AltInit:
	DEC 4, XSP
	PUSH QIZ
	LD (XSP + 004h), A
	LD A, (XSP + 004h)
	EXTZ WA
	LD BC, 0
	CALR AlgoType_StateWrite
	LD A, (XSP + 004h)
	EXTZ WA
	CALR Voice_ActiveFlag_CheckAndLoad
	LD A, (XSP + 004h)
	EXTZ WA
	CALR DSP_SlotParam_Write_Slot0
	LD A, (XSP + 004h)
