	CALR DSP_SlotParam_Write_Slot1
	LD A, (XSP + 004h)
	EXTZ WA
	CALR DSP_SlotParam_Write_Slot2
	LD A, (XSP + 004h)
	EXTZ WA
	CALR DSP_SlotParam_Write_Slot3
	LD A, (XSP + 004h)
