	JR NC, VoiceSlot_AltInit_Epilogue

VoiceSlot_AltInit_Loop1:
	LD QIZH, 0
	CP QIZH, 4
	JR NC, VoiceSlot_AltInit_Loop2

VoiceSlot_AltInit_Loop1Next:
	LD A, (XSP + 004h)
	LD L, A
	EXTZ HL
	LD A, (XSP + 002h)
	LD C, A
	EXTZ BC
	LD A, QIZH
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR AlgoFlag_Write_Bit3
	LD A, (XSP + 004h)
	LD L, A
	EXTZ HL
	LD A, (XSP + 002h)
	LD C, A
	EXTZ BC
	LD A, QIZH
	LD E, A
	EXTZ DE
	LD WA, HL
	CALR AlgoFlag_Write
	INC 1, QIZH
	CP QIZH, 4
