DSP_WriteCount_Compute:
	LD BC, 4970h
	SRL 1, BC
	LD XWA, (04531Ch)
	LDA XWA, XWA + 010h
	LD DE, 0
	CP BC, 0
	JR Z, DSP_WriteCount_Next

DSP_WriteCount_Loop:
	ADD DE, (XWA+)
	DJNZ BC, DSP_WriteCount_Loop

DSP_WriteCount_Next:
	LD WA, DE
	CPL WA
	LD HL, WA
	RET

DSP_InitChannelSlot:
	DEC 6, XSP
	PUSH XIZ
	LD (XSP + 008h), BC
	LD XDE, XWA
	LD WA, (XSP + 008h)
	LD C, A
	EXTZ BC
	LD XWA, XDE
	LD DE, 00ffh
	CALL ToneDB_Find_SubToneRecord
	LD (XSP + 004h), XHL
	LD WA, (XSP + 008h)
	EXTZ XWA
	LD XBC, XWA
	SLL 2, XBC
	ADD XBC, XWA
	SLL 4, XBC
	ADD XBC, 00004aa7h
	LD XDE, XBC
	ADD XDE, (04531Ch)
	LD XWA, (XSP + 004h)
	LD XIY, XWA
	LD XIX, XDE
	LD BC, 001dh
	LDIRW_95
	LD WA, (XSP + 008h)
	EXTZ XWA
	LD XBC, XWA
	SLL 2, XBC
	ADD XBC, XWA
	SLL 4, XBC
	ADD XBC, 00004aa7h
	ADD XBC, (04531Ch)
	LD (XSP + 004h), XBC
	LD XWA, XBC
	LDA XWA, XWA + 010h
	LD XIZ, XWA
	LD XBC, XIZ
	LD WA, (XSP + 008h)
	EXTZ WA
	PUSHW 00ffh
	LD DE, WA
	LD WA, 0
	CALL WaveSel_StageA1_FromToneSlot
	LD WA, (XSP + 008h)
	EXTZ XWA
	LD XBC, XWA
	SLL 2, XBC
	ADD XBC, XWA
	SLL 4, XBC
	ADD XBC, 00004aa7h
	LD XWA, XBC
	ADD XWA, (04531Ch)
	LD XIY, XHL
	LDA XIX, XWA + 03ah
	LD BC, 5
	LDIRW_95
	LDI
	AND (XIZ + 002h), 0cfh
	SET 4, (XIZ + 002h)
	LD XWA, (XSP + 004h)
	LDA XWA, XWA + 025h
	LD XIZ, XWA
	LD XBC, XIZ
	LD WA, (XSP + 008h)
	EXTZ WA
	PUSHW 00ffh
	LD DE, WA
	LD WA, 1
	CALL WaveSel_StageA1_FromToneSlot
	LD WA, (XSP + 008h)
	EXTZ XWA
	LD XBC, XWA
	SLL 2, XBC
	ADD XBC, XWA
	SLL 4, XBC
	ADD XBC, 00004aa7h
	LD XWA, XBC
	ADD XWA, (04531Ch)
	LD XIY, XHL
	LDA XIX, XWA + 045h
	LD BC, 5
	LDIRW_95
	LDI
	AND (XIZ + 002h), 0cfh
	SET 4, (XIZ + 002h)
	POP XIZ
	INC 6, XSP
	RET

DSP_FlushAllSlots:
	DEC 4, XSP
	PUSH IZ
	EXTZ WA
	EXTZ BC
	CALL ToneDB_Find_ToneRecord
	LD (XSP + 002h), XHL
	LD XDE, (04531Ch)
	LD XWA, (XSP + 002h)
	LD XIY, XWA
	LDA XIX, XDE + 4980h
	LD BC, 0093h
	LDIRW_95
	LDI
	LD IZ, 0
	CP IZ, 0080h
	JR NC, DSP_FlushAllSlots_Loop1Next

DSP_FlushAllSlots_Loop1:
	LD WA, IZ
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, 000049a7h
	ADD XWA, (04531Ch)
	RES 5, (XWA + 001h)
	LD WA, IZ
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, 000049a7h
	ADD XWA, (04531Ch)
	SET 5, (XWA + 001h)
	INC 1, IZ
	CP IZ, 0080h
	JR C, DSP_FlushAllSlots_Loop1

DSP_FlushAllSlots_Loop1Next:
	LD IZ, 0
	CP IZ, 0080h
	JR NC, DSP_FlushAllSlots_Loop2Next

DSP_FlushAllSlots_Loop2:
	LD XWA, (XSP + 002h)
	LD BC, IZ
	CALR DSP_InitChannelSlot
	INC 1, IZ
	CP IZ, 0080h
	JR C, DSP_FlushAllSlots_Loop2

DSP_FlushAllSlots_Loop2Next:
	LD IZ, 0
	CP IZ, 0010h
	JR NC, DSP_FlushAllSlots_Loop3Next

DSP_FlushAllSlots_Loop3:
	LD WA, IZ
	EXTZ XWA
	ADD XWA, 00004980h
	LD XDE, XWA
	ADD XDE, (04531Ch)
	LD WA, IZ
	EXTZ XWA
	LD XBC, 000120f4h
	ADD XBC, XWA
	LD A, (XBC)
	LD (XDE), A
	INC 1, IZ
	CP IZ, 0010h
	JR C, DSP_FlushAllSlots_Loop3

DSP_FlushAllSlots_Loop3Next:
	LDA XWA, 7800h:24
	LD BC, 72aah
	LD XDE, 001e0000h
	CALL InterCPU_E1_DMA_Transfer
	POP IZ
	INC 4, XSP
	RET

DSP_FlushAllSlots_Data:
	db 0C9h, 08Bh, 0D9h, 012h, 0D9h, 009h, 01Fh, 001h
	db 0F2h, 081h, 013h, 004h, 032h, 0C3h, 007h, 0E8h
	db 0E4h, 023h, 0CBh, 08Dh, 0DAh, 012h, 0D8h, 012h
	db 0D8h, 009h, 01Fh, 001h, 0F2h, 082h, 013h, 004h
	db 031h, 0C3h, 007h, 0E4h, 0E0h, 021h, 0C9h, 08Bh
	db 0D9h, 012h, 0DAh, 088h, 078h, 018h, 0FFh

DSP1_ResolveStreamPtr:
	LD XHL, 00050000h
	LD XBC, (XHL + 0088h)
	ADD WA, BC
	LD XBC, (XHL + 008h)
	LD XDE, XHL
	ADD XDE, XBC
	EXTZ XWA
	SLL 2, XWA
	ADD XDE, XWA
	LD XWA, (XDE)
	LD XBC, XHL
	ADD XHL, XWA
	RET

DSP_ResetAlgoDefaults:
	LD HL, 0
	CP HL, 0010h
	RET NC

DSP_ResetAlgoDefaults_Loop:
	LD WA, HL
	EXTZ XWA
	LD XDE, XWA
	ADD XDE, (04531Ch)
	LD WA, HL
	EXTZ XWA
	LD XBC, 000120e3h
	ADD XBC, XWA
	LD A, (XBC)
	LD (XDE), A
	INC 1, HL
	CP HL, 0010h
	JR C, DSP_ResetAlgoDefaults_Loop
