DSP_WriteAlgoBuffer:
	PUSH XIZ
	LD E, C
	CP A, 01ah
	JR NC, DSP_WriteAlgoBuffer_PathA
	CP E, 028h
	JR C, DSP_WriteAlgoBuffer_PathB

DSP_WriteAlgoBuffer_PathA:
	LD_L 002h
	JRL T, DSP_WriteAlgoBuffer_Data

DSP_WriteAlgoBuffer_PathB:
	LD C, E
	EXTZ BC
	MULS_BC 01d6h
	LD IZ, BC
	ADD IZ, 0010h
	LD XHL, (04531Ch)
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XIX, 04136Eh
	LD XIY, (XIX + BC)
	LDA XIX, XHL + IZ
	LD BC, 00d5h
	LDIRW_95
	LD_L 000h
	CP L, 4
	JRL NC, DSP_WriteAlgoBuffer_Epilogue

DSP_WriteAlgoBuffer_Loop:
	LD C, L
	EXTZ BC
	MULS_BC 000bh
	LD IX, BC
	LD C, E
	EXTZ BC
	MULS_BC 01d6h
	LD IY, BC
	ADD IY, IX
	LD XBC, (04531Ch)
	LDA XIZ, XBC + IY
	LD C, L
	EXTZ BC
	MULS_BC 0025h
	LD IY, BC
	ADD IY, 006eh
	LD C, A
	EXTZ BC
	MULS_BC 011fh
	LDA XIX, 041368h
	EXTS XBC
	ADD XBC, XIX
	LDA XBC, XBC + IY
	LD XIY, (XBC + 004h)
	LDA XIX, XIZ + 01bah
	LD BC, 5
	LDIRW_95
	LDI
	LD C, L
	EXTZ BC
	MULS_BC 0051h
	LD IX, BC
	LD C, E
	EXTZ BC
	MULS_BC 01d6h
	LD IY, BC
	ADD IY, IX
	LD XBC, (04531Ch)
	LDA XIX, XBC + IY
	LDA XIX, XIX + 079h
	LD C, (XIX)
	AND C, 0c0h
	CP C, 0c0h
	JR Z, DSP_WriteAlgoBuffer_LoopNext
	AND (XIX), 0cfh
	SET 4, (XIX)

DSP_WriteAlgoBuffer_LoopNext:
	INC 1, L
	CP L, 4
	JRL C, DSP_WriteAlgoBuffer_Loop

DSP_WriteAlgoBuffer_Epilogue:
	CALR DSP_WriteCount_Compute
	LD XWA, (04531Ch)
	LD (XWA + 72a8h), HL
	LDA XWA, 7800h:24
	LD BC, 72aah
	LD XDE, 001e0000h
	CALL InterCPU_E1_DMA_Transfer
	LD_L 000h

DSP_WriteAlgoBuffer_Data:
	POP XIZ
	RET

DSP_Reinit_VoiceSlots:
	DEC 4, XSP
	PUSH XIZ
	CP A, 040h
	JRL NC, DSP_Reinit_VoiceSlots_Loop2A
	CP C, 0ffh
	JR Z, DSP_Reinit_VoiceSlots_Loop1
	EXTZ BC
	EXTZ WA
	MUL_WA 0014h
	LD QIZ, WA
	ADD WA, BC
	LD QIZ, WA
	CALR DSP1_ResolveStreamPtr
	LD (XSP + 004h), XHL
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 000001d6h
	CALL FP_MulAccum64
	ADD XHL, 00000010h
	ADD XHL, (04531Ch)
	LD XWA, (XSP + 004h)
	LD XIY, XWA
	LD XIX, XHL
	LD BC, 00d5h
	LDIRW_95
	JR T, DSP_Reinit_VoiceSlots_Loop2

DSP_Reinit_VoiceSlots_Loop1:
	LD IZL, A
	EXTZ IZ
	LD WA, IZ
	MUL_WA 0014h
	LD IZ, WA
	LD QIZ, IZ
	LD BC, IZ
	ADD BC, 0014h
	LD WA, QIZ
	CP WA, BC
	JR NC, DSP_Reinit_VoiceSlots_Loop2

DSP_Reinit_VoiceSlots_Loop1Next:
	LD WA, QIZ
	CALR DSP1_ResolveStreamPtr
	LD (XSP + 004h), XHL
	LD WA, QIZ
	EXTZ XWA
	LD XBC, 000001d6h
	CALL FP_MulAccum64
	ADD XHL, 00000010h
	ADD XHL, (04531Ch)
	LD XWA, (XSP + 004h)
	LD XIY, XWA
	LD XIX, XHL
	LD BC, 00d5h
	LDIRW_95
	INC 1, QIZ
	LD BC, IZ
	ADD BC, 0014h
	LD WA, QIZ
	CP WA, BC
	JR C, DSP_Reinit_VoiceSlots_Loop1Next

DSP_Reinit_VoiceSlots_Loop2:
	CALR DSP_WriteCount_Compute
	LD XWA, (04531Ch)
	LD (XWA + 72a8h), HL
	JRL T, DSP_Reinit_VoiceSlots_DMAFlush

DSP_Reinit_VoiceSlots_Loop2A:
	CP A, 0ffh
	JR Z, DSP_Reinit_VoiceSlots_Loop3A
	CP C, 0ffh
	JR Z, DSP_Reinit_VoiceSlots_Loop2B
	LD XWA, (04531Ch)
	LDA XWA, XWA + 4980h
	EXTZ BC
	CALR DSP_InitChannelSlot
	JR T, DSP_Reinit_VoiceSlots_Loop3

DSP_Reinit_VoiceSlots_Loop2B:
	LD QIZ, IZ
	CP QIZ, 0080h
	JR NC, DSP_Reinit_VoiceSlots_Loop3

DSP_Reinit_VoiceSlots_Loop2Next:
	LD XWA, (04531Ch)
	LDA XWA, XWA + 4980h
	LD BC, QIZ
	CALR DSP_InitChannelSlot
	INC 1, QIZ
	CP QIZ, 0080h
	JR C, DSP_Reinit_VoiceSlots_Loop2Next

DSP_Reinit_VoiceSlots_Loop3:
	CALR DSP_WriteCount_Compute
	LD XWA, (04531Ch)
	LD (XWA + 72a8h), HL
	JR T, DSP_Reinit_VoiceSlots_DMAFlush

DSP_Reinit_VoiceSlots_Loop3A:
	CALR DSP_ResetAlgoDefaults
	LD IZ, 0
	CP IZ, 0028h
	JR NC, DSP_Reinit_VoiceSlots_OuterNext

DSP_Reinit_VoiceSlots_Loop3Next:
	LD WA, IZ
	CALR DSP1_ResolveStreamPtr
	LD (XSP + 004h), XHL
	LD WA, IZ
	EXTZ XWA
	LD XBC, 000001d6h
	CALL FP_MulAccum64
	ADD XHL, 00000010h
	ADD XHL, (04531Ch)
	LD XWA, (XSP + 004h)
	LD XIY, XWA
	LD XIX, XHL
	LD BC, 00d5h
	LDIRW_95
	INC 1, IZ
	CP IZ, 0028h
	JR C, DSP_Reinit_VoiceSlots_Loop3Next

DSP_Reinit_VoiceSlots_OuterNext:
	LD WA, 0
	LD BC, 0040h
	CALR DSP_FlushAllSlots
	CALR DSP_WriteCount_Compute
	LD XWA, (04531Ch)
	LD (XWA + 72a8h), HL

DSP_Reinit_VoiceSlots_DMAFlush:
	LDA XWA, 7800h:24
	LD BC, 72aah
	LD XDE, 001e0000h
	CALL InterCPU_E1_DMA_Transfer
	POP XIZ
	INC 4, XSP
	RET

DSP_VoiceState_Dispatch:
	PUSH QIZ
	LD QIZH, 0
	CP QIZH, 01ah
	JRL NC, DSP_VoiceState_Dispatch_Epilogue

DSP_VoiceState_Dispatch_Scan:
	LD A, QIZH
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041382h
	CP (XBC + WA), 010h
	JR Z, DSP_VoiceState_Dispatch_ActiveVoice
	LD A, QIZH
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041382h
	CP (XBC + WA), 050h
	JRL NZ, DSP_VoiceState_Dispatch_LoopNext

DSP_VoiceState_Dispatch_ActiveVoice:
	LD A, QIZH
	LD L, A
	EXTZ HL
	LD A, QIZH
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041381h
	LD A, (XBC + WA)
	LD IXL, A
	EXTZ IX
	LD A, QIZH
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 041382h
	LD A, (XBC + WA)
	LD E, A
	EXTZ DE
	LD WA, HL
	LD BC, IX
	CALL WaveSel_Rebuild_PartCaches
	LD A, QIZH
	EXTZ WA
	MULS_WA 011fh
	LDA XBC, 04136Eh
	LD XWA, (XBC + WA)
	LD A, (XWA + 010h)
	AND A, 0c0h
	CP A, 080h
	JR Z, DSP_VoiceState_Dispatch_LoopNext
	CP A, 040h
	JR Z, DSP_VoiceState_Dispatch_SubPathB
	CP A, 0c0h
	JR Z, DSP_VoiceState_Dispatch_SubPathA
	CP A, 0
	JR NZ, DSP_VoiceState_Dispatch_LoopNext

DSP_VoiceState_Dispatch_SubPathA:
	LD A, QIZH
	EXTZ WA
	CALL VoiceSlot_FullInit
	JR T, DSP_VoiceState_Dispatch_LoopNext

DSP_VoiceState_Dispatch_SubPathB:
	LD A, QIZH
	EXTZ WA
	CALL Voice_PortamentoTargets_SetAll
	LD A, QIZH
	EXTZ WA
	CALL VoiceSlot_AltInit

DSP_VoiceState_Dispatch_LoopNext:
	INC 1, QIZH
	CP QIZH, 01ah
	JRL C, DSP_VoiceState_Dispatch_Scan

DSP_VoiceState_Dispatch_Epilogue:
	POP QIZ
	RET

DSP_ResetWriteBufferPtr:
	LDA XWA, 7800h:24
	LD (045320h), XWA
	LDA XWA, 7800h:24
	LD (04531Ch), XWA
	RET

DSP_Stub_RetA:
	RET

DSP_Stub_RetB:
	RET

DSP_Stub_RetC:
	RET

DSP_VelocityToVolume:
	LD BC, WA
	MUL XBC, WA
	SRL 2, BC
	LD HL, BC
	ADD HL, 003fh
	RET

DSP_GetEffectRouting:
	LD HL, 0
	CP (041377h), 000h
	JR Z, DSP_GetEffectRouting_Path
	LD A, (041377h)
	EXTZ WA
	SLL 8, WA
	OR HL, WA

DSP_GetEffectRouting_Path:
	CP (04137Ah), 000h
	RET Z
	LD A, (041377h)
	EXTZ WA
	OR HL, WA
	RET

ToneGen_SetupPolyVoice:
	DEC 4, XSP
	LD (XSP), E
	LD E, C
	LD (XSP + 002h), A
	LD XIY, 00012115h
	LD XIX, 00003b1ch
	LD BC, 0022h
	LDIRW_95
	LD A, E
	EXTZ WA
	LDA XBC, 012171h
	LD A, (XBC + WA)
	ADD A, (XSP)
	LD (XSP), A
	RES 7, (XSP)
	LD A, (XSP)
	EXTZ WA
	SLL 8, WA
	SET 7, WA
	LD (3B2Ah), WA
	LD A, E
	EXTZ WA
	LDA XBC, 012177h
	CP (XBC + WA), 000h
	JR Z, ToneGen_SetupPolyVoice_Path
	LD A, E
	EXTZ WA
	LDA XBC, 012177h
	LD A, (XBC + WA)
	LD (XSP + 008h), A

ToneGen_SetupPolyVoice_Path:
	LD A, (XSP + 008h)
	EXTZ WA
	CALR DSP_VelocityToVolume
	OR (3B20h), HL
	CALR DSP_GetEffectRouting
	OR (3B22h), HL
	LD A, (XSP)
	EXTZ WA
	DIV_A 00ch
	LD A, W
	EXTZ WA
	ADD WA, WA
	LDA XBC, 01217Dh
	LD WA, (XBC + WA)
	LD (3B1Eh), WA
	LD A, (XSP + 002h)
	EXTZ WA
	LDA XBC, 3B1Ch
	CALL ToneGen_WriteVoiceParams
	LD A, (XSP + 002h)
	EXTZ WA
	LD BC, (3B1Ch)
	CALL ToneGen_WriteSingleReg
	INC 4, XSP
	RETD 0002h

ToneGen_SetupPercussionVoice:
	DEC 2, XSP
	LD (XSP), A
	LD XIY, 00012115h
	LD XIX, 00003b1ch
	LD BC, 0022h
	LDIRW_95
	LD A, E
	EXTZ WA
	DIV_A 00ch
	LD C, W
	SUB E, C
	RES 7, E
	LD A, E
	EXTZ WA
	SLL 8, WA
	OR (3B2Ah), WA
	LD A, C
	EXTZ WA
	ADD WA, WA
	LDA XBC, 012195h
	LD WA, (XBC + WA)
	OR (3B1Ch), WA
	CALR DSP_GetEffectRouting
	OR (3B22h), HL
	ORW (3B20h), 0fffh
	LD WA, (01217Dh)
	LD (3B1Eh), WA
	LD A, (XSP)
	EXTZ WA
	LDA XBC, 3B1Ch
	CALL ToneGen_WriteVoiceParams
	LD A, (XSP)
	EXTZ WA
	LD BC, (3B1Ch)
	CALL ToneGen_WriteSingleReg
	INC 2, XSP
	RETD 0002h

Voice_Poly_NoteOn:
	PUSH XIZ
	LD E, (XWA + 001h)
	LD C, E
	AND C, 00fh
	LD QIZH, C
	CP E, 0f0h
	JRL C, Voice_Poly_NoteOn_Epilogue
	CP QIZH, 5
	JR ULE, Voice_Poly_NoteOn_RoundRobin
	LD QIZH, 0

Voice_Poly_NoteOn_RoundRobin:
	LD C, (3B13h)
	INC 1, C
	AND C, 007h
	LD (3B13h), C
	LD C, (XWA + 003h)
	RES 7, C
	LD IZH, C
	LD A, (XWA + 002h)
	RES 7, A
	LD QIZL, A
	CP IZH, 0
	JRL Z, Voice_Poly_NoteOn_ReleasePath
	RES 7, (P6)
	LD A, (3B13h)
	EXTZ WA
	ADD WA, 0840h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0ff00h
	JR T, Voice_Poly_NoteOn_SlotSearch

Voice_Poly_NoteOn_SlotSearch:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD A, (3B13h)
	EXTZ WA
	ADD WA, 0800h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0ff80h
	JR T, Voice_Poly_NoteOn_SlotFound

Voice_Poly_NoteOn_SlotFound:
	NOP
	NOP
	NOP
	LD A, (3B13h)
	LD L, A
	EXTZ HL
	LD A, QIZH
	LD C, A
	EXTZ BC
	LD A, QIZL
	LD E, A
	EXTZ DE
	LD A, IZH
	EXTZ WA
	PUSH WA
	LD WA, HL
	LD L, QIZH
	EXTZ HL
	SLA 2, HL
	LDA XIX, CALL_TABLE_12159
	EXTS XHL
	ADD XHL, XIX
	LD XHL, (XHL)
	CALL T, XHL
	LD A, (3B13h)
	EXTZ WA
	LDA XBC, 3B14h
	LD DE, WA
	EXTZ XDE
	ADD XDE, XBC
	LD A, QIZL
	SET 7, A
	LD (XDE), A
	JR T, Voice_Poly_NoteOn_Epilogue

Voice_Poly_NoteOn_ReleasePath:
	SET 7, QIZL
	LD QIZH, 0
	CP QIZH, 008h
	JR NC, Voice_Poly_NoteOn_Epilogue

Voice_Poly_NoteOn_ReleaseCheck:
	LD A, QIZH
	EXTZ WA
	LDA XBC, 3B14h
	EXTZ XWA
	ADD XWA, XBC
	LD A, (XWA)
	CP A, QIZL
	JR NZ, Voice_Poly_NoteOn_AssignSlot
	RES 7, (P6)
	LD A, QIZH
	EXTZ WA
	ADD WA, 0840h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a200h
	JR T, Voice_Poly_NoteOn_ReleaseNext

Voice_Poly_NoteOn_ReleaseNext:
	NOP
	NOP
	NOP
	RES 7, (P6)
	LD A, QIZH
	EXTZ WA
	ADD WA, 0800h
	LD (100000h), WA
	NOP
	SET 7, (P6)
	LDW (100002h:24), 0a280h
	JR T, Voice_Poly_NoteOn_ReleaseDone

Voice_Poly_NoteOn_ReleaseDone:
	NOP
	NOP
	NOP
	LD A, QIZH
	EXTZ WA
	LDA XBC, 3B14h
	EXTZ XWA
	ADD XWA, XBC
	RES 7, (XWA)
	JR T, Voice_Poly_NoteOn_Epilogue

Voice_Poly_NoteOn_AssignSlot:
	INC 1, QIZH
	CP QIZH, 008h
	JR C, Voice_Poly_NoteOn_ReleaseCheck

Voice_Poly_NoteOn_Epilogue:
	POP XIZ
	RET

DSP_StoreBufferCount:
	LD (4366h), WA
	RET

; ===========================================================================
; DSP2_Init - Initialize second DSP chip
; ===========================================================================
; Entry: None
; Exit:  DSP2 state cleared
; Notes: Clears DSP2 control variables at 0x3B60-0x3B64
;        Called during Audio_System_Init after primary DSP initialization
; ===========================================================================
DSP2_Init:
	LDW (3B64h), 0000h
	LD WA, 0
	LD (3B62h), WA
	LD (3B60h), WA
	RET

Voice_Poly_NoteOn_Data:
	db 00Eh, 00Eh

DSP_RingBuf_Read:
	CPW (XWA + 004h), 0000h
	JR Z, DSP_RingBuf_Read_Empty
	LDA XBC, XWA + 002h
	LD DE, (XBC)
	INCW 1, (XBC)
	AND DE, 07ffh
	LD BC, DE
	EXTZ XBC
	INC 6, XBC
	ADD XBC, XWA
	LD C, (XBC)
	EXTZ BC
	LD HL, BC
	DECW 1, (XWA + 004h)
	JR T, DSP_RingBuf_Read_Return

DSP_RingBuf_Read_Empty:
	LD HL, 0ffffh

DSP_RingBuf_Read_Return:
	RET

DSP_RingBuf_Read_Data:
	db 0F1h, 060h, 03Bh, 030h, 068h, 0D1h

DSP_RingBuf_Skip:
	PUSH XIZ
	LD XIZ, XWA
	LD XWA, XIZ
	CALR DSP_RingBuf_Read
	CP HL, 0
	JR LT, DSP_RingBuf_Skip_Epilogue

DSP_RingBuf_Skip_Loop:
	LD XWA, XIZ
	CALR DSP_RingBuf_Read
	CP HL, 0
	JR GE, DSP_RingBuf_Skip_Loop

DSP_RingBuf_Skip_Epilogue:
	LD WA, (XIZ + 002h)
	LD (XIZ), WA
	POP XIZ
	RET

DSP_RingBuf_Write2K:
	db 0E8h, 08Ah, 092h, 023h, 092h, 061h, 0DBh, 0CCh
	db 0FFh, 007h, 0DBh, 08Ah, 0EAh, 012h, 0EAh, 066h
	db 0E8h, 082h, 0B2h, 043h, 098h, 004h, 061h, 00Eh

Audio_CmdHandler_60_7F:
	LD XHL, (XSP + 006h)
	LD DE, (XSP + 004h)
	CPW (448Ch), 0000h
	JR Z, CmdHandler60_StreamSizeC
	CPW (448Ch), 0001h
	JR ULE, CmdHandler60_StreamSizeA
	LD IX, 0

CmdHandler60_StreamSizeA:
	LD WA, (448Ah)
	ADD WA, DE
	CP WA, (4488h)
	JR NC, CmdHandler60_StreamSizeB
	ADD (448Ah), DE
	INCW 1, (448Ch)
	JR T, DSP_EnqueueOrReturn

CmdHandler60_StreamSizeB:
	LDW (448Ah), 0000h
	LDW (448Ch), 0000h
	JR T, DSP_EnqueueOrReturn

CmdHandler60_StreamSizeC:
	CP DE, 0020h
	JR NZ, DSP_CmdHandler_StateReset
	LD A, (XHL + 005h)
	EXTZ WA
	AND WA, 07ffh
	LD BC, WA
	SLL 7, BC
	LD A, (XHL + 006h)
	EXTZ WA
	ADD WA, BC
	INC 8, WA
	LD (4488h), WA
	ADDW (448Ah), 0020h
	LDW (448Ch), 0001h
	JR T, DSP_EnqueueOrReturn

DSP_CmdHandler_StateReset:
	LDW (448Ah), 0000h
	LDW (448Ch), 0000h

DSP_EnqueueOrReturn:
	LD IX, 0
	CP IX, DE
	JR NC, DSP_Enqueue_ReturnOK

DSP_RingBuf_Enqueue:
	LDA XWA, 3B60h
	LD BC, (XWA)
	INCW 1, (XWA)
	AND BC, 07ffh
	LDA XWA, 3B66h
	EXTZ XBC
	ADD XBC, XWA
	LD A, (XHL+)
	LD (XBC), A
	INCW 1, (3B64h)
	INC 1, IX
	CP IX, DE
	JR C, DSP_RingBuf_Enqueue

DSP_Enqueue_ReturnOK:
	LD HL, 0
	RET

Extract_14Bit_PayloadSize:
	LD C, (XWA + 006h)
	EXTZ BC
	AND BC, 007fh
	LD A, (XWA + 005h)
	EXTZ WA
	AND WA, 007fh
	SLL 7, WA
	LD HL, WA
	OR HL, BC
	RET

DSP_Pack3x7bitFields:
	db 088h, 002h, 023h, 0CBh, 030h, 007h, 022h, 000h
	db 0E9h, 012h, 0E9h, 08Ah, 0EAh, 0EEh, 007h, 088h
	db 001h, 023h, 0CBh, 030h, 007h, 022h, 000h, 0E9h
	db 012h, 0E9h, 0EEh, 00Eh, 0EAh, 0E1h, 088h, 003h
	db 021h, 0C9h, 030h, 007h, 020h, 000h, 0E8h, 012h
	db 0E8h, 08Bh, 0E9h, 0E3h, 00Eh

Extract_14Bit_VoiceParam:
	LD C, (XWA + 003h)
	EXTZ BC
	AND BC, 007fh
	LD A, (XWA + 002h)
	EXTZ WA
	AND WA, 007fh
	SLL 7, WA
	LD HL, WA
	OR HL, BC
	RET

DSP_Cmd_DequeueHeader:
	PUSH XIZ
	LD XIZ, XWA
	LD XWA, XIZ
	CALR DSP_RingBuf_Read
	LD (4369h), L
	LD XWA, XIZ
	CALR DSP_RingBuf_Read
	LD (436Ah), L
	LD XWA, XIZ
	CALR DSP_RingBuf_Read
	LD (436Bh), L
	LD XWA, XIZ
	CALR DSP_RingBuf_Read
	LD (436Ch), L
	LD XWA, XIZ
	CALR DSP_RingBuf_Read
	LD (436Dh), L
	LD XWA, XIZ
	CALR DSP_RingBuf_Read
	LD (436Eh), L
	LD XWA, XIZ
	CALR DSP_RingBuf_Read
	LD (436Fh), L
	POP XIZ
	RET

DSP_Cmd_LoadEffectPreset:
	LDA XSP, XSP - 10
	PUSH XIZ
	LD (XSP + 00ah), XWA
	LD A, (436Dh)
	EXTZ WA
	LD BC, WA
	SLL 7, BC
	LD A, (436Eh)
	EXTZ WA
	ADD WA, BC
	CP WA, 0122h
	JR NZ, DSP_LoadEffPreset_Loop3Next
	CALL DSP_GetConfigBuffer
	LD (XSP + 006h), XHL
	LDW (XSP + 004h), 0008h
	LD IZ, 0
	CP IZ, (XSP + 004h)
	JR NC, DSP_LoadEffPreset_Loop1Next

DSP_LoadEffPreset_Loop1:
	LD XWA, (XSP + 00ah)
	CALR DSP_RingBuf_Read
	LD XWA, (XSP + 006h)
	LD (XWA+), L
	LD (XSP + 006h), XWA
	INC 1, IZ
	CP IZ, (XSP + 004h)
	JR C, DSP_LoadEffPreset_Loop1

DSP_LoadEffPreset_Loop1Next:
	LDW (XSP + 004h), 0038h
	LD QIZ, 0
	CP QIZ, 5
	JR NC, DSP_LoadEffPreset_Loop3A

DSP_LoadEffPreset_Loop2:
	LD WA, QIZ
	CALL EFF_GetSlotBuffer
	LD (XSP + 006h), XHL
	LD IZ, 0
	CP IZ, (XSP + 004h)
	JR NC, DSP_LoadEffPreset_Loop3

DSP_LoadEffPreset_Loop2Next:
	LD XWA, (XSP + 00ah)
	CALR DSP_RingBuf_Read
	LD XWA, (XSP + 006h)
	LD (XWA+), L
	LD (XSP + 006h), XWA
	INC 1, IZ
	CP IZ, (XSP + 004h)
	JR C, DSP_LoadEffPreset_Loop2Next

DSP_LoadEffPreset_Loop3:
	INC 1, QIZ
	CP QIZ, 5
	JR C, DSP_LoadEffPreset_Loop2

DSP_LoadEffPreset_Loop3A:
	LD XWA, (XSP + 00ah)
	CALR DSP_RingBuf_Read
	LD XWA, (XSP + 00ah)
	CALR DSP_RingBuf_Read
	LD HL, 0
	JR T, DSP_LoadEffPreset_Epilogue

DSP_LoadEffPreset_Loop3Next:
	LD XWA, (XSP + 00ah)
	CALR DSP_RingBuf_Skip
	LD HL, 0ffffh

DSP_LoadEffPreset_Epilogue:
	POP XIZ
	LDA XSP, XSP + 00ah
	RET

DSP_RingBuf_ReadAndCompare:
	DEC 8, XSP
	PUSH XIZ
	LD (XSP + 004h), XBC
	LD (XSP + 008h), XWA
	LD IZ, 0
	JR T, DSP_RingBuf_Compare_MismatchPath

DSP_RingBuf_Compare_Loop:
	LD XWA, (XSP + 008h)
	CALR DSP_RingBuf_Read
	LD XWA, (XSP + 004h)
	CP (XWA), L
	JR Z, DSP_RingBuf_Compare_MatchPath
	INC 1, QIZ

DSP_RingBuf_Compare_MatchPath:
	LD XWA, (XSP + 004h)
	LD (XWA+), L
	LD (XSP + 004h), XWA
	INC 1, IZ

DSP_RingBuf_Compare_MismatchPath:
	LD A, (436Eh)
	EXTZ WA
	CP IZ, WA
	JR C, DSP_RingBuf_Compare_Loop
	CP (436Fh), 0ffh
	JR Z, DSP_RingBuf_Compare_LoopNext
	CP QIZ, 2
	JR C, DSP_RingBuf_Compare_FoundPath

DSP_RingBuf_Compare_LoopNext:
	LD L, (436Fh)
	JR T, DSP_RingBuf_Compare_Epilogue

DSP_RingBuf_Compare_FoundPath:
	LD_L 000h

DSP_RingBuf_Compare_Epilogue:
	POP XIZ
	INC 8, XSP
	RET

; ===========================================================================
; Audio_Process_DSP - DSP audio processing main loop
; ===========================================================================
; Entry: Called from main audio loop after MIDI_Dispatch
; Exit:  DSP state updated, audio buffers processed
; Notes: Processes pending DSP commands from buffer at 0x3B60
;        Updates DSP2 voice parameters and effect processing
;        Part of main audio loop: ToneGen -> MIDI -> DSP -> Final
; ===========================================================================
Audio_Process_DSP:
	LDA XSP, XSP - 10
	PUSH XIZ
	LDA XWA, 3B60h
	LD (XSP + 004h), XWA
	LD WA, (XWA + 004h)
	CALR DSP_StoreBufferCount
	CPW (448Ch), 0000h
	JRL Z, DSP_Process_ReadNext
	JRL T, DSP_Process_Exit

DSP_Process_NextCmd:
	LD XWA, (XSP + 004h)
	LD WA, (XWA + 002h)
	INC 5, WA
	AND WA, 07ffh
	EXTZ XWA
	INC 6, XWA
	ADD XWA, (XSP + 004h)
	LD A, (XWA)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 004h)
	CP BC, (XWA + 004h)
	JR ULE, Audio_Process_DSP_MsgSizeCheck
	LD XWA, (XSP + 004h)
	DECW 1, (XWA + 002h)
	LD XWA, (XSP + 004h)
	INCW 1, (XWA + 004h)
	LDW (448Ch), 0001h
	JRL T, DSP_Process_Exit

Audio_Process_DSP_MsgSizeCheck:
	LD XWA, (XSP + 004h)
	CALR DSP_Cmd_DequeueHeader
	LD WA, (XSP + 00ch)
	LD (4368h), A
	CP A, 02dh
	JRL Z, DSP_CmdHandler_2D
	CP A, 02ch
	JRL Z, DSP_CmdHandler_2C
	CP A, 02bh
	JRL NZ, DSP_Cmd_DefaultSkip
	LDA XWA, 4370h
	LD XBC, XWA
	LD XWA, (XSP + 004h)
	CALR DSP_RingBuf_ReadAndCompare
	LD A, (4369h)
	LD QIZH, A
	CP QIZH, 030h
	JRL C, DSP_Cmd2B_SkipAndContinue
	CP QIZH, 03fh
	JRL UGT, DSP_Cmd2B_SkipAndContinue
	CP (436Ah), 07fh
	JRL NZ, DSP_Cmd2B_VoiceParamWrite
	LD A, QIZH
	LD IZL, A
	EXTZ IZ
	AND IZ, 000fh
	LDA XWA, 4370h
	LD (XSP + 00ah), XWA
	LD A, (436Bh)
	CP A, 030h
	JRL Z, DSP_Cmd2B_Noop
	CP A, 027h
	JRL Z, DSP_Cmd2B_ReadParam11
	CP A, 024h
	JRL Z, DSP_Cmd2B_SetParam
	CP A, 022h
	JRL Z, DSP_Cmd2B_ReadParam5D
	CP A, 020h
	JRL Z, DSP_Cmd2B_MixSendConfig
	CP A, 3
	JR Z, DSP_Cmd2B_StateControl
	CP A, 0
	JR Z, DSP_Cmd2B_AlgoSelect
	EXTZ WA
	SUB WA, 0010h
	CP WA, 0
	JRL LT, DSP_Cmd2B_UnknownSkip
	CP WA, 7
	JRL GT, DSP_Cmd2B_UnknownSkip
	ADD WA, WA
	LDA XIX, 0121DBh
	LD WA, (XIX + WA)
	LDA XIX, 035BC6h
	JP T, XIX + WA

DSP_Cmd2B_AlgoSelect:
	LD WA, IZ
	CALL CheckStatusBits_40
	CP HL, 0
	JR Z, DSP_Cmd2B_AlgoSelect_Continue
	LD WA, IZ
	CALL Voice_Slot_CalcArticParams

DSP_Cmd2B_AlgoSelect_Continue:
	LD A, IZL
	LD E, A
	EXTZ DE
	LD A, (4370h)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD XDE, (XSP + 00ah)
	CALL DSP_AlgoSelect
	JRL T, DSP_Cmd2B_PostProcess

DSP_Cmd2B_StateControl:
	LD A, (XSP + 008h)
	AND A, 00fh
	EXTZ WA
	LD XBC, (XSP + 00ah)
	CALL DSP_EffectStateQuery
	JRL T, DSP_Cmd2B_PostProcess
	LD A, (XSP + 008h)
	AND A, 00fh
	EXTZ WA
	LD XDE, (XSP + 00ah)
	LD BC, 0
	CALL DSP_VoiceParamReadWrite
	JRL T, DSP_Cmd2B_PostProcess
	LD A, (XSP + 008h)
	AND A, 00fh
	EXTZ WA
	LD XDE, (XSP + 00ah)
	LD BC, 1
	CALL DSP_VoiceParamReadWrite
	JRL T, DSP_Cmd2B_PostProcess
	LD A, (XSP + 008h)
	AND A, 00fh
	EXTZ WA
	LD XDE, (XSP + 00ah)
	LD BC, 2
	CALL DSP_VoiceParamReadWrite
	JRL T, DSP_Cmd2B_PostProcess
	LD A, (XSP + 008h)
	AND A, 00fh
	EXTZ WA
	LD XDE, (XSP + 00ah)
	LD BC, 3
	CALL DSP_VoiceParamReadWrite
	JRL T, DSP_Cmd2B_PostProcess
	LD A, (XSP + 008h)
	AND A, 00fh
	EXTZ WA
	LD XDE, (XSP + 00ah)
	LD BC, 4
	CALL DSP_VoiceParamReadWrite
	JRL T, DSP_Cmd2B_PostProcess
	LD A, (XSP + 008h)
	AND A, 00fh
	EXTZ WA
	LD XDE, (XSP + 00ah)
	LD BC, 5
	CALL DSP_VoiceParamReadWrite
	JRL T, DSP_Cmd2B_PostProcess
	LD A, (XSP + 008h)
	AND A, 00fh
	EXTZ WA
	LD XDE, (XSP + 00ah)
	LD BC, 6
	CALL DSP_VoiceParamReadWrite
	JRL T, DSP_Cmd2B_PostProcess
	LD A, (XSP + 008h)
	AND A, 00fh
	EXTZ WA
	LD XDE, (XSP + 00ah)
	LD BC, 7
	CALL DSP_VoiceParamReadWrite
	JRL T, DSP_Cmd2B_PostProcess

DSP_Cmd2B_MixSendConfig:
	LD A, (4370h)
	LD E, A
	EXTZ DE
	LD A, (4371h)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD XDE, (XSP + 00ah)
	CALL DSP_MixSendConfig
	JRL T, DSP_Cmd2B_PostProcess

DSP_Cmd2B_ReadParam5D:
	LD A, (4370h)
	LD E, A
	EXTZ DE
	LD A, (4371h)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD XDE, (XSP + 00ah)
	CALL DSP_ReadVoiceParam5D
	JR T, DSP_Cmd2B_PostProcess

DSP_Cmd2B_SetParam:
	LD A, (4370h)
	LD E, A
	EXTZ DE
	LD A, (4371h)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD XDE, (XSP + 00ah)
	CALL DSP_SetVoiceCoefficients
	JR T, DSP_Cmd2B_PostProcess

DSP_Cmd2B_ReadParam11:
	LD A, (4370h)
	LD E, A
	EXTZ DE
	LD A, (4371h)
	LD C, A
	EXTZ BC
	LD WA, DE
	LD XDE, (XSP + 00ah)
	CALL DSP_ReadVoiceParam11
	JR T, DSP_Cmd2B_PostProcess

DSP_Cmd2B_Noop:
	LD HL, 0
	JR T, DSP_Cmd2B_PostProcess

DSP_Cmd2B_UnknownSkip:
	LD XWA, (XSP + 004h)
	CALR DSP_RingBuf_Skip
	LD HL, 0
	JR T, DSP_Cmd2B_PostProcess

DSP_Cmd2B_VoiceParamWrite:
	LD A, QIZH
	EXTZ WA
	LD IZ, WA
	AND IZ, 000fh
	LDA XWA, 4368h
	CALR Extract_14Bit_VoiceParam
	LD QIZ, HL
	LDA XWA, 4368h
	CALR Extract_14Bit_PayloadSize
	LDA XWA, 4370h
	PUSH XWA
	LD WA, IZ
	LD BC, QIZ
	LD DE, HL
	CALL DSP_WriteVoiceParam

DSP_Cmd2B_PostProcess:
	CP HL, 0
	JRL Z, DSP_Process_ReadNext
	INC 8, HL
	LDA XDE, 4368h
	LD BC, HL
	LD WA, 3
	CALL InterCPU_DMA_Send
	JRL T, DSP_Process_ReadNext

DSP_Cmd2B_SkipAndContinue:
	CP QIZH, 040h
	JR NZ, DSP_Cmd2B_SkipPath
	LD XWA, (XSP + 004h)
	CALR DSP_RingBuf_Skip
	JRL T, DSP_Process_ReadNext

DSP_Cmd2B_SkipPath:
	LD XWA, (XSP + 004h)
	CALR DSP_RingBuf_Skip
	JRL T, DSP_Process_ReadNext

DSP_CmdHandler_2C:
	LDA XWA, 4370h
	LD XBC, XWA
	LD XWA, (XSP + 004h)
	CALR DSP_RingBuf_ReadAndCompare
	LD A, (4369h)
	LD QIZH, A
	CP QIZH, 0
	JRL NZ, CmdHandler2C_SubCmd1
	CP (436Ah), 008h
	JRL NZ, DSP_Process_ReadNext
	LD A, (436Bh)
	EXTZ WA
	CP WA, 0
	JRL MI, CmdHandler2C_SubCmd0
	CP WA, 0008h
	JR LE, CmdHandler2C_JumpDispatch
	SUB WA, 0017h
	CP WA, 0009h
	JRL LT, CmdHandler2C_SubCmd0
	CP WA, 000eh
	JRL GT, CmdHandler2C_SubCmd0

CmdHandler2C_JumpDispatch:
	ADD WA, WA
	LDA XIX, 0121BDh
	LD WA, (XIX + WA)
	LDA XIX, 035DD2h
	JP T, XIX + WA
CmdHandler2C_TableData:
	db 0C1h, 070h, 043h, 021h, 0D8h, 013h, 01Dh, 023h
	db 08Bh, 002h, 078h, 054h, 002h, 0C1h, 070h, 043h
	db 021h, 0D8h, 012h, 01Dh, 005h, 062h, 003h, 078h
	db 047h, 002h, 0C1h, 070h, 043h, 021h, 0D8h, 012h
	db 01Dh, 01Ch, 062h, 003h, 078h, 03Ah, 002h, 0C1h
	db 070h, 043h, 021h, 0D8h, 012h, 01Dh, 02Eh, 08Dh
	db 002h, 078h, 02Dh, 002h, 0C1h, 070h, 043h, 021h
	db 0D8h, 013h, 01Dh, 030h, 08Bh, 002h, 078h, 020h
	db 002h, 0C1h, 070h, 043h, 021h, 0D8h, 012h, 01Dh
	db 037h, 062h, 003h, 078h, 013h, 002h, 0C1h, 070h
	db 043h, 021h, 0D8h, 012h, 01Dh, 052h, 062h, 003h
	db 078h, 006h, 002h, 0C1h, 070h, 043h, 021h, 0D8h
	db 012h, 01Dh, 07Ah, 062h, 003h, 078h, 0F9h, 001h
	db 0C1h, 070h, 043h, 021h, 0D8h, 012h, 01Dh, 0A2h
