	LD E, A
	EXTZ DE
	LD A, (4371h)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALL DSP_Reinit_VoiceSlots
	LD WA, 00ffh
	LD BC, 00ffh
	CALL DSP_VoiceState_Dispatch
	JRL T, DSP_Process_ReadNext

