DSP_CmdHandler_2D:
	LD A, (4369h)
	LD QIZH, A
	CP QIZH, 0
	JRL NZ, CmdHandler2D_PathD
	LD A, (436Ah)
	LD QIZH, A
	CP QIZH, 009h
	JR NZ, CmdHandler2D_PathA
	LD XWA, (XSP + 004h)
	CALR DSP_Cmd_LoadEffectPreset
	LD WA, HL
	EXTS XWA
	CP XWA, 0ffffffffh
	JRL Z, DSP_Process_ReadNext
	CALL DSP_ReconfigAndStatus
	JRL T, DSP_Process_ReadNext

CmdHandler2D_PathA:
	CP QIZH, 00ah
	JR C, CmdHandler2D_PathC
	CP QIZH, 00eh
	JR UGT, CmdHandler2D_PathC
	LD A, QIZH
	SUB A, 00ah
	EXTZ WA
	CALL EFF_GetSlotBuffer
	LD (XSP + 00ah), XHL
	LD XWA, (XSP + 00ah)
	CP XWA, 0ffffffffh
	JRL Z, DSP_Process_ReadNext
	LD A, (436Eh)
	LD C, A
	EXTZ BC
	LD XWA, (XSP + 004h)
	CP BC, (XWA + 004h)
	JR UGT, CmdHandler2D_PathB
	LD XWA, (XSP + 004h)
	LD XBC, (XSP + 00ah)
	CALR DSP_RingBuf_ReadAndCompare
	LD A, QIZH
	SUB A, 00ah
	LD IXL, A
	EXTZ IX
	LDA XWA, 4370h
	LD XBC, XWA
	LD E, L
	EXTZ DE
	LD WA, IX
	CALL DSP_ApplyConfig
	JR T, DSP_Process_ReadNext

