	JR C, CmdHandler2D_EnqueueOrReturn
	CP QIZH, 03fh
	JR UGT, CmdHandler2D_EnqueueOrReturn
	LD A, (4370h)
	LD XBC, 0
	LD C, A
	LD XWA, (XSP + 004h)
	CALR DSP_RingBuf_ReadAndCompare
	CP (436Ah), 07fh
	JR Z, CmdHandler2D_MsgSizeMatch
	LD A, QIZH
	SUB A, 030h
	LD IZL, A
	EXTZ IZ
	JR T, DSP_Process_ReadNext

CmdHandler2D_MsgSizeMatch:
