	LD XIY, 0000f01eh
	LD XIX, 0000448eh
	LD BC, 0091h
	LDIRW_95
	LDA XWA, 448Eh
	CALL DSP_State_LoadAndApplyAll
	LDW (4492h), 0000h
	CALL DSP_State_DmaLoadPresets
	LD IZ, (0F026h)
