DSP2_Send_Command:
	DEC 6, XSP
	PUSH XIZ
	LD (XSP + 006h), BC
	LD (XSP + 008h), A
	LDW (XSP + 004h), 0000h
	CALR DSP_WakeAudioTask
	EI 6
	LD A, (XSP + 008h)
	LD QIZH, A
	LD WA, (XSP + 006h)
	CALL DSP_Select_Chip
	CALR DSP2_SPI_ClockPulseHigh
	LD IZ, 0008h
	CP IZ, 0
	JRL LE, DSP2_SendCmd_PostLoop_Entry

DSP2_SendCmd_BitLoop:
	BIT 7, QIZH
	JR Z, DSP2_SendCmd_BitClear
	SET 0, (PF)
	JR T, DSP2_SendCmd_BitSet_Done

