	LD XIY, XWA
	LD XIX, 000045cah
	LD BC, 0091h
	LDIRW_95
	RET

DSP_AlgoChange_CheckAndFlag:
	LD BC, (XWA + 006h)
	CP BC, (45D0h)
	JR NZ, DSP_AlgoChange_NoChange
	CPW (XWA + 002h), 0001h
	JR Z, DSP_AlgoChange_NoChange
	CPW (XWA + 004h), 0001h
	JR NZ, DSP_AlgoChange_FlagAndClear

DSP_AlgoChange_NoChange:
	LDW (493Eh), 0001h
	RET

DSP_AlgoChange_FlagAndClear:
	LDW (493Eh), 0000h
	RET

DSP_SlotParam_DiffAndFlag:
	LD HL, 0
	CP HL, 5
	RET NC

DSP_SlotParam_DiffLoop:
	LD BC, HL
	MUL_BC 0038h
	LDA XDE, 45D2h
	LD IX, BC
	EXTZ XIX
	ADD XIX, XDE
	LD BC, HL
	EXTZ XBC
	LD XDE, XBC
	SLL 3, XDE
	SUB XDE, XBC
	SLL 3, XDE
	INC 8, XDE
	ADD XDE, XWA
	LD BC, (XDE)
	CP BC, (XIX)
	JR Z, DSP_SlotParam_DiffMatch
	LD BC, HL
	MUL_BC 0032h
	LDA XDE, 4940h
	EXTZ XBC
	ADD XBC, XDE
	LDW (XBC), 0001h
	JR T, DSP_SlotParam_DiffMismatch

DSP_SlotParam_DiffMatch:
	LD BC, HL
	MUL_BC 0032h
	LDA XDE, 4940h
	EXTZ XBC
	ADD XBC, XDE
	LDW (XBC), 0000h

DSP_SlotParam_DiffMismatch:
	INC 1, HL
	CP HL, 5
	JR C, DSP_SlotParam_DiffLoop
	RET

