	CP QIZ, 0ffffh
	JR LE, EFF_SecLinkPath_Pass2Epilogue

EFF_SecLinkPath_Pass2Body:
	LD WA, QIZ
	MUL_WA 032h
	ADD WA, 0010h
	LDA XBC, 495Eh
	EXTZ XWA
	ADD XWA, XBC
	CPW (XWA), 0001h
	JR NZ, EFF_SecLinkPath_Pass2Next
	LD WA, QIZ
	MULS_WA 038h
	LD BC, WA
	INC 8, BC
	LD XWA, (XSP + 004h)
	LDA XWA, XWA + BC
	CPW (XWA + 036h), 0000h
	JR NZ, EFF_SecLinkPath_Pass2Next
	CP QIZ, 3
	JR Z, EFF_SecLinkPath_Pass2MaxVol
	CP QIZ, 2
	JR Z, EFF_SecLinkPath_Pass2MaxVol
	LD WA, QIZ
	LD XBC, (XSP + 004h)
	LD BC, (XBC + 006h)
	CALL EFF_Disconnect

EFF_SecLinkPath_Pass2MaxVol:
	LD DE, IZ
	LDA XWA, 01ED72h
	LD A, (XWA + QIZ)
	LD C, A
	EXTZ BC
	LD WA, DE
	CALR Unsigned_Max_Select
	LD IZ, HL

EFF_SecLinkPath_Pass2Next:
	DEC 1, QIZ
	CP QIZ, 0ffffh
	JR GT, EFF_SecLinkPath_Pass2Body

EFF_SecLinkPath_Pass2Epilogue:
	CP IZ, 0
	JR Z, EFF_SecLinkPath_Epilogue
	LD WA, IZ
	CALL DSP_ScheduleDelay

EFF_SecLinkPath_Epilogue:
	POP XIZ
	INC 4, XSP
	RET

EFF_VolumeLoop:
	DEC 4, XSP
	PUSH IZ
	LD (XSP + 002h), XWA
	LD IZ, 0
	CP IZ, 5
	JRL NC, EFF_VolumeLoop_Epilogue

EFF_VolumeLoop_Body:
	LD WA, IZ
	EXTZ XWA
	LD XBC, XWA
	SLL 3, XBC
	SUB XBC, XWA
	SLL 3, XBC
	INC 8, XBC
	ADD XBC, (XSP + 002h)
	LD BC, (XBC + 026h)
	SLL 1, BC
	LD WA, IZ
	MUL_WA 032h
	ADD WA, BC
	LDA XBC, 4944h
	EXTZ XWA
	ADD XWA, XBC
	CPW (XWA), 0001h
	JRL NZ, EFF_VolumeLoop_Next
	LD WA, IZ
	EXTZ XWA
	LD XBC, XWA
	SLL 3, XBC
	SUB XBC, XWA
	SLL 3, XBC
	INC 8, XBC
	ADD XBC, (XSP + 002h)
	LD DE, (XBC + 026h)
	LD WA, IZ
	EXTZ XWA
	LD XBC, XWA
	SLL 3, XBC
	SUB XBC, XWA
	SLL 3, XBC
	INC 8, XBC
	ADD XBC, (XSP + 002h)
	CPW (XBC), 003fh
	JRL NZ, EFF_VolumeLoop_ApplyDelta
	LD WA, IZ
	EXTZ XWA
	LD XBC, XWA
	SLL 3, XBC
	SUB XBC, XWA
	SLL 3, XBC
	INC 8, XBC
	LD XIX, XBC
	ADD XIX, (XSP + 002h)
	LD WA, IZ
	EXTZ XWA
	LD XBC, XWA
	SLL 3, XBC
	SUB XBC, XWA
	SLL 3, XBC
	INC 8, XBC
	ADD XBC, (XSP + 002h)
	LDA XHL, 0122C4h
	LD WA, (XBC + 006h)
	LD A, (XHL + WA)
	EXTZ WA
	LD HL, (XIX + 004h)
	SUB HL, WA
	LD WA, IZ
	EXTZ XWA
	LD XBC, XWA
	SLL 3, XBC
	SUB XBC, XWA
	SLL 3, XBC
	INC 8, XBC
	ADD XBC, (XSP + 002h)
	LD (XBC + 004h), HL
	LD WA, IZ
	EXTZ XWA
	LD XBC, XWA
	SLL 3, XBC
	SUB XBC, XWA
	SLL 3, XBC
	INC 8, XBC
	ADD XBC, (XSP + 002h)
	CPW (XBC + 004h), 0000h
	JR GE, EFF_VolumeLoop_ApplyDelta
	LD WA, IZ
	EXTZ XWA
	LD XBC, XWA
	SLL 3, XBC
	SUB XBC, XWA
	SLL 3, XBC
	INC 8, XBC
	ADD XBC, (XSP + 002h)
	LDW (XBC + 004h), 0000h

EFF_VolumeLoop_ApplyDelta:
	LD WA, IZ
	EXTZ XWA
	LD XBC, XWA
	SLL 3, XBC
	SUB XBC, XWA
	SLL 3, XBC
	INC 8, XBC
	ADD XBC, (XSP + 002h)
	LD XWA, (XSP + 002h)
	PUSH XWA
	LD WA, IZ
	LD BC, (XBC)
	CALL EFF_VolumeUpdate_WithDebug

EFF_VolumeLoop_Next:
	INC 1, IZ
	CP IZ, 5
	JRL C, EFF_VolumeLoop_Body

EFF_VolumeLoop_Epilogue:
	POP IZ
	INC 4, XSP
	RET

EFF_DisconnectLoop:
	DEC 4, XSP
	PUSH IZ
	LD (XSP + 002h), XWA
	LD IZ, 4
	CP IZ, 0ffffh
	JR LE, EFF_DisconnectLoop_Epilogue

EFF_DisconnectLoop_Body:
	CP IZ, 3
	JR Z, EFF_DisconnectLoop_Next
	CP IZ, 2
	JR Z, EFF_DisconnectLoop_Next
	LD WA, IZ
	LD XBC, (XSP + 002h)
	LD BC, (XBC + 006h)
	CALL EFF_Disconnect

EFF_DisconnectLoop_Next:
	DEC 1, IZ
	CP IZ, 0ffffh
	JR GT, EFF_DisconnectLoop_Body

EFF_DisconnectLoop_Epilogue:
	POP IZ
	INC 4, XSP
	RET

DSP_State_Dispatcher:
	PUSH XIZ
	LD XIZ, XWA
	CPW (XIZ + 004h), 0001h
	JR NZ, DSP_StateDispatcher_MutePath
	CALR DSP_ResetLoop
	JR T, DSP_StateDispatcher_PostMute

DSP_StateDispatcher_MutePath:
	LD XWA, XIZ
	CALR EFF_MuteLoop

DSP_StateDispatcher_PostMute:
	CALR DSP_MuteLoop
	LD XWA, XIZ
	CALR DSP_AlgorithmChangeCheck
	CPW (XIZ + 004h), 0001h
	JR Z, DSP_StateDispatcher_DisconnectPath
	CPW (XIZ + 002h), 0001h
	JR NZ, DSP_StateDispatcher_UnmutePath

DSP_StateDispatcher_DisconnectPath:
	LD WA, 0
	CALL EFF_WriteHeader
	LD XWA, XIZ
	CALR EFF_DisconnectLoop

DSP_StateDispatcher_UnmutePath:
	CALR DSP_UnmuteLoop
	LD XWA, XIZ
	CALR EFF_HeaderChangeDataLoop
	LD XWA, XIZ
	CALR EFF_LinkLoop
	LD XWA, XIZ
	CALR EFF_VolumeLoop
	LD XWA, XIZ
	CALR EFF_SecondaryLinkPath
	LD DE, 4
	CP DE, 0ffffh
	JR LE, DSP_StateDispatcher_Epilogue

DSP_StateDispatcher_AlgoLoop:
	LD WA, DE
	MULS_WA 038h
	INC 8, WA
	LD IX, (XIZ + WA)
	LD WA, DE
	MUL_WA 032h
	LDA XBC, 4940h
	EXTZ XWA
	ADD XWA, XBC
	CPW (XWA), 0001h
	JR NZ, DSP_StateDispatcher_AlgoNext
	LD WA, IX
	EXTZ XWA
	LD XBC, 00012226h
	ADD XBC, XWA
	CP (XBC), 000h
	JR Z, DSP_StateDispatcher_AlgoClear
	LD WA, DE
	ADD WA, WA
	LDA XBC, 45BCh
	LD HL, WA
	EXTZ XHL
	ADD XHL, XBC
	LD WA, IX
	EXTZ XWA
	LD XBC, 00012226h
	ADD XBC, XWA
	LD A, (XBC)
	INC 1, A
	EXTZ WA
	LD (XHL), WA
	JR T, DSP_StateDispatcher_AlgoNext

DSP_StateDispatcher_AlgoClear:
	LD WA, DE
	ADD WA, WA
	LDA XBC, 45BCh
	EXTZ XWA
	ADD XWA, XBC
	LDW (XWA), 0000h

DSP_StateDispatcher_AlgoNext:
	DEC 1, DE
	CP DE, 0ffffh
	JR GT, DSP_StateDispatcher_AlgoLoop

DSP_StateDispatcher_Epilogue:
	POP XIZ
	RET

DSP_State_LookupAlgoIndex:
	EXTZ XWA
	LD XBC, 00012226h
	ADD XBC, XWA
	LD L, (XBC)
	EXTZ HL
	RET

DSP_State_Dispatcher_Data:
	db 045h, 0ECh, 046h, 000h, 000h, 044h, 00Eh, 048h
	db 000h, 000h, 031h, 091h, 000h, 095h, 011h, 0DBh
	db 0A8h, 00Eh, 045h, 00Eh, 048h, 000h, 000h, 044h
	db 0ECh, 046h, 000h, 000h, 031h, 091h, 000h, 095h
	db 011h, 0DBh, 0A8h, 00Eh

