	LD WA, (XSP + 006h)
	EXTZ WA
	LD BC, IZ
	CALL DSP_DispatchData
	LD XWA, (XSP + 002h)
	LD BC, IZ
	CALR DSP_WriteParamWord
	POP IZ
	INC 6, XSP
	RET

