DSP_WriteLUT_MainLoop_Init:
	LD XBC, (XSP + 00ah)
	LD XWA, 1
	ADD (XSP + 00ah), XWA
	LD A, (XBC)
	EXTZ WA
	LD (XSP + 00eh), WA
	LDW (XSP + 004h), 0000h
	LD WA, (XSP + 002h)
	SRL 2, WA
	CP (XSP + 004h), WA
	JRL NC, DSP_WriteLUT_MainLoop_Done

DSP_WriteLUT_MainLoop_Body:
	CPW (XSP + 004h), 0000h
	JR Z, DSP_WriteLUT_MainLoop_FirstEntry
	LD BC, (XSP + 01ah)
	LD WA, 1
	CALL DSP_DispatchCommand
	LD IZ, HL
	LD BC, (XSP + 01ah)
	LD WA, 1
	CALL DSP_DispatchData
	LD IZ, HL
	LD BC, (XSP + 01ah)
	LD WA, 0060h
