	LD WA, (XSP + 004h)
	SLL 2, WA
	LD IZ, WA
	ADD IZ, (XSP + 00eh)
	LDA XWA, XSP + 00ah
	CALR DSP_UnpackParam3B
	PUSHW (XSP + 018h)
	LD WA, IZ
