	LDA XWA, XSP + 00ah
	CALR DSP_UnpackParam3B
	LD XWA, XHL
	LD BC, (XSP + 01ah)
	LD DE, (XSP + 018h)
	CALR DSP_WriteCoeffData_5B
	LD IZ, HL
	LD BC, (XSP + 01ah)
	LD WA, 3
	CALL DSP_DispatchCommand
	INCW 1, (XSP + 004h)
	LD WA, (XSP + 002h)
	SRL 2, WA
	CP (XSP + 004h), WA
	JRL C, DSP_WriteLUT_MainLoop_Body

