DSP_Bytecode_Op0D_StateChange:
	CALL DSP2_SPI_BusIdle
	CALR DSP_Bytecode_NotifyStateChange
	JR T, DSP_BytecodeInterpreter_CheckEnd

DSP_Bytecode_Op0E_SendCommand:
	LD XWA, (XSP + 01ah)
	LD C, (XWA+)
	LD (XSP + 01ah), XWA
	LD A, C
	EXTZ WA
	LD BC, (XSP + 014h)
	CALL DSP_DispatchCommand
	LD QIZ, HL
	LDW (XSP + 004h), 0001h
	LD WA, (XSP + 006h)
	DEC 1, WA
	CP (XSP + 004h), WA
	JR UGT, DSP_BytecodeInterpreter_CheckEnd

DSP_Bytecode_Op0E_DataLoop:
	LD XWA, (XSP + 01ah)
	LD C, (XWA+)
	LD (XSP + 01ah), XWA
	LD A, C
	EXTZ WA
	LD BC, (XSP + 014h)
	CALL DSP_DispatchData
	LD QIZ, HL
	INCW 1, (XSP + 004h)
	LD WA, (XSP + 006h)
	DEC 1, WA
	CP (XSP + 004h), WA
	JR ULE, DSP_Bytecode_Op0E_DataLoop

DSP_BytecodeInterpreter_CheckEnd:
	LD XWA, (XSP + 01ah)
	LD A, (XWA)
	AND A, 0f0h
	CP A, 0f0h
	JRL NZ, DSP_BytecodeInterpreter_Loop
	LD HL, QIZ
	POP XIZ
	LDA XSP, XSP + 012h
	RETD 0004h

DSP_ParameterWriteEngine:
	LDA XSP, XSP - 012h
	PUSH XIZ
	LD (XSP + 00ch), XDE
	LD (XSP + 010h), XBC
	LD (XSP + 014h), WA
	LD XIZ, (XSP + 020h)
	LD WA, (XSP + 014h)
	EXTZ XWA
	LD XBC, 0001ed6dh
	ADD XBC, XWA
	LD A, (XBC)
	EXTZ WA
	LD (XSP + 004h), WA
	LDW (XSP + 00ah), 0000h
	LDA XWA, XSP + 00ah
	LD XDE, XWA
	LDA XWA, XSP + 006h
	PUSH XWA
	LD XWA, XIZ
	LD BC, (XSP + 022h)
	CALR DSP_TableWalk_SearchWithState
	LD XIZ, XHL
	CPW (XSP + 00ah), 0000h
	JR Z, DSP_ParamLoop_CheckBound
	LD WA, (XSP + 00ah)
	CALR DSP_NopReturn
	JR T, DSP_ParamLoop_Return

DSP_ParamLoop_CheckBound:
	CP XIZ, (XSP + 006h)
	JR NC, DSP_ParamLoop_Return

DSP_ParamLoop_Iterate:
	CPW (XSP + 004h), 0000h
	JR NZ, DSP_ParamLoop_CallTranslator
	LD BC, (XSP + 004h)
	LD WA, 1
	CALL DSP_DispatchCommand
	LD (XSP + 00ah), HL
	LD BC, (XSP + 004h)
	LD WA, 1
	CALL DSP_DispatchData
	LD (XSP + 00ah), HL
	LD BC, (XSP + 004h)
	LD WA, 0060h
	CALL DSP_DispatchData
	LD (XSP + 00ah), HL

DSP_ParamLoop_CallTranslator:
	PUSH XIZ
	LD XWA, (XSP + 010h)
	PUSH XWA
	LD XWA, (XSP + 022h)
	PUSH XWA
	LD XWA, (XSP + 01ch)
	PUSH XWA
	LDA XWA, XSP + 01ah
	PUSH XWA
	LD WA, (XSP + 018h)
	LD BC, (XSP + 028h)
	LD DE, (XSP + 032h)
	CALR DSP_PerParameterTranslator
	LD XIZ, XHL
	CPW (XSP + 00ah), 0000h
	JR Z, DSP_ParamLoop_PostCall
	LD WA, (XSP + 00ah)
	CALR DSP_NopReturn
	JR T, DSP_ParamLoop_Return

DSP_ParamLoop_PostCall:
	CPW (XSP + 004h), 0000h
	JR NZ, DSP_ParamLoop_SendEndCmd
	LD BC, (XSP + 004h)
	LD WA, 3
	CALL DSP_DispatchCommand
	LD (XSP + 00ah), HL

DSP_ParamLoop_SendEndCmd:
	CP XIZ, (XSP + 006h)
	JR C, DSP_ParamLoop_Iterate

DSP_ParamLoop_Return:
	POP XIZ
	LDA XSP, XSP + 012h
	RETD 000ah

DSP_PerParameterTranslator:
	LDA XSP, XSP - 012h
	PUSH XIZ
	LD (XSP + 010h), DE
	LD (XSP + 012h), BC
	LD (XSP + 014h), WA
	LD XDE, (XSP + 01eh)
	LD WA, (XSP + 012h)
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	SLL 2, XBC
	ADD XBC, XDE
	LD WA, (XBC)
	LD (XSP + 004h), WA
	LD WA, (XSP + 012h)
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	SLL 2, XBC
	ADD XBC, XDE
	LD WA, (XBC + 002h)
	LD (XSP + 006h), WA
	LD WA, (XSP + 012h)
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	SLL 2, XBC
	ADD XBC, XDE
	LD WA, (XBC + 004h)
	LD (XSP + 008h), WA
	LD WA, (XSP + 012h)
	EXTZ XWA
	LD XBC, XWA
	ADD XBC, XBC
	ADD XBC, XWA
	SLL 2, XBC
	ADD XBC, XDE
	LD XWA, (XBC + 008h)
	LD (XSP + 00ah), XWA
	JRL T, DSP_Translator_CheckEnd

DSP_Translator_ReadOpcode:
	LD XBC, (XSP + 02ah)
	LD XWA, 1
	ADD (XSP + 02ah), XWA
	LD A, (XBC)
	LD E, A
	EXTZ DE
	LDA XWA, XSP + 00eh
	PUSH XWA
	LD XWA, (XSP + 02ah)
	LD BC, QIZ
	CALR DSP_TableWalk_Search
	CPW (XSP + 00eh), 0000h
	JRL NZ, DSP_Translator_Return
	LD A, (XHL)
	LD IZL, A
	EXTZ IZ
	LD WA, (XSP + 010h)
	EXTZ XWA
	ADD XWA, XWA
	ADD XWA, (XSP + 022h)
	LD DE, (XWA)
	EXTS XDE
	LD WA, QIZ
	CP WA, 0021h
	JRL Z, DSP_Op_0x21_Interp2Point
	CP WA, 0024h
	JRL Z, DSP_Op_0x24_MultiStepInterp
	CP WA, 0040h
	JRL Z, DSP_Op_0x40_PanScale
	SUB WA, 0061h
	CP WA, 0
	JRL C, DSP_Op_Unknown_Error
	CP WA, 0018h
	JRL UGT, DSP_Op_Unknown_Error
	ADD WA, WA
	LDA XIX, OFFSETS_14745
	LD WA, (XIX + WA)
	LDA XIX, 03CB8Eh
	JP T, XIX + WA
DSP_Translator_JumpTable:
	db 0BFh, 02Ah, 030h, 0EAh, 089h, 01Dh, 09Fh, 08Eh
	db 003h, 09Fh, 004h, 004h, 0DEh, 088h, 0EBh, 089h
	db 09Fh, 016h, 022h, 01Dh, 0E6h, 087h, 003h, 0BFh
	db 00Eh, 053h

DSP_Translator_PostDispatch:
	CPW (XSP + 014h), 0001h
	JR NZ, DSP_Translator_CheckEnd
	CALL DSP2_SPI_BusIdle
	CALR DSP_Bytecode_NotifyStateChange

DSP_Translator_CheckEnd:
	LD XBC, (XSP + 02ah)
	LD XWA, 1
	ADD (XSP + 02ah), XWA
	LD A, (XBC)
	EXTZ WA
	LD QIZ, WA
	CP WA, 007ah
	JRL NZ, DSP_Translator_ReadOpcode

DSP_Translator_Return:
	LD XBC, (XSP + 01ah)
	LD WA, (XSP + 00eh)
	LD (XBC), WA
	LD XHL, (XSP + 02ah)
	POP XIZ
	LDA XSP, XSP + 012h
	RETD 0014h
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_ParamFetch_SingleTable
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JR T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_ParamFetch_AlgoTypeTable
	PUSHW (XSP + 006h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteFreqParam_AlgoType
	LD (XSP + 00eh), HL
	JR T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_AlgoParam_Decode
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_PitchParam_Scale
	PUSHW (XSP + 006h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteFreqParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_VolumeParam_Scale
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_ParamInterp_2Point
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_ParamInterp_FPScale
	PUSHW (XSP + 008h)
	LD XWA, (XSP + 00ch)
	PUSH XWA
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 01ah)
	CALL DSP_WriteOscParam_Offset
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_ParamInterp_Div0xB4
	PUSHW (XSP + 006h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteFreqParam
