	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_VolumeCurve_FP
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_FreqCurve_FP
	PUSHW (XSP + 006h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteFreqParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_FreqInterp_2Point
	PUSHW (XSP + 006h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteFreqParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	LD XDE, (XSP + 00ah)
	CALL DSP_ParamInterp_3Point_WithOffset
	PUSHW (XSP + 006h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteFreqParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_ReverbCurve_FP
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_ParamInterp_FPComplex
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_PanCurve_PiecewiseLin
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LD XWA, (XSP + 02ah)
	PUSH XWA
	PUSH IZ
	LD XWA, (XSP + 028h)
	PUSH XWA
	PUSHW (XSP + 00eh)
	LDA XWA, XSP + 01ah
	PUSH XWA
	LD WA, (XSP + 024h)
	LD BC, (XSP + 022h)
	LD DE, (XSP + 020h)
	CALL DSP_BiquadCoeff_Compute
	LD (XSP + 02ah), XHL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_DetuneCurve_SignedFP
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	PUSHW (XSP + 010h)
	PUSH IZ
	PUSHW (XSP + 018h)
	PUSHW (XSP + 00ah)
	LDA XWA, XSP + 032h
	LD XBC, (XSP + 02ah)
	LD DE, (XSP + 01ah)
	CALL DSP_BiquadWarp_FP
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_ParamInterp_Div0xC6
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
