DSP_Op_0x40_PanScale:
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_PanScale_Simple
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch

DSP_Op_0x24_MultiStepInterp:
	PUSHW (XSP + 012h)
	PUSHW (XSP + 012h)
	LDA XWA, XSP + 02eh
	LD XBC, XDE
	LD XDE, (XSP + 026h)
	CALL DSP_ParamInterp_MultiStep
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch

DSP_Op_0x21_Interp2Point:
	LDA XWA, XSP + 02ah
	LD XBC, XDE
	CALL DSP_ParamInterp_2Point
	PUSHW (XSP + 004h)
	LD WA, IZ
	LD XBC, XHL
	LD DE, (XSP + 016h)
	CALL DSP_WriteOscParam
	LD (XSP + 00eh), HL
	JRL T, DSP_Translator_PostDispatch

DSP_Op_Unknown_Error:
	LDW (XSP + 00eh), 0005h
	JRL T, DSP_Translator_Return

DSP_StreamDecode_3ByteWord:
	LD XDE, XWA
	LD_XWA_XDE_plus
	LD A, (XWA)
	EXTS WA
	EXTS XWA
	SLA 8, XWA
	SLA_0_XWA
	AND XWA, 0ff000000h
	LD XHL, XWA
	LD_XWA_XDE_plus
	LD A, (XWA)
	EXTS WA
	EXTS XWA
	LD XIX, XWA
	SLA_0_XIX
	AND XIX, 00ff0000h
	LD_XWA_XDE_plus
	LD A, (XWA)
	EXTS WA
	EXTS XWA
	LD XIY, XWA
	SLA 8, XIY
	AND XIY, 0000ff00h
	LD XWA, XHL
	ADD XWA, XIX
	ADD XWA, XIY
	LD (XBC), XWA
	LD XHL, XDE
	RET

DSP_TableWalk_Search:
	LD XHL, XWA
	JR T, DSP_TableWalk_ReadHeader

DSP_TableWalk_CheckEntry:
	LD IX, IY
	EXTZ XIX
	ADD XIX, XHL
	INC 2, XHL
	LD A, (XHL)
	EXTZ WA
	CP WA, BC
	JR NZ, DSP_TableWalk_SkipEntry
	LD WA, DE
	EXTZ XWA
	INC 1, XWA
	ADD XHL, XWA
	CP XHL, XIX
	JR C, DSP_TableWalk_FoundInRange
	LD BC, 4
	JR T, DSP_TableWalk_Return

DSP_TableWalk_FoundInRange:
	LD BC, 0
	JR T, DSP_TableWalk_Return

DSP_TableWalk_SkipEntry:
	LD XHL, XIX

DSP_TableWalk_ReadHeader:
	LD A, (XHL + 001h)
	LD IXL, A
	EXTZ IX
	LD A, (XHL)
	EXTZ WA
	LD IY, WA
	SLL 8, IY
	ADD IY, IX
	LD WA, IY
	SRL 8, WA
	CP WA, 00f0h
	JR NZ, DSP_TableWalk_CheckEntry
	LD BC, 3

DSP_TableWalk_Return:
	LD XWA, (XSP + 004h)
	LD (XWA), BC
	RETD 0004h

DSP_TableWalk_SearchWithState:
	LD XHL, XDE
	JR T, DSP_TableWalk_State_ReadHeader

DSP_TableWalk_State_CheckEntry:
	CP BC, 0
	JR NZ, DSP_TableWalk_State_Advance
	LD IX, 0
	LD XDE, (XSP + 004h)
	LD BC, IY
	EXTZ XBC
	ADD XBC, XWA
	LD (XDE), XBC
	INC 2, XWA
	JR T, DSP_TableWalk_State_Return

DSP_TableWalk_State_Advance:
	LD DE, IY
	EXTZ XDE
	ADD XWA, XDE
	DEC 1, BC

DSP_TableWalk_State_ReadHeader:
	LD E, (XWA + 001h)
	LD IXL, E
	EXTZ IX
	LD E, (XWA)
	EXTZ DE
	LD IY, DE
	SLL 8, IY
	ADD IY, IX
	LD DE, IY
	SRL 8, DE
	CP DE, 00f0h
	JR NZ, DSP_TableWalk_State_CheckEntry
	LD IX, 2

DSP_TableWalk_State_Return:
	LD (XHL), IX
	LD XHL, XWA
	RETD 0004h

DSP_NopReturn:
	RET


Audio_CmdHandler_A0_BF:
	LD XBC, (XSP + 006h)
	LD A, (XBC)
	CP A, 1
	JR Z, CmdA0BF_CheckSubByte
	CP A, 0
	JR NZ, CmdA0BF_Return
	CP (XBC + 001h), 001h
	JR NZ, CmdA0BF_Return
	LD (4A4Ah), 001h
	JR T, CmdA0BF_Return

CmdA0BF_CheckSubByte:
	CP (XBC + 001h), 009h
	JR UGT, CmdA0BF_Return
	db 089h, 001h, 019h, 048h, 04ah ; LD (4A48h), (XBC + 001h)

CmdA0BF_Return:
	LD HL, 0
	RET

; ----------------------------------------------------------------------------
; ToneGen_Init - Initialize tone generator subsystem
; Entry: None
; Exit:  Via JRL to ToneGen_Process
; Notes: Sets up tone generator state at 0x4A48 (mode = 6)
;        Tone generator is memory-mapped at 0x00110000
;        State buffer at 0x4A42-0x4A5C
; ----------------------------------------------------------------------------
ToneGen_Init:			; 03D016h
	LD (4A48h), 006h	; Set tone gen mode to 6
	JRL T, ToneGen_Poll_Init	; Continue to main processing

; ----------------------------------------------------------------------------
; ToneGen_Process_Notes - Process incoming note events from tone generator
; Entry: Called from main tone gen handler
; Exit:  Note events dispatched to appropriate voice slots
; Notes: Reads notes via Keybed_Read_Event, manages voice allocation
;        at 0x4A4C-0x4A5C (16 voice slots), sends to DMA at 0x4A42
; ----------------------------------------------------------------------------
ToneGen_Process_Notes:		; 03D01Eh
	DEC 2, XSP		; Allocate 2 bytes for result
	LD WA, 0
	LDA XWA, XSP
	CALR Keybed_Read_Event
	CP HL, 0ffffh
	JRL Z, ToneGen_Note_Done

ToneGen_Note_Loop:		; 03D02Eh
	CP (XSP + 001h), 000h	; Check velocity
	JR Z, ToneGen_Note_Off_Slot
	LD A, (XSP + 000h:8)	; Get note number
	EXTZ WA
	LDA XBC, 4A4Ch		; Voice slot table
	EXTZ XWA
	ADD XWA, XBC
	LD (XWA), 0ffh		; Mark slot as note-on
	LD (4A42h), 090h	; DMA command: note on
	LD A, (XSP + 000h:8)
	LD (4A43h), A		; Store note number
	LD A, (XSP + 001h)
	LD (4A44h), A		; Store velocity
	CP (4A4Ah), 001h	; Check if DMA enabled
	JR NZ, ToneGen_Note_Continue
	LD XDE, 00004a42h
	LD WA, 2
	LD BC, 3
	CALL InterCPU_DMA_Send	; Send via DMA
	JR T, ToneGen_Note_Continue

ToneGen_Note_Off_Slot:		; 03D06Dh
	LD A, (XSP + 000h:8)
	EXTZ WA
	LDA XBC, 4A4Ch
	EXTZ XWA
	ADD XWA, XBC
	CP (XWA), 0ffh		; Check if slot was active
	JR NZ, ToneGen_Note_Continue
	LD A, (XSP + 000h:8)
	EXTZ WA
	LDA XBC, 4A4Ch
	EXTZ XWA
	ADD XWA, XBC
	LD (XWA), 000h		; Clear slot
	LD (4A42h), 090h	; DMA command: note off
	LD A, (XSP + 000h:8)
	LD (4A43h), A
	LD A, (XSP + 001h)
	LD (4A44h), A
	CP (4A4Ah), 001h
	JR NZ, ToneGen_Note_Continue
	LD XDE, 00004a42h
	LD WA, 2
	LD BC, 3
	CALL InterCPU_DMA_Send

ToneGen_Note_Continue:		; 03D0B6h
	LDA XWA, XSP
	CALR Keybed_Read_Event
	CP HL, 0ffffh
	JRL NZ, ToneGen_Note_Loop

ToneGen_Note_Done:		; 03D0C2h
	INC 2, XSP
	RET

; ----------------------------------------------------------------------------
; Keybed_Read_Event - Read one key event from the KEYBED port
; Entry: XWA = pointer to 2-byte result buffer
; Exit:  HL = 0 (success) or 0xFFFF (FIFO empty)
; Notes: 0x110000 / 0x110002 are the keybed data and status ports, NOT tone-
;        generator voice state -- the routine was called ToneGen_Read_Voice_Data.
;        P6.7 selects between the two halves of the A23 multiplex.
;        Extracts note (low byte) and velocity (high byte)
; ----------------------------------------------------------------------------
Keybed_Read_Event:	; 03D0C5h
	PUSH XIZ
	LD XIZ, XWA
	SET 7, (P6)		; Assert A23 for status read
	NOP
	LD BC, (110002h)	; Read status register
	BIT 0, BC		; Check data ready bit
	JR Z, Keybed_Read_Event_NotReady
	RES 7, (P6)		; Deassert A23 for data read
	NOP
	LD WA, (110000h)	; Read voice data (16-bit)
	LD L, A			; L = note byte (low)
	AND L, 0ffh
	SRL 8, WA
	LD E, A			; E = velocity byte (high)
	AND E, 0ffh
	CP E, 0ffh		; Check for note-off
	JR Z, Keybed_Read_Event_NoteOff
	BIT 1, BC		; Check status bit 1
	JR Z, Keybed_Read_Event_NoteOn

Keybed_Read_Event_NoteOff:		; 03D0F6h
	BIT 7, L		; Check note high bit (release flag)
	JR Z, Keybed_Read_Event_Release
	LD HL, 0ffffh		; Return not ready
	JR T, Keybed_Read_Event_Done

Keybed_Read_Event_Release:		; 03D100h
	LD C, L
	LD XWA, XIZ
	CALR Keybed_Decode_Event
	LD (XIZ + 001h), 000h	; Clear velocity for note-off
	LD HL, 0
	JR T, Keybed_Read_Event_Done

Keybed_Read_Event_NoteOn:		; 03D10Fh
	LD C, L
	LD XWA, XIZ
	CALR Keybed_Decode_Event
	LD HL, 0
	JR T, Keybed_Read_Event_Done

Keybed_Read_Event_NotReady:		; 03D11Ah
	LD HL, 0ffffh

Keybed_Read_Event_Done:		; 03D11Dh
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; Keybed_Decode_Event - Calculate pitch value for voice
; Entry: C = note number, XWA = result pointer
; Exit:  Pitch value stored at (XWA), velocity at (XWA+1)
; Notes: Uses lookup tables at 0x01F43E (note map), 0x01F420 (mode params)
;        Mode stored at 0x4A48, calculation uses MULS/DIVS
; ----------------------------------------------------------------------------
; ----------------------------------------------------------------------------
; Keybed_Decode_Event - decode one key-bed FIFO event into (MIDI note, velocity)
; Entry: C = raw key byte (bit 7 = BREAK/release flag), E = key-travel TIME byte,
;        XWA = 2-byte output buffer
; Exit:  (XWA+0) = MIDI note = (C & 0x7F) + 0x24 ; (XWA+1) = velocity 1..127,
;        or 0 when C bit 7 is set (release)
; Notes: RENAMED from Keybed_Decode_Event, which was WRONG: this routine computes no
;        pitch at all.  It converts the key bed s TRAVEL TIME into a MIDI velocity:
;          x   = Keybed_Time_To_Strength[E]           (256 bytes, monotone DECREASING)
;          m   = Keybed_Touch_Mode                    (0..9, power-on default 6)
;          G   = Keybed_Touch_Curve_Table[m].gain     ; byte +0 of the 3-byte record
;          O   = Keybed_Touch_Curve_Table[m].offset   ; byte +1
;          y   = (x - Keybed_Touch_TimeRef) * G / Keybed_Touch_Divisor + O
;          if (note mod 12) is 1,3,6,8 or 10 (a BLACK KEY):
;                 y -= Keybed_Touch_Curve_Table[m].black   ; byte +2
;          y   = clamp(y, 0, 0xFF)
;          vel = Keybed_Strength_To_Velocity[y]       (256 bytes, monotone INCREASING)
;        Because the first table DECREASES, the FIFO byte is a make-to-break interval:
;        a short travel time is a hard strike.  MEASURED (tables dumped from ROM).
;        NEW this pass: the third byte of each touch record is a BLACK-KEY velocity
;        trim (0,3,6,8,11,14,16,19,22,24 for modes 0..9).  It is absent from
;        notes/kn5000-variant-model.md 3.3, which documents only gain and offset.
; ----------------------------------------------------------------------------
Keybed_Decode_Event:		; 03D11Fh
	LD L, C
	RES 7, L		; Clear release flag
	ADD L, 024h		; Add pitch offset (36)
	LD (XWA), L		; Store base pitch
	BIT 7, C		; Check if release (note-off)
	JRL Z, Keybed_Decode_NoteOff
	LD C, E
	EXTZ BC
	LDA XDE, 01F43Eh
	LD C, (XDE + BC)
	EXTZ BC
	EXTZ XBC
	LD XDE, XBC
	LD BC, (01F418h)
	LD HL, DE
	SUB HL, BC
	LD C, (4A48h)
	EXTZ BC
	MULS_BC 0003h
	LDA XDE, 01F420h
	LD C, (XDE + BC)
	EXTZ BC
	MULS XBC, HL
	LD DE, (01F41Ah)
	EXTS XBC
	DIVS XBC, DE
	LD HL, BC
	LD C, (4A48h)
	EXTZ BC
	MULS_BC 0003h
	LDA XDE, 01F421h
	LD C, (XDE + BC)
	EXTZ BC
	ADD BC, HL
	LD DE, BC
	EXTS XDE
	LD C, (XWA)
	EXTZ BC
	DIV_C 00ch
	LD C, B
	CP C, 00ah
	JR Z, Keybed_Vel_BlackKey_Trim
	CP C, 008h
	JR Z, Keybed_Vel_BlackKey_Trim
	CP C, 6
	JR Z, Keybed_Vel_BlackKey_Trim
	CP C, 3
	JR Z, Keybed_Vel_BlackKey_Trim
	CP C, 1
	JR NZ, Keybed_Vel_Clamp

Keybed_Vel_BlackKey_Trim:		; 03D1AAh - apply mode-specific pitch offset
	LD C, (4A48h)		; Get tone gen mode
	EXTZ BC
	MULS_BC 0003h		; mode * 3 for table index
	LDA XHL, 01F422h	; Pitch offset table
	LD C, (XHL + BC)
	EXTZ BC
	EXTZ XBC
	SUB XDE, XBC		; Apply offset

Keybed_Vel_Clamp:		; 03D1C4h - clamp pitch to 0-255 range
	LD XBC, 000000ffh
	CP XDE, 000000ffh
	JR GT, Keybed_Vel_ClampHi
	LD XBC, XDE

Keybed_Vel_ClampHi:		; 03D1D3h
	LD XDE, XBC
	LD XBC, 0
	CP XDE, 00000000h
	JR LT, Keybed_Vel_ClampLo
	LD XBC, XDE

Keybed_Vel_ClampLo:		; 03D1E1h
	LD XDE, XBC
	LD C, E
	EXTZ BC
	LDA XDE, 01F53Eh	; Velocity lookup table
	LD C, (XDE + BC)
	LD (XWA + 001h), C	; Store velocity
	RET

Keybed_Decode_NoteOff:		; 03D1F5h - note-off, no velocity
	LD (XWA + 001h), 000h
	RET

ToneGen_Poll_Padding:		; 03D1FAh
	db 00Eh

; ----------------------------------------------------------------------------
; ToneGen_Poll_Init - Initialize and poll all tone generator voices
; Entry: Called from ToneGen_Init
; Exit:  Voice status updated in buffer at (0x01F41C)
; Notes: Clears 8 voice buffers, then polls 16 iterations
; ----------------------------------------------------------------------------
ToneGen_Poll_Init:		; 03D1FBh
	LD HL, 0
	CP HL, 0008h
	JR NC, ToneGen_Poll_All

ToneGen_Clear_Voice_Loop:	; 03D203h
	LD WA, HL
	EXTZ XWA
	ADD XWA, (01F41Ch)	; Voice status buffer base
	LD (XWA), 000h		; Clear voice status
	INC 1, HL
	CP HL, 0008h
	JR C, ToneGen_Clear_Voice_Loop

; ----------------------------------------------------------------------------
; ToneGen_Poll_All - Poll tone generator for all 16 channels
; Entry: None
; Exit:  Voice status bits updated
; Notes: Reads from 0x110000/0x110002, uses P6.7 for control
; ----------------------------------------------------------------------------
ToneGen_Poll_All:		; 03D217h
	LD HL, 0
	CP HL, 0010h		; 16 iterations (one per MIDI channel)
	RET NC

ToneGen_Poll_Channel:		; 03D21Fh
	LD WA, 0
	CP WA, 2710h		; 10000 delay cycles
	JR NC, ToneGen_Poll_Read

ToneGen_Poll_Delay:		; 03D227h
	NOP
	INC 1, WA
	CP WA, 2710h
	JR C, ToneGen_Poll_Delay

ToneGen_Poll_Read:		; 03D230h
	SET 7, (P6)	; A23 pin tied to D5VNAD (both pins "NAD" and "EXADL0" of of tone generator)
	NOP
	LD WA, (110002h)
	RES 7, (P6)
	NOP
	LD WA, (110000h)
	LD C, A
	AND C, 0ffh
	SRL 8, WA
	AND A, 0ffh
	LD A, C
	SRL 3, A		; Extract voice index (bits 3-5)
	AND A, 007h
	LD E, A
	LD A, C
	AND A, 007h		; Extract bit position (bits 0-2)
	LD W, A
	BIT 7, C		; Check note-on flag
	JR Z, ToneGen_Poll_NoteOff
	LD A, E			; Note ON - set voice bit
	LD IXL, A
	EXTZ IX
	LD XBC, (01F41Ch)	; Voice status buffer
	LD DE, 1
	LD A, W
	AND A, 00fh
	JR Z, ToneGen_Poll_SetBit
	SLA A, DE		; Create bit mask

ToneGen_Poll_SetBit:		; 03D27Ah
	OR (XBC + IX), E	; Set voice active bit
	JR T, ToneGen_Poll_Next

ToneGen_Poll_NoteOff:		; 03D281h - Note OFF - clear voice bit
	LD A, E
	LD IXL, A
	EXTZ IX
	LD XBC, (01F41Ch)
	LD DE, 1
	LD A, W
	AND A, 00fh
	JR Z, ToneGen_Poll_ClearBit
	SLA A, DE

ToneGen_Poll_ClearBit:		; 03D298h
	LD WA, DE
	CPL WA			; Invert mask
	AND (XBC + IX), A	; Clear voice bit

ToneGen_Poll_Next:		; 03D2A1h
	INC 1, HL
	CP HL, 0010h
	JRL C, ToneGen_Poll_Channel
	RET

ToneGen_Voice_Padding:		; 03D2ABh
	db 0FFh

; ----------------------------------------------------------------------------
; ToneGen_Compare_Voice - Compare two voice parameter blocks
; Entry: XWA = voice 1 pointer, XBC = voice 2 pointer, DE = comparison type
; Exit:  HL = comparison result (0 = different, 1 = same, or lookup value)
; Notes: Compares 8-byte voice blocks at XWA and XBC
;        Uses lookup table at 0x03D978 for result mapping
; ----------------------------------------------------------------------------
ToneGen_Compare_Voice:		; 03D2ACh
	LD XIX, (XWA + 004h)	; Compare high 4 bytes
	CP XIX, (XBC + 004h)
	JR NZ, ToneGen_Compare_Diff
	LD XIY, (XWA)		; Compare low 4 bytes
	CP XIY, (XBC)
	JR NZ, ToneGen_Compare_Result
	LDA XIX, 03D978h	; Exact match - lookup result
	LD L, (XIX + DE)
	LD_H 000h
	RET

ToneGen_Compare_Diff:		; 03D2C7h
	LD XIY, (XWA)

ToneGen_Compare_Result:		; 03D2C9h
	LD HL, 0
	CP DE, 4
	RET Z
	LD HL, 1
	CP DE, 5
	RET Z
	LD XWA, (XBC + 004h)
	LD HL, 0
	LDCF 0fh, QIX
	JR NC, ToneGen_Compare_Sign
	XORCF 0fh, QWA
	SCC NC, HL

ToneGen_Compare_Sign:		; 03D2E6h
	CP XIX, XWA
	JR GT, ToneGen_Cmp_Greater
	JR LT, ToneGen_Cmp_Less
	CP XIY, (XBC)
	JR UGT, ToneGen_Cmp_Greater

ToneGen_Cmp_Less:		; 03D2F0h - voice 1 < voice 2
	LDA XIX, 03D97Eh	; Less-than lookup table
	XOR L, (XIX + DE)
	RET

ToneGen_Cmp_Greater:		; 03D2FBh - voice 1 > voice 2
	LDA XIX, 03D984h	; Greater-than lookup table
	XOR L, (XIX + DE)
	RET

; ----------------------------------------------------------------------------
; ToneGen_Compare_Voice_32 - Compare two 32-bit voice parameters
; Entry: XWA = voice 1 pointer, XBC = voice 2 pointer, DE = comparison type
; Exit:  HL = comparison result
; Notes: Simplified version comparing only first 4 bytes
; ----------------------------------------------------------------------------
ToneGen_Compare_Voice_32:	; 03D306h
	LD HL, 0
	LD XWA, (XWA)		; Load 32-bit value from voice 1
	LD XBC, (XBC)		; Load 32-bit value from voice 2
	CP XWA, XBC
	JR NZ, ToneGen_Cmp32_NotEqual
	LDA XIX, 03D978h	; Equal - lookup result
	LD L, (XIX + DE)
	RET

ToneGen_Cmp32_NotEqual:		; 03D31Bh
	CP DE, 4
	RET Z
	LD HL, 1
	CP DE, 5
	RET Z
	LD HL, 0
	LDCF 0fh, QWA		; Load carry from sign bit
	JR NC, ToneGen_Cmp32_Sign
	XORCF 0fh, QBC
	SCC NC, HL

ToneGen_Cmp32_Sign:		; 03D333h
	CP XWA, XBC
	JR GT, ToneGen_Cmp32_Greater
	LDA XIX, 03D97Eh
	XOR L, (XIX + DE)
	RET

ToneGen_Cmp32_Greater:		; 03D342h
	LDA XIX, 03D984h
	XOR L, (XIX + DE)
	RET

VoiceFloat_DispatchMulAdd:
	LDA XSP, XSP - 030h
	PUSHW 0000h
	LDA XIY, XSP + 03ah
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 022h
	PUSH XWA
	CALL FP_DP_CmpAndCopy
	LDA XSP, XSP + 00ch
	LDA XBC, 0F3CAh:24
	LDA XDE, XSP + 01ah
	LDA XWA, XSP + 022h
	CALL FP_DP_Mul
	LDA XIY, XSP + 022h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XIY, XSP + 042h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 03ah
	PUSH XWA
	CALL VoiceFloat_BlendAndMerge
	LDA XSP, XSP + 016h
	LD XWA, (XSP + 034h)
	LDA XBC, XSP + 028h
	CALL FP_DP_Raw8Copy
	LDA XSP, XSP + 030h
	RET

VoiceFloat_SubDP:
	PUSH XIZ
	LDA XSP, XSP - 01ch
	LD XIZ, XDE
	LD (XSP + 018h), XWA
	LD XWA, XSP
	CALL FP_DP_Decode
	LD XBC, XIZ
	LDA XIZ, XSP + 00ch
	LDA XWA, XIZ
	CALL FP_DP_Decode
	LD XWA, XSP
	LDA XBC, XIZ
	CALL FP_DP_Mul_Outer
	LD XWA, (XSP + 018h)
	LD XBC, XSP
	CALL FP_DP_Encode
	LDA XSP, XSP + 01ch
	POP XIZ
	RET

VoiceFloat_SubSP:
	PUSH XIZ
	LDA XSP, XSP - 014h
	LD XIZ, XDE
	LD (XSP + 010h), XWA
	LD XWA, XSP
	CALL FP_SP_Decode
	LD XBC, XIZ
	LDA XIZ, XSP + 008h
	LDA XWA, XIZ
	CALL FP_SP_Decode
	LD XWA, XSP
	LDA XBC, XIZ
	CALL FP_SP_Mul_Outer
	LD XWA, (XSP + 010h)
	LD XBC, XSP
	CALL FP_SP_Encode
	LDA XSP, XSP + 014h
	POP XIZ
	RET

FP_DP_CopyOrNegate8:
	CP XWA, XBC
	JR Z, FP_DP_NegateInPlace8
	LD XHL, (XBC)
	LD (XWA), XHL
	LD XHL, (XBC + 004h)
	XOR QH, 080h
	LD (XWA + 004h), XHL
	RET

FP_DP_NegateInPlace8:
	XOR (XWA + 007h), 080h
	RET

FP_SP_CopyOrNegate4:
	CP XWA, XBC
	JR Z, FP_SP_NegateInPlace4
	LD XHL, (XBC)
	XOR QH, 080h
	LD (XWA), XHL
	RET

FP_SP_NegateInPlace4:
	XOR (XWA + 003h), 080h
	RET

FP_DP_CmpAndCopy:
	LDA XWA, XSP + 008h
	LD BC, 1
	CALL FP_DP_CmpZero64
	LDA XBC, XSP + 008h
	LD XWA, (XSP + 004h)
	CP HL, 0
	JR NZ, FP_DP_CmpAndCopy_Negate
	CALL FP_DP_Raw8Copy
	RET

FP_DP_CmpAndCopy_Negate:
	CALL FP_DP_CopyOrNegate8
	RET

FP_DP_CmpAndCopy_Pad:
	db 0FFh

FP_SP_Decode_ReadSign:
	PUSH XIZ
	LDA XSP, XSP - 8
	LD XIZ, XWA
	LD XWA, XSP
	CALL FP_SP_Decode
	LD XWA, XSP
	CALL FP_DP_ShiftDecode
	LD (XIZ), XHL
	LDA XSP, XSP + 008h
	POP XIZ
	RET

FP_SP_Decode_ReadSign_Pad:
	db 0FFh

FP_DP_CmpZero64:
	LD HL, 0
	LD XDE, 0
	LD XIY, (XWA + 004h)
	CP XIY, XDE
	JR LT, FP_DP_CmpZero64_Less
	JR GT, FP_DP_CmpZero64_Greater
	LD XIY, (XWA)
	CP XIY, XDE
	JR NZ, FP_DP_CmpZero64_Greater
	LDA XDE, 03D978h
	LD L, (XDE + BC)
	RET

FP_DP_CmpZero64_Less:
	LDA XDE, 03D97Eh
	LD L, (XDE + BC)
	RET

FP_DP_CmpZero64_Greater:
	LDA XDE, 03D984h
	LD L, (XDE + BC)
	RET

FP_SP_CmpZero32:
	LD HL, 0
	LD XDE, (XWA)
	CP XDE, 00000000h
	JR LT, FP_SP_CmpZero32_Less
	JR GT, FP_SP_CmpZero32_Greater
	LDA XDE, 03D978h
	LD L, (XDE + BC)
	RET

FP_SP_CmpZero32_Less:
	LDA XDE, 03D97Eh
	LD L, (XDE + BC)
	RET

FP_SP_CmpZero32_Greater:
	LDA XDE, 03D984h
	LD L, (XDE + BC)
	RET

VoiceFloat_MulAddDispatch:
	LDA XSP, XSP - 028h
	PUSH XIZ
	LD XIZ, (XSP + 030h)
	LD WA, (XSP + 03ah)
	AND WA, 7ff0h
	CP WA, 41e0h
	JR C, VoiceFloat_MulAddDispatch_InRange
	LDW (040C22h), 0022h
	LD XWA, XIZ
	LDA XBC, 01F63Eh
	CALL FP_DP_Raw8Copy
	JR T, VoiceFloat_MulAddDispatch_Epilog

VoiceFloat_MulAddDispatch_InRange:
	LDA XIY, XSP + 034h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 024h
	PUSH XWA
	CALL VoiceFloat_DispatchMulAdd
	LDA XIY, XSP + 040h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 028h
	PUSH XWA
	CALL VoiceFloat_MulAddVariant2
	LDA XSP, XSP + 018h
	LDA XBC, XSP + 014h
	LDA XDE, XSP + 01ch
	LDA XWA, XSP + 024h
	CALL VoiceFloat_SubDP
	LD XWA, XIZ
	LDA XBC, XSP + 024h
	CALL FP_DP_Raw8Copy

VoiceFloat_MulAddDispatch_Epilog:
	POP XIZ
	LDA XSP, XSP + 028h
	RET

VoiceFloat_CompareAndConvert:
	LDA XSP, XSP - 038h
	PUSH IZ
	LDA XWA, XSP + 04ah
	LDA XBC, 01F646h
	LD DE, 1
	CALL ToneGen_Compare_Voice
	CP HL, 0
	JR NZ, VoiceFloat_CompareAndConvert_Invalid
	LDA XWA, XSP + 04ah
	LDA XBC, 01F64Eh
	LD DE, 3
	CALL ToneGen_Compare_Voice
	CP HL, 0
	JR NZ, VoiceFloat_CompareAndConvert_Invalid
	LDA XBC, XSP + 04ah
	LDA XWA, XSP + 036h
	CALL FP_DP_DecodeToInt
	JR T, VoiceFloat_CompareAndConvert_AfterRange

VoiceFloat_CompareAndConvert_Invalid:
	LD XWA, 0ffffffffh
	LD (XSP + 036h), XWA

VoiceFloat_CompareAndConvert_AfterRange:
	LDA XWA, XSP + 042h
	LD BC, 2
	CALL FP_DP_CmpZero64
	CP HL, 0
	JR NZ, VoiceFloat_CompareAndConvert_AltPath
	LDA XBC, XSP + 036h
	LDA XWA, XSP + 012h
	CALL FP_ScalarToDP
	LDA XWA, XSP + 012h
	LDA XBC, XSP + 04ah
	LD DE, 4
	CALL ToneGen_Compare_Voice
	CP HL, 0
	JR NZ, VoiceFloat_CompareAndConvert_AltPath
	LDW (040C22h), 0021h
	LD XWA, (XSP + 03eh)
	LDA XBC, 01F656h
	CALL FP_DP_Raw8Copy
	JRL T, VoiceFloat_CompareAndConvert_Epilog

VoiceFloat_CompareAndConvert_AltPath:
	LDA XWA, XSP + 04ah
	LD BC, 3
	CALL FP_DP_CmpZero64
	CP HL, 0
	JR NZ, VoiceFloat_CompareAndConvert_AltPath2
	LDA XWA, XSP + 042h
	LD BC, 5
	CALL FP_DP_CmpZero64
	CP HL, 0
	JR NZ, VoiceFloat_CompareAndConvert_AltPath2
	LDW (040C22h), 0021h
	LD XWA, (XSP + 03eh)
	LDA XBC, 01F65Eh
	CALL FP_DP_Raw8Copy
	JRL T, VoiceFloat_CompareAndConvert_Epilog

VoiceFloat_CompareAndConvert_AltPath2:
	LDA XBC, XSP + 036h
	LDA XWA, XSP + 012h
	CALL FP_ScalarToDP
	LDA XWA, XSP + 012h
	LDA XBC, XSP + 04ah
	LD DE, 5
	CALL ToneGen_Compare_Voice
	CP HL, 0
	JRL NZ, VoiceFloat_ConvergenceLoop
	LD XWA, (XSP + 036h)
	CP XWA, 00000000h
	JR GE, VoiceFloat_SignedDelta_Positive
	LD XWA, (XSP + 036h)
	CPL WA
	CPL QWA
	INC 1, XWA
	LD (XSP + 036h), XWA

VoiceFloat_SignedDelta_Positive:
	LDA XBC, 01F666h
	LDA XWA, XSP + 02eh
	CALL FP_DP_Raw8Copy
	JRL T, VoiceFloat_IterationLoop_CheckContinue

VoiceFloat_IterationLoop:
	LDA XWA, XSP + 024h
	PUSH XWA
	LDA XIY, XSP + 046h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 026h
	PUSH XWA
	CALL FP_DP_FreqAdjust
	LDA XSP, XSP + 010h
	LD WA, (XSP + 024h)
	ADD WA, WA
	CP WA, 0fc03h
	JR GE, VoiceFloat_IterationLoop_LargeStep
	LDA XWA, XSP + 04ah
	LD BC, 2
	CALL FP_DP_CmpZero64
	CP HL, 0
	JR NZ, VoiceFloat_IterationLoop_LessPath
	LDW (040C22h), 0022h
	LDA XWA, XSP + 042h
	LD BC, 2
	CALL FP_DP_CmpZero64
	LDA XBC, 0F420h:24
	CP HL, 0
	JR NZ, VoiceFloat_IterationLoop_GreaterPath
	LDA XWA, XSP + 02eh
	CALL FP_DP_CopyOrNegate8
	JR T, VoiceFloat_IterationLoop_CopyResult

VoiceFloat_IterationLoop_GreaterPath:
	LDA XWA, XSP + 02eh
	CALL FP_DP_Raw8Copy
	JR T, VoiceFloat_IterationLoop_CopyResult

VoiceFloat_IterationLoop_LessPath:
	LDA XBC, 01F66Eh
	LDA XWA, XSP + 02eh
	CALL FP_DP_Raw8Copy

VoiceFloat_IterationLoop_CopyResult:
	LD XWA, (XSP + 03eh)
	LDA XBC, XSP + 02eh
	CALL FP_DP_Raw8Copy
	JRL T, VoiceFloat_CompareAndConvert_Epilog

VoiceFloat_IterationLoop_LargeStep:
	LDA XDE, XSP + 042h
	CP WA, 0400h
	JR LE, VoiceFloat_IterationLoop_SmallStep
	LDW (040C22h), 0022h
	LD XWA, XDE
	LD BC, 2
	CALL FP_DP_CmpZero64
	CP HL, 0
	JR NZ, VoiceFloat_IterationLoop_LargeStep_NegPath
	LDA XBC, 0F420h:24
	LDA XWA, XSP + 02eh
	CALL FP_DP_CopyOrNegate8
	JR T, VoiceFloat_IterationLoop_LargeStep_Copy

VoiceFloat_IterationLoop_LargeStep_NegPath:
	LDA XBC, 0F420h:24
	LDA XWA, XSP + 02eh
	CALL FP_DP_Raw8Copy

VoiceFloat_IterationLoop_LargeStep_Copy:
	LD XWA, (XSP + 03eh)
	LDA XBC, XSP + 02eh
	CALL FP_DP_Raw8Copy
	JRL T, VoiceFloat_CompareAndConvert_Epilog

VoiceFloat_IterationLoop_SmallStep:
	LD XWA, (XSP + 036h)
	BIT 0, WA
	JR Z, VoiceFloat_IterationLoop_SmallStep_Add
	LDA XWA, XSP + 02eh
	LD XBC, XWA
	CALL FP_DP_Add_Outer

VoiceFloat_IterationLoop_SmallStep_Add:
	LDA XWA, XSP + 042h
	LD XBC, XWA
	LD XDE, XWA
	CALL FP_DP_Add_Outer
	LD XWA, (XSP + 036h)
	SRA 1, XWA
	LD (XSP + 036h), XWA

VoiceFloat_IterationLoop_CheckContinue:
	LD XWA, (XSP + 036h)
	OR XWA, XWA
	JRL NZ, VoiceFloat_IterationLoop
	LDA XWA, XSP + 04ah
	LD BC, 1
	CALL FP_DP_CmpZero64
	CP HL, 0
	JR NZ, VoiceFloat_IterationLoop_DifferentPath
	LD XWA, (XSP + 03eh)
	LDA XBC, XSP + 02eh
	CALL FP_DP_Raw8Copy
	JRL T, VoiceFloat_CompareAndConvert_Epilog

VoiceFloat_IterationLoop_DifferentPath:
	LD XWA, (XSP + 03eh)
	LDA XBC, 01F676h
	LDA XDE, XSP + 02eh
	CALL VoiceFloat_SubDP
	JRL T, VoiceFloat_CompareAndConvert_Epilog

VoiceFloat_ConvergenceLoop:
	LD IZ, (040C22h)
	LDW (040C22h), 0000h
	LDA XIY, XSP + 042h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 02eh
	PUSH XWA
	CALL VoiceAmp_ConvergeEngine
	LDA XSP, XSP + 00ch
	CPW (040C22h), 0021h
	JR NZ, VoiceFloat_ConvergenceLoop_Body
	LD XWA, (XSP + 03eh)
	LDA XBC, 01F67Eh
	CALL FP_DP_Raw8Copy
	JRL T, VoiceFloat_CompareAndConvert_Epilog

VoiceFloat_ConvergenceLoop_Body:
	LD (040C22h), IZ
	LDA XWA, XSP + 024h
	PUSH XWA
	LDA XIY, XSP + 046h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 016h
	PUSH XWA
	CALL FP_DP_FreqAdjust
	LDA XWA, XSP + 032h
	PUSH XWA
	LDA XIY, XSP + 05eh
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 01eh
	PUSH XWA
	CALL FP_DP_FreqAdjust
	LDA XSP, XSP + 020h
	CPW (XSP + 024h), 0000h
	JR GE, VoiceFloat_ConvergenceLoop_SumCheck
	CPW (XSP + 022h), 0000h
	JR GE, VoiceFloat_ConvergenceLoop_SumCheck
	LD WA, (XSP + 022h)
	NEG WA
	LD (XSP + 022h), WA

VoiceFloat_ConvergenceLoop_SumCheck:
	LD IZ, (XSP + 024h)
	ADD IZ, (XSP + 022h)
	LDA XWA, XSP + 04ah
	LD BC, 2
	CALL FP_DP_CmpZero64
	CP HL, 0
	JR NZ, VoiceFloat_ConvergenceLoop_RangeCheck
	LD WA, IZ
	NEG WA
	LD IZ, WA

VoiceFloat_ConvergenceLoop_RangeCheck:
	CP IZ, 0400h
	JR LE, VoiceFloat_ConvergenceLoop_Clamp
	LDW (040C22h), 0022h
	LDA XWA, XSP + 042h
	LD BC, 2
	CALL FP_DP_CmpZero64
	LDA XWA, XSP + 02eh
	LDA XBC, 0F420h:24
	CP HL, 0
	JR NZ, VoiceFloat_ConvergenceLoop_NegResult
	CALL FP_DP_CopyOrNegate8
	JR T, VoiceFloat_ConvergenceLoop_StoreResult

VoiceFloat_ConvergenceLoop_NegResult:
	CALL FP_DP_Raw8Copy

VoiceFloat_ConvergenceLoop_StoreResult:
	LD XWA, (XSP + 03eh)
	LDA XBC, XSP + 02eh
	CALL FP_DP_Raw8Copy
	JR T, VoiceFloat_CompareAndConvert_Epilog

VoiceFloat_ConvergenceLoop_Clamp:
	CP IZ, 0fc03h
	JR GE, VoiceFloat_ConvergenceLoop_CrossZero
	LDW (040C22h), 0022h
	LD XWA, (XSP + 03eh)
	LDA XBC, 01F686h
	CALL FP_DP_Raw8Copy
	JR T, VoiceFloat_CompareAndConvert_Epilog

VoiceFloat_ConvergenceLoop_CrossZero:
	LDA XBC, XSP + 026h
	LDA XDE, XSP + 04ah
	LDA XWA, XSP + 012h
	CALL FP_DP_Add_Outer
	LDA XIY, XSP + 012h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 036h
	PUSH XWA
	CALL VoicePitch_SlideEngine
	LDA XSP, XSP + 00ch
	LD XWA, (XSP + 03eh)
	LDA XBC, XSP + 02eh
	CALL FP_DP_Raw8Copy

VoiceFloat_CompareAndConvert_Epilog:
	POP IZ
	LDA XSP, XSP + 038h
	RET

VoiceFloat_MulAddVariant2:
	LDA XSP, XSP - 030h
	PUSH XIZ
	LD XIZ, (XSP + 038h)
	LDA XWA, XSP + 03ch
	LD BC, 2
	CALL FP_DP_CmpZero64
	CP HL, 0
	JR NZ, VoiceFloat_MulAddVariant2_AltPath
	PUSHW 0001h
	LDA XBC, XSP + 03eh
	LDA XWA, XSP + 02eh
	CALL FP_DP_CopyOrNegate8
	LDA XIY, XSP + 02eh
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XIY, XSP + 046h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 036h
	PUSH XWA
	CALL VoiceFloat_BlendAndMerge
	LDA XSP, XSP + 016h
	LD XWA, XIZ
	LDA XBC, XSP + 024h
	CALL FP_DP_Raw8Copy
	JR T, VoiceFloat_MulAddVariant2_Epilog

VoiceFloat_MulAddVariant2_AltPath:
	PUSHW 0000h
	LDA XIY, XSP + 03eh
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XIY, XSP + 046h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 02eh
	PUSH XWA
	CALL VoiceFloat_BlendAndMerge
	LDA XSP, XSP + 016h
	LD XWA, XIZ
	LDA XBC, XSP + 01ch
	CALL FP_DP_Raw8Copy

VoiceFloat_MulAddVariant2_Epilog:
	POP XIZ
	LDA XSP, XSP + 030h
	RET

FP_MulAccum64:
	LD HL, QWA
	MUL XHL, BC
	LD DE, QBC
	MUL XDE, WA
	ADD XHL, XDE
	LD QHL, HL
	LD HL, 0
	MUL XWA, BC
	ADD XHL, XWA
	RET

FP_DP_Sub:
	PUSH XIZ
	LDA XSP, XSP - 01ch
	LD XIZ, XDE
	LD (XSP + 018h), XWA
	LD XWA, XSP
	CALL FP_DP_Decode
	LD XBC, XIZ
	LDA XIZ, XSP + 00ch
	LDA XWA, XIZ
	CALL FP_DP_Decode
	LD XWA, XSP
	LDA XBC, XIZ
	CALL FP_DP_AlignMantissa
	LD XWA, XSP
	LDA XBC, XIZ
	LD E, (XSP + 003h)
	XOR E, (XIZ + 003h)
	JR Z, FP_DP_Sub_SameSign
	BIT 0, (XSP + 002h)
	JR NZ, FP_DP_Sub_SameSign
	CALL FP_DP_AddMantissa
	JR T, FP_DP_Sub_Done

FP_DP_Sub_SameSign:
	CALL FP_DP_SubMantissa

FP_DP_Sub_Done:
	LD XWA, (XSP + 018h)
	LD XBC, XSP
	CALL FP_DP_Encode
	LDA XSP, XSP + 01ch
	POP XIZ
	RET

FP_SP_Sub_Pad:
	db 0FFh

FP_SP_Sub:
	PUSH XIZ
	LDA XSP, XSP - 014h
	LD XIZ, XDE
	LD (XSP + 010h), XWA
	LD XWA, XSP
	CALL FP_SP_Decode
	LD XBC, XIZ
	LDA XIZ, XSP + 008h
	LDA XWA, XIZ
	CALL FP_SP_Decode
	LD XWA, XSP
	LDA XBC, XIZ
	CALL FP_SP_AlignMantissa
	LD XWA, XSP
	LDA XBC, XIZ
	LD E, (XSP + 003h)
	XOR E, (XIZ + 003h)
	JR Z, FP_SP_Sub_SameSign
	BIT 0, (XSP + 002h)
	JR NZ, FP_SP_Sub_SameSign
	CALL FP_SP_AddMantissa
	JR T, FP_SP_Sub_Done

FP_SP_Sub_SameSign:
	CALL FP_SP_SubMantissa

FP_SP_Sub_Done:
	LD XWA, (XSP + 010h)
	LD XBC, XSP
	CALL FP_SP_Encode
	LDA XSP, XSP + 014h
	POP XIZ
	RET

; ----------------------------------------------------------------------------
; ToneGen_Compare_Tables - Lookup tables for voice comparison results
; 0x03D978: Equal result table (6 bytes)
; 0x03D97E: Less-than result table (6 bytes)
; 0x03D984: Greater-than result table (6 bytes)
; ----------------------------------------------------------------------------
ToneGen_Compare_Tables:		; 03D977h
	db 0FFh			; Padding
	; Equal table (0x03D978)
	db 001h, 000h, 001h, 000h, 001h, 000h
	; Less-than table (0x03D97E)
	db 001h, 001h, 000h, 000h, 000h, 001h
	; Greater-than table (0x03D984)
	db 000h, 000h, 001h, 001h, 000h, 001h

VoiceFloat_BlendAndMerge:
	LDA XSP, XSP - 080h
	PUSH XIZ
	LD WA, (XSP + 0092h)
	AND WA, 7ff0h
	CP WA, 41e0h
	JR C, VoiceFloat_BlendAndMerge_InRange
	LDW (040C22h), 0022h
	LD XWA, (XSP + 0088h)
	LDA XBC, 01F68Eh
	CALL FP_DP_Raw8Copy
	JRL T, VoiceFloat_BlendAndMerge_Epilog

VoiceFloat_BlendAndMerge_InRange:
	LDA XWA, XSP + 074h
	PUSH XWA
	LDA XDE, 0F396h:24
	LDA XBC, XSP + 0098h
	LDA XWA, XSP + 048h
	CALL FP_DP_Add_Outer
	LDA XIY, XSP + 048h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 070h
	PUSH XWA
	CALL DSP_VoiceBlend
	LDA XSP, XSP + 010h
	LDA XWA, XSP + 064h
	LDA XBC, 01F696h
	LD DE, 1
	CALL ToneGen_Compare_Voice
	CP HL, 0
	JR NZ, VoiceFloat_BlendAndMerge_Phase2
	LDA XWA, XSP + 074h
	LD XBC, XWA
	LDA XDE, 01F69Eh
	CALL FP_DP_Mul

VoiceFloat_BlendAndMerge_Phase2:
	LDA XBC, XSP + 074h
	LDA XWA, XSP + 040h
	CALL FP_DP_DecodeToInt
	LD XWA, (XSP + 040h)
	BIT 0, WA
	JR Z, VoiceFloat_BlendAndMerge_Phase3
	CPW (XSP + 009ch), 0000h
	SCC Z, WA
	LD (XSP + 009ch), WA

VoiceFloat_BlendAndMerge_Phase3:
	LDA XIY, XSP + 008ch
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 064h
	PUSH XWA
	CALL FP_DP_CmpAndCopy
	LDA XSP, XSP + 00ch
	LDA XWA, XSP + 05ch
	LDA XBC, XSP + 0094h
	LD DE, 4
	CALL ToneGen_Compare_Voice
	CP HL, 0
	JR NZ, VoiceFloat_BlendAndMerge_Phase4
	LDA XWA, XSP + 074h
	LD XBC, XWA
	LDA XDE, 01F6A6h
	CALL FP_DP_Sub

VoiceFloat_BlendAndMerge_Phase4:
	LDA XWA, XSP + 008ch
	PUSH XWA
	LDA XIY, XSP + 0090h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 060h
	PUSH XWA
	CALL FP_DP_CmpAndCopy
	LDA XSP, XSP + 00ch
	LDA XIY, XSP + 058h
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 078h
	PUSH XWA
	CALL DSP_VoiceBlend
	LDA XDE, 0F39Eh:24
	LDA XBC, XSP + 0084h
	LDA XWA, XSP + 054h
	CALL FP_DP_Add_Outer
	LDA XBC, XSP + 009ch
	LDA XWA, XSP + 054h
	LD XDE, XWA
	CALL FP_DP_Sub
	LDA XWA, XSP + 054h
	LD XBC, XWA
	LDA XDE, XSP + 07ch
	CALL FP_DP_Mul
	LDA XBC, 0F38Eh:24
	LDA XWA, XSP + 048h
	CALL FP_DP_CopyOrNegate8
	LDA XWA, XSP + 048h
	LD XBC, XWA
	LDA XDE, XSP + 0084h
	CALL FP_DP_Add_Outer
	LDA XBC, XSP + 054h
	LDA XDE, XSP + 048h
	LDA XWA, XSP + 008ch
	CALL FP_DP_Sub
	LDA XIY, XSP + 008ch
	LD XIX, (XIY + 004h)
	PUSH XIX
	LD XIX, (XIY)
	PUSH XIX
	LDA XWA, XSP + 064h
	PUSH XWA
	CALL FP_DP_CmpAndCopy
	LDA XSP, XSP + 01ch
	LDA XBC, 0F3A6h:24
	LDA XWA, XSP + 04ch
	LD DE, 0
	CALL ToneGen_Compare_Voice
	CP HL, 0
	JRL NZ, VoiceFloat_BlendAndMerge_FinalCheck
	LDA XDE, XSP + 07ch
	LD XBC, XDE
	LDA XWA, XSP + 06ch
	CALL FP_DP_Add_Outer
	LDA XWA, 0F34Eh:24
	LDA XIZ, XWA + 030h
	LDA XBC, XWA + 038h
	LDA XDE, XSP + 06ch
	LDA XWA, XSP + 038h
	CALL FP_DP_Add_Outer
	LDA XWA, XSP + 038h
	LD XBC, XWA
	LD XDE, XIZ
	CALL FP_DP_Sub
	LDA XWA, XSP + 038h
	LD XBC, XWA
	LDA XDE, XSP + 06ch
	CALL FP_DP_Add_Outer
	LDA XBC, 0F376h:24
	LDA XWA, XSP + 038h
	LD XDE, XWA
	CALL FP_DP_Mul
	LDA XWA, XSP + 038h
	LD XBC, XWA
	LDA XDE, XSP + 06ch
	CALL FP_DP_Add_Outer
	LDA XDE, 0F36Eh:24
	LDA XWA, XSP + 038h
	LD XBC, XWA
	CALL FP_DP_Sub
	LDA XWA, XSP + 038h
	LD XBC, XWA
	LDA XDE, XSP + 06ch
	CALL FP_DP_Add_Outer
	LDA XBC, 0F366h:24
	LDA XWA, XSP + 038h
	LD XDE, XWA
	CALL FP_DP_Mul
	LDA XWA, XSP + 038h
	LD XBC, XWA
	LDA XDE, XSP + 06ch
	CALL FP_DP_Add_Outer
	LDA XDE, 0F35Eh:24
	LDA XWA, XSP + 038h
	LD XBC, XWA
	CALL FP_DP_Sub
	LDA XWA, XSP + 038h
	LD XBC, XWA
	LDA XDE, XSP + 06ch
	CALL FP_DP_Add_Outer
	LDA XBC, 0F356h:24
	LDA XWA, XSP + 038h
	LD XDE, XWA
	CALL FP_DP_Mul
	LDA XWA, XSP + 038h
	LD XBC, XWA
	LDA XDE, XSP + 06ch
	CALL FP_DP_Add_Outer
	LDA XDE, 0F34Eh:24
	LDA XWA, XSP + 038h
	LD XBC, XWA
	CALL FP_DP_Sub
	LDA XWA, XSP + 038h
	LD XBC, XWA
	LDA XDE, XSP + 06ch
	CALL FP_DP_Add_Outer
	LDA XWA, XSP + 038h
	LD XBC, XWA
	LDA XDE, XSP + 07ch
	CALL FP_DP_Add_Outer
	LDA XBC, XSP + 038h
	LDA XWA, XSP + 07ch
	LD XDE, XWA
	CALL FP_DP_Mul

VoiceFloat_BlendAndMerge_FinalCheck:
	CPW (XSP + 009ch), 0000h
	JR Z, VoiceFloat_BlendAndMerge_FinalCopy
	LDA XWA, XSP + 07ch
	LD XBC, XWA
	CALL FP_DP_CopyOrNegate8

VoiceFloat_BlendAndMerge_FinalCopy:
	LD XWA, (XSP + 0088h)
	LDA XBC, XSP + 07ch
	CALL FP_DP_Raw8Copy

VoiceFloat_BlendAndMerge_Epilog:
	POP XIZ
	LDA XSP, XSP + 0080h
	RET

Int_SignedDiv:
	LD_E 000h
	BIT 0fh, QWA
	JR Z, Int_SignedDiv_AfterSignA
	LD_E 001h
	CPL QWA
	CPL WA
	INC 1, XWA

Int_SignedDiv_AfterSignA:
	BIT 0fh, QBC
	JR Z, Int_SignedDiv_CallUnsigned
	OR E, 002h
	CPL QBC
	CPL BC
	INC 1, XBC

Int_SignedDiv_CallUnsigned:
	PUSH DE
	CALR FP_UnsignedDiv
	POP WA
	CP W, 1
	JR Z, Int_SignedDiv_ResultCorr
	LD XHL, XDE
	BIT 0, A
	SCC NZ, A
	JR T, Int_SignedDiv_NegResult

Int_SignedDiv_ResultCorr:
	CP A, 3
	RET Z

Int_SignedDiv_NegResult:
	OR XHL, XHL
	RET Z
	CP A, 0
	RET Z
	CPL QHL
	CPL HL
	INC 1, XHL
	RET

Int_SignedDiv_ConstData:
	db 024h, 000h, 068h, 0B5h

Int_SignedDiv_AltEntry:
	LD_D 001h
	JR T, Int_SignedDiv
	CALR FP_UnsignedDiv
	LD XHL, XDE
	RET

FP_UnsignedDiv:
	CP XBC, 00000001h
	JR Z, FP_UnsignedDiv_ByOne
	JR C, FP_UnsignedDiv_Zero
	CP XWA, XBC
	JR ULE, FP_UnsignedDiv_SmallDividend
	CP QBC, 0
	JR NZ, FP_UnsignedDiv_General
	LD XDE, XWA
	DIV XWA, BC
	JR OV, FP_UnsignedDiv_Overflow
	LD XHL, 0
	LD XDE, XHL
	LD HL, WA
	LD DE, QWA
	RET

FP_UnsignedDiv_Overflow:
	LD WA, QDE
	EXTZ XWA
	DIV XWA, BC
	LD QHL, WA
	LD WA, DE
	DIV XWA, BC
	LD HL, WA
	LD DE, QWA
	EXTZ XDE
	RET

FP_UnsignedDiv_ByOne:
	LD XHL, XWA
	LD XDE, 0
	RET

FP_UnsignedDiv_Zero:
	LD XHL, 0
	LD XDE, XHL
	DEC 1, XHL
	RET

FP_UnsignedDiv_SmallDividend:
	LD XHL, 1
	LD XDE, 0
	RET Z
	DEC 1, XHL
	LD XDE, XWA
	RET

FP_UnsignedDiv_General:
	LD_D 000h

FP_UnsignedDiv_ShiftLoop:
	CP XWA, XBC
	JR C, FP_UnsignedDiv_ShiftLoopDone
	INC 1, D
	ADD XBC, XBC
	JR NC, FP_UnsignedDiv_ShiftLoop
	STCF 0, BC
	RRC 1, XBC
	JR T, FP_UnsignedDiv_Subtract

FP_UnsignedDiv_ShiftLoopDone:
	SRL 1, XBC

FP_UnsignedDiv_Subtract:
	LD XHL, 0

FP_UnsignedDiv_SubtractLoop:
	ADD XHL, XHL
	CP XWA, XBC
	JR C, FP_UnsignedDiv_Done
	SET 0, L
	SUB XWA, XBC

FP_UnsignedDiv_Done:
	SRL 1, XBC
	DJNZ D, FP_UnsignedDiv_SubtractLoop
	LD XDE, XWA
	RET

FP_DP_Raw8Copy:
	LD XIX, (XBC)
	LD XIY, (XBC + 004h)
	LD (XWA), XIX
	LD (XWA + 004h), XIY
	RET

FP_DP_Raw8Copy_Pad:
	db 0FFh

FP_DP_NegMantissaLS:
	PUSH XIZ
	LDA XSP, XSP - 12
	LD XIZ, XWA
	LD XWA, XSP
	CALL FP_SP_Decode
	CP L, 0
	JR NZ, FP_DP_NegMantissaLS_Store
	LD XHL, (XSP + 004h)
	LD XDE, 0
	SRL 1, XHL
	STCF 0, DE
	RRC 1, XDE
	SRL 1, XHL
	STCF 0, DE
	RRC 1, XDE
	SRL 1, XHL
	STCF 0, DE
	RRC 1, XDE
	LD (XSP + 008h), XHL
	LD (XSP + 004h), XDE

FP_DP_NegMantissaLS_Store:
	LD XWA, XIZ
	LD XBC, XSP
	CALL FP_DP_Encode
	LDA XSP, XSP + 00ch
	POP XIZ
	RET

FP_ScalarToDP_Pad:
	db 0FFh

FP_ScalarToDP:
	PUSH XIZ
	LDA XSP, XSP - 12
	LD XIZ, XWA
	LD XWA, XSP
	LD XBC, (XBC)
	CALL FP_SP_Normalize
	LD XWA, XIZ
	LD XBC, XSP
	CALL FP_DP_Encode
	LDA XSP, XSP + 00ch
	POP XIZ
	RET

FP_DP_CallWithBuf12:
	db 03Eh, 0BFh, 0F4h, 037h, 0E8h, 08Eh, 0EFh, 088h
	db 0A1h, 021h, 01Dh, 0EFh, 0DFh, 003h, 0EEh, 088h
	db 0EFh, 089h, 01Dh, 046h, 0E0h, 003h, 0BFh, 00Ch
	db 037h, 05Eh, 00Eh

FP_DP_NormalizeMantissa:
	PUSH XIZ
	LDA XSP, XSP - 12
	LD XIZ, XWA
	LD XWA, XSP
	CALL FP_DP_Decode
	CP L, 0
	JR NZ, FP_DP_NormalizeMantissa_Encode
	LD XHL, (XSP + 008h)
	LD DE, (XSP + 006h)
	SLL 1, DE
	STCF 0fh, QHL
	RLC 1, XHL
	SLL 1, DE
	STCF 0fh, QHL
	RLC 1, XHL
	SLL 1, DE
	STCF 0fh, QHL
	RLC 1, XHL
	CP D, 080h
	JR C, FP_DP_NormalizeMantissa_StoreHL
	INC 1, XHL
	BIT 7, QHL
	JR NZ, FP_DP_NormalizeMantissa_StoreHL
	INCW 1, (XSP + 000h:8)
	SRL 1, XHL

FP_DP_NormalizeMantissa_StoreHL:
	LD (XSP + 004h), XHL

FP_DP_NormalizeMantissa_Encode:
	LD XWA, XIZ
	LD XBC, XSP
	CALL FP_SP_Encode
	LDA XSP, XSP + 00ch
	POP XIZ
	RET

FP_SP_Raw4Copy_Pad:
	db 0FFh

FP_SP_Raw4Copy:
	LD XIX, (XBC)
	LD (XWA), XIX
	RET

FP_SP_CallWithBuf8_Pad:
	db 0FFh

FP_SP_CallWithBuf8:
	PUSH XIZ
	LDA XSP, XSP - 8
	LD XIZ, XWA
	LD XWA, XSP
	LD XBC, (XBC)
	CALL FP_DP_Normalize
	LD XWA, XIZ
	LD XBC, XSP
	CALL FP_SP_Encode
	LDA XSP, XSP + 008h
	POP XIZ
	RET

FP_SP_CallWithBuf8b:
	db 03Eh, 0BFh, 0F8h, 037h, 0E8h, 08Eh, 0EFh, 088h
	db 0A1h, 021h, 01Dh, 033h, 0DEh, 003h, 0EEh, 088h
	db 0EFh, 089h, 01Dh, 0B0h, 0E0h, 003h, 0BFh, 008h
	db 037h, 05Eh, 00Eh

FP_DP_DecodeToInt:
	PUSH XIZ
	LDA XSP, XSP - 12
	LD XIZ, XWA
	LD XWA, XSP
	CALL FP_DP_Decode
	LD XWA, XSP
	CALL FP_SP_DecodeToInt
	LD (XIZ), XHL
	LDA XSP, XSP + 00ch
	POP XIZ
	RET

FP_DP_Normalize_Pad:
	db 0FFh

FP_DP_Normalize:
	LD_E 000h
	LDCF 0fh, QBC
	STCF 7, E
	JR NC, FP_DP_Normalize_StoreSign
	CPL QBC
	CPL BC
	INC 1, XBC

FP_DP_Normalize_StoreSign:
	CALR FP_DP_NormCore
	LD (XIY + 003h), E
	RET

FP_DP_NormCore:
	LD XIY, XWA
	OR XBC, XBC
	JR Z, FP_DP_NormCore_Zero
	BS1B A, QBC
	JR OV, FP_DP_NormCore_Overflow
	ADD A, 010h
	JR T, FP_DP_NormCore_Shift

FP_DP_NormCore_Overflow:
	BS1B A, BC

FP_DP_NormCore_Shift:
	LD HL, 0
	LD (XIY + 002h), HL
	LD L, A
	LD (XIY + 000h:8), HL
	CP L, 017h
	JR Z, FP_DP_NormCore_StoreResult
	JR LT, FP_DP_NormCore_ShiftLeft
	SUB L, 017h
	LD A, L
	SRL A, XBC
	JR NC, FP_DP_NormCore_StoreResult
	INC 1, XBC
	BIT 0, QB
	JR Z, FP_DP_NormCore_StoreResult
	SRL 1, XBC
	INC 1, (XIY + 000h:8)
	JR T, FP_DP_NormCore_StoreResult

FP_DP_NormCore_ShiftLeft:
	LD_A 017h
	SUB A, L
	CP A, 010h
	JR LT, FP_DP_NormCore_ShiftLeftLoop
	LD QBC, BC
	LD BC, 0
	SUB A, 010h
	JR Z, FP_DP_NormCore_StoreResult

FP_DP_NormCore_ShiftLeftLoop:
	SLL A, XBC

FP_DP_NormCore_StoreResult:
	LD (XIY + 004h), XBC
	RET

FP_DP_NormCore_Zero:
	LD (XIY + 002h), 001h
	RET

FP_DP_ShiftDecode_Pad:
	db 0FFh

FP_DP_ShiftDecode:
	LD XDE, (XWA)
	CP QE, 0
	JR NZ, FP_DP_ShiftDecode_Zero
	CP DE, 0
	JR LT, FP_DP_ShiftDecode_Underflow
	CP DE, 001fh
	JR GT, FP_DP_ShiftDecode_Overflow
	LD XIX, (XWA + 004h)
	CP DE, 0017h
	JR Z, FP_DP_ShiftDecode_SignCorrect
	JR LT, FP_DP_ShiftDecode_ShiftRight
	LD A, E
	SUB A, 017h
	SLL A, XIX
	JR T, FP_DP_ShiftDecode_SignCorrect

FP_DP_ShiftDecode_ShiftRight:
	LD_A 017h
	SUB A, E
	CP A, 010h
	JR LT, FP_DP_ShiftDecode_ShiftRightLoop
	LD IX, QIX
	EXTZ XIX
	SUB A, 010h
	JR Z, FP_DP_ShiftDecode_SignCorrect

FP_DP_ShiftDecode_ShiftRightLoop:
	SRL A, XIX

FP_DP_ShiftDecode_SignCorrect:
	CP QD, 0
	JR Z, FP_DP_ShiftDecode_Return
	CPL QIX
	CPL IX
	INC 1, XIX

FP_DP_ShiftDecode_Return:
	LD XHL, XIX
	RET

FP_DP_ShiftDecode_Underflow:
	LD XHL, 0
	JR T, FP_DP_ShiftDecode_SetError

FP_DP_ShiftDecode_Overflow:
	LD XHL, 0
	DEC 1, XHL

FP_DP_ShiftDecode_SetError:
	LDW (040C22h), 0022h
	RET

FP_DP_ShiftDecode_Zero:
	LD XHL, 0
	RET

FP_DP_AddMantissa:
	LD E, (XWA + 002h)
	OR E, (XBC + 002h)
	JP NZ, FP_DP_CopyWithSign
	LD XHL, (XWA + 008h)
	LD XDE, (XWA + 004h)
	ADD XDE, (XBC + 004h)
	ADC XHL, (XBC + 008h)
	BIT 5, QHL
	JR Z, FP_DP_AddMantissa_Store
	SRL 1, XHL
	STCF 1, BC
	LDCF 0, DE
	STCF 0, BC
	RRC 1, XDE
	LDCF 1, BC
	STCF 0fh, QDE
	LDCF 0, BC
	INCW 1, (XWA + 000h:8)
	JR NC, FP_DP_AddMantissa_Store
	ADD XDE, 00000001h
	ADC XHL, 00000000h

FP_DP_AddMantissa_Store:
	LD (XWA + 004h), XDE
	LD (XWA + 008h), XHL
	RET

FP_SP_AddMantissa:
	LD E, (XWA + 002h)
	OR E, (XBC + 002h)
	JP NZ, FP_DP_CopyNoSign
	LD XIX, (XWA + 004h)
	ADD XIX, (XBC + 004h)
	BIT 8, QIX
	JR Z, FP_SP_AddMantissa_Store
	INCW 1, (XWA + 000h:8)
	SRL 1, XIX
	ADC XIX, 00000000h

FP_SP_AddMantissa_Store:
	LD (XWA + 004h), XIX
	RET

FP_DP_Decode_Pad:
	db 0FFh

FP_DP_Decode:
	LD XHL, 0
	LD XDE, (XBC)
	LD XBC, (XBC + 004h)
	LD HL, QBC
	AND QBC, 000fh
	LDCF 0fh, HL
	STCF 0fh, QHL
	RES 0fh, HL
	SRL 4, HL
	JR Z, FP_DP_Decode_Zero
	SUB HL, 03ffh
	SET 4, QBC
	LD (XWA), XHL
	LD L, QL
	LD (XWA + 004h), XDE
	LD (XWA + 008h), XBC
	RET

FP_DP_Decode_Zero:
	LD_L 001h
	LD (XWA + 002h), L
	LD (XWA + 003h), 000h
	RET

FP_SP_Decode:
	LD XHL, 0
	LD XIX, (XBC)
	LD DE, QIX
	LDCF 0fh, DE
	STCF 0fh, QHL
	LD HL, DE
	SLL 1, HL
	LD_L 000h
	EX H, L
	CP HL, 0
	JR Z, FP_SP_Decode_Zero
	AND DE, 007fh
	SET 7, DE
	LD QIX, DE
	SUB HL, 007fh

FP_SP_Decode_Store:
	LD (XWA), XHL
	LD (XWA + 004h), XIX
	LD L, QL
	RET

FP_SP_Decode_Zero:
	LD XIX, 0
	LD QL, 1
	JR T, FP_SP_Decode_Store
	SWI 7

FP_SP_Normalize:
	LD_E 000h
	LDCF 0fh, QBC
	STCF 7, E
	JR NC, FP_SP_Normalize_StoreSign
	CPL QBC
	CPL BC
	INC 1, XBC

FP_SP_Normalize_StoreSign:
	CALR FP_SP_NormCore
	LD (XIY + 003h), E
	RET

FP_SP_NormCore:
	LD XIY, XWA
	OR XBC, XBC
	JR Z, FP_SP_NormCore_Zero
	BS1B A, QBC
	JR OV, FP_SP_NormCore_Overflow
	ADD A, 010h
	JR T, FP_SP_NormCore_Shift

FP_SP_NormCore_Overflow:
	BS1B A, BC

FP_SP_NormCore_Shift:
	LD HL, 0
	LD (XIY + 002h), HL
	LD L, A
	LD (XIY + 000h:8), HL
	LD XIX, 0
	CP L, 014h
	JR Z, FP_SP_NormCore_StoreResult
	JR LT, FP_SP_NormCore_ShiftLeft
	SUB L, 014h

FP_SP_NormCore_ShiftRight:
	SRL 1, XBC
	STCF 0, IX
	RRC 1, XIX
	DJNZ L, FP_SP_NormCore_ShiftRight
	JR T, FP_SP_NormCore_StoreResult

FP_SP_NormCore_ShiftLeft:
	LD_A 014h
	SUB A, L
	CP A, 010h
	JR LT, FP_SP_NormCore_ShiftLeftLoop
	LD QBC, BC
	LD BC, 0
	SUB A, 010h
	JR Z, FP_SP_NormCore_StoreResult

FP_SP_NormCore_ShiftLeftLoop:
	SLL A, XBC

FP_SP_NormCore_StoreResult:
	LD (XIY + 008h), XBC
	LD (XIY + 004h), XIX
	RET

FP_SP_NormCore_Zero:
	LD (XIY + 002h), 001h
	RET

FP_DP_Encode:
	LD XHL, (XBC)
	CP QL, 0
	JR NZ, FP_DP_Encode_NaN
	LD XIX, (XBC + 008h)
	LD XIY, (XBC + 004h)
	CP HL, 03ffh
	JR GT, FP_DP_Encode_Overflow
	CP HL, 0fc02h
	JR LT, FP_DP_Encode_Zero
	ADD HL, 03ffh
	RES 4, QIX
	SLL 4, HL
	OR H, QH
	OR HL, QIX
	LD QIX, HL

FP_DP_Encode_Store:
	LD (XWA), XIY
	LD (XWA + 004h), XIX
	RET

FP_DP_Encode_Zero:
	LD XIX, 0
	LD XIY, XIX
	JR T, FP_DP_Encode_Store

FP_DP_Encode_NaN:
	BIT 0, QL
	JR NZ, FP_DP_Encode_Zero

FP_DP_Encode_Overflow:
	LDW (040C22h), 0022h
	LD XDE, 0
	DEC 1, XDE
	LD (XWA), XDE
	LD XDE, 7fefffffh
	LD C, QH
	OR C, QD
	LD QD, C
	LD (XWA + 004h), XDE
