	JR NZ, FP_SP_Encode_NaN
	LD XDE, (XBC + 004h)
	CP HL, 007fh
	JR GT, FP_SP_Encode_Overflow
	CP HL, 0ff82h
	JR LT, FP_SP_Encode_Zero
	ADD HL, 007fh
	LD BC, QDE
	RES 7, BC
	SLL 7, HL
	OR H, QH
	OR HL, BC
	LD QDE, HL
	LD (XWA), XDE
	RET

FP_SP_Encode_NaN:
	LD E, QL
	CP E, 008h
	JR NZ, FP_SP_Encode_Zero
	LD XDE, 0
	JR T, FP_SP_Encode_Overflow_Store

FP_SP_Encode_Zero:
	LD XDE, 0
	LD (XWA), XDE
	RET

FP_SP_Encode_Overflow:
	LD DE, 0ffffh
	LD BC, 7f7fh
