FP_DP_FreqAdjust_Combine:
	SLL 4, HL
	LD A, (XBC)
	AND A, 00fh
	EXTZ WA
	OR HL, WA
	BIT 7, (XIY)
	JR Z, FP_DP_FreqAdjust_StoreResult
	SET 0fh, HL

FP_DP_FreqAdjust_StoreResult:
	LD (XBC), HL
	LD XWA, XIX
	LD XBC, XDE
