FP_DP_AlignMantissa:
	LD H, (XWA + 002h)
	OR H, (XBC + 002h)
	RET NZ
	LD IX, (XWA + 000h:8)
	LD IY, (XBC + 000h:8)
	CP IX, IY
	RET Z
	JR LT, FP_DP_AlignMantissa_ShiftA
	LD (XBC + 000h:8), IX
	LD XWA, XBC
	SUB IX, IY
	JR T, FP_DP_AlignMantissa_Shift

FP_DP_AlignMantissa_ShiftA:
	LD (XWA + 000h:8), IY
	SUB IX, IY
	NEG IX

FP_DP_AlignMantissa_Shift:
	LD XDE, (XWA + 003h)
	LD XHL, (XWA + 007h)
	LD_E 000h
	CP IX, 0035h
	JR GT, FP_DP_AlignMantissa_MaxShift
	CP IX, 0020h
	JR LT, FP_DP_AlignMantissa_Shift16
	LD XDE, XHL
	LD XHL, 0
	SUB IX, 0020h
	JR Z, FP_DP_AlignMantissa_Round

FP_DP_AlignMantissa_Shift16:
	CP IX, 0010h
	JR LT, FP_DP_AlignMantissa_Shift8
	LD DE, QDE
	LD QDE, HL
	LD HL, QHL
	LD QHL, 0
	SUB IX, 0010h
	JR Z, FP_DP_AlignMantissa_Round

FP_DP_AlignMantissa_Shift8:
	CP IX, 0008h
	JR LT, FP_DP_AlignMantissa_ShiftBit
	SRL 8, XDE
	LD QD, L
	SRL 8, XHL
	SUB IX, 0008h
	JR Z, FP_DP_AlignMantissa_Round

FP_DP_AlignMantissa_ShiftBit:
	SRL 1, XHL
	STCF 0, DE
	RRC 1, XDE
	DJNZ IX, FP_DP_AlignMantissa_ShiftBit

FP_DP_AlignMantissa_Round:
	LD C, E
	SRL 8, XDE
	LD QD, L
	SRL 8, XHL
	CP C, 080h
	JR C, FP_DP_AlignMantissa_Store
	ADD XDE, 00000001h
	JR NC, FP_DP_AlignMantissa_Store
	ADC XHL, 00000000h

FP_DP_AlignMantissa_Store:
	LD (XWA + 004h), XDE
	LD (XWA + 008h), XHL
	RET

FP_DP_AlignMantissa_MaxShift:
	LD XDE, 0
	LD (XWA), XDE
	LD (XWA + 004h), XDE
	LD (XWA + 008h), XDE
	LD (XWA + 002h), 001h
	RET

FP_SP_AlignMantissa_Pad:
	db 0FFh

FP_SP_AlignMantissa:
	LD E, (XWA + 002h)
	OR E, (XBC + 002h)
	RET NZ
	LD IX, (XWA + 000h:8)
	LD HL, (XBC + 000h:8)
	CP IX, HL
	RET Z
	JR LT, FP_SP_AlignMantissa_ShiftA
	EX HL, IX
	JR T, FP_SP_AlignMantissa_Shift

FP_SP_AlignMantissa_ShiftA:
	LD XBC, XWA

FP_SP_AlignMantissa_Shift:
	LD XDE, (XBC + 003h)
	LD_E 000h
	LD (XBC + 000h:8), HL
	SUB HL, IX
	CP HL, 0018h
	JR GT, FP_SP_AlignMantissa_MaxShift
	BIT 4, L
	JR Z, FP_SP_AlignMantissa_Shift_Odd
	SRL_0_XDE
	AND L, 00fh
	JR Z, FP_SP_AlignMantissa_Round

FP_SP_AlignMantissa_Shift_Odd:
	LD A, L
	SRL A, XDE

FP_SP_AlignMantissa_Round:
	LD L, E
	SRL 8, XDE
	CP L, 080h
	JR C, FP_SP_AlignMantissa_Store
	INC 1, XDE

FP_SP_AlignMantissa_Store:
	LD (XBC + 004h), XDE
	RET

FP_SP_AlignMantissa_MaxShift:
	LD XIX, 0
	LD (XBC + 004h), XIX
	LD QIXL, 1
	LD (XBC), XIX
	RET

FP_DP_Mul_Outer:
	LD E, (XWA + 002h)
	OR E, (XBC + 002h)
	JP NZ, FP_NaN_Handler
	LD L, (XBC + 003h)
	XOR (XWA + 003h), L
	LD HL, (XBC + 000h:8)
	SUB (XWA + 000h:8), HL
	LD XHL, (XBC + 008h)
	LD XDE, (XBC + 004h)
	CP XHL, 00100000h
	JR NZ, FP_DP_MulMantissaCore
	OR XDE, XDE
	RET Z

FP_DP_MulMantissaCore:
	PUSH XIZ
	LDA XSP, XSP - 12
	LD XIY, (XWA + 008h)
	LD XIX, (XWA + 004h)
	LD_C 008h
	LD B, QH
	LD XIZ, 0
	CALL FP_Div_Step_Bit3
	LD (XSP), XIZ
	LD_C 008h
	LD XIZ, 0
	CALL FP_Div_Step4Bits
	LD (XSP + 004h), XIZ
	LD XIY, (XSP)
	LD XIX, (XSP + 004h)
	BIT 0fh, QIY
	JR NZ, FP_DP_MulMantissaCore_Round
	SLL 1, XIX
	STCF 0fh, QIY
	RLC 1, XIY
	DECW 1, (XWA + 000h:8)

FP_DP_MulMantissaCore_Round:
	LD BC, IX
	SRL 3, BC
	SRL 8, XIX
	LD E, IYL
	LD QIXH, E
	SRL 8, XIY
	SRL 1, XIY
	STCF 0, IX
	RRC 1, XIX
	SRL 1, XIY
	STCF 0, IX
	RRC 1, XIX
	SRL 1, XIY
	STCF 0, IX
	RRC 1, XIX
	CP C, 080h
	JR C, FP_DP_MulMantissaCore_Store
	ADD XIX, 00000001h
	ADC XIY, 00000000h
	BIT 4, QIY
	JR NZ, FP_DP_MulMantissaCore_Store
	SRL 1, XIY
	STCF 0, IX
	RRC 1, XIX
	INCW 1, (XWA + 000h:8)

FP_DP_MulMantissaCore_Store:
	LD (XWA + 008h), XIY
	LD (XWA + 004h), XIX
	LDA XSP, XSP + 00ch
	POP XIZ
	RET

FP_SP_Mul_Outer_Pad:
	db 0FFh

FP_SP_Mul_Outer:
	LD E, (XWA + 002h)
	OR E, (XWA + 002h)
	JP NZ, FP_NaN_Handler
	PUSH XIZ
	PUSH XWA
	LD HL, (XBC + 000h:8)
	SUB (XWA + 000h:8), HL
	LD L, (XBC + 003h)
	XOR (XWA + 003h), L
	LD XWA, (XWA + 004h)
	LD XBC, (XBC + 004h)
	CP XBC, 00800000h
	JR Z, FP_SP_MulMantissaCore_Divisor1
	LD XHL, 0
	LD XIX, XBC
	ADD XIX, XIX
	LD XIY, XIX
	ADD XIY, XIY
	LD XIZ, XIY
	ADD XIZ, XIZ
	LD DE, 0008h
	SLL 3, XWA

FP_SP_MulMantissaCore_Loop:
	CP XWA, XIZ
	JR C, FP_SP_MulMantissaCore_Bit2
	SUB XWA, XIZ
	SET 3, L

FP_SP_MulMantissaCore_Bit2:
	CP XWA, XIY
	JR C, FP_SP_MulMantissaCore_Bit1
	SUB XWA, XIY
	SET 2, L

FP_SP_MulMantissaCore_Bit1:
	CP XWA, XIX
	JR C, FP_SP_MulMantissaCore_Bit0
	SUB XWA, XIX
	SET 1, L

FP_SP_MulMantissaCore_Bit0:
	CP XWA, XBC
	JR C, FP_SP_MulMantissaCore_IterDone
	SUB XWA, XBC
	SET 0, L

FP_SP_MulMantissaCore_IterDone:
	DEC 1, E
	JR Z, FP_SP_MulMantissaCore_Round
	SLL 4, XHL
	SLL 4, XWA
	JR T, FP_SP_MulMantissaCore_Loop

FP_SP_MulMantissaCore_Round:
	POP XWA
	BIT 0fh, QHL
	JR NZ, FP_SP_MulMantissaCore_RoundUp
	SLL 1, XHL
	DECW 1, (XWA + 000h:8)

FP_SP_MulMantissaCore_RoundUp:
	CP L, 080h
	JR C, FP_SP_MulMantissaCore_Shift8
	ADD XHL, 00000100h
	JR NC, FP_SP_MulMantissaCore_Shift8
	STCF 0, HL
	RRC 1, XHL

FP_SP_MulMantissaCore_Shift8:
	SRL 8, XHL

FP_SP_MulMantissaCore_Store:
	LD (XWA + 004h), XHL
	POP XIZ
	RET

FP_SP_MulMantissaCore_Divisor1:
	LD XHL, XWA
	POP XWA
	JR T, FP_SP_MulMantissaCore_Store

FP_DP_SubMantissa:
	LD E, (XWA + 002h)
	OR E, (XBC + 002h)
	JP NZ, FP_DP_NegWithSign
	LD XHL, (XWA + 008h)
	LD XDE, (XWA + 004h)
	SUB XDE, (XBC + 004h)
	SBC XHL, (XBC + 008h)
	LD_B 000h
	JR NC, FP_DP_SubMantissa_NoBorrow
	LD_B 080h
	LD XIY, 0
	DEC 1, XIY
	XOR XDE, XIY
	XOR XHL, XIY
	ADD XDE, 00000001h
	ADC XHL, 00000000h
	JR T, FP_DP_SubMantissa_Normalize

FP_DP_SubMantissa_NoBorrow:
	LD XIY, XHL
	OR XIY, XDE
	JR Z, FP_DP_SubMantissa_Zero

FP_DP_SubMantissa_Normalize:
	BIT 4, QHL
	JR NZ, FP_DP_SubMantissa_Store
	LD IY, WA
	LD IX, (XWA + 000h:8)

FP_DP_SubMantissa_NormLoop:
	BS1B A, QHL
	JR NOV, FP_DP_SubMantissa_Shift
	LD QHL, HL
	LD HL, QDE
	LD QDE, DE
	LD DE, 0
	SUB IX, 0010h
	JR T, FP_DP_SubMantissa_NormLoop

FP_DP_SubMantissa_Shift:
	CP A, 4
	JR LT, FP_DP_SubMantissa_ShiftLeft
	DEC 4, A
	EXTZ WA
	ADD IX, WA
	CP A, 008h
	JR LT, FP_DP_SubMantissa_ShiftBit
	SRL 8, XDE
	LD QD, L
	SRL 8, XHL
	DEC 8, A
	JR Z, FP_DP_SubMantissa_StoreExp

FP_DP_SubMantissa_ShiftBit:
	SRL 1, XHL
	STCF 0, DE
	RRC 1, XDE
	DJNZ A, FP_DP_SubMantissa_ShiftBit
	JR T, FP_DP_SubMantissa_StoreExp

FP_DP_SubMantissa_ShiftLeft:
	SLL 1, XDE
	STCF 0fh, QHL
	RLC 1, XHL
	DEC 1, IX
	BIT 4, QHL
	JR Z, FP_DP_SubMantissa_ShiftLeft

FP_DP_SubMantissa_StoreExp:
	LD WA, IY
	LD (XWA + 000h:8), IX

FP_DP_SubMantissa_Store:
	LD (XWA + 004h), XDE
	LD (XWA + 008h), XHL
	XOR (XWA + 003h), B
	RET

FP_DP_SubMantissa_Zero:
	LD (XWA + 002h), 001h
	RET

FP_SP_SubMantissa:
	LD E, (XWA + 002h)
	OR E, (XBC + 002h)
	JP NZ, FP_DP_NegNoSign
	LD XIY, XWA
	LD DE, (XWA + 000h:8)
	LD XIX, (XWA + 004h)
	SUB XIX, (XBC + 004h)
	LD_B 000h
	JR Z, FP_SP_SubMantissa_Zero
	JR NC, FP_SP_SubMantissa_Normalize
	CPL QIX
	CPL IX
	INC 1, XIX
	LD_B 080h

FP_SP_SubMantissa_Normalize:
	CP QIX, 0
	JR NZ, FP_SP_SubMantissa_AlignBits
	SLL 8, XIX
	DEC 8, DE
	JR T, FP_SP_SubMantissa_Normalize

FP_SP_SubMantissa_AlignBits:
	LD_W 007h
	BS1B A, QIX
	SUB W, A
	LD A, W
	JR Z, FP_SP_SubMantissa_Store
	EXTZ WA
	SLL A, XIX
	SUB DE, WA

FP_SP_SubMantissa_Store:
	LD (XIY + 004h), XIX
	LD (XIY + 000h:8), DE
	XOR (XIY + 003h), B
	RET

FP_SP_SubMantissa_Zero:
	LD (XIY + 004h), XIX
	LD QIXL, 1
	LD (XIY), XIX
	RET

VoicePitch_SlideEngine:
	LDA XSP, XSP - 030h
	PUSH IZ
	LDA XBC, 01F6B6h
	LDA XWA, XSP + 022h
