VoicePitch_SlideEngine_IterLoop:
	LDA XBC, XSP + 022h
	LDA XWA, XSP + 01ah
	CALL FP_DP_Raw8Copy
	LD WA, IZ
	EXTS XWA
	LD (XSP + 016h), XWA
	LDA XBC, XSP + 016h
	LDA XWA, XSP + 00eh
	CALL FP_ScalarToDP
	LDA XBC, XSP + 03ah
	LDA XWA, XSP + 00eh
