	LDA XWA, XSP + 01ah
	LDA XBC, XSP + 022h
	LD DE, 5
	CALL ToneGen_Compare_Voice
	CP HL, 0
	JR Z, VoicePitch_SlideEngine_Done
	INC 1, IZ
	CP IZ, 012ch
	JR LE, VoicePitch_SlideEngine_IterLoop

VoicePitch_SlideEngine_Done:
	LD XWA, (XSP + 036h)
	LDA XBC, XSP + 022h
