	LD (XSP + 006h), XWA
	LD A, (XWA)
	LD QA, A
	AND A, 0f0h
	EXTZ WA
	LD IY, WA
	SRA 4, IY
	LD XIX, XHL
	LD L, (XHL)
	LD A, L
	RES 7, A
	EXTZ WA
	SLA 4, WA
	ADD WA, IY
	LD IY, WA
	LD IZ, 0
	CP BC, 0
	JR LE, VoiceFreq_EnvelopeStep_DecCheck
	CP BC, 0
	JR LE, VoiceFreq_EnvelopeStep_StoreResult

VoiceFreq_EnvelopeStep_IncLoop:
	LD WA, IY
