FP_DP_MulAdd_Sum2:
	LD IX, (XSP + 005h)
	LD XDE, (XSP + 007h)
	LD XHL, (XSP + 00bh)
	BIT 1, QHL
	JR Z, FP_DP_MulAdd_Round
	INCW 1, (XWA + 000h:8)
	SRL 1, XHL
	STCF 0, DE
	RRC 1, XDE
	STCF 0, IX
	RRC 1, IX

FP_DP_MulAdd_Round:
	LD C, IXH
	LD B, QD
	SRL 4, C
	SRL 4, B
	SLL 4, XHL
	SLL 4, XDE
	SLL 4, IX
	OR E, C
	OR L, B
	CP IXH, 080h
	JR C, FP_DP_MulAdd_Store
	ADD XDE, 00000001h
	ADC XHL, 00000000h
	BIT 4, QHL
	JR NZ, FP_DP_MulAdd_Store
	SRL 1, XHL
	STCF 0, DE
	RRC 1, XDE
	INCW 1, (XWA + 000h:8)

FP_DP_MulAdd_Store:
	LD (XWA + 004h), XDE
	LD (XWA + 008h), XHL
	LDA XSP, XSP + 010h
	POP XIZ
	RET

FP_SP_MulAdd:
	LD E, (XWA + 002h)
	OR E, (XBC + 002h)
	JP NZ, FP_Overflow_Handler
	PUSH XIZ
	LD XIZ, XWA
	LD XHL, (XBC)
	ADD (XWA + 000h:8), HL
	LD L, QH
	XOR (XWA + 003h), L
	LD XWA, (XWA + 004h)
	LD XBC, (XBC + 004h)
	LD DE, QWA
	LD HL, DE
	LD IX, QBC
	MUL XDE, IX
	MUL XHL, BC
	MUL XIX, WA
	MUL XWA, BC
	ADD XHL, XIX
	EX DE, QDE
	ADD XDE, XHL
	LD HL, QWA
	EXTZ XHL
	ADD XDE, XHL
	BIT 0fh, QDE
	JR Z, FP_SP_MulAdd_NormCheck
	INCW 1, (XIZ + 000h:8)
	JR T, FP_SP_MulAdd_Round

FP_SP_MulAdd_NormCheck:
	SLL 1, WA
	STCF 0fh, QDE
	RLC 1, XDE

FP_SP_MulAdd_Round:
	CP E, 080h
	JR C, FP_SP_MulAdd_Store
	ADD XDE, 00000100h
	JR NC, FP_SP_MulAdd_Store
	STCF 0, DE
	RRC 1, XDE
	INCW 1, (XIZ + 000h:8)

FP_SP_MulAdd_Store:
	SRL 8, XDE
	LD (XIZ + 004h), XDE
	POP XIZ
	RET

FP_MulMantissa64x64:
	LD DE, QHL
	LD IX, DE
	LD IZ, QIY
	MUL XDE, IZ
	MUL XIX, IY
	MUL XIZ, HL
	MUL XHL, IY
	ADD XIX, XIZ
	ADC QDE, 0000h
	ADD DE, QIX
	ADC QDE, 0000h
	ADD IX, QHL
	LD QHL, IX
	RET NC
	ADC XDE, 00000000h
	RET

